const GRAMMAR_VOCAB_ITEMS = [{"id":"gv-kc-01-1","level":"kc","focus":"tense","q":"Look at those dark clouds over the school gate! It ______ very soon.","options":["rains","is going to rain","has rained","rained"],"correct":1,"answer":"is going to rain","vi":"Nhìn mấy đám mây đen trên cổng trường kìa! Trời sắp mưa rồi.","explanation":"A prediction based on present evidence (the dark clouds) takes <b>be going to</b>; the present simple, present perfect and past simple do not talk about the near future."},{"id":"gv-kc-01-2","level":"kc","focus":"word-choice","q":"Nam paid the taxi ______ with the coins he had left in his pocket.","options":["fare","fee","fine","tip"],"correct":0,"answer":"fare","vi":"Nam trả tiền taxi bằng mấy đồng xu còn lại trong túi.","explanation":"The money you pay for a journey by taxi, bus or train is a <b>fare</b>; a <b>fee</b> is paid for a service such as a course, a <b>fine</b> is a punishment, and a <b>tip</b> is extra money given as thanks."},{"id":"gv-kc-01-3","level":"kc","focus":"collocation","q":"There was ______ rain all afternoon, so the football match was cancelled.","options":["strong","hard","heavy","big"],"correct":2,"answer":"heavy","vi":"Mưa to suốt cả buổi chiều nên trận bóng đá đã bị hủy.","explanation":"Rain that falls in large amounts is <b>heavy rain</b>; <b>strong</b> goes with wind, and <b>hard</b> and <b>big</b> do not collocate with rain."},{"id":"gv-kc-01-4","level":"kc","focus":"idiom","q":"Lan: Did you buy the new maths workbook? / Nam: Yes, but I had to ______ for it at the shop near school.","options":["pay lip service","pay my way","pay my respects","pay through the nose"],"correct":3,"answer":"pay through the nose","vi":"Lan: Cậu mua cuốn bài tập toán mới chưa? / Nam: Rồi, nhưng tớ phải trả giá cắt cổ ở tiệm gần trường.","explanation":"To <b>pay through the nose</b> for something is to pay far too much for it. <b>Pay lip service to</b> means to support something only in words, <b>pay your way</b> is to pay your own costs, and <b>pay your respects</b> is to greet someone politely."},{"id":"gv-kc-01-5","level":"kc","focus":"phrasal-verb","q":"Lan: Who ______ your little brother when your parents are at work? / Nam: My grandmother does.","options":["looks after","looks up","looks into","looks for"],"correct":0,"answer":"looks after","vi":"Lan: Ai trông em trai cậu khi bố mẹ cậu đi làm? / Nam: Bà tớ.","explanation":"<b>Look after</b> means to take care of someone. <b>Look up</b> is to find information, <b>look into</b> is to investigate, and <b>look for</b> is to search for something lost."},{"id":"gv-kc-01-6","level":"kc","focus":"modal","q":"Nam ______ have taken my umbrella — he wasn't even at school today.","options":["must","can't","should","needn't"],"correct":1,"answer":"can't","vi":"Nam không thể nào lấy ô của tớ được — hôm nay cậu ấy thậm chí còn không đi học.","explanation":"<b>Can't have + past participle</b> says that something was impossible in the past; <b>must have</b> would mean the speaker is sure it happened, which the second clause rules out."},{"id":"gv-kc-01-7","level":"kc","focus":"relative","q":"The teacher ______ class we have on Monday mornings is going to retire next year.","options":["who","which","whose","whom"],"correct":2,"answer":"whose","vi":"Cô giáo mà chúng tôi có tiết học vào các sáng thứ Hai sẽ nghỉ hưu vào năm sau.","explanation":"A noun (<b>class</b>) follows the blank, so the relative pronoun must show possession: <b>whose</b>. <b>Who</b>, <b>which</b> and <b>whom</b> cannot be followed directly by a noun in this way."},{"id":"gv-kc-01-8","level":"kc","focus":"article-quantifier","q":"Lan: Do you want to play badminton? / Nam: Sorry, I have too ______ homework to finish before nine.","options":["many","few","a lot","much"],"correct":3,"answer":"much","vi":"Lan: Cậu có muốn chơi cầu lông không? / Nam: Xin lỗi, tớ có quá nhiều bài tập về nhà phải làm xong trước chín giờ.","explanation":"<b>Homework</b> is an uncountable noun, so it takes <b>too much</b>; <b>many</b> and <b>few</b> go with countable nouns, and <b>a lot</b> cannot follow <b>too</b>."},{"id":"gv-kc-01-9","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your project to school tomorrow — the teacher is going to collect it.","options":["bringing","to bring","bring","brought"],"correct":1,"answer":"to bring","vi":"Nhớ mang dự án đến trường ngày mai nhé — cô giáo sẽ thu đấy.","explanation":"<b>Remember to do</b> something means not to forget a task you still have to do; <b>remember doing</b> refers to a memory of something already done."},{"id":"gv-kc-01-10","level":"kc","focus":"linking","q":"It rained all day on Saturday; ______, the school picnic was put off until next week.","options":["however","whereas","consequently","otherwise"],"correct":2,"answer":"consequently","vi":"Thứ Bảy trời mưa cả ngày; do đó, buổi dã ngoại của trường bị hoãn sang tuần sau.","explanation":"The second sentence is the result of the first, so the linker is <b>consequently</b>; <b>however</b> and <b>whereas</b> show contrast and <b>otherwise</b> means 'if not'."},{"id":"gv-kc-01-11","level":"kc","focus":"conditional","q":"If it ______ tomorrow, we will have PE in the gym instead of on the field.","options":["rains","will rain","rained","would rain"],"correct":0,"answer":"rains","vi":"Nếu ngày mai trời mưa, chúng tôi sẽ học thể dục trong nhà thi đấu thay vì ngoài sân.","explanation":"A real future possibility is a first conditional: <b>if + present simple</b>, will + verb in the main clause. <b>Will</b> does not go in the if-clause, and <b>rained</b>/<b>would rain</b> belong to the second conditional."},{"id":"gv-kc-01-12","level":"kc","focus":"passive","q":"The final exam results ______ on the school website next Friday.","options":["will announce","are announcing","have announced","will be announced"],"correct":3,"answer":"will be announced","vi":"Kết quả kỳ thi cuối kỳ sẽ được công bố trên trang web của trường vào thứ Sáu tới.","explanation":"The results do not announce anything; they are announced by the school, so the verb must be passive: <b>will be announced</b>."},{"id":"gv-kc-01-13","level":"kc","focus":"reported","q":"Lan said that she ______ a doctor when she grew up.","options":["will be","would be","is","has been"],"correct":1,"answer":"would be","vi":"Lan nói rằng khi lớn lên cô ấy sẽ trở thành bác sĩ.","explanation":"After a past reporting verb (<b>said</b>), <b>will</b> shifts back to <b>would</b>; the present forms do not match the past tense of the whole sentence."},{"id":"gv-kc-01-14","level":"kc","focus":"preposition","q":"Our maths teacher is strict, but she is always patient ______ slow learners.","options":["to","for","with","at"],"correct":2,"answer":"with","vi":"Cô giáo toán của chúng tôi nghiêm khắc, nhưng cô luôn kiên nhẫn với những học sinh tiếp thu chậm.","explanation":"The adjective <b>patient</b> takes the preposition <b>with</b> when it refers to a person; <b>good at</b>, <b>kind to</b> and <b>famous for</b> use other prepositions."},{"id":"gv-kc-01-15","level":"kc","focus":"comparison","q":"This winter is much ______ than last winter — I have to wear two jumpers to school.","options":["colder","cold","coldest","the coldest"],"correct":0,"answer":"colder","vi":"Mùa đông năm nay lạnh hơn nhiều so với mùa đông năm ngoái — tôi phải mặc hai cái áo len đi học.","explanation":"<b>Than</b> signals a comparison of two things, so a comparative is needed: <b>colder</b>. A superlative is used with <b>the</b> and no <b>than</b>."},{"id":"gv-kc-01-16","level":"kc","focus":"idiom","q":"Whenever I show my brother an essay, he ______ it and tells me everything that is wrong.","options":["turns a blind eye to","picks holes in","makes light of","pulls strings for"],"correct":1,"answer":"picks holes in","vi":"Mỗi lần tôi đưa anh trai xem bài luận, anh ấy lại bới lông tìm vết và chỉ ra mọi lỗi sai.","explanation":"To <b>pick holes in</b> something is to find faults in it. <b>Turn a blind eye to</b> means to ignore, <b>make light of</b> is to treat as unimportant, and <b>pull strings for</b> is to use influence to help someone."},{"id":"gv-kc-01-17","level":"kc","focus":"phrasal-verb","q":"Lan: Do you ______ your new classmates? / Nam: Yes, they are really friendly.","options":["get over","get away with","get through","get on with"],"correct":3,"answer":"get on with","vi":"Lan: Cậu có hòa hợp với các bạn cùng lớp mới không? / Nam: Có, các bạn ấy rất thân thiện.","explanation":"<b>Get on with</b> someone means to have a friendly relationship with them. <b>Get over</b> is to recover from something, <b>get away with</b> is to escape punishment, and <b>get through</b> is to finish or survive something."},{"id":"gv-kc-01-18","level":"kc","focus":"tense","q":"I ______ my old primary school report while I was tidying my desk last night.","options":["came across","was coming across","have come across","had come across"],"correct":0,"answer":"came across","vi":"Tối qua tôi tình cờ thấy học bạ tiểu học cũ của mình khi đang dọn bàn học.","explanation":"A short action that happened during a longer one (<b>while I was tidying</b>) takes the past simple: <b>came across</b>. The past continuous is for the longer background action, and <b>last night</b> rules out the present perfect."},{"id":"gv-kc-01-19","level":"kc","focus":"word-choice","q":"Please check the new class ______ — chemistry has moved to Thursday afternoon.","options":["calendar","diary","timetable","menu"],"correct":2,"answer":"timetable","vi":"Hãy kiểm tra thời khóa biểu mới của lớp — môn hóa đã chuyển sang chiều thứ Năm.","explanation":"A list of the times of school lessons is a <b>timetable</b>; a <b>calendar</b> shows the days of the year, a <b>diary</b> is a personal record, and a <b>menu</b> lists food."},{"id":"gv-kc-01-20","level":"kc","focus":"word-choice","q":"Keep the ______ in case the calculator stops working and you need to take it back to the shop.","options":["recipe","receipt","bill","ticket"],"correct":1,"answer":"receipt","vi":"Hãy giữ hóa đơn phòng khi máy tính bỏ túi bị hỏng và bạn cần mang ra trả lại cửa hàng.","explanation":"A <b>receipt</b> is the paper proving you paid for something, which a shop asks for when you return goods; a <b>recipe</b> is cooking instructions, a <b>bill</b> asks for payment, and a <b>ticket</b> lets you travel or enter."},{"id":"gv-kc-01-21","level":"kc","focus":"word-choice","q":"The weather ______ says it will be sunny and 32 degrees in Ho Chi Minh City tomorrow.","options":["prediction","estimate","guess","forecast"],"correct":3,"answer":"forecast","vi":"Dự báo thời tiết nói ngày mai ở Thành phố Hồ Chí Minh trời nắng và 32 độ.","explanation":"A statement of what the weather will probably be is a <b>weather forecast</b>; <b>estimate</b> and <b>guess</b> are rough judgements, and <b>prediction</b> is not the word used with weather."},{"id":"gv-kc-01-22","level":"kc","focus":"word-choice","q":"To get a part-time job at the café, you have to fill in an ______ form first.","options":["application","appointment","advertisement","interview"],"correct":0,"answer":"application","vi":"Để xin làm thêm ở quán cà phê, trước tiên bạn phải điền vào đơn xin việc.","explanation":"The form you complete to ask for a job is an <b>application form</b>; an <b>appointment</b> is a fixed meeting time, an <b>advertisement</b> announces the job, and an <b>interview</b> comes after you apply."},{"id":"gv-kc-01-23","level":"kc","focus":"collocation","q":"Nam wants to be a pilot, so he is ______ a lot of effort into his English lessons.","options":["making","taking","putting","giving"],"correct":2,"answer":"putting","vi":"Nam muốn trở thành phi công nên cậu ấy đang dồn rất nhiều công sức vào các tiết tiếng Anh.","explanation":"The collocation is <b>put effort into</b> something; <b>make an effort</b> exists but is not followed by <b>into</b>, and <b>take</b>/<b>give effort</b> are not English."},{"id":"gv-kc-01-24","level":"kc","focus":"collocation","q":"Lan: Can you come out and play? / Nam: Sorry, I haven't ______ my homework yet.","options":["made","taken","given","done"],"correct":3,"answer":"done","vi":"Lan: Cậu ra ngoài chơi được không? / Nam: Xin lỗi, tớ chưa làm xong bài tập về nhà.","explanation":"The verb that goes with <b>homework</b> is <b>do</b>: do your homework. <b>Make</b> is used for creating things (make a cake, make a decision), never for homework."},{"id":"gv-kc-01-25","level":"kc","focus":"tense","q":"My uncle ______ as a chef in a hotel in Da Nang since 2019.","options":["works","has worked","is working","worked"],"correct":1,"answer":"has worked","vi":"Chú tôi đã làm đầu bếp ở một khách sạn tại Đà Nẵng từ năm 2019.","explanation":"<b>Since + a starting point</b> describes an action that began in the past and continues now, which takes the present perfect: <b>has worked</b>."},{"id":"gv-kc-02-1","level":"kc","focus":"tense","q":"I ______ this novel since Monday, and I still haven't reached the last chapter.","options":["am reading","have been reading","read","was reading"],"correct":1,"answer":"have been reading","vi":"Tôi đọc cuốn tiểu thuyết này từ thứ Hai mà vẫn chưa tới chương cuối.","explanation":"An action that began in the past (<b>since Monday</b>) and is still going on takes the present perfect continuous: <b>have been reading</b>. The present simple, past simple and past continuous cannot go with <b>since</b> + a starting point."},{"id":"gv-kc-02-2","level":"kc","focus":"word-choice","q":"Lan: How much is the bus ______ to the cinema? / Nam: Only seven thousand dong each way.","options":["fare","fee","price","charge"],"correct":0,"answer":"fare","vi":"Lan: Vé xe buýt tới rạp chiếu phim bao nhiêu tiền? / Nam: Chỉ bảy nghìn đồng một chiều thôi.","explanation":"The money you pay for a bus, taxi or train ride is a <b>fare</b>. A <b>fee</b> is paid for a service (a doctor, a school), a <b>price</b> is for goods in a shop, and a <b>charge</b> is a general amount a company asks for, not the fixed word for transport."},{"id":"gv-kc-02-3","level":"kc","focus":"idiom","q":"My parents ______ for my sister's wedding party: a live band, fireworks and a five-tier cake.","options":["pulled some strings","pulled their socks up","pulled out all the stops","pulled our legs"],"correct":2,"answer":"pulled out all the stops","vi":"Bố mẹ tôi đã dốc toàn lực cho tiệc cưới của chị tôi: ban nhạc sống, pháo hoa và chiếc bánh cưới năm tầng.","explanation":"<b>Pull out all the stops</b> means to make every possible effort so that something is a success. <b>Pull strings</b> is to use influence, <b>pull your socks up</b> is to start working harder, and <b>pull someone's leg</b> is to joke with them."},{"id":"gv-kc-02-4","level":"kc","focus":"collocation","q":"My brother ______ the housework on Saturdays while I cook lunch.","options":["makes","does","takes","gives"],"correct":1,"answer":"does","vi":"Anh tôi làm việc nhà vào thứ Bảy còn tôi nấu bữa trưa.","explanation":"We <b>do</b> the housework, the shopping and the washing-up; <b>make</b> goes with things you create (make a cake, make a decision). <b>Take</b> and <b>give</b> do not collocate with <b>housework</b>."},{"id":"gv-kc-02-5","level":"kc","focus":"relative","q":"That's the singer ______ concert we went to last month.","options":["whose","who","whom","which"],"correct":0,"answer":"whose","vi":"Đó là ca sĩ mà tháng trước chúng tôi đã đi xem buổi hòa nhạc của cô ấy.","explanation":"The concert belongs to the singer, so we need the possessive relative <b>whose</b> + noun. <b>Who</b> and <b>whom</b> replace a person, not a possession, and <b>which</b> is for things."},{"id":"gv-kc-02-6","level":"kc","focus":"phrasal-verb","q":"Minh's birthday party has been ______ until next Saturday because his mother is ill.","options":["put out","put off","put up","set off"],"correct":1,"answer":"put off","vi":"Tiệc sinh nhật của Minh đã bị hoãn đến thứ Bảy tuần sau vì mẹ cậu ấy bị ốm.","explanation":"<b>Put off</b> means to postpone, which fits <b>until next Saturday</b>. <b>Put out</b> is to extinguish a fire, <b>put up</b> is to build or to give someone a bed, and <b>set off</b> is to start a journey."},{"id":"gv-kc-02-7","level":"kc","focus":"word-choice","q":"To save money, my friends and I stayed at a cheap ______ where we shared a room with six other travellers.","options":["hostel","hotel","resort","campsite"],"correct":0,"answer":"hostel","vi":"Để tiết kiệm tiền, tôi và bạn bè ở một nhà nghỉ tập thể giá rẻ, chung phòng với sáu du khách khác.","explanation":"A <b>hostel</b> is cheap accommodation where travellers share large rooms. In a <b>hotel</b> or <b>resort</b> you have your own room, and at a <b>campsite</b> you sleep in a tent, not in a room."},{"id":"gv-kc-02-8","level":"kc","focus":"modal","q":"Nam ______ the film last night — he was at my house until midnight.","options":["must have seen","might have seen","should have seen","can't have seen"],"correct":3,"answer":"can't have seen","vi":"Nam không thể nào đã xem bộ phim tối qua được — cậu ấy ở nhà tôi đến tận nửa đêm.","explanation":"<b>Can't have</b> + past participle says something was impossible in the past: he was with me, so seeing the film was impossible. <b>Must have</b> expresses near certainty that it happened, <b>might have</b> a possibility, and <b>should have</b> an action that was expected but not done."},{"id":"gv-kc-02-9","level":"kc","focus":"article-quantifier","q":"There were only ______ guests at the party, so we all sat around one table.","options":["few","a few","little","a little"],"correct":1,"answer":"a few","vi":"Bữa tiệc chỉ có vài vị khách, nên tất cả chúng tôi ngồi quanh một bàn.","explanation":"<b>Guests</b> is a countable plural, so it takes <b>few / a few</b>, not <b>little / a little</b>. After <b>only</b> we use <b>a few</b> (a small number); <b>few</b> on its own means almost none and does not follow <b>only</b>."},{"id":"gv-kc-02-10","level":"kc","focus":"tense","q":"By the time we found our seats, the film ______.","options":["has already started","already starts","is already starting","had already started"],"correct":3,"answer":"had already started","vi":"Lúc chúng tôi tìm được chỗ ngồi thì bộ phim đã bắt đầu rồi.","explanation":"<b>By the time</b> + past simple (found) needs the past perfect for the earlier action: <b>had already started</b>. Present forms cannot combine with a past-time clause."},{"id":"gv-kc-02-11","level":"kc","focus":"gerund-infinitive","q":"After the doctor's visit, my father decided ______ smoking for good.","options":["giving up","give up","to give up","to giving up"],"correct":2,"answer":"to give up","vi":"Sau khi đi khám bác sĩ, bố tôi quyết định bỏ hẳn thuốc lá.","explanation":"<b>Decide</b> is followed by a to-infinitive: <b>decided to give up</b>. The gerund and the bare infinitive do not follow <b>decide</b>, and <b>to giving up</b> is not a form that exists after this verb."},{"id":"gv-kc-02-12","level":"kc","focus":"word-choice","q":"From our hotel balcony we had a wonderful ______ of the harbour.","options":["sight","view","scene","scenery"],"correct":1,"answer":"view","vi":"Từ ban công khách sạn, chúng tôi ngắm được toàn cảnh bến cảng thật tuyệt.","explanation":"<b>Have a view of</b> something is the fixed pattern for what you can see from a place. <b>Sight</b> is the ability to see or a place worth visiting, a <b>scene</b> is a part of a film or an event, and <b>scenery</b> is uncountable and never takes <b>a</b>."},{"id":"gv-kc-02-13","level":"kc","focus":"linking","q":"______ the film was three hours long, nobody left the cinema early.","options":["Although","Despite","However","Because"],"correct":0,"answer":"Although","vi":"Mặc dù bộ phim dài ba tiếng, không ai rời rạp sớm cả.","explanation":"A contrast introduced by a full clause (subject + verb) needs <b>although</b>. <b>Despite</b> must be followed by a noun or -ing form, <b>however</b> cannot join two clauses this way, and <b>because</b> gives a reason, which does not fit the meaning."},{"id":"gv-kc-02-14","level":"kc","focus":"collocation","q":"The picnic was cancelled because of the ______ rain on Sunday morning.","options":["strong","hard","big","heavy"],"correct":3,"answer":"heavy","vi":"Buổi dã ngoại bị hủy vì trận mưa lớn sáng Chủ nhật.","explanation":"Rain, traffic and snow are described as <b>heavy</b>. <b>Strong</b> collocates with wind or coffee, and <b>hard</b> and <b>big</b> are not used with <b>rain</b>."},{"id":"gv-kc-02-15","level":"kc","focus":"idiom","q":"Dad finally ______ and said that nobody could use a phone at the dinner table.","options":["put his feet up","put his foot down","put his back into it","put his cards on the table"],"correct":1,"answer":"put his foot down","vi":"Cuối cùng bố cũng cương quyết ra lệnh rằng không ai được dùng điện thoại trong bữa tối.","explanation":"<b>Put your foot down</b> means to be firm and refuse to allow something. <b>Put your feet up</b> is to relax, <b>put your back into it</b> is to work hard, and <b>put your cards on the table</b> is to be honest about your plans."},{"id":"gv-kc-02-16","level":"kc","focus":"conditional","q":"If my brother ______ so much noise every evening, I could finish my book in a week.","options":["doesn't make","hadn't made","didn't make","won't make"],"correct":2,"answer":"didn't make","vi":"Nếu em trai tôi không làm ồn như vậy mỗi tối thì tôi có thể đọc xong cuốn sách trong một tuần.","explanation":"This is a second conditional about a present situation that is not true (<b>every evening</b> + <b>could finish</b>), so the if-clause takes the past simple: <b>didn't make</b>. The present and future forms belong to the first conditional, and <b>hadn't made</b> would refer to a finished past event."},{"id":"gv-kc-02-17","level":"kc","focus":"word-choice","q":"Our ______ was a quiet village by the sea, but the bus dropped us in the wrong town.","options":["direction","distance","arrival","destination"],"correct":3,"answer":"destination","vi":"Điểm đến của chúng tôi là một ngôi làng yên tĩnh ven biển, nhưng xe buýt lại thả chúng tôi ở nhầm thị trấn.","explanation":"The place you are travelling to is your <b>destination</b>. <b>Direction</b> is the way you go (north, left), <b>distance</b> is how far it is, and <b>arrival</b> is the act of getting there, not the place itself."},{"id":"gv-kc-02-18","level":"kc","focus":"agreement","q":"Neither my parents nor my little sister ______ horror films.","options":["like","likes","are liking","have liked"],"correct":1,"answer":"likes","vi":"Cả bố mẹ tôi lẫn em gái tôi đều không thích phim kinh dị.","explanation":"With <b>neither … nor</b>, the verb agrees with the subject nearest to it: <b>my little sister likes</b>. <b>Like</b>, <b>are liking</b> and <b>have liked</b> would agree with the plural <b>parents</b>, and <b>like</b> is a state verb that is not used in continuous forms anyway."},{"id":"gv-kc-02-19","level":"kc","focus":"phrasal-verb","q":"My cousin has ______ the piano and practises every evening after dinner.","options":["taken over","taken in","taken off","taken up"],"correct":3,"answer":"taken up","vi":"Em họ tôi mới bắt đầu học đàn piano và luyện tập mỗi tối sau bữa ăn.","explanation":"<b>Take up</b> means to start a new hobby or activity. <b>Take over</b> is to take control of something, <b>take in</b> is to understand or to give someone a home, and <b>take off</b> is to remove clothes or to leave the ground."},{"id":"gv-kc-02-20","level":"kc","focus":"participle","q":"The chocolate cake ______ by my grandmother was the best thing at the party.","options":["making","was made","made","had made"],"correct":2,"answer":"made","vi":"Chiếc bánh sô-cô-la do bà tôi làm là món ngon nhất trong bữa tiệc.","explanation":"A past participle shortens the relative clause <b>which was made by my grandmother</b>: <b>the cake made by</b>. <b>Making</b> would mean the cake did the making, and <b>was made / had made</b> would give the sentence two main verbs."},{"id":"gv-kc-02-21","level":"kc","focus":"tense","q":"This time next week we ______ on the beach in Nha Trang with all our cousins.","options":["will be lying","lie","have lain","were lying"],"correct":0,"answer":"will be lying","vi":"Giờ này tuần sau chúng tôi sẽ đang nằm trên bãi biển Nha Trang cùng tất cả anh chị em họ.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, which takes the future continuous: <b>will be lying</b>. The present simple, present perfect and past continuous do not describe a future moment."},{"id":"gv-kc-02-22","level":"kc","focus":"word-choice","q":"On the first day in Hue, my family went ______ and took photos of every old palace.","options":["watching","viewing","sightseeing","looking"],"correct":2,"answer":"sightseeing","vi":"Ngày đầu tiên ở Huế, gia đình tôi đi tham quan và chụp ảnh mọi cung điện cổ.","explanation":"<b>Go sightseeing</b> is the set expression for visiting the famous places of a town. <b>Watching</b> and <b>viewing</b> need an object (watching a film), and <b>go looking</b> needs <b>for</b> something."},{"id":"gv-kc-02-23","level":"kc","focus":"pronoun","q":"My brother and I often cook dinner ______ when our parents work late.","options":["ourself","themselves","each other","ourselves"],"correct":3,"answer":"ourselves","vi":"Anh em tôi thường tự nấu bữa tối khi bố mẹ đi làm về muộn.","explanation":"<b>My brother and I</b> = <b>we</b>, so the reflexive pronoun is <b>ourselves</b> (meaning without help). <b>Ourself</b> does not exist in standard English, <b>themselves</b> refers to <b>they</b>, and <b>each other</b> would mean we cook one another, which makes no sense."},{"id":"gv-kc-02-24","level":"kc","focus":"collocation","q":"Could you ______ a photo of us in front of the cinema, please?","options":["make","do","take","catch"],"correct":2,"answer":"take","vi":"Bạn chụp giúp bọn mình một tấm ảnh trước rạp chiếu phim được không?","explanation":"In English you <b>take</b> a photo. <b>Make</b> and <b>do</b> are the usual learner mistakes, and <b>catch</b> is used with a bus, a ball or a cold, not a photo."},{"id":"gv-kc-02-25","level":"kc","focus":"question-tag","q":"Let's watch a comedy tonight, ______?","options":["shall we","will we","do we","don't we"],"correct":0,"answer":"shall we","vi":"Tối nay chúng ta xem phim hài nhé?","explanation":"A suggestion with <b>Let's</b> always takes the tag <b>shall we?</b>. <b>Will you</b> follows an imperative, and <b>do / don't we</b> follow a present simple statement with <b>we</b>."},{"id":"gv-kc-03-1","level":"kc","focus":"word-choice","q":"At the checkout, the ______ scanned my items and asked if I wanted a bag.","options":["cashier","customer","accountant","banker"],"correct":0,"answer":"cashier","vi":"Ở quầy tính tiền, nhân viên thu ngân quét các món hàng của tôi và hỏi tôi có cần túi không.","explanation":"A <b>cashier</b> takes payment at the checkout. A <b>customer</b> is the buyer, an <b>accountant</b> keeps company accounts and a <b>banker</b> works in a bank."},{"id":"gv-kc-03-2","level":"kc","focus":"word-choice","q":"Thousands of ______ cheered when the striker scored in the last minute.","options":["witnesses","spectators","observers","audiences"],"correct":1,"answer":"spectators","vi":"Hàng nghìn khán giả reo hò khi tiền đạo ghi bàn ở phút cuối.","explanation":"<b>Spectators</b> are the people watching a sports event. <b>Witnesses</b> see a crime or accident, <b>observers</b> watch officially, and <b>audience</b> is a group noun that is not counted as 'thousands of audiences'."},{"id":"gv-kc-03-3","level":"kc","focus":"word-choice","q":"My sister's ______ in the chess final was a boy who had never lost a game.","options":["partner","colleague","opponent","teammate"],"correct":2,"answer":"opponent","vi":"Đối thủ của chị tôi trong trận chung kết cờ vua là một cậu bé chưa từng thua ván nào.","explanation":"An <b>opponent</b> is the person you play against. A <b>partner</b> or <b>teammate</b> plays on your side, and a <b>colleague</b> works with you."},{"id":"gv-kc-03-4","level":"kc","focus":"word-choice","q":"The ______ blew her whistle and told the children to get out of the pool.","options":["bodyguard","doorman","guardian","lifeguard"],"correct":3,"answer":"lifeguard","vi":"Nhân viên cứu hộ thổi còi và bảo bọn trẻ ra khỏi hồ bơi.","explanation":"A <b>lifeguard</b> watches swimmers at a pool or beach. A <b>bodyguard</b> protects a person, a <b>doorman</b> stands at a building's entrance, and a <b>guardian</b> is legally responsible for a child."},{"id":"gv-kc-03-5","level":"kc","focus":"word-choice","q":"A famous ______ with two million subscribers reviews new phones on her video channel every week.","options":["vlogger","blogger","editor","reporter"],"correct":0,"answer":"vlogger","vi":"Một vlogger nổi tiếng với hai triệu người đăng ký đánh giá điện thoại mới trên kênh video của cô ấy mỗi tuần.","explanation":"A <b>vlogger</b> makes videos for a channel. A <b>blogger</b> writes posts, an <b>editor</b> checks and corrects texts, and a <b>reporter</b> writes news."},{"id":"gv-kc-03-6","level":"kc","focus":"collocation","q":"Before buying the phone, Nam ______ a lot of research online.","options":["made","did","took","gave"],"correct":1,"answer":"did","vi":"Trước khi mua điện thoại, Nam đã tìm hiểu rất nhiều trên mạng.","explanation":"The collocation is <b>do research</b>; we do not say 'make', 'take' or 'give' research."},{"id":"gv-kc-03-7","level":"kc","focus":"collocation","q":"Choose a ______ password so that nobody can get into your account.","options":["heavy","hard","strong","powerful"],"correct":2,"answer":"strong","vi":"Hãy chọn một mật khẩu mạnh để không ai vào được tài khoản của bạn.","explanation":"A password that is difficult to guess is a <b>strong password</b>; 'heavy', 'hard' and 'powerful' do not collocate with 'password'."},{"id":"gv-kc-03-8","level":"kc","focus":"collocation","q":"Please ______ attention when the referee explains the rules of the game.","options":["give","take","make","pay"],"correct":3,"answer":"pay","vi":"Hãy chú ý khi trọng tài giải thích luật của trận đấu.","explanation":"The fixed collocation is <b>pay attention</b>; 'give', 'take' and 'make' are not used with 'attention' in this meaning."},{"id":"gv-kc-03-9","level":"kc","focus":"tense","q":"Even though it started to rain, the players ______ with the match until the referee stopped it.","options":["carried on","have carried on","carry on","had carried on"],"correct":0,"answer":"carried on","vi":"Dù trời bắt đầu mưa, các cầu thủ vẫn tiếp tục trận đấu cho đến khi trọng tài dừng lại.","explanation":"A finished past story told in order (it started to rain, they carried on, the referee stopped it) uses the <b>past simple</b>: <b>carried on</b>."},{"id":"gv-kc-03-10","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Nam's mum: He ______ football in the park at the moment.","options":["plays","is playing","has played","played"],"correct":1,"answer":"is playing","vi":"Lan: Nam đâu ạ? / Mẹ Nam: Nó đang đá bóng trong công viên.","explanation":"<b>At the moment</b> signals an action happening now, so the present continuous <b>is playing</b> is needed."},{"id":"gv-kc-03-11","level":"kc","focus":"tense","q":"I ______ this phone for three years, so it's time to buy a new one.","options":["had","am having","have had","have"],"correct":2,"answer":"have had","vi":"Tôi đã dùng chiếc điện thoại này ba năm rồi, nên đã đến lúc mua cái mới.","explanation":"A situation that began in the past and continues now, with <b>for three years</b>, takes the present perfect: <b>have had</b>."},{"id":"gv-kc-03-12","level":"kc","focus":"tense","q":"By the time the shop opened, dozens of people ______ outside for hours.","options":["waited","have waited","were waiting","had been waiting"],"correct":3,"answer":"had been waiting","vi":"Đến lúc cửa hàng mở cửa, hàng chục người đã đứng chờ bên ngoài suốt mấy tiếng.","explanation":"An activity that continued up to a past moment (<b>by the time the shop opened</b>) with <b>for hours</b> takes the past perfect continuous: <b>had been waiting</b>."},{"id":"gv-kc-03-13","level":"kc","focus":"idiom","q":"Lan: Do you know a shop called Phone World? / Nam: The name ______, but I can't remember where it is.","options":["breaks the ice","rings a bell","hits the nail on the head","gets on my nerves"],"correct":1,"answer":"rings a bell","vi":"Lan: Cậu biết cửa hàng tên Phone World không? / Nam: Cái tên nghe quen quen, nhưng tớ không nhớ nó ở đâu.","explanation":"<b>Ring a bell</b> means 'sound familiar'. <b>Break the ice</b> is to make people relax, <b>hit the nail on the head</b> is to be exactly right, and <b>get on someone's nerves</b> is to annoy them."},{"id":"gv-kc-03-14","level":"kc","focus":"idiom","q":"Our team played well in the first half but ______ after the break and lost 3-1.","options":["ran out of steam","hit the roof","missed the boat","made ends meet"],"correct":0,"answer":"ran out of steam","vi":"Đội chúng tôi chơi tốt ở hiệp một nhưng đuối sức sau giờ nghỉ và thua 3-1.","explanation":"<b>Run out of steam</b> means to lose energy and stop trying hard. <b>Hit the roof</b> is to get very angry, <b>miss the boat</b> is to lose a chance, and <b>make ends meet</b> is to have just enough money."},{"id":"gv-kc-03-15","level":"kc","focus":"phrasal-verb","q":"The shop ______ my request for a refund because I had lost the receipt.","options":["turned up","turned over","turned off","turned down"],"correct":3,"answer":"turned down","vi":"Cửa hàng đã từ chối yêu cầu hoàn tiền của tôi vì tôi làm mất hóa đơn.","explanation":"<b>Turn down</b> means to refuse a request or offer. <b>Turn up</b> is to arrive or increase, <b>turn over</b> is to flip something, and <b>turn off</b> is to switch off."},{"id":"gv-kc-03-16","level":"kc","focus":"phrasal-verb","q":"Please don't ______ the money I owe you in front of my parents.","options":["bring back","bring about","bring up","bring in"],"correct":2,"answer":"bring up","vi":"Làm ơn đừng nhắc đến số tiền tớ nợ cậu trước mặt bố mẹ tớ.","explanation":"<b>Bring up</b> means to mention a subject. <b>Bring back</b> is to return something, <b>bring about</b> is to cause, and <b>bring in</b> is to introduce or earn."},{"id":"gv-kc-03-17","level":"kc","focus":"modal","q":"Nam paid full price in the shop. He ______ have bought the phone online, where the same model is much cheaper.","options":["must","should","can't","needn't"],"correct":1,"answer":"should","vi":"Nam đã trả nguyên giá ở cửa hàng. Lẽ ra cậu ấy nên mua điện thoại trên mạng, nơi cùng mẫu đó rẻ hơn nhiều.","explanation":"<b>Should have + past participle</b> criticises a past action that was not done. <b>Must have</b> is a deduction, <b>can't have</b> a negative deduction, and <b>needn't have</b> means it was unnecessary but done."},{"id":"gv-kc-03-18","level":"kc","focus":"modal","q":"Lan ______ have spent much money at the market - she only bought a keyring.","options":["can't","must","should","needn't"],"correct":0,"answer":"can't","vi":"Lan không thể nào tiêu nhiều tiền ở chợ được - cô ấy chỉ mua một cái móc khóa.","explanation":"<b>Can't have + past participle</b> says the speaker is sure something did NOT happen. <b>Must have</b> is a positive deduction, <b>should have</b> gives criticism, and <b>needn't have</b> means something was done unnecessarily."},{"id":"gv-kc-03-19","level":"kc","focus":"relative","q":"The girl ______ phone was stolen on the bus reported it to the police.","options":["who","which","whom","whose"],"correct":3,"answer":"whose","vi":"Cô gái có điện thoại bị lấy cắp trên xe buýt đã báo cảnh sát.","explanation":"<b>Whose</b> shows possession (the girl's phone). <b>Who</b> and <b>whom</b> replace a person, and <b>which</b> replaces a thing, but none of them can stand before a noun like 'phone'."},{"id":"gv-kc-03-20","level":"kc","focus":"relative","q":"The shop ______ I bought my headphones has closed down.","options":["which","that","where","whose"],"correct":2,"answer":"where","vi":"Cửa hàng nơi tôi mua tai nghe đã đóng cửa rồi.","explanation":"<b>Where</b> replaces 'in the shop' - a place with a full clause after it. <b>Which</b> or <b>that</b> would need a preposition ('from which'), and <b>whose</b> shows possession."},{"id":"gv-kc-03-21","level":"kc","focus":"article-quantifier","q":"There isn't ______ time left before the sale ends, so hurry up.","options":["many","much","a few","few"],"correct":1,"answer":"much","vi":"Không còn nhiều thời gian trước khi đợt giảm giá kết thúc, nên nhanh lên.","explanation":"<b>Time</b> is uncountable, so a negative sentence takes <b>much</b>; <b>many</b>, <b>a few</b> and <b>few</b> go with plural countable nouns."},{"id":"gv-kc-03-22","level":"kc","focus":"gerund-infinitive","q":"Don't forget ______ your phone before the match; you'll want to take photos.","options":["to charge","charging","charge","to charging"],"correct":0,"answer":"to charge","vi":"Đừng quên sạc điện thoại trước trận đấu; cậu sẽ muốn chụp ảnh đấy.","explanation":"<b>Forget to do</b> refers to a task you need to do; <b>forget doing</b> means having no memory of something already done, and the bare form and 'to charging' are ungrammatical here."},{"id":"gv-kc-03-23","level":"kc","focus":"linking","q":"The tickets were quite expensive; ______, the stadium was completely full.","options":["therefore","because","although","however"],"correct":3,"answer":"however","vi":"Vé khá đắt; tuy nhiên, sân vận động vẫn chật kín.","explanation":"Two contrasting ideas joined with a semicolon and a comma need the adverb <b>however</b>. <b>Therefore</b> shows result, and <b>because</b> and <b>although</b> are conjunctions that cannot sit between a semicolon and a comma."},{"id":"gv-kc-03-24","level":"kc","focus":"conditional","q":"If I ______ so much on clothes last month, I could buy those trainers now.","options":["didn't spend","haven't spent","hadn't spent","wouldn't spend"],"correct":2,"answer":"hadn't spent","vi":"Nếu tháng trước tôi không tiêu quá nhiều vào quần áo thì bây giờ tôi đã có thể mua đôi giày thể thao đó.","explanation":"A mixed conditional: an unreal past condition (<b>last month</b>) takes the past perfect <b>hadn't spent</b>, with a present result (<b>could buy ... now</b>)."},{"id":"gv-kc-03-25","level":"kc","focus":"inversion","q":"Only after the final whistle ______ how tired he was.","options":["Nam realised","did Nam realise","Nam did realise","realised Nam"],"correct":1,"answer":"did Nam realise","vi":"Chỉ sau tiếng còi kết thúc Nam mới nhận ra mình mệt đến thế nào.","explanation":"After <b>Only after ...</b> at the start of a sentence, the subject and auxiliary are inverted: <b>did Nam realise</b>."},{"id":"gv-kc-04-1","level":"kc","focus":"tense","q":"Grandma ______ in this village since she was a little girl.","options":["lives","has lived","lived","is living"],"correct":1,"answer":"has lived","vi":"Bà nội đã sống ở ngôi làng này từ khi còn là một cô bé.","explanation":"<b>Since</b> + a past point in time needs the present perfect: <b>has lived</b> (she started then and still lives there)."},{"id":"gv-kc-04-2","level":"kc","focus":"word-choice","q":"Although she had made lots of new friends at the summer camp, Lan still felt ______ and kept talking about her mum’s cooking and her own little bedroom.","options":["homesick","lonely","nostalgic","bored"],"correct":0,"answer":"homesick","vi":"Dù đã có nhiều bạn mới ở trại hè, Lan vẫn thấy nhớ nhà và cứ nhắc mãi về món mẹ nấu và căn phòng nhỏ của mình.","explanation":"<b>Homesick</b> = sad because you are away from home and miss it, which is why she keeps talking about home. <b>Lonely</b> = sad because you have no friends, <b>nostalgic</b> = missing the past, and <b>bored</b> does not explain missing her mum’s cooking."},{"id":"gv-kc-04-3","level":"kc","focus":"collocation","q":"The forecast says there will be ______ rain all weekend, so the picnic in the forest is cancelled.","options":["strong","hard","heavy","big"],"correct":2,"answer":"heavy","vi":"Dự báo nói cuối tuần sẽ mưa to suốt, nên buổi dã ngoại trong rừng bị hủy.","explanation":"English says <b>heavy rain</b> (also heavy snow, heavy traffic). <b>Strong</b> goes with wind, not rain; <b>hard</b> and <b>big</b> do not collocate with 'rain'."},{"id":"gv-kc-04-4","level":"kc","focus":"phrasal-verb","q":"We ______ for the mountains at five in the morning to avoid the traffic.","options":["set up","set about","set down","set off"],"correct":3,"answer":"set off","vi":"Chúng tôi lên đường đi lên núi lúc năm giờ sáng để tránh kẹt xe.","explanation":"<b>Set off</b> = start a journey. <b>Set up</b> = establish, <b>set about</b> = begin a task, <b>set down</b> = put something down."},{"id":"gv-kc-04-5","level":"kc","focus":"modal","q":"Nam: I saw Lan at the hospital yesterday. / Hoa: You ______ her — she has been in Hà Nội all week.","options":["can't have seen","mustn't have seen","shouldn't have seen","needn't have seen"],"correct":0,"answer":"can't have seen","vi":"Nam: Hôm qua tớ thấy Lan ở bệnh viện. / Hoa: Cậu không thể nào thấy cô ấy được — cả tuần nay cô ấy ở Hà Nội mà.","explanation":"<b>Can't have + past participle</b> says something in the past was impossible. <b>Mustn't have</b> is not used for deduction; <b>shouldn't have</b> = it was wrong to; <b>needn't have</b> = it was unnecessary."},{"id":"gv-kc-04-6","level":"kc","focus":"idiom","q":"Tickets for the island boat tour are ______ — book now or you will miss out.","options":["burning the midnight oil","selling like hot cakes","raining cats and dogs","going the extra mile"],"correct":1,"answer":"selling like hot cakes","vi":"Vé tour thuyền ra đảo đang bán đắt như tôm tươi — đặt ngay kẻo hết.","explanation":"<b>Sell like hot cakes</b> = sell very quickly in large numbers. <b>Burn the midnight oil</b> = work late at night, <b>rain cats and dogs</b> = rain heavily, <b>go the extra mile</b> = make extra effort."},{"id":"gv-kc-04-7","level":"kc","focus":"relative","q":"The dentist to ______ my mother goes has moved her clinic to District 3.","options":["who","whose","whom","which"],"correct":2,"answer":"whom","vi":"Nha sĩ mà mẹ tôi hay đến khám đã chuyển phòng khám sang Quận 3.","explanation":"After a preposition (<b>to</b>) the relative pronoun must be the object form <b>whom</b>: ‘to whom my mother goes’. <b>Who</b> is the subject form and cannot follow a preposition, <b>whose</b> needs a noun after it, and <b>which</b> is for things."},{"id":"gv-kc-04-8","level":"kc","focus":"word-choice","q":"Mum was ______ to hear that it was only a cold and not the flu.","options":["relaxed","comfortable","peaceful","relieved"],"correct":3,"answer":"relieved","vi":"Mẹ nhẹ cả người khi nghe đó chỉ là cảm lạnh chứ không phải cúm.","explanation":"<b>Relieved</b> = happy because a worry has gone. <b>Relaxed</b>, <b>comfortable</b> and <b>peaceful</b> describe a calm state, not the feeling of a worry disappearing, and are not used with 'to hear that'."},{"id":"gv-kc-04-9","level":"kc","focus":"preposition","q":"My uncle has suffered ______ back pain for years, so he sees a doctor every month.","options":["from","of","with","by"],"correct":0,"answer":"from","vi":"Chú tôi bị đau lưng nhiều năm nay nên tháng nào cũng đi khám bác sĩ.","explanation":"The verb <b>suffer</b> takes the preposition <b>from</b> when it means to have an illness or a pain."},{"id":"gv-kc-04-10","level":"kc","focus":"tense","q":"This time next week we ______ on a beach in Phú Quốc.","options":["lie","are lying","will be lying","have been lying"],"correct":2,"answer":"will be lying","vi":"Giờ này tuần sau chúng tôi sẽ đang nằm dài trên bãi biển ở Phú Quốc.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, so the future continuous <b>will be lying</b> is needed."},{"id":"gv-kc-04-11","level":"kc","focus":"article-quantifier","q":"There's ______ time before the flight, so let's have a coffee.","options":["a few","a little","few","many"],"correct":1,"answer":"a little","vi":"Còn một chút thời gian trước chuyến bay, nên mình đi uống cà phê đi.","explanation":"<b>Time</b> is uncountable, so <b>a little</b> (= some). <b>A few</b> and <b>many</b> go with countable nouns, and <b>few</b> means 'almost none', which would not fit 'let's have a coffee'."},{"id":"gv-kc-04-12","level":"kc","focus":"collocation","q":"I would like to ______ an appointment with Dr Hùng for tomorrow morning, please.","options":["do","take","put","make"],"correct":3,"answer":"make","vi":"Tôi muốn đặt lịch hẹn với bác sĩ Hùng vào sáng mai ạ.","explanation":"You <b>make</b> an appointment (also make a booking, make a decision). <b>Do</b>, <b>take</b> and <b>put</b> do not collocate with 'appointment'."},{"id":"gv-kc-04-13","level":"kc","focus":"word-choice","q":"Minh was ______ when the doctor told him he could not play football for a month.","options":["disappointed","ashamed","amused","grateful"],"correct":0,"answer":"disappointed","vi":"Minh thất vọng khi bác sĩ bảo cậu không được đá bóng trong một tháng.","explanation":"<b>Disappointed</b> = sad because something you hoped for will not happen. <b>Ashamed</b> = feeling guilty, <b>amused</b> = finding something funny, <b>grateful</b> = thankful — none of them fit bad news."},{"id":"gv-kc-04-14","level":"kc","focus":"conditional","q":"If I ______ you, I would see a doctor about that cough.","options":["am","were","had been","would be"],"correct":1,"answer":"were","vi":"Nếu tớ là cậu, tớ sẽ đi khám bác sĩ về cơn ho đó.","explanation":"Second conditional (an imaginary present): <b>if + past simple</b>, and 'If I <b>were</b> you' is the fixed form for giving advice."},{"id":"gv-kc-04-15","level":"kc","focus":"phrasal-verb","q":"We ______ petrol halfway to the beach and had to push the car to a garage.","options":["ran into","ran after","ran out of","ran over"],"correct":2,"answer":"ran out of","vi":"Chúng tôi hết xăng giữa đường ra biển và phải đẩy xe đến tiệm sửa.","explanation":"<b>Run out of</b> = have no more of something. <b>Run into</b> = meet by chance or crash into, <b>run after</b> = chase, <b>run over</b> = hit with a vehicle."},{"id":"gv-kc-04-16","level":"kc","focus":"linking","q":"The weather in Sa Pa was terrible all week; ______, we still had a wonderful holiday.","options":["therefore","moreover","otherwise","however"],"correct":3,"answer":"however","vi":"Thời tiết ở Sa Pa tệ suốt cả tuần; tuy nhiên, chúng tôi vẫn có một kỳ nghỉ tuyệt vời.","explanation":"The two ideas contrast (bad weather / great holiday), so <b>however</b>. <b>Therefore</b> shows a result, <b>moreover</b> adds a similar point, <b>otherwise</b> = if not."},{"id":"gv-kc-04-17","level":"kc","focus":"word-choice","q":"Hoa felt ______ when she realised she had been following the wrong tour group for ten minutes.","options":["frightened","embarrassed","delighted","proud"],"correct":1,"answer":"embarrassed","vi":"Hoa thấy xấu hổ khi nhận ra mình đã đi theo nhầm đoàn du lịch suốt mười phút.","explanation":"<b>Embarrassed</b> = ashamed and uncomfortable because of a silly mistake. <b>Frightened</b> = scared, and <b>delighted</b> and <b>proud</b> are positive feelings that do not fit a mistake."},{"id":"gv-kc-04-18","level":"kc","focus":"passive","q":"Thousands of young trees ______ in the national park every year by student volunteers.","options":["are planted","are planting","plant","have planted"],"correct":0,"answer":"are planted","vi":"Hàng nghìn cây non được trồng trong vườn quốc gia mỗi năm bởi các tình nguyện viên học sinh.","explanation":"The trees receive the action and the agent follows <b>by</b>, so the sentence is passive: <b>are planted</b>. The active forms would make the trees do the planting."},{"id":"gv-kc-04-19","level":"kc","focus":"idiom","q":"The doctor went on television to ______ about the rumours that the new vaccine was dangerous.","options":["hit the nail on the head","turn over a new leaf","break the ice","set the record straight"],"correct":3,"answer":"set the record straight","vi":"Bác sĩ lên truyền hình để làm rõ sự thật về những tin đồn rằng vắc-xin mới nguy hiểm.","explanation":"<b>Set the record straight</b> = tell the true facts after false ones have spread. <b>Hit the nail on the head</b> = say exactly the right thing, <b>turn over a new leaf</b> = start behaving better, <b>break the ice</b> = make people feel relaxed."},{"id":"gv-kc-04-20","level":"kc","focus":"gerund-infinitive","q":"I am really looking forward to ______ my cousins in Huế this summer.","options":["see","to see","seeing","to seeing"],"correct":2,"answer":"seeing","vi":"Tớ rất mong được gặp các anh chị em họ ở Huế hè này.","explanation":"In <b>look forward to</b>, 'to' is a preposition, so it is followed by a gerund: <b>seeing</b>, never the infinitive."},{"id":"gv-kc-04-21","level":"kc","focus":"reported","q":"Lan asked me ______ on holiday that summer.","options":["where I was going","where was I going","where am I going","where I am going"],"correct":0,"answer":"where I was going","vi":"Lan hỏi tôi sẽ đi nghỉ ở đâu vào mùa hè năm đó.","explanation":"A reported question keeps statement word order (subject before verb) and shifts the tense back: <b>where I was going</b>."},{"id":"gv-kc-04-22","level":"kc","focus":"collocation","q":"The doctor asked me to ______ a deep breath and hold it for five seconds.","options":["make","take","do","give"],"correct":1,"answer":"take","vi":"Bác sĩ bảo tôi hít một hơi thật sâu và giữ trong năm giây.","explanation":"The collocation is <b>take a (deep) breath</b>. <b>Make</b>, <b>do</b> and <b>give</b> are not used with 'breath' in this meaning."},{"id":"gv-kc-04-23","level":"kc","focus":"word-choice","q":"Our tour guide stayed ______ even when the bus broke down in the rain, joking with everyone until help came.","options":["anxious","jealous","cheerful","hopeless"],"correct":2,"answer":"cheerful","vi":"Hướng dẫn viên của chúng tôi vẫn vui vẻ ngay cả khi xe buýt hỏng giữa trời mưa, đùa với mọi người cho tới khi có người tới giúp.","explanation":"<b>Cheerful</b> = happy and in a good mood, which matches 'joking with everyone'. <b>Anxious</b> and <b>hopeless</b> are negative feelings, and <b>jealous</b> does not fit the situation."},{"id":"gv-kc-04-24","level":"kc","focus":"comparison","q":"The mountains were ______ than we expected, so we bought warm jackets at the market.","options":["as cold","far coldest","more cold","far colder"],"correct":3,"answer":"far colder","vi":"Trên núi lạnh hơn nhiều so với chúng tôi tưởng, nên chúng tôi mua áo khoác ấm ở chợ.","explanation":"<b>Than</b> needs a comparative: <b>far colder</b> ('far' = much). <b>Coldest</b> is a superlative, <b>as cold</b> needs 'as' not 'than', and a one-syllable adjective takes <b>-er</b>, not 'more'."},{"id":"gv-kc-04-25","level":"kc","focus":"tense","q":"Lan: You look exhausted! / Nam: Yes, I ______ back from Đà Lạt — the bus took eight hours.","options":["have just come","had just come","just come","am just coming"],"correct":0,"answer":"have just come","vi":"Lan: Trông cậu mệt quá! / Nam: Ừ, tớ vừa mới về từ Đà Lạt — xe buýt đi mất tám tiếng.","explanation":"<b>Just</b> + a recent action with a present result ('you look exhausted') takes the present perfect: <b>have just come</b>. <b>Had just come</b> needs another past event to refer to."},{"id":"gv-kc-05-1","level":"kc","focus":"tense","q":"Grandma ______ the sticky rice for Tết right now, so the kitchen is full of steam.","options":["steams","is steaming","has steamed","steamed"],"correct":1,"answer":"is steaming","vi":"Bà đang đồ xôi cho Tết ngay lúc này nên bếp đầy hơi nước.","explanation":"<b>Right now</b> points to an action in progress at the moment of speaking, so the present continuous <b>is steaming</b> is needed."},{"id":"gv-kc-05-2","level":"kc","focus":"word-choice","q":"Vegetables are cheap at the village market; a whole basket of tomatoes only ______ 20,000 dong.","options":["costs","pays","spends","charges"],"correct":0,"answer":"costs","vi":"Rau ở chợ làng rất rẻ; cả một rổ cà chua chỉ có giá 20.000 đồng.","explanation":"A thing <b>costs</b> an amount of money; people <b>pay</b> or <b>spend</b> money, and a seller <b>charges</b> a price."},{"id":"gv-kc-05-3","level":"kc","focus":"idiom","q":"Lan: The recipe says 200 grams of sugar, but you used 210. / Nam: Let's not ______ — ten grams won't change the taste.","options":["pull strings","cut corners","split hairs","beat around the bush"],"correct":2,"answer":"split hairs","vi":"Lan: Công thức ghi 200 gam đường mà cậu cho 210. / Nam: Đừng bắt bẻ từng li từng tí — mười gam chẳng làm đổi vị đâu.","explanation":"To <b>split hairs</b> is to argue about tiny, unimportant differences. <b>Cut corners</b> means do something cheaply or carelessly, <b>pull strings</b> means use influence, and <b>beat around the bush</b> means avoid the main point."},{"id":"gv-kc-05-4","level":"kc","focus":"collocation","q":"Could you ______ the table before the guests arrive for the New Year dinner?","options":["make","put","do","lay"],"correct":3,"answer":"lay","vi":"Con dọn bàn ăn trước khi khách đến dự bữa tối năm mới được không?","explanation":"The fixed collocation is <b>lay (or set) the table</b>, meaning put out the plates and cutlery; <b>make</b>, <b>put</b> and <b>do</b> do not collocate with <b>the table</b> in this sense."},{"id":"gv-kc-05-5","level":"kc","focus":"relative","q":"Our class won the school football final, ______ everyone because we had lost every practice match.","options":["that surprised","which surprised","what surprised","it surprised"],"correct":1,"answer":"which surprised","vi":"Lớp mình đã thắng trận chung kết bóng đá của trường, điều đó làm mọi người bất ngờ vì bọn mình thua hết các trận giao hữu.","explanation":"After a comma, <b>which</b> can refer back to the whole previous clause (the fact that we won). <b>That</b> cannot follow a comma in a non-defining clause, <b>what</b> means 'the thing that' and cannot add a comment to a clause, and <b>it</b> would need a new sentence or a conjunction."},{"id":"gv-kc-05-6","level":"kc","focus":"phrasal-verb","q":"I can't ______ the barking from the neighbours' dogs any longer; it goes on all night.","options":["put off","put up with","put out","put away"],"correct":1,"answer":"put up with","vi":"Tôi không thể chịu đựng tiếng sủa của mấy con chó nhà hàng xóm thêm nữa; nó kéo dài suốt đêm.","explanation":"<b>Put up with</b> means tolerate. <b>Put off</b> is postpone, <b>put out</b> is extinguish, and <b>put away</b> is tidy something into its place."},{"id":"gv-kc-05-7","level":"kc","focus":"word-choice","q":"The restaurant added a ten per cent service ______ to our bill, so the meal cost more than we expected.","options":["price","fare","cost","charge"],"correct":3,"answer":"charge","vi":"Nhà hàng cộng thêm 10% phí phục vụ vào hóa đơn nên bữa ăn đắt hơn chúng tôi tưởng.","explanation":"A <b>charge</b> is an amount asked for a service, as in <b>service charge</b>; a <b>fare</b> is paid for transport, a <b>price</b> is what goods are sold for, and <b>cost</b> is what you spend overall."},{"id":"gv-kc-05-8","level":"kc","focus":"tense","q":"By the time we reached the market, the fishmonger ______ every last prawn.","options":["has sold","sold","had sold","was selling"],"correct":2,"answer":"had sold","vi":"Lúc chúng tôi tới chợ thì người bán cá đã bán hết sạch tôm.","explanation":"The selling finished <b>before</b> another past action (we reached the market), so the past perfect <b>had sold</b> is required."},{"id":"gv-kc-05-9","level":"kc","focus":"article-quantifier","q":"There's only ______ milk left in the fridge, so I can't make pancakes for everyone.","options":["a little","a few","many","few"],"correct":0,"answer":"a little","vi":"Trong tủ lạnh chỉ còn một ít sữa nên mình không làm bánh kếp cho cả nhà được.","explanation":"<b>Milk</b> is uncountable, so it takes <b>a little</b>; <b>a few</b>, <b>few</b> and <b>many</b> go with plural countable nouns."},{"id":"gv-kc-05-10","level":"kc","focus":"modal","q":"You ______ feed the goldfish more than once a day, or it will get sick.","options":["needn't","mustn't","don't have to","might not"],"correct":1,"answer":"mustn't","vi":"Con không được cho cá vàng ăn quá một lần mỗi ngày, nếu không nó sẽ bị bệnh.","explanation":"<b>Mustn't</b> expresses prohibition — it is forbidden because of the harm. <b>Needn't</b> and <b>don't have to</b> only say something is not necessary, and <b>might not</b> expresses possibility."},{"id":"gv-kc-05-11","level":"kc","focus":"word-choice","q":"We ______ nearly all our pocket money on snacks at the Mid-Autumn fair.","options":["paid","bought","spent","cost"],"correct":2,"answer":"spent","vi":"Chúng tôi tiêu gần hết tiền tiêu vặt vào đồ ăn vặt ở hội chợ Trung thu.","explanation":"You <b>spend money on</b> something; you <b>pay for</b> something, you <b>buy</b> goods rather than money, and things <b>cost</b> money."},{"id":"gv-kc-05-12","level":"kc","focus":"question-tag","q":"Lan: Your parrot can say a few words, ______? / Nam: Yes, it says 'hello' every morning.","options":["can it","isn't it","doesn't it","can't it"],"correct":3,"answer":"can't it","vi":"Lan: Con vẹt của cậu nói được vài từ, phải không? / Nam: Ừ, sáng nào nó cũng nói 'hello'.","explanation":"A positive statement takes a negative tag with the same auxiliary: <b>can</b> → <b>can't it</b>."},{"id":"gv-kc-05-13","level":"kc","focus":"collocation","q":"The vet told us to ______ the puppy a bath every two weeks, not every day.","options":["give","take","make","do"],"correct":0,"answer":"give","vi":"Bác sĩ thú y dặn chúng tôi tắm cho chó con hai tuần một lần, chứ không phải mỗi ngày.","explanation":"You <b>give</b> an animal (or a child) a bath; you <b>take</b> or <b>have</b> a bath yourself. <b>Make</b> and <b>do</b> do not collocate with <b>a bath</b>."},{"id":"gv-kc-05-14","level":"kc","focus":"conditional","q":"If it ______ so heavily, the village wouldn't have called off the boat race.","options":["didn't rain","hadn't rained","wouldn't rain","doesn't rain"],"correct":1,"answer":"hadn't rained","vi":"Nếu trời không mưa to như vậy thì làng đã không hủy cuộc đua thuyền.","explanation":"A past event that did not happen takes the third conditional: <b>if + past perfect</b> (<b>hadn't rained</b>) with <b>would have + past participle</b> in the main clause."},{"id":"gv-kc-05-15","level":"kc","focus":"linking","q":"The soup smelt wonderful; ______, it was far too salty to eat.","options":["therefore","moreover","however","because"],"correct":2,"answer":"however","vi":"Món canh thơm tuyệt; tuy nhiên, nó mặn quá không ăn nổi.","explanation":"The second clause contrasts with the first, so <b>however</b> is needed; <b>therefore</b> shows a result, <b>moreover</b> adds a similar point, and <b>because</b> gives a reason."},{"id":"gv-kc-05-16","level":"kc","focus":"word-choice","q":"The pet shop gave us a small ______ because the cage had a scratch on one side.","options":["bargain","sale","bonus","discount"],"correct":3,"answer":"discount","vi":"Cửa hàng thú cưng giảm giá một chút cho chúng tôi vì cái lồng bị xước một bên.","explanation":"A <b>discount</b> is an amount taken off the price. A <b>bargain</b> is something bought cheaply, a <b>sale</b> is a period of lower prices, and a <b>bonus</b> is extra money given to a worker."},{"id":"gv-kc-05-17","level":"kc","focus":"gerund-infinitive","q":"Don't forget ______ the hamster's cage before we leave for the festival.","options":["to clean","cleaning","clean","to cleaning"],"correct":0,"answer":"to clean","vi":"Đừng quên dọn lồng chuột hamster trước khi chúng ta đi lễ hội nhé.","explanation":"<b>Forget to do</b> refers to a task that still needs doing; <b>forget doing</b> means not remember something already done."},{"id":"gv-kc-05-18","level":"kc","focus":"phrasal-verb","q":"It took Mai several weeks to ______ the loss of her old cat.","options":["get by","get along","get over","get up"],"correct":2,"answer":"get over","vi":"Mai phải mất mấy tuần mới nguôi ngoai nỗi mất con mèo già của mình.","explanation":"<b>Get over</b> means recover from an illness or a sad experience. <b>Get by</b> is manage with little money, <b>get along</b> is have a good relationship, and <b>get up</b> is rise from bed."},{"id":"gv-kc-05-19","level":"kc","focus":"agreement","q":"Neither the dog nor the cats ______ allowed in the kitchen while Mum is cooking.","options":["is","are","was","has been"],"correct":1,"answer":"are","vi":"Cả con chó lẫn mấy con mèo đều không được vào bếp khi mẹ đang nấu ăn.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, <b>the cats</b>, so the plural present <b>are</b> is correct."},{"id":"gv-kc-05-20","level":"kc","focus":"idiom","q":"You should ______ if the butcher tries to charge more than the price on the sign.","options":["stand your ground","hold your tongue","pull your weight","mind your step"],"correct":0,"answer":"stand your ground","vi":"Bạn nên giữ vững lập trường nếu người bán thịt cố tính giá cao hơn giá ghi trên bảng.","explanation":"<b>Stand your ground</b> means refuse to give in. <b>Hold your tongue</b> is stay silent, <b>pull your weight</b> is do your share of the work, and <b>mind your step</b> is be careful where you walk."},{"id":"gv-kc-05-21","level":"kc","focus":"tense","q":"My uncle ______ dogs since he was a little boy, and he still has three.","options":["keeps","kept","is keeping","has kept"],"correct":3,"answer":"has kept","vi":"Chú tôi nuôi chó từ hồi còn bé, và giờ chú vẫn nuôi ba con.","explanation":"<b>Since</b> + a past starting point, for a situation that continues up to now, takes the present perfect: <b>has kept</b>."},{"id":"gv-kc-05-22","level":"kc","focus":"participle","q":"______ the mooncakes, Mai carried a plate of them next door for the neighbours.","options":["Baking","Having baked","Baked","To bake"],"correct":1,"answer":"Having baked","vi":"Nướng xong bánh trung thu, Mai bưng một đĩa sang nhà hàng xóm.","explanation":"<b>Having + past participle</b> shows the first action was finished before the second; <b>baking</b> would suggest the two happened at the same time, and <b>baked</b> would make Mai the thing that was baked."},{"id":"gv-kc-05-23","level":"kc","focus":"pronoun","q":"The two puppies love chasing ______ around the garden all afternoon.","options":["themselves","itself","each other","another"],"correct":2,"answer":"each other","vi":"Hai chú chó con thích rượt đuổi nhau quanh vườn suốt buổi chiều.","explanation":"<b>Each other</b> shows the action goes both ways between two subjects; <b>themselves</b> would mean each puppy chases its own self."},{"id":"gv-kc-05-24","level":"kc","focus":"word-choice","q":"My aunt ______ about 500,000 dong a month by selling homemade fish sauce online.","options":["earns","wins","gains","charges"],"correct":0,"answer":"earns","vi":"Dì tôi kiếm được khoảng 500.000 đồng một tháng nhờ bán nước mắm nhà làm trên mạng.","explanation":"You <b>earn</b> money by working or selling; you <b>win</b> a prize, <b>gain</b> experience or weight, and <b>charge</b> a customer a price."},{"id":"gv-kc-05-25","level":"kc","focus":"collocation","q":"The whole village ______ part in the lantern parade every autumn.","options":["makes","does","gets","takes"],"correct":3,"answer":"takes","vi":"Cả làng đều tham gia rước đèn mỗi mùa thu.","explanation":"The fixed collocation is <b>take part in</b> (= join an activity); <b>make</b>, <b>do</b> and <b>get</b> do not combine with <b>part in</b>."},{"id":"gv-kc-06-1","level":"kc","focus":"tense","q":"We ______ football in the park when it suddenly started to pour.","options":["played","were playing","have played","had played"],"correct":1,"answer":"were playing","vi":"Chúng tôi đang chơi bóng đá trong công viên thì trời bỗng đổ mưa như trút.","explanation":"A longer action in progress that is interrupted by a shorter past action (<b>started</b>) takes the past continuous: <b>were playing</b>."},{"id":"gv-kc-06-2","level":"kc","focus":"word-choice","q":"We moved to a quiet ______ near the river, where all the neighbours know each other.","options":["region","territory","neighbourhood","zone"],"correct":2,"answer":"neighbourhood","vi":"Chúng tôi chuyển đến một khu dân cư yên tĩnh gần bờ sông, nơi hàng xóm đều quen biết nhau.","explanation":"A <b>neighbourhood</b> is the small residential area around your home. A <b>region</b> or <b>territory</b> is a large part of a country, and a <b>zone</b> is an area set aside for a purpose (a no-parking zone)."},{"id":"gv-kc-06-3","level":"kc","focus":"collocation","q":"Please ______ attention to the safety rules before you start the chemistry experiment.","options":["give","take","pay","put"],"correct":2,"answer":"pay","vi":"Hãy chú ý đến các quy tắc an toàn trước khi bạn bắt đầu thí nghiệm hóa học.","explanation":"The fixed collocation is <b>pay attention (to)</b>. <b>Give</b>, <b>take</b> and <b>put</b> do not combine with attention: we give advice, take notes and put effort into something."},{"id":"gv-kc-06-4","level":"kc","focus":"idiom","q":"Now that Mr Ba is retiring, he wants to ______ and let the younger teachers run the football club.","options":["take a rain check","take the floor","take a stand","take a back seat"],"correct":3,"answer":"take a back seat","vi":"Giờ sắp nghỉ hưu, thầy Ba muốn lui về phía sau và để các giáo viên trẻ điều hành câu lạc bộ bóng đá.","explanation":"To <b>take a back seat</b> is to stop leading and let others take charge. To <b>take the floor</b> is to start speaking, to <b>take a stand</b> is to defend an opinion, and to <b>take a rain check</b> is to postpone an invitation."},{"id":"gv-kc-06-5","level":"kc","focus":"relative","q":"My grandparents still live in the small town ______ my father grew up.","options":["which","whose","who","where"],"correct":3,"answer":"where","vi":"Ông bà tôi vẫn sống ở thị trấn nhỏ nơi bố tôi lớn lên.","explanation":"The relative adverb <b>where</b> replaces 'in the town' and is followed by a full clause (my father grew up). <b>Which</b> would need a preposition (in which) because 'grew up' has no object, and <b>who</b> and <b>whose</b> refer to people."},{"id":"gv-kc-06-6","level":"kc","focus":"phrasal-verb","q":"Lan: How did you ______ that the test was cancelled? / Nam: Our teacher posted it in the class group.","options":["look out","find out","make out","turn out"],"correct":1,"answer":"find out","vi":"Lan: Sao cậu biết được là bài kiểm tra bị hủy? / Nam: Cô giáo đăng trong nhóm lớp.","explanation":"To <b>find out</b> is to discover a fact. <b>Look out</b> means be careful, <b>make out</b> means see or hear with difficulty, and <b>turn out</b> means happen in the end."},{"id":"gv-kc-06-7","level":"kc","focus":"modal","q":"The streets are all wet this morning. It ______ have rained during the night.","options":["can't","should","must","needn't"],"correct":2,"answer":"must","vi":"Sáng nay đường phố ướt hết cả. Chắc hẳn đêm qua trời đã mưa.","explanation":"<b>Must have</b> + past participle expresses a confident conclusion about the past based on evidence (the wet streets). <b>Can't have</b> would mean the opposite, and <b>should</b> and <b>needn't</b> do not express deduction."},{"id":"gv-kc-06-8","level":"kc","focus":"word-choice","q":"The little shelter at the bus ______ outside our school keeps us dry when it rains.","options":["station","terminal","harbour","stop"],"correct":3,"answer":"stop","vi":"Mái che nhỏ ở trạm xe buýt trước cổng trường giúp chúng tôi khỏi bị ướt khi trời mưa.","explanation":"A bus <b>stop</b> is the small roadside place where a bus picks people up. A <b>station</b> or <b>terminal</b> is a large building where many routes start and end, and a <b>harbour</b> is for ships."},{"id":"gv-kc-06-9","level":"kc","focus":"tense","q":"By the time the bus finally came, we ______ for over half an hour.","options":["had waited","waited","have waited","are waiting"],"correct":0,"answer":"had waited","vi":"Đến lúc xe buýt cuối cùng cũng tới, chúng tôi đã đợi hơn nửa tiếng.","explanation":"<b>By the time</b> + past simple points to an action completed before that past moment, which takes the past perfect: <b>had waited</b>."},{"id":"gv-kc-06-10","level":"kc","focus":"article-quantifier","q":"There is ______ traffic on this road in the early morning, so we usually get to school on time.","options":["few","little","a few","many"],"correct":1,"answer":"little","vi":"Sáng sớm đường này rất ít xe cộ, nên chúng tôi thường đến trường đúng giờ.","explanation":"<b>Traffic</b> is uncountable, so it takes <b>little</b> (= not much). <b>Few</b>, <b>a few</b> and <b>many</b> only go with plural countable nouns."},{"id":"gv-kc-06-11","level":"kc","focus":"collocation","q":"Nam usually ______ his homework right after dinner so he can watch TV later.","options":["makes","writes","does","works"],"correct":2,"answer":"does","vi":"Nam thường làm bài tập về nhà ngay sau bữa tối để lát nữa được xem tivi.","explanation":"The fixed collocation is <b>do homework</b>. <b>Make</b> is used for creating things (make a cake, make a decision), and <b>work</b> needs a preposition (work on)."},{"id":"gv-kc-06-12","level":"kc","focus":"conditional","q":"If it ______ so cold today, we would go for a walk along the river.","options":["isn't","hadn't been","wouldn't be","weren't"],"correct":3,"answer":"weren't","vi":"Nếu hôm nay trời không lạnh thế này thì chúng tôi sẽ đi dạo dọc bờ sông.","explanation":"An unreal present situation (it IS cold) takes the second conditional: <b>if</b> + past subjunctive (<b>weren't</b>) with <b>would</b> in the main clause. <b>Hadn't been</b> would refer to the past."},{"id":"gv-kc-06-13","level":"kc","focus":"word-choice","q":"There is a small ______ in the middle of town where people sit and feed the pigeons.","options":["corner","square","yard","block"],"correct":1,"answer":"square","vi":"Có một quảng trường nhỏ ở giữa thị trấn, nơi mọi người ngồi cho bồ câu ăn.","explanation":"A <b>square</b> is an open public space in a town. A <b>yard</b> belongs to a house or school, a <b>block</b> is a group of buildings between streets, and a <b>corner</b> is where two streets meet, not a place to sit."},{"id":"gv-kc-06-14","level":"kc","focus":"phrasal-verb","q":"Our old school bus ______ on the way to the museum, so we arrived an hour late.","options":["broke down","broke up","broke out","made up"],"correct":0,"answer":"broke down","vi":"Chiếc xe buýt cũ của trường bị hỏng giữa đường đến bảo tàng, nên chúng tôi tới muộn một tiếng.","explanation":"A vehicle or machine <b>breaks down</b> when it stops working. <b>Break up</b> is to end a relationship or the school term, <b>break out</b> is to start suddenly (a fire, a war), and <b>make up</b> is to invent a story."},{"id":"gv-kc-06-15","level":"kc","focus":"linking","q":"Lan has practised the piano every day for months; ______, she played beautifully at the school concert.","options":["therefore","however","otherwise","meanwhile"],"correct":0,"answer":"therefore","vi":"Lan đã luyện đàn piano mỗi ngày suốt nhiều tháng; vì vậy, cô ấy chơi rất hay trong buổi hòa nhạc của trường.","explanation":"Playing beautifully is the result of months of practice, so we need <b>therefore</b>. <b>However</b> shows a contrast, <b>otherwise</b> means 'if not', and <b>meanwhile</b> means 'at the same time'."},{"id":"gv-kc-06-16","level":"kc","focus":"tense","q":"Lan: Have you finished your maths homework? / Nam: Not yet. I ______ the last two problems.","options":["don't do","didn't do","hadn't done","haven't done"],"correct":3,"answer":"haven't done","vi":"Lan: Cậu làm xong bài tập toán chưa? / Nam: Chưa. Tớ vẫn chưa làm hai bài cuối.","explanation":"<b>Not yet</b> describes an unfinished action up to now, which takes the present perfect: <b>haven't done</b>. The past simple <b>didn't do</b> would need a finished past time."},{"id":"gv-kc-06-17","level":"kc","focus":"idiom","q":"Before opening a second shop, Mrs Hoa decided to ______ by selling her cakes at the weekend market.","options":["break the ice","test the waters","hit the road","clear the air"],"correct":1,"answer":"test the waters","vi":"Trước khi mở cửa hàng thứ hai, cô Hoa quyết định thăm dò thị trường bằng cách bán bánh ở chợ cuối tuần.","explanation":"To <b>test the waters</b> is to try something in a small way before committing to it. <b>Break the ice</b> is to make people relax when they first meet, <b>hit the road</b> is to set off, and <b>clear the air</b> is to end a misunderstanding."},{"id":"gv-kc-06-18","level":"kc","focus":"word-choice","q":"Turn left at the ______ where Nguyen Trai Street meets Le Loi Street, and the school is on your right.","options":["junction","lane","pavement","bridge"],"correct":0,"answer":"junction","vi":"Rẽ trái ở ngã tư nơi đường Nguyễn Trãi giao với đường Lê Lợi, trường ở bên tay phải.","explanation":"A <b>junction</b> is the place where two roads meet. A <b>lane</b> is a narrow road, the <b>pavement</b> is where people walk beside the road, and a <b>bridge</b> crosses a river or another road."},{"id":"gv-kc-06-19","level":"kc","focus":"modal","q":"Lan: ______ I borrow your ruler for a minute? / Nam: Sure, here you are.","options":["Must","Should","Could","Would"],"correct":2,"answer":"Could","vi":"Lan: Tớ mượn thước của cậu một lát được không? / Nam: Được chứ, đây này.","explanation":"<b>Could I…?</b> is the polite way to ask for permission. <b>Must I</b> asks about obligation, <b>Should I</b> asks for advice, and <b>Would I borrow</b> is not a request."},{"id":"gv-kc-06-20","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your raincoat tomorrow; it looks like a storm is coming.","options":["taking","take","to taking","to take"],"correct":3,"answer":"to take","vi":"Nhớ mang áo mưa ngày mai nhé; có vẻ bão sắp đến rồi.","explanation":"<b>Remember to do</b> means not to forget a task you still have to do. <b>Remember doing</b> refers to a memory of something already done, which does not fit 'tomorrow'."},{"id":"gv-kc-06-21","level":"kc","focus":"relative","q":"The new bridge, ______ opened last month, has cut my journey to school in half.","options":["that","which","where","what"],"correct":1,"answer":"which","vi":"Cây cầu mới, mới thông xe tháng trước, đã rút ngắn quãng đường đến trường của tôi một nửa.","explanation":"A non-defining relative clause (between commas) about a thing takes <b>which</b>; <b>that</b> cannot follow a comma. <b>Where</b> needs a full clause after it, and <b>what</b> is not a relative pronoun."},{"id":"gv-kc-06-22","level":"kc","focus":"collocation","q":"Hurry up, or we'll ______ the school bus again and have to walk!","options":["miss","lose","drop","fail"],"correct":0,"answer":"miss","vi":"Nhanh lên, không thì chúng ta lại lỡ xe buýt của trường và phải đi bộ đấy!","explanation":"You <b>miss</b> a bus, train or plane when you arrive too late for it. <b>Lose the bus</b> is a direct translation that English does not use."},{"id":"gv-kc-06-23","level":"kc","focus":"inversion","q":"______ had we left the house when it began to snow.","options":["No sooner","Not until","Hardly","Only"],"correct":2,"answer":"Hardly","vi":"Chúng tôi vừa mới ra khỏi nhà thì tuyết bắt đầu rơi.","explanation":"<b>Hardly</b> + had + subject + past participle… <b>when</b> is the inverted pattern. <b>No sooner</b> needs <b>than</b>, not <b>when</b>, and <b>Not until</b> and <b>Only</b> do not fit this structure."},{"id":"gv-kc-06-24","level":"kc","focus":"word-choice","q":"Sa Pa is a favourite ______ for tourists who want to see snow in winter.","options":["direction","journey","arrival","destination"],"correct":3,"answer":"destination","vi":"Sa Pa là điểm đến yêu thích của du khách muốn ngắm tuyết vào mùa đông.","explanation":"A <b>destination</b> is the place people travel to. A <b>journey</b> is the trip itself, a <b>direction</b> is the way you go, and an <b>arrival</b> is the act of reaching a place."},{"id":"gv-kc-06-25","level":"kc","focus":"tense","q":"This time next week, we ______ on the beach in Nha Trang instead of sitting in class.","options":["lie","will be lying","are lying","have lain"],"correct":1,"answer":"will be lying","vi":"Giờ này tuần sau, chúng tôi sẽ đang nằm trên bãi biển Nha Trang thay vì ngồi trong lớp.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, which takes the future continuous: <b>will be lying</b>."},{"id":"gv-kc-07-1","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Minh: He ______ for a job interview at the moment, so don't disturb him.","options":["prepares","is preparing","has prepared","prepared"],"correct":1,"answer":"is preparing","vi":"Lan: Nam đâu rồi? / Minh: Bạn ấy đang chuẩn bị cho buổi phỏng vấn xin việc lúc này, nên đừng làm phiền.","explanation":"<b>At the moment</b> signals an action happening right now, so the present continuous <b>is preparing</b> is needed; the simple present, present perfect and past do not describe an ongoing action at the time of speaking."},{"id":"gv-kc-07-2","level":"kc","focus":"word-choice","q":"Our garden party was cancelled because of a sudden ______ that flooded the lawn in minutes.","options":["downpour","drizzle","mist","frost"],"correct":0,"answer":"downpour","vi":"Bữa tiệc ngoài vườn của chúng tôi bị hủy vì một trận mưa như trút bất ngờ làm ngập bãi cỏ chỉ trong vài phút.","explanation":"A <b>downpour</b> is a sudden, very heavy fall of rain — the only option that could flood a lawn in minutes. <b>Drizzle</b> is very light rain, <b>mist</b> is thin fog, and <b>frost</b> is ice on cold surfaces."},{"id":"gv-kc-07-3","level":"kc","focus":"collocation","q":"My brother has to ______ a decision about which career to follow before he finishes school.","options":["do","have","make","get"],"correct":2,"answer":"make","vi":"Anh trai tôi phải đưa ra quyết định về nghề nghiệp sẽ theo đuổi trước khi học xong.","explanation":"The fixed collocation is <b>make a decision</b>. <b>Do</b>, <b>have</b> and <b>get</b> do not combine with <b>decision</b> in this meaning."},{"id":"gv-kc-07-4","level":"kc","focus":"idiom","q":"Nam: Should I take the job in Da Nang or stay here? / Lan: ______ is that you need a steady income, so take it.","options":["The last straw","The tip of the iceberg","The eleventh hour","The bottom line"],"correct":3,"answer":"The bottom line","vi":"Nam: Mình nên nhận việc ở Đà Nẵng hay ở lại đây? / Lan: Điều cốt lõi là cậu cần một nguồn thu nhập ổn định, nên nhận đi.","explanation":"<b>The bottom line</b> means the most important fact that decides a matter. <b>The last straw</b> is the final problem that makes you lose patience, <b>the tip of the iceberg</b> is a small visible part of a bigger problem, and <b>the eleventh hour</b> is the last possible moment."},{"id":"gv-kc-07-5","level":"kc","focus":"phrasal-verb","q":"Lan: Why isn't Minh at school anymore? / Nam: He decided to ______ of school to help his father at the shop.","options":["drop out","drop off","drop in","drop by"],"correct":0,"answer":"drop out","vi":"Lan: Sao Minh không còn đi học nữa? / Nam: Cậu ấy quyết định bỏ học để phụ bố ở cửa hàng.","explanation":"<b>Drop out of</b> school means to leave before finishing. <b>Drop off</b> means to fall asleep or deliver someone, while <b>drop in</b> and <b>drop by</b> mean to pay a short visit — none takes <b>of school</b>."},{"id":"gv-kc-07-6","level":"kc","focus":"modal","q":"You ______ such an expensive present; just coming to my birthday party was enough.","options":["mustn't have bought","can't have bought","needn't have bought","won't have bought"],"correct":2,"answer":"needn't have bought","vi":"Bạn không cần phải mua món quà đắt tiền như vậy đâu; chỉ cần đến dự sinh nhật mình là đủ rồi.","explanation":"<b>Needn't have + past participle</b> says that something was done but was not necessary. <b>Can't have</b> expresses a past deduction, <b>won't have</b> is future perfect, and <b>mustn't have</b> is not used for a past action that was unnecessary."},{"id":"gv-kc-07-7","level":"kc","focus":"relative","q":"Do you remember the year ______ our family first moved to Ho Chi Minh City?","options":["where","whom","which","when"],"correct":3,"answer":"when","vi":"Bạn có nhớ năm mà gia đình chúng ta lần đầu chuyển đến Thành phố Hồ Chí Minh không?","explanation":"<b>When</b> is the relative adverb for a time noun such as <b>the year</b>. <b>Where</b> refers to a place, <b>whom</b> to a person, and <b>which</b> would need a preposition (<b>in which</b>) to follow <b>the year</b>."},{"id":"gv-kc-07-8","level":"kc","focus":"word-choice","q":"Dad drove to work very slowly because of the thick ______ on the road this morning.","options":["hail","thunder","drought","fog"],"correct":3,"answer":"fog","vi":"Sáng nay bố lái xe đi làm rất chậm vì sương mù dày đặc trên đường.","explanation":"<b>Thick fog</b> makes it hard to see, so drivers slow down. <b>Hail</b> is frozen rain, <b>thunder</b> is the sound of a storm, and <b>drought</b> is a long period without rain — none is described as <b>thick</b> on the road."},{"id":"gv-kc-07-9","level":"kc","focus":"tense","q":"By the time we got to Hoa's house, the party ______.","options":["has already started","had already started","was already starting","already starts"],"correct":1,"answer":"had already started","vi":"Lúc chúng tôi đến nhà Hoa thì bữa tiệc đã bắt đầu rồi.","explanation":"<b>By the time + past simple</b> describes an action that was completed before another past action, so the past perfect <b>had already started</b> is required."},{"id":"gv-kc-07-10","level":"kc","focus":"article-quantifier","q":"There isn't ______ milk left in the fridge, so could you buy some on the way home?","options":["much","many","a few","few"],"correct":0,"answer":"much","vi":"Trong tủ lạnh không còn nhiều sữa, nên bạn mua thêm trên đường về nhà được không?","explanation":"<b>Milk</b> is uncountable, so it takes <b>much</b> in a negative sentence. <b>Many</b>, <b>a few</b> and <b>few</b> are only used with plural countable nouns."},{"id":"gv-kc-07-11","level":"kc","focus":"collocation","q":"Put on your coat, or you will ______ a cold waiting for the bus in this wind.","options":["catch","take","hold","bring"],"correct":0,"answer":"catch","vi":"Mặc áo khoác vào đi, không thì bạn sẽ bị cảm lạnh khi đứng đợi xe buýt trong gió này.","explanation":"The fixed collocation is <b>catch a cold</b> (become ill with one). <b>Take</b>, <b>hold</b> and <b>bring</b> do not combine with <b>a cold</b> in this meaning."},{"id":"gv-kc-07-12","level":"kc","focus":"gerund-infinitive","q":"My aunt is used to ______ up early because she runs a stall at the market.","options":["get","to get","got","getting"],"correct":3,"answer":"getting","vi":"Dì tôi đã quen với việc dậy sớm vì dì bán hàng ở chợ.","explanation":"<b>Be used to</b> (= be accustomed to) is followed by a noun or a gerund: <b>used to getting up</b>. The to-infinitive (<b>used to get up</b>) only follows <b>used to</b> without <b>be</b>, when it describes a past habit."},{"id":"gv-kc-07-13","level":"kc","focus":"word-choice","q":"My uncle's farm lost most of its rice this year because of the long ______.","options":["flood","drought","hail","lightning"],"correct":1,"answer":"drought","vi":"Nông trại của chú tôi mất gần hết lúa năm nay vì đợt hạn hán kéo dài.","explanation":"A <b>drought</b> is a long period with no rain, which dries up crops, and it is the only option naturally described as <b>long</b>. A <b>flood</b> is too much water, while <b>hail</b> and <b>lightning</b> are short events in a storm."},{"id":"gv-kc-07-14","level":"kc","focus":"linking","q":"Nam wants to become a doctor, ______ his twin brother dreams of opening a restaurant.","options":["whereas","however","therefore","so that"],"correct":0,"answer":"whereas","vi":"Nam muốn trở thành bác sĩ, trong khi người anh sinh đôi của cậu ấy lại mơ mở một nhà hàng.","explanation":"<b>Whereas</b> is a conjunction that contrasts two clauses in one sentence. <b>However</b> needs a full stop or semicolon before it, <b>therefore</b> shows a result, and <b>so that</b> shows purpose."},{"id":"gv-kc-07-15","level":"kc","focus":"phrasal-verb","q":"Could you ______ my little sister from school today? I have a job interview at three.","options":["drop off","take up","pick up","bring up"],"correct":2,"answer":"pick up","vi":"Hôm nay bạn đón em gái mình ở trường giúp được không? Mình có buổi phỏng vấn xin việc lúc ba giờ.","explanation":"<b>Pick up</b> someone <b>from</b> a place means to collect them. <b>Drop off</b> is the opposite (leave someone <b>at</b> a place), <b>take up</b> means start a hobby, and <b>bring up</b> means raise a child or mention a topic."},{"id":"gv-kc-07-16","level":"kc","focus":"conditional","q":"If I ______ you, I would apply for the job at the new hotel before somebody else does.","options":["am","had been","will be","were"],"correct":3,"answer":"were","vi":"Nếu tôi là bạn, tôi sẽ nộp đơn xin việc ở khách sạn mới trước khi người khác nộp.","explanation":"The second conditional gives advice about an unreal present situation: <b>If I were you, I would...</b>. <b>Am</b> and <b>will be</b> belong to the first conditional, and <b>had been</b> would need <b>would have applied</b>."},{"id":"gv-kc-07-17","level":"kc","focus":"idiom","q":"Lan: I want to save up for a new laptop. / Nam: Then you'll have to ______ and stop buying bubble tea every day.","options":["hold your horses","tighten your belt","keep your chin up","bite your tongue"],"correct":1,"answer":"tighten your belt","vi":"Lan: Mình muốn để dành tiền mua laptop mới. / Nam: Vậy thì cậu phải thắt lưng buộc bụng và ngừng mua trà sữa mỗi ngày.","explanation":"<b>Tighten your belt</b> means to spend less money because you have less of it. <b>Hold your horses</b> means wait, <b>keep your chin up</b> means stay cheerful, and <b>bite your tongue</b> means stop yourself from speaking."},{"id":"gv-kc-07-18","level":"kc","focus":"passive","q":"The invitations for the party ______ to all our classmates yesterday.","options":["sent","have been sent","were sent","are sent"],"correct":2,"answer":"were sent","vi":"Thiệp mời dự tiệc đã được gửi tới tất cả các bạn cùng lớp hôm qua.","explanation":"The invitations receive the action, so the passive is needed, and <b>yesterday</b> fixes the past simple: <b>were sent</b>. <b>Have been sent</b> cannot go with a finished past time, and <b>sent</b> alone is active."},{"id":"gv-kc-07-19","level":"kc","focus":"word-choice","q":"After the rain stopped, a bright ______ stretched across the sky above our house.","options":["thunder","lightning","hail","rainbow"],"correct":3,"answer":"rainbow","vi":"Sau khi mưa tạnh, một chiếc cầu vồng rực rỡ trải dài trên bầu trời phía trên nhà chúng tôi.","explanation":"A <b>rainbow</b> is the coloured arc that appears in the sky after rain. <b>Thunder</b> is a sound, <b>lightning</b> is a sudden flash during a storm, and <b>hail</b> is frozen rain — none <b>stretches across the sky</b> after the rain has stopped."},{"id":"gv-kc-07-20","level":"kc","focus":"reported","q":"Mai said that she ______ her grandparents in the countryside the following weekend.","options":["would visit","will visit","visits","has visited"],"correct":0,"answer":"would visit","vi":"Mai nói rằng cô ấy sẽ về thăm ông bà ở quê vào cuối tuần sau đó.","explanation":"After a past reporting verb (<b>said</b>), <b>will</b> shifts back to <b>would</b>, and <b>the following weekend</b> confirms reported speech. The other options keep a present tense that does not match <b>said</b>."},{"id":"gv-kc-07-21","level":"kc","focus":"collocation","q":"My cousins are going to ______ a party for Grandma's seventieth birthday next month.","options":["make","do","throw","put"],"correct":2,"answer":"throw","vi":"Các anh chị họ của tôi sẽ tổ chức một bữa tiệc mừng sinh nhật lần thứ bảy mươi của bà vào tháng sau.","explanation":"In English you <b>throw</b> (or have/hold) <b>a party</b>. <b>Make a party</b>, <b>do a party</b> and <b>put a party</b> are not English collocations."},{"id":"gv-kc-07-22","level":"kc","focus":"tense","q":"My father ______ at the same bank since he left college, and he still enjoys it.","options":["works","has worked","is working","worked"],"correct":1,"answer":"has worked","vi":"Bố tôi đã làm việc ở cùng một ngân hàng kể từ khi rời trường cao đẳng, và bố vẫn thích công việc đó.","explanation":"<b>Since</b> + a past starting point with a situation that continues to now takes the present perfect: <b>has worked</b>. The simple present, present continuous and past simple do not link a past start to the present."},{"id":"gv-kc-07-23","level":"kc","focus":"preposition","q":"At the class reunion, I finally had time to catch up ______ my old friends.","options":["on","to","at","with"],"correct":3,"answer":"with","vi":"Ở buổi họp lớp, cuối cùng tôi cũng có thời gian hàn huyên với bạn bè cũ.","explanation":"<b>Catch up with</b> someone means to talk to them and find out their news. <b>Catch up on</b> is used with things you missed (work, sleep), and <b>to</b> and <b>at</b> do not follow <b>catch up</b>."},{"id":"gv-kc-07-24","level":"kc","focus":"word-choice","q":"Check the weather ______ before you invite everyone to the beach on Sunday.","options":["forecast","climate","temperature","season"],"correct":0,"answer":"forecast","vi":"Hãy xem dự báo thời tiết trước khi mời mọi người đi biển vào Chủ nhật.","explanation":"A <b>weather forecast</b> is a prediction of the coming weather, which is what you check before planning a trip. <b>Climate</b> is the usual weather of a region over years, <b>temperature</b> is only how hot or cold it is, and <b>season</b> is a part of the year."},{"id":"gv-kc-07-25","level":"kc","focus":"comparison","q":"Living in the city is ______ more expensive than living in our hometown, so I might move back after graduation.","options":["very","too","far","so"],"correct":2,"answer":"far","vi":"Sống ở thành phố đắt đỏ hơn nhiều so với sống ở quê, nên có lẽ tôi sẽ chuyển về sau khi tốt nghiệp.","explanation":"A comparative (<b>more expensive</b>) can be strengthened with <b>far</b>, <b>much</b> or <b>a lot</b>. <b>Very</b>, <b>too</b> and <b>so</b> modify plain adjectives, not comparatives."},{"id":"gv-kc-08-1","level":"kc","focus":"word-choice","q":"Our class ______ shows that we have PE right after lunch on Mondays.","options":["timetable","register","diary","agenda"],"correct":0,"answer":"timetable","vi":"Thời khóa biểu của lớp mình cho thấy thứ Hai có tiết Thể dục ngay sau giờ ăn trưa.","explanation":"A <b>timetable</b> lists when each lesson happens. A <b>register</b> records who is present, a <b>diary</b> is personal, and an <b>agenda</b> is the list of points for a meeting."},{"id":"gv-kc-08-2","level":"kc","focus":"collocation","q":"Lan ______ most of her pocket money on comic books and film magazines.","options":["pays","spends","costs","uses"],"correct":1,"answer":"spends","vi":"Lan tiêu phần lớn tiền tiêu vặt vào truyện tranh và tạp chí điện ảnh.","explanation":"We <b>spend money on</b> something. <b>Pay</b> takes <b>for</b>, <b>cost</b> needs the thing as its subject, and <b>use money on</b> is not a natural collocation."},{"id":"gv-kc-08-3","level":"kc","focus":"tense","q":"By next Friday, Lan ______ all her exam revision, so she can join the camping trip.","options":["finishes","will finish","will have finished","has finished"],"correct":2,"answer":"will have finished","vi":"Đến thứ Sáu tuần sau, Lan sẽ ôn thi xong hết nên có thể tham gia chuyến cắm trại.","explanation":"<b>By + a future time</b> marks an action that will be complete before that point, so we use the future perfect: <b>will have finished</b>. <b>Will finish</b> only says it happens in the future, and the present forms cannot follow <b>by next Friday</b>."},{"id":"gv-kc-08-4","level":"kc","focus":"idiom","q":"The new coach is strict: any player who refuses to ______ will be dropped from the team.","options":["cross the line","draw the line","hold the line","toe the line"],"correct":3,"answer":"toe the line","vi":"Huấn luyện viên mới rất nghiêm: cầu thủ nào không chịu tuân thủ kỷ luật sẽ bị loại khỏi đội.","explanation":"<b>Toe the line</b> means to obey the rules. <b>Cross the line</b> is to go too far, <b>draw the line</b> is to set a limit, and <b>hold the line</b> is to keep a position."},{"id":"gv-kc-08-5","level":"kc","focus":"phrasal-verb","q":"The doctor told Nam to ______ sweets and fizzy drinks before the big race.","options":["cut down on","cut off","cut up","cut across"],"correct":0,"answer":"cut down on","vi":"Bác sĩ bảo Nam giảm bớt kẹo và nước ngọt có ga trước cuộc đua lớn.","explanation":"<b>Cut down on</b> means to reduce the amount of something you eat or use. <b>Cut off</b> means to disconnect, <b>cut up</b> means to chop, and <b>cut across</b> means to take a short way through."},{"id":"gv-kc-08-6","level":"kc","focus":"word-choice","q":"Lan got full ______ in the music quiz because she knew every song.","options":["degrees","grades","marks","levels"],"correct":2,"answer":"marks","vi":"Lan được điểm tối đa trong cuộc thi đố vui âm nhạc vì bạn ấy biết hết mọi bài hát.","explanation":"<b>Full marks</b> is the fixed phrase for the highest possible score. <b>Grades</b> are letters like A or B, a <b>degree</b> is a university qualification, and <b>levels</b> are stages."},{"id":"gv-kc-08-7","level":"kc","focus":"modal","q":"Nam ______ have bought the concert tickets yet — the box office doesn't open until ten.","options":["mustn't","can't","needn't","shouldn't"],"correct":1,"answer":"can't","vi":"Nam không thể nào đã mua vé buổi hòa nhạc được — quầy vé mười giờ mới mở cửa mà.","explanation":"<b>Can't have + past participle</b> says that something was impossible in the past. <b>Needn't have</b> and <b>shouldn't have</b> describe things that actually happened, and <b>mustn't have</b> is not used for deduction."},{"id":"gv-kc-08-8","level":"kc","focus":"collocation","q":"Nam ______ two goals in the final, so his team won the school cup.","options":["made","hit","won","scored"],"correct":3,"answer":"scored","vi":"Nam ghi hai bàn trong trận chung kết nên đội của cậu ấy giành cúp của trường.","explanation":"In football you <b>score a goal</b>. You <b>win</b> a match or a cup, not a goal, and <b>make</b> and <b>hit</b> do not collocate with <b>goal</b>."},{"id":"gv-kc-08-9","level":"kc","focus":"relative","q":"Nam told his mother everything ______ had happened at the football match.","options":["who","which","that","what"],"correct":2,"answer":"that","vi":"Nam kể cho mẹ nghe mọi chuyện đã xảy ra ở trận bóng đá.","explanation":"After <b>everything</b>, <b>all</b> and superlatives, the relative pronoun is <b>that</b>. <b>What</b> cannot follow a noun it refers back to, <b>who</b> is for people, and <b>which</b> is not used after <b>everything</b>."},{"id":"gv-kc-08-10","level":"kc","focus":"word-choice","q":"Lan has to ______ two chapters of history tonight, so she can't come to the cinema.","options":["rehearse","remind","revise","repeat"],"correct":2,"answer":"revise","vi":"Tối nay Lan phải ôn lại hai chương lịch sử nên không đi xem phim được.","explanation":"<b>Revise</b> means to study something again before a test. <b>Rehearse</b> is for practising a performance, <b>remind</b> needs a person as its object, and <b>repeat</b> means to say or do again."},{"id":"gv-kc-08-11","level":"kc","focus":"article-quantifier","q":"There were very ______ people at the early screening, so we got the best seats.","options":["few","little","a few","a little"],"correct":0,"answer":"few","vi":"Có rất ít người ở suất chiếu sớm nên bọn mình được ngồi chỗ đẹp nhất.","explanation":"<b>People</b> is countable, so we use <b>few</b>; <b>little</b> goes with uncountable nouns. <b>Very</b> cannot come before <b>a few</b> or <b>a little</b>."},{"id":"gv-kc-08-12","level":"kc","focus":"tense","q":"Since Nam started spending every evening at the game arcade, he ______ in maths.","options":["falls behind","fell behind","has fallen behind","had fallen behind"],"correct":2,"answer":"has fallen behind","vi":"Từ khi Nam bắt đầu tối nào cũng ở tiệm game, cậu ấy đã bị tụt lại môn toán.","explanation":"<b>Since + a past starting point</b> describes a situation that began in the past and continues now, so the main clause takes the present perfect: <b>has fallen behind</b>."},{"id":"gv-kc-08-13","level":"kc","focus":"gerund-infinitive","q":"Nam remembers ______ his wallet on the shop counter, but now it isn't there.","options":["to leave","leaving","leave","left"],"correct":1,"answer":"leaving","vi":"Nam nhớ là đã để ví trên quầy cửa hàng, nhưng giờ nó không còn ở đó nữa.","explanation":"<b>Remember + -ing</b> refers to a memory of something that happened. <b>Remember + to-infinitive</b> means not forgetting to do a future action."},{"id":"gv-kc-08-14","level":"kc","focus":"idiom","q":"I didn't want to go to the concert, but Lan ______ and I ended up buying a ticket.","options":["pulled my leg","caught my eye","twisted my arm","held my hand"],"correct":2,"answer":"twisted my arm","vi":"Tôi không muốn đi xem hòa nhạc, nhưng Lan cứ nài ép nên cuối cùng tôi cũng mua vé.","explanation":"<b>Twist someone's arm</b> means to persuade someone to do something they don't want to do. <b>Pull someone's leg</b> is to joke, <b>catch someone's eye</b> is to attract attention, and <b>hold someone's hand</b> is to support them closely."},{"id":"gv-kc-08-15","level":"kc","focus":"linking","q":"Set your alarm tonight; ______, you will miss the early bus to the museum.","options":["otherwise","therefore","besides","although"],"correct":0,"answer":"otherwise","vi":"Tối nay nhớ đặt báo thức, nếu không bạn sẽ lỡ chuyến xe buýt sớm đi bảo tàng.","explanation":"<b>Otherwise</b> means 'if you don't do that': no alarm, so you miss the bus. <b>Therefore</b> shows a result, <b>besides</b> adds a point, and <b>although</b> introduces a contrast clause, not a separate sentence."},{"id":"gv-kc-08-16","level":"kc","focus":"word-choice","q":"The school ______ ends next week, so the swimming pool will be full of students.","options":["period","break","lesson","term"],"correct":3,"answer":"term","vi":"Học kỳ sắp kết thúc vào tuần tới nên bể bơi sẽ đầy học sinh.","explanation":"A <b>term</b> is one of the parts a school year is divided into. A <b>period</b> or <b>lesson</b> lasts under an hour, and a <b>break</b> is the time between lessons."},{"id":"gv-kc-08-17","level":"kc","focus":"phrasal-verb","q":"The bookshop has ______ plastic bags, so remember to bring your own.","options":["done up","done away with","done without","done in"],"correct":1,"answer":"done away with","vi":"Hiệu sách đã bỏ hẳn túi ni lông, nên nhớ mang túi của mình theo.","explanation":"<b>Do away with</b> means to get rid of or stop using something. <b>Do up</b> means to fasten or repair, <b>do without</b> means to manage without, and <b>do in</b> means to exhaust."},{"id":"gv-kc-08-18","level":"kc","focus":"conditional","q":"If I ______ more pocket money, I would buy that second-hand guitar.","options":["have","had","would have","have had"],"correct":1,"answer":"had","vi":"Nếu tôi có nhiều tiền tiêu vặt hơn, tôi sẽ mua cây đàn ghi-ta cũ đó.","explanation":"A second conditional (unreal present) takes the past simple in the if-clause and <b>would + verb</b> in the main clause: <b>If I had</b>… I would buy."},{"id":"gv-kc-08-19","level":"kc","focus":"collocation","q":"Lan ______ chess with her grandfather every Sunday afternoon.","options":["plays","does","goes","makes"],"correct":0,"answer":"plays","vi":"Chiều Chủ nhật nào Lan cũng chơi cờ vua với ông.","explanation":"We <b>play</b> games like chess and football. <b>Do</b> goes with activities like yoga or homework, <b>go</b> with -ing sports like swimming, and <b>make</b> does not collocate with games."},{"id":"gv-kc-08-20","level":"kc","focus":"agreement","q":"Either Nam or his sister ______ going to buy the tickets this afternoon.","options":["are","am","be","is"],"correct":3,"answer":"is","vi":"Hoặc Nam hoặc chị của cậu ấy sẽ đi mua vé chiều nay.","explanation":"With <b>either… or</b>, the verb agrees with the nearer subject, <b>his sister</b>, so it is singular: <b>is</b>."},{"id":"gv-kc-08-21","level":"kc","focus":"participle","q":"The novel ______ by our English teacher turned out to be much funnier than I expected.","options":["recommending","to recommend","recommend","recommended"],"correct":3,"answer":"recommended","vi":"Cuốn tiểu thuyết được cô giáo tiếng Anh giới thiệu hóa ra vui hơn tôi tưởng nhiều.","explanation":"A past participle replaces a passive relative clause: the novel <b>(which was) recommended</b> by our teacher. The -ing form would mean the novel itself was recommending something."},{"id":"gv-kc-08-22","level":"kc","focus":"word-choice","q":"Nam can't go to football practice tonight because he has too much ______ to finish.","options":["classwork","housework","homework","paperwork"],"correct":2,"answer":"homework","vi":"Tối nay Nam không đi tập bóng đá được vì có quá nhiều bài tập về nhà phải làm.","explanation":"<b>Homework</b> is school work done at home. <b>Classwork</b> is done in class, <b>housework</b> is cleaning and cooking, and <b>paperwork</b> is office forms and documents."},{"id":"gv-kc-08-23","level":"kc","focus":"pronoun","q":"Nam and Lan often lend ______ their favourite comic books.","options":["each other","themselves","ourselves","yourselves"],"correct":0,"answer":"each other","vi":"Nam và Lan thường cho nhau mượn những cuốn truyện tranh yêu thích.","explanation":"<b>Each other</b> shows that Nam lends to Lan and Lan lends to Nam. <b>Themselves</b> would mean each lends to himself or herself, and <b>ourselves</b> / <b>yourselves</b> do not match the subject."},{"id":"gv-kc-08-24","level":"kc","focus":"question-tag","q":"Let's watch the new animated film on Saturday, ______?","options":["will we","do we","don't we","shall we"],"correct":3,"answer":"shall we","vi":"Thứ Bảy mình đi xem bộ phim hoạt hình mới nhé?","explanation":"A suggestion with <b>Let's</b> takes the tag <b>shall we</b>. <b>Will you</b> follows an imperative, and <b>do / don't we</b> follow present simple statements."},{"id":"gv-kc-08-25","level":"kc","focus":"tense","q":"Nam ______ a comic book in bed when the lights suddenly went out.","options":["has read","was reading","reads","has been reading"],"correct":1,"answer":"was reading","vi":"Nam đang đọc truyện tranh trên giường thì đèn bỗng nhiên tắt.","explanation":"A longer action in progress (<b>was reading</b>) is interrupted by a short past action (the lights went out): past continuous + past simple."},{"id":"gv-kc-09-1","level":"kc","focus":"tense","q":"Lan ______ the road when a motorbike suddenly pulled out in front of her.","options":["crossed","was crossing","has crossed","had been crossing"],"correct":1,"answer":"was crossing","vi":"Lan đang băng qua đường thì một chiếc xe máy bất ngờ lao ra trước mặt cô.","explanation":"A longer action already in progress (crossing the road) that is interrupted by a sudden short action in the past simple (<i>pulled out</i>) takes the past continuous: <b>was crossing</b>; <b>crossed</b> would make the two actions happen one after the other, and the perfect forms do not fit a <b>when</b> interruption."},{"id":"gv-kc-09-2","level":"kc","focus":"word-choice","q":"The doctor said Nam should eat smaller ______ at dinner if he wants to lose weight.","options":["ingredients","flavours","portions","recipes"],"correct":2,"answer":"portions","vi":"Bác sĩ nói Nam nên ăn những khẩu phần nhỏ hơn vào bữa tối nếu muốn giảm cân.","explanation":"A <b>portion</b> is the amount of food served to one person, so you can eat a smaller one; <b>ingredients</b> are what a dish is made of, a <b>flavour</b> is a taste and a <b>recipe</b> is a set of cooking instructions."},{"id":"gv-kc-09-3","level":"kc","focus":"collocation","q":"You should ______ an appointment with the dentist before the holiday starts.","options":["make","do","take","put"],"correct":0,"answer":"make","vi":"Bạn nên đặt lịch hẹn với nha sĩ trước khi kỳ nghỉ bắt đầu.","explanation":"The verb that collocates with <b>appointment</b> is <b>make</b>: you <b>make an appointment</b>; <b>do</b>, <b>take</b> and <b>put</b> do not go with it."},{"id":"gv-kc-09-4","level":"kc","focus":"phrasal-verb","q":"The forum's rules are strict, so nobody can ______ posting rude comments for long.","options":["get on with","get round to","get down to","get away with"],"correct":3,"answer":"get away with","vi":"Quy định của diễn đàn rất nghiêm, nên không ai có thể đăng bình luận thô lỗ mà thoát được lâu.","explanation":"<b>Get away with</b> something means to do something wrong without being punished; <b>get on with</b> is to continue, <b>get round to</b> is to finally find time for, and <b>get down to</b> is to start working seriously."},{"id":"gv-kc-09-5","level":"kc","focus":"relative","q":"The doctor ______ treated my brother has just moved to a hospital in Hue.","options":["which","who","whose","whom"],"correct":1,"answer":"who","vi":"Vị bác sĩ đã chữa cho anh tôi vừa chuyển đến một bệnh viện ở Huế.","explanation":"The relative pronoun is the <b>subject</b> of <i>treated</i> and refers to a person, so it must be <b>who</b>; <b>whom</b> is only an object, <b>whose</b> shows possession, and <b>which</b> is for things."},{"id":"gv-kc-09-6","level":"kc","focus":"idiom","q":"Since Grandma came home from hospital, everyone has been ______ around her so as not to upset her.","options":["walking on eggshells","walking on air","walking on thin ice","walking on water"],"correct":0,"answer":"walking on eggshells","vi":"Từ khi bà đi viện về, cả nhà ai cũng phải rón rén giữ ý quanh bà để không làm bà buồn.","explanation":"To <b>walk on eggshells</b> is to be very careful not to offend or upset someone; <b>walk on air</b> means to be extremely happy, <b>walk on thin ice</b> is to be in a risky situation, and <b>walk on water</b> is to do the impossible."},{"id":"gv-kc-09-7","level":"kc","focus":"modal","q":"You ______ a taxi from the airport; the hotel bus was free for all guests.","options":["mustn't have taken","can't have taken","needn't have taken","must have taken"],"correct":2,"answer":"needn't have taken","vi":"Bạn đã không cần phải đi taxi từ sân bay; xe buýt của khách sạn miễn phí cho mọi khách.","explanation":"<b>Needn't have + past participle</b> says that something was done although it was not necessary; <b>can't have</b> and <b>must have</b> express deductions about what happened, which do not fit here, and <b>mustn't have</b> is not used for a past deduction."},{"id":"gv-kc-09-8","level":"kc","focus":"word-choice","q":"The waiter brought us the ______ so that we could choose what to order.","options":["dish","dessert","snack","menu"],"correct":3,"answer":"menu","vi":"Người phục vụ mang thực đơn ra để chúng tôi chọn món.","explanation":"The <b>menu</b> is the list of dishes you choose from before ordering; a <b>dish</b>, a <b>dessert</b> and a <b>snack</b> are kinds of food, not something you choose from."},{"id":"gv-kc-09-9","level":"kc","focus":"tense","q":"Nam looks tired because he ______ on the phone since eight o'clock this morning.","options":["has been talking","is talking","was talking","talks"],"correct":0,"answer":"has been talking","vi":"Nam trông mệt mỏi vì cậu ấy nói chuyện điện thoại từ tám giờ sáng đến giờ.","explanation":"An activity that started in the past and is still going on, with <b>since</b> and a visible result (he looks tired), takes the present perfect continuous: <b>has been talking</b>."},{"id":"gv-kc-09-10","level":"kc","focus":"article-quantifier","q":"There were very ______ tourists on the beach in the early morning, so it was wonderfully peaceful.","options":["a few","few","little","a little"],"correct":1,"answer":"few","vi":"Sáng sớm trên bãi biển có rất ít khách du lịch, nên nơi đó yên bình tuyệt vời.","explanation":"<b>Tourists</b> is a plural countable noun, so it takes <b>few</b> (almost none), and <b>very</b> can only go before <b>few</b>, not <b>a few</b>; <b>little</b> and <b>a little</b> are for uncountable nouns."},{"id":"gv-kc-09-11","level":"kc","focus":"collocation","q":"Remember to ______ a photo of your passport before you travel abroad.","options":["make","do","catch","take"],"correct":3,"answer":"take","vi":"Nhớ chụp một tấm ảnh hộ chiếu của bạn trước khi đi nước ngoài nhé.","explanation":"In English you <b>take a photo</b>; <b>make</b>, <b>do</b> and <b>catch</b> do not collocate with <b>photo</b>."},{"id":"gv-kc-09-12","level":"kc","focus":"word-choice","q":"Bún bò Huế is a famous ______ of central Vietnam, which every visitor should try.","options":["ingredient","diet","speciality","flavour"],"correct":2,"answer":"speciality","vi":"Bún bò Huế là một đặc sản nổi tiếng của miền Trung Việt Nam mà du khách nào cũng nên thử.","explanation":"A <b>speciality</b> is a food that a place is famous for; an <b>ingredient</b> is one part of a dish, a <b>diet</b> is what a person usually eats, and a <b>flavour</b> is a taste."},{"id":"gv-kc-09-13","level":"kc","focus":"conditional","q":"If I ______ my phone charger at home, I could show you the holiday photos now.","options":["hadn't left","didn't leave","haven't left","wouldn't leave"],"correct":0,"answer":"hadn't left","vi":"Nếu tôi không để quên sạc điện thoại ở nhà thì giờ tôi có thể cho bạn xem ảnh kỳ nghỉ rồi.","explanation":"This is a <b>mixed conditional</b>: a past condition (I left the charger at home) with a present result (I could show you now), so the if-clause takes the past perfect <b>hadn't left</b>."},{"id":"gv-kc-09-14","level":"kc","focus":"phrasal-verb","q":"Grandpa finds it hard to ______ all the new apps his grandchildren use.","options":["keep on with","keep up with","keep out of","keep away from"],"correct":1,"answer":"keep up with","vi":"Ông thấy khó theo kịp tất cả những ứng dụng mới mà các cháu dùng.","explanation":"<b>Keep up with</b> means to stay at the same level as something that is changing fast; <b>keep on with</b> is to continue, <b>keep out of</b> is to stay away from trouble, and <b>keep away from</b> is to avoid going near."},{"id":"gv-kc-09-15","level":"kc","focus":"tense","q":"While I ______ the hotel website, the internet connection suddenly dropped.","options":["checked","have checked","was checking","am checking"],"correct":2,"answer":"was checking","vi":"Trong lúc tôi đang xem trang web của khách sạn thì kết nối mạng bỗng nhiên bị mất.","explanation":"A longer action in progress (<b>while</b>) that is interrupted by a short past action takes the past continuous: <b>was checking</b>."},{"id":"gv-kc-09-16","level":"kc","focus":"relative","q":"The hotel, the rooms ______ all face the sea, is fully booked until August.","options":["whose","of whom","in which","of which"],"correct":3,"answer":"of which","vi":"Khách sạn đó, với các phòng đều hướng ra biển, đã kín chỗ cho đến tận tháng Tám.","explanation":"When possession is expressed after the noun, a thing (the hotel) takes <b>of which</b>: <i>the rooms of which</i> = <i>whose rooms</i>; <b>of whom</b> is for people, <b>whose</b> must stand <b>before</b> the noun, and <b>in which</b> would mean the rooms are inside something."},{"id":"gv-kc-09-17","level":"kc","focus":"gerund-infinitive","q":"The receptionist reminded us ______ our room keys before we left the hotel.","options":["handing in","to hand in","hand in","to handing in"],"correct":1,"answer":"to hand in","vi":"Lễ tân nhắc chúng tôi nộp lại chìa khóa phòng trước khi rời khách sạn.","explanation":"<b>Remind somebody to do</b> something takes the <b>to-infinitive</b>; the phrasal verb <b>hand in</b> means to give something to the person in charge."},{"id":"gv-kc-09-18","level":"kc","focus":"idiom","q":"My patience is beginning to ______ — the hostel Wi-Fi has stopped working for the third time today.","options":["wear thin","fall flat","go blank","run wild"],"correct":0,"answer":"wear thin","vi":"Tôi bắt đầu hết kiên nhẫn rồi — Wi-Fi ở nhà nghỉ đã hỏng lần thứ ba trong ngày hôm nay.","explanation":"When your patience <b>wears thin</b>, you gradually stop being able to put up with something; a joke <b>falls flat</b>, your mind <b>goes blank</b>, and your imagination <b>runs wild</b>."},{"id":"gv-kc-09-19","level":"kc","focus":"word-choice","q":"The soup had a strong ______ of ginger, which really helped my sore throat.","options":["texture","appetite","portion","flavour"],"correct":3,"answer":"flavour","vi":"Món súp có vị gừng rất đậm, và điều đó thực sự giúp cổ họng đau của tôi dễ chịu hơn.","explanation":"The <b>flavour</b> of a food is its particular taste; <b>texture</b> is how it feels in the mouth, <b>appetite</b> is the desire to eat, and a <b>portion</b> is the amount served."},{"id":"gv-kc-09-20","level":"kc","focus":"linking","q":"My sister loves crowded night markets, ______ I prefer quiet cafés by the river.","options":["despite","so that","whereas","otherwise"],"correct":2,"answer":"whereas","vi":"Chị tôi thích những khu chợ đêm đông đúc, trong khi tôi lại thích những quán cà phê yên tĩnh bên sông.","explanation":"<b>Whereas</b> joins two clauses that contrast two different people or things; <b>despite</b> cannot be followed by a clause, <b>so that</b> gives a purpose, and <b>otherwise</b> means 'if not'."},{"id":"gv-kc-09-21","level":"kc","focus":"modal","q":"Passengers ______ switch their phones to flight mode before the plane takes off; it is an airline rule.","options":["must","might","could","would"],"correct":0,"answer":"must","vi":"Hành khách phải chuyển điện thoại sang chế độ máy bay trước khi máy bay cất cánh; đó là quy định của hãng.","explanation":"A rule or strong obligation is expressed with <b>must</b>; <b>might</b> and <b>could</b> only talk about possibility, and <b>would</b> is for hypothetical or repeated past actions."},{"id":"gv-kc-09-22","level":"kc","focus":"collocation","q":"Lan ______ a bad cold on the plane and spent the first two days of the holiday in bed.","options":["took","caught","made","held"],"correct":1,"answer":"caught","vi":"Lan bị cảm nặng trên máy bay và nằm giường suốt hai ngày đầu của kỳ nghỉ.","explanation":"You <b>catch a cold</b> (or the flu); <b>take</b>, <b>make</b> and <b>hold</b> do not collocate with an illness."},{"id":"gv-kc-09-23","level":"kc","focus":"inversion","q":"______ had we boarded the plane when the baby behind us started crying.","options":["No sooner","Not until","Hardly","Only when"],"correct":2,"answer":"Hardly","vi":"Chúng tôi vừa mới lên máy bay thì em bé ngồi sau bắt đầu khóc.","explanation":"<b>Hardly</b> + inverted past perfect pairs with <b>when</b>: <i>Hardly had we boarded … when …</i>; <b>No sooner</b> needs <b>than</b>, and <b>Not until</b> and <b>Only when</b> are followed by a clause before the inversion."},{"id":"gv-kc-09-24","level":"kc","focus":"word-choice","q":"The doctor put Grandpa on a low-salt ______ after his blood pressure test.","options":["meal","dish","menu","diet"],"correct":3,"answer":"diet","vi":"Sau khi đo huyết áp, bác sĩ cho ông theo chế độ ăn ít muối.","explanation":"A <b>diet</b> is the kind of food a person regularly eats, especially for health reasons; a <b>meal</b> and a <b>dish</b> are single occasions of eating, and a <b>menu</b> is a list of food in a restaurant."},{"id":"gv-kc-09-25","level":"kc","focus":"tense","q":"When we finally reached the gate, the plane ______ already.","options":["left","had left","has left","was leaving"],"correct":1,"answer":"had left","vi":"Khi cuối cùng chúng tôi tới được cửa ra máy bay thì máy bay đã cất cánh rồi.","explanation":"The plane's departure happened <b>before</b> the past moment of reaching the gate, so the earlier action takes the past perfect: <b>had left</b>."},{"id":"gv-kc-10-1","level":"kc","focus":"tense","q":"Look! The cat ______ on the kitchen table again.","options":["sleeps","is sleeping","slept","has slept"],"correct":1,"answer":"is sleeping","vi":"Nhìn kìa! Con mèo lại đang ngủ trên bàn bếp.","explanation":"<b>Look!</b> points to something happening right now, so the present continuous <b>is sleeping</b> is needed, not a simple or perfect form."},{"id":"gv-kc-10-2","level":"kc","focus":"word-choice","q":"The kitten ______ its paw on a piece of broken glass in the garden.","options":["bruised","sprained","cut","strained"],"correct":2,"answer":"cut","vi":"Con mèo con bị đứt chân vì một mảnh thủy tinh vỡ trong vườn.","explanation":"Broken glass makes a <b>cut</b>. You <b>bruise</b> yourself by knocking against something, and you <b>sprain</b> or <b>strain</b> a joint or muscle by twisting it."},{"id":"gv-kc-10-3","level":"kc","focus":"idiom","q":"Everyone expects Tuan's dog to ______ at Sunday's race because it is much faster than the others.","options":["run out of steam","win by a whisker","lose its way","win hands down"],"correct":3,"answer":"win hands down","vi":"Ai cũng nghĩ chó của Tuấn sẽ thắng dễ dàng ở cuộc đua hôm Chủ nhật vì nó nhanh hơn hẳn những con khác.","explanation":"<b>Win hands down</b> = win very easily. <b>Win by a whisker</b> means win only just, which contradicts 'much faster'; <b>run out of steam</b> and <b>lose its way</b> describe failing."},{"id":"gv-kc-10-4","level":"kc","focus":"collocation","q":"You should ______ your promise to visit Grandma this weekend, or she will be very upset.","options":["hold","stay","keep","save"],"correct":2,"answer":"keep","vi":"Con nên giữ lời hứa đi thăm bà vào cuối tuần này, không thì bà sẽ buồn lắm.","explanation":"The collocation is <b>keep a promise</b> (do what you said you would do). <b>Hold</b>, <b>stay</b> and <b>save</b> do not go with promise in this meaning."},{"id":"gv-kc-10-5","level":"kc","focus":"phrasal-verb","q":"Don't ______ your teammates by missing the school cooking contest on Saturday.","options":["turn down","let off","let down","put down"],"correct":2,"answer":"let down","vi":"Đừng làm đồng đội thất vọng bằng cách bỏ lỡ cuộc thi nấu ăn của trường vào thứ Bảy.","explanation":"<b>Let somebody down</b> = disappoint someone. <b>Turn down</b> = refuse, <b>let off</b> = not punish, <b>put down</b> = criticise or place something."},{"id":"gv-kc-10-6","level":"kc","focus":"relative","q":"Nobody could explain the reason ______ the school swimming pool stayed closed all summer.","options":["which","where","when","why"],"correct":3,"answer":"why","vi":"Không ai giải thích được lý do vì sao bể bơi của trường đóng cửa suốt cả mùa hè.","explanation":"After <b>the reason</b>, the relative adverb <b>why</b> is used. <b>Where</b> follows a place, <b>when</b> a time, and <b>which</b> would need to be the subject or object of the clause, which it is not here."},{"id":"gv-kc-10-7","level":"kc","focus":"word-choice","q":"After eating the fish that had been left out in the sun, Nam felt ______ and had to lie down.","options":["sore","bruised","hurt","sick"],"correct":3,"answer":"sick","vi":"Sau khi ăn con cá bị để ngoài nắng, Nam thấy buồn nôn và phải nằm nghỉ.","explanation":"Bad food makes you feel <b>sick</b>. <b>Sore</b>, <b>bruised</b> and <b>hurt</b> describe a painful part of the body, not a feeling of illness."},{"id":"gv-kc-10-8","level":"kc","focus":"modal","q":"The bowl is empty — the cat ______ all the fish while we were out.","options":["must have eaten","should have eaten","needn't have eaten","can't have eaten"],"correct":0,"answer":"must have eaten","vi":"Cái bát trống không — chắc chắn con mèo đã ăn hết cá lúc chúng ta đi vắng.","explanation":"<b>Must have + past participle</b> is a confident guess about the past based on evidence (the empty bowl). <b>Can't have</b> means the opposite; <b>should have</b> and <b>needn't have</b> express advice or lack of need, not deduction."},{"id":"gv-kc-10-9","level":"kc","focus":"preposition","q":"Parrots are famous ______ copying the sounds of human speech.","options":["of","about","for","with"],"correct":2,"answer":"for","vi":"Vẹt nổi tiếng vì bắt chước được âm thanh tiếng người.","explanation":"The adjective <b>famous</b> takes the preposition <b>for</b> before the thing someone is known for; of, about and with do not follow it."},{"id":"gv-kc-10-10","level":"kc","focus":"tense","q":"My grandmother ______ the same soup recipe since she was a little girl.","options":["uses","used","is using","has used"],"correct":3,"answer":"has used","vi":"Bà tôi đã dùng cùng một công thức nấu canh này từ khi bà còn là một cô bé.","explanation":"<b>Since</b> + a past starting point describes something that continues up to now, so the present perfect <b>has used</b> is needed."},{"id":"gv-kc-10-11","level":"kc","focus":"word-choice","q":"Lan's ankle became ______ after she twisted it on the mountain trail.","options":["dizzy","swollen","hoarse","feverish"],"correct":1,"answer":"swollen","vi":"Cổ chân của Lan bị sưng lên sau khi cô ấy bị trẹo chân trên đường mòn lên núi.","explanation":"A twisted ankle becomes <b>swollen</b> (bigger than normal). <b>Dizzy</b>, <b>hoarse</b> and <b>feverish</b> describe a person's head, voice or temperature, not a joint."},{"id":"gv-kc-10-12","level":"kc","focus":"collocation","q":"Could you ______ the table while I finish the spring rolls?","options":["put","make","lay","do"],"correct":2,"answer":"lay","vi":"Con dọn bàn ăn giúp mẹ trong lúc mẹ làm nốt chả giò được không?","explanation":"The collocation is <b>lay the table</b> (put out the plates, bowls and chopsticks). <b>Put</b>, <b>make</b> and <b>do</b> do not go with 'the table' in this meaning."},{"id":"gv-kc-10-13","level":"kc","focus":"conditional","q":"Lan: Are we going to the beach tomorrow? / Nam: If the weather ______ fine, we'll take the dog with us.","options":["will be","is","was","would be"],"correct":1,"answer":"is","vi":"Lan: Mai mình đi biển chứ? / Nam: Nếu trời đẹp, mình sẽ dắt chó theo.","explanation":"A first conditional uses the present simple in the <b>if</b>-clause and <b>will</b> in the main clause, even when it refers to the future."},{"id":"gv-kc-10-14","level":"kc","focus":"idiom","q":"Planting ten trees is only ______ when a whole forest has been cut down.","options":["a drop in the ocean","a piece of cake","a storm in a teacup","a breath of fresh air"],"correct":0,"answer":"a drop in the ocean","vi":"Trồng mười cái cây chỉ như muối bỏ biển khi cả một khu rừng đã bị chặt.","explanation":"<b>A drop in the ocean</b> = a very small amount compared with what is needed. <b>A piece of cake</b> = very easy; <b>a storm in a teacup</b> = a fuss about nothing; <b>a breath of fresh air</b> = something pleasantly new."},{"id":"gv-kc-10-15","level":"kc","focus":"article-quantifier","q":"There is only ______ rice left in the pot, so I'll cook some noodles as well.","options":["a few","many","a little","several"],"correct":2,"answer":"a little","vi":"Trong nồi chỉ còn một ít cơm, nên mình sẽ nấu thêm mì.","explanation":"<b>Rice</b> is uncountable, so it takes <b>a little</b>. <b>A few</b>, <b>many</b> and <b>several</b> are only used with plural countable nouns."},{"id":"gv-kc-10-16","level":"kc","focus":"word-choice","q":"Mai has a bad ______, so she keeps coughing and sneezing in class.","options":["cold","ache","bruise","rash"],"correct":0,"answer":"cold","vi":"Mai bị cảm nặng nên cứ ho và hắt hơi liên tục trong lớp.","explanation":"Coughing and sneezing are the signs of a <b>cold</b>. An <b>ache</b> is a dull pain, a <b>bruise</b> is a dark mark on the skin, and a <b>rash</b> is a patch of red spots."},{"id":"gv-kc-10-17","level":"kc","focus":"phrasal-verb","q":"Our old dog ______ peacefully last winter, and we buried him under the mango tree.","options":["passed out","gave away","passed by","passed away"],"correct":3,"answer":"passed away","vi":"Con chó già của chúng tôi đã qua đời thanh thản vào mùa đông năm ngoái, và chúng tôi chôn nó dưới gốc xoài.","explanation":"<b>Pass away</b> is a gentle way of saying die. <b>Pass out</b> = faint, <b>pass by</b> = go past, <b>give away</b> = give something as a present."},{"id":"gv-kc-10-18","level":"kc","focus":"reported","q":"The vet said she ______ the problem with our rabbit's teeth the next day.","options":["will look into","looks into","would look into","has looked into"],"correct":2,"answer":"would look into","vi":"Bác sĩ thú y nói rằng hôm sau cô ấy sẽ xem xét vấn đề về răng của con thỏ nhà chúng tôi.","explanation":"In reported speech after <b>said</b>, <b>will</b> becomes <b>would</b>: 'I will look into it tomorrow' becomes she <b>would look into</b> it the next day."},{"id":"gv-kc-10-19","level":"kc","focus":"gerund-infinitive","q":"Nam: Shall we eat out tonight? / Lan: I'd rather ______ at home; I've bought some fresh prawns.","options":["cook","cooking","to cook","cooked"],"correct":0,"answer":"cook","vi":"Nam: Tối nay mình ra ngoài ăn nhé? / Lan: Tớ thích nấu ở nhà hơn; tớ mới mua ít tôm tươi.","explanation":"<b>Would rather</b> is followed by the bare infinitive: <b>I'd rather cook</b>, not 'to cook', 'cooking' or 'cooked'."},{"id":"gv-kc-10-20","level":"kc","focus":"tense","q":"When I got home from school, my dog ______ my new slippers to pieces.","options":["chews","has chewed","is chewing","had chewed"],"correct":3,"answer":"had chewed","vi":"Khi tôi đi học về thì con chó đã cắn nát đôi dép mới của tôi.","explanation":"The chewing happened <b>before</b> I got home, so the earlier past action takes the past perfect: <b>had chewed</b>. Present forms cannot follow a past time clause here."},{"id":"gv-kc-10-21","level":"kc","focus":"word-choice","q":"Minh has a terrible ______, so he can't chew the sticky rice cake his mother made.","options":["headache","toothache","earache","stomachache"],"correct":1,"answer":"toothache","vi":"Minh bị đau răng dữ dội nên không nhai được bánh chưng mẹ làm.","explanation":"Only a <b>toothache</b> stops you chewing. A <b>headache</b>, an <b>earache</b> and a <b>stomachache</b> are pains in other parts of the body."},{"id":"gv-kc-10-22","level":"kc","focus":"linking","q":"Nam loves spicy food, ______ his sister cannot eat even a little chilli.","options":["therefore","whereas","so that","because"],"correct":1,"answer":"whereas","vi":"Nam rất thích đồ ăn cay, trong khi chị của cậu ấy không ăn nổi dù chỉ một chút ớt.","explanation":"<b>Whereas</b> links two contrasting facts. <b>Therefore</b> and <b>so that</b> give a result or purpose, and <b>because</b> gives a reason — none of them fits a contrast."},{"id":"gv-kc-10-23","level":"kc","focus":"passive","q":"Fresh vegetables ______ to the market every morning by farmers from the countryside.","options":["bring","brought","are bringing","are brought"],"correct":3,"answer":"are brought","vi":"Rau tươi được nông dân từ vùng quê chở đến chợ mỗi sáng.","explanation":"The vegetables do not act; they receive the action, and <b>by farmers</b> shows the agent, so the present simple passive <b>are brought</b> is needed."},{"id":"gv-kc-10-24","level":"kc","focus":"comparison","q":"Lan: Why don't you buy frozen fish? It's cheaper. / Nam: Fresh fish tastes far ______ than frozen fish.","options":["best","better","good","well"],"correct":1,"answer":"better","vi":"Lan: Sao cậu không mua cá đông lạnh? Rẻ hơn mà. / Nam: Cá tươi ăn ngon hơn cá đông lạnh nhiều.","explanation":"<b>Than</b> signals a comparative, and the comparative of <b>good</b> is <b>better</b>; <b>far</b> simply makes the comparison stronger."},{"id":"gv-kc-10-25","level":"kc","focus":"collocation","q":"After dinner, Nam always ______ the washing-up so that his mother can rest.","options":["does","makes","takes","gets"],"correct":0,"answer":"does","vi":"Sau bữa tối, Nam luôn rửa bát để mẹ được nghỉ ngơi.","explanation":"The collocation is <b>do the washing-up</b>, like do the cooking or do the dishes; <b>make</b>, <b>take</b> and <b>get</b> do not go with it."},{"id":"gv-kc-11-1","level":"kc","focus":"tense","q":"Look! The lion dance team ______ down our street right now.","options":["comes","is coming","has come","came"],"correct":1,"answer":"is coming","vi":"Nhìn kìa! Đội múa lân đang đi xuống phố nhà mình ngay lúc này.","explanation":"An action happening at the moment of speaking (<b>Look!</b>, <b>right now</b>) takes the present continuous: <b>is coming</b>; the present simple, present perfect and past simple do not describe what is going on now."},{"id":"gv-kc-11-2","level":"kc","focus":"word-choice","q":"In the south of Viet Nam, the rainy ______ usually lasts from May to November.","options":["season","term","era","decade"],"correct":0,"answer":"season","vi":"Ở miền Nam Việt Nam, mùa mưa thường kéo dài từ tháng Năm đến tháng Mười Một.","explanation":"A <b>season</b> is a part of the year with its own weather; a <b>term</b> is part of a school year, an <b>era</b> is a long period of history, and a <b>decade</b> is ten years."},{"id":"gv-kc-11-3","level":"kc","focus":"collocation","q":"The forecast says a ______ wind will blow from the north tonight, so bring a jacket.","options":["heavy","thick","strong","large"],"correct":2,"answer":"strong","vi":"Dự báo nói tối nay sẽ có gió mạnh thổi từ phía bắc, nên hãy mang theo áo khoác.","explanation":"Wind is <b>strong</b> (or light); <b>heavy</b> goes with rain and traffic, <b>thick</b> with fog, and <b>large</b> does not describe wind."},{"id":"gv-kc-11-4","level":"kc","focus":"idiom","q":"Since Mai joined the school drama club, she has really ______ — she chats with everyone now.","options":["come to her senses","come down to earth","come full circle","come out of her shell"],"correct":3,"answer":"come out of her shell","vi":"Từ khi Mai vào câu lạc bộ kịch của trường, bạn ấy thật sự đã cởi mở hơn hẳn — giờ bạn ấy trò chuyện với tất cả mọi người.","explanation":"To <b>come out of your shell</b> is to stop being shy and start talking to people. <b>Come to your senses</b> is to start thinking sensibly, <b>come down to earth</b> is to become realistic, and <b>come full circle</b> is to return to where something started."},{"id":"gv-kc-11-5","level":"kc","focus":"phrasal-verb","q":"The tour guide ______ that the old market had been rebuilt after the fire.","options":["pointed out","pointed at","turned out","left out"],"correct":0,"answer":"pointed out","vi":"Hướng dẫn viên chỉ ra rằng khu chợ cũ đã được xây lại sau vụ cháy.","explanation":"To <b>point out</b> is to tell people a fact they may not have noticed. <b>Point at</b> needs a thing you aim your finger at, <b>turn out</b> is used with <b>it</b> (it turned out that…), and <b>leave out</b> means to omit."},{"id":"gv-kc-11-6","level":"kc","focus":"modal","q":"The streets are completely dry this morning, so it ______ last night.","options":["must have rained","can't have rained","should have rained","might rain"],"correct":1,"answer":"can't have rained","vi":"Sáng nay đường phố khô ráo hoàn toàn, nên tối qua chắc chắn là không mưa.","explanation":"<b>Can't have</b> + past participle expresses a confident conclusion that something did NOT happen in the past; <b>must have</b> would mean the opposite, and <b>should have</b> and <b>might rain</b> do not fit the dry-street evidence."},{"id":"gv-kc-11-7","level":"kc","focus":"word-choice","q":"There will be a fifteen-minute ______ between the two water-puppet shows, so you can buy some snacks.","options":["delay","recess","interval","era"],"correct":2,"answer":"interval","vi":"Sẽ có mười lăm phút giải lao giữa hai suất múa rối nước, nên bạn có thể mua chút đồ ăn vặt.","explanation":"A planned break between two parts of a show is an <b>interval</b>; a <b>delay</b> is unplanned lateness, a <b>recess</b> is a break at school or in court, and an <b>era</b> is a long period of history."},{"id":"gv-kc-11-8","level":"kc","focus":"relative","q":"The bus ______ Nam takes to school every morning was twenty minutes late again today.","options":["who","whose","where","which"],"correct":3,"answer":"which","vi":"Chiếc xe buýt mà Nam đi học mỗi sáng hôm nay lại trễ hai mươi phút.","explanation":"The relative pronoun refers to a thing (<b>the bus</b>) and is the object of <b>takes</b>, so <b>which</b> (or <b>that</b>) is used; <b>who</b> is for people, <b>whose</b> shows possession, and <b>where</b> would need a complete clause after it."},{"id":"gv-kc-11-9","level":"kc","focus":"article-quantifier","q":"Very ______ pupils remembered to bring their raincoats, so most of them got soaked on the way home.","options":["a few","little","few","a little"],"correct":2,"answer":"few","vi":"Rất ít học sinh nhớ mang áo mưa, nên hầu hết các em bị ướt sũng trên đường về nhà.","explanation":"<b>Few</b> means 'almost no', stressing how small the number is, and it is the only option that can follow <b>very</b>; <b>a few</b> means 'some' (very a few is impossible), while <b>little</b> and <b>a little</b> go with uncountable nouns, not <b>pupils</b>."},{"id":"gv-kc-11-10","level":"kc","focus":"tense","q":"Lan ______ the lantern festival three times since she moved to Hoi An.","options":["visited","had visited","has visited","visits"],"correct":2,"answer":"has visited","vi":"Từ khi chuyển đến Hội An, Lan đã đi lễ hội đèn lồng ba lần.","explanation":"<b>Since</b> + a past point and <b>three times</b> describe experience up to now, so the present perfect <b>has visited</b> is needed; the past simple and past perfect cut the link with the present."},{"id":"gv-kc-11-11","level":"kc","focus":"gerund-infinitive","q":"On the way to the beach, Dad stopped ______ some petrol at the station near the bridge.","options":["to buy","buying","buy","bought"],"correct":0,"answer":"to buy","vi":"Trên đường ra biển, bố dừng lại để mua xăng ở cây xăng gần cầu.","explanation":"<b>Stop to do</b> means to pause in order to do something else: Dad stopped the car so that he could buy petrol. <b>Stop doing</b> would mean he gave up buying petrol, and a bare infinitive or past form cannot follow <b>stop</b>."},{"id":"gv-kc-11-12","level":"kc","focus":"collocation","q":"Please ______ your seat belt before the coach pulls out of the station.","options":["tie","close","fix","fasten"],"correct":3,"answer":"fasten","vi":"Vui lòng thắt dây an toàn trước khi xe khách rời bến.","explanation":"You <b>fasten</b> (or do up) a seat belt; <b>tie</b> is for shoelaces and ropes, <b>close</b> for doors and windows, and <b>fix</b> means to repair or attach."},{"id":"gv-kc-11-13","level":"kc","focus":"word-choice","q":"Uncle Tam is always ______: his bus leaves the depot at exactly six every morning.","options":["temporary","punctual","recent","urgent"],"correct":1,"answer":"punctual","vi":"Bác Tâm lúc nào cũng đúng giờ: xe buýt của bác rời bến đúng sáu giờ mỗi sáng.","explanation":"A <b>punctual</b> person does things at the right time; <b>temporary</b> means lasting a short while, <b>recent</b> means happening not long ago, and <b>urgent</b> means needing action at once."},{"id":"gv-kc-11-14","level":"kc","focus":"linking","q":"There was a thunderstorm last night; ______, the morning market opened as usual.","options":["nevertheless","therefore","moreover","otherwise"],"correct":0,"answer":"nevertheless","vi":"Tối qua có giông bão; tuy vậy, chợ sáng vẫn mở cửa như thường lệ.","explanation":"The second clause contrasts with the first, so the linking adverb of contrast <b>nevertheless</b> is needed; <b>therefore</b> shows a result, <b>moreover</b> adds a point, and <b>otherwise</b> means 'if not'."},{"id":"gv-kc-11-15","level":"kc","focus":"idiom","q":"Somehow the whole class ______ Nam's surprise party, so it wasn't a surprise at all.","options":["got the hang of","got the better of","got wind of","got rid of"],"correct":2,"answer":"got wind of","vi":"Không hiểu sao cả lớp đã nghe phong thanh về bữa tiệc bất ngờ của Nam, nên nó chẳng còn bất ngờ chút nào.","explanation":"To <b>get wind of</b> something is to hear about it, often by chance or before it is meant to be known. <b>Get the hang of</b> is to learn how to do something, <b>get the better of</b> is to defeat, and <b>get rid of</b> is to throw away."},{"id":"gv-kc-11-16","level":"kc","focus":"conditional","q":"If the weather office hadn't ruled out a storm, the boat race on the river ______.","options":["would be cancelled","will be cancelled","was cancelled","would have been cancelled"],"correct":3,"answer":"would have been cancelled","vi":"Nếu cơ quan khí tượng không loại trừ khả năng có bão thì cuộc đua thuyền trên sông đã bị hủy rồi.","explanation":"The <b>if</b>-clause is past perfect (<b>hadn't ruled out</b>), a third conditional about an unreal past, so the main clause takes <b>would have</b> + past participle: <b>would have been cancelled</b>."},{"id":"gv-kc-11-17","level":"kc","focus":"word-choice","q":"We reached the station ten minutes ______, so we had time for a coffee before the train left.","options":["soon","early","lately","quickly"],"correct":1,"answer":"early","vi":"Chúng tôi đến ga sớm mười phút, nên có thời gian uống cà phê trước khi tàu chạy.","explanation":"<b>Ten minutes early</b> means before the planned time; <b>soon</b> means in a short time from now, <b>lately</b> means recently, and <b>quickly</b> describes speed, not time of arrival."},{"id":"gv-kc-11-18","level":"kc","focus":"agreement","q":"A number of lanterns ______ hung along the river every full-moon night in Hoi An.","options":["are","is","has","was"],"correct":0,"answer":"are","vi":"Nhiều chiếc đèn lồng được treo dọc bờ sông vào mỗi đêm rằm ở Hội An.","explanation":"<b>A number of</b> + plural noun takes a plural verb (only <b>the number of</b> is singular), and <b>every full-moon night</b> calls for the present simple, so <b>are</b> hung."},{"id":"gv-kc-11-19","level":"kc","focus":"phrasal-verb","q":"At the meeting, the head girl ______ a plan for a greener school festival.","options":["put off","put away","put forward","put up"],"correct":2,"answer":"put forward","vi":"Tại cuộc họp, bạn nữ đại diện học sinh đã đề xuất một kế hoạch cho lễ hội trường xanh hơn.","explanation":"To <b>put forward</b> a plan or idea is to suggest it for discussion. <b>Put off</b> means to postpone, <b>put away</b> means to store, and <b>put up</b> means to build something or display a poster."},{"id":"gv-kc-11-20","level":"kc","focus":"participle","q":"______ from the top of the hill, the whole town looks like a toy model.","options":["Seeing","Seen","To see","Having seen"],"correct":1,"answer":"Seen","vi":"Nhìn từ đỉnh đồi, cả thị trấn trông như một mô hình đồ chơi.","explanation":"The town is <b>seen</b> (it does not do the seeing), so the past participle gives the passive meaning; <b>Seeing</b> or <b>Having seen</b> would need a subject who looks, and <b>To see</b> expresses purpose."},{"id":"gv-kc-11-21","level":"kc","focus":"tense","q":"By next Tet, my family ______ in this town for exactly ten years.","options":["will live","has lived","lived","will have lived"],"correct":3,"answer":"will have lived","vi":"Đến Tết sang năm, gia đình tôi sẽ sống ở thị trấn này tròn mười năm.","explanation":"<b>By</b> + a future time and <b>for ten years</b> describe an action completed up to a point in the future, so the future perfect <b>will have lived</b> is needed."},{"id":"gv-kc-11-22","level":"kc","focus":"word-choice","q":"The old tram line closed years ago; ______ most people in the city take the metro.","options":["nowadays","lately","formerly","previously"],"correct":0,"answer":"nowadays","vi":"Tuyến tàu điện cũ đã đóng cửa nhiều năm trước; ngày nay hầu hết người dân thành phố đi tàu điện ngầm.","explanation":"<b>Nowadays</b> means at the present time, in contrast with the past; <b>lately</b> needs the present perfect, and <b>formerly</b> and <b>previously</b> both refer to the past."},{"id":"gv-kc-11-23","level":"kc","focus":"pronoun","q":"______ gets to the bus stop first should save seats for the rest of the group.","options":["Whatever","Whichever","Whoever","Whom"],"correct":2,"answer":"Whoever","vi":"Ai đến trạm xe buýt trước thì nên giữ chỗ cho cả nhóm.","explanation":"<b>Whoever</b> means 'the person who' and can be the subject of <b>gets</b>; <b>whatever</b> and <b>whichever</b> refer to things, and <b>whom</b> is an object form that cannot be a subject."},{"id":"gv-kc-11-24","level":"kc","focus":"collocation","q":"Tet ______ on a different date each year because it follows the lunar calendar.","options":["drops","falls","sets","lies"],"correct":1,"answer":"falls","vi":"Tết rơi vào một ngày khác nhau mỗi năm vì nó theo lịch âm.","explanation":"A festival or holiday <b>falls on</b> a date; <b>drop</b>, <b>set</b> and <b>lie</b> are not used with dates."},{"id":"gv-kc-11-25","level":"kc","focus":"question-tag","q":"Let's go to the flower market on Sunday morning, ______?","options":["will we","do we","don't we","shall we"],"correct":3,"answer":"shall we","vi":"Sáng Chủ nhật mình đi chợ hoa nhé?","explanation":"The question tag for <b>Let's</b> is always <b>shall we</b>; <b>will you</b> is the tag for an imperative, and <b>do/don't we</b> follow a present simple statement."},{"id":"gv-kc-12-1","level":"kc","focus":"tense","q":"By the time Lan gets home from school, her little brother ______ all the birthday cake.","options":["has eaten","ate","will have eaten","is eating"],"correct":2,"answer":"will have eaten","vi":"Đến lúc Lan đi học về thì em trai cô ấy sẽ ăn hết cả cái bánh sinh nhật rồi.","explanation":"An action that will be finished <b>before</b> a future point (by the time she gets home) takes the future perfect: <b>will have eaten</b>."},{"id":"gv-kc-12-2","level":"kc","focus":"word-choice","q":"Could you ______ the kitchen floor? There are crumbs everywhere after the party.","options":["sweep","dust","fold","hang"],"correct":0,"answer":"sweep","vi":"Bạn quét sàn bếp giúp mình được không? Sau bữa tiệc, vụn bánh rơi khắp nơi.","explanation":"You <b>sweep</b> a floor with a broom. You <b>dust</b> shelves, <b>fold</b> clothes and <b>hang</b> washing — none of these fit a floor covered in crumbs."},{"id":"gv-kc-12-3","level":"kc","focus":"idiom","q":"Nam's parents ______ when they found out he had skipped school to go to a party.","options":["went round in circles","went through the roof","went down the drain","went off the rails"],"correct":1,"answer":"went through the roof","vi":"Bố mẹ Nam nổi giận đùng đùng khi phát hiện cậu ấy trốn học đi dự tiệc.","explanation":"<b>Go through the roof</b> means to become extremely angry. <b>Go round in circles</b> is to make no progress, <b>go down the drain</b> is to be wasted, and <b>go off the rails</b> is to start behaving badly."},{"id":"gv-kc-12-4","level":"kc","focus":"modal","q":"Lan: Shall I bring some snacks tonight? / Nam: No, you ______ — my mum has made enough for everyone.","options":["mustn't","can't","won't","needn't"],"correct":3,"answer":"needn't","vi":"Lan: Tối nay mình mang chút đồ ăn vặt tới nhé? / Nam: Không, cậu không cần đâu — mẹ mình đã làm đủ cho mọi người rồi.","explanation":"<b>Needn't</b> means it is not necessary. <b>Mustn't</b> forbids something, <b>can't</b> denies permission or ability, and <b>won't</b> is a refusal — none matches \"my mum has made enough\"."},{"id":"gv-kc-12-5","level":"kc","focus":"relative","q":"The letters on our badge, ______ stand for the school's name, were designed by a student.","options":["which","that","who","whose"],"correct":0,"answer":"which","vi":"Các chữ cái trên huy hiệu của chúng tôi, vốn là viết tắt của tên trường, do một học sinh thiết kế.","explanation":"A non-defining clause (between commas) about a thing takes <b>which</b>. <b>That</b> cannot follow a comma, <b>who</b> is for people and <b>whose</b> needs a noun after it."},{"id":"gv-kc-12-6","level":"kc","focus":"collocation","q":"Minh is ______ a real effort to finish his homework before the party starts.","options":["doing","making","taking","having"],"correct":1,"answer":"making","vi":"Minh đang thực sự cố gắng làm xong bài tập về nhà trước khi bữa tiệc bắt đầu.","explanation":"The fixed collocation is <b>make an effort</b>. We <b>do</b> homework, <b>take</b> a break and <b>have</b> a party, but never <b>do / take / have an effort</b>."},{"id":"gv-kc-12-7","level":"kc","focus":"word-choice","q":"It's your turn to ______ the dishes tonight; I did them yesterday.","options":["mop","sweep","wash","dust"],"correct":2,"answer":"wash","vi":"Tối nay đến lượt cậu rửa bát; hôm qua mình rửa rồi.","explanation":"We <b>wash</b> the dishes. <b>Mop</b> and <b>sweep</b> are for floors, and <b>dust</b> is for furniture and shelves."},{"id":"gv-kc-12-8","level":"kc","focus":"phrasal-verb","q":"Hung only bought that expensive phone to ______ in front of his classmates.","options":["show off","show up","put off","take off"],"correct":0,"answer":"show off","vi":"Hùng mua cái điện thoại đắt tiền đó chỉ để khoe khoang trước mặt các bạn cùng lớp.","explanation":"<b>Show off</b> means to try to impress people with what you have. <b>Show up</b> is to arrive, <b>put off</b> is to postpone and <b>take off</b> is to remove or to leave the ground."},{"id":"gv-kc-12-9","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Hoa: He ______ his homework in the library — he'll be back at six.","options":["does","has done","did","is doing"],"correct":3,"answer":"is doing","vi":"Lan: Nam đâu rồi? / Hoa: Cậu ấy đang làm bài tập trong thư viện — sáu giờ sẽ về.","explanation":"An action in progress <b>right now</b> (he is not here at this moment) takes the present continuous: <b>is doing</b>. <b>Has done</b> and <b>did</b> would mean the homework is finished."},{"id":"gv-kc-12-10","level":"kc","focus":"word-choice","q":"Before the party, we had to ______ the living room so there was space to dance.","options":["mend","tidy","polish","iron"],"correct":1,"answer":"tidy","vi":"Trước bữa tiệc, chúng tôi phải dọn gọn phòng khách để có chỗ nhảy.","explanation":"<b>Tidy</b> a room means to put things in order and make space. <b>Mend</b> is to repair, <b>polish</b> is to make shoes or furniture shine, and <b>iron</b> is for clothes."},{"id":"gv-kc-12-11","level":"kc","focus":"article-quantifier","q":"I have very ______ homework tonight, so I can come to Hoa's party after all.","options":["few","a few","little","a little"],"correct":2,"answer":"little","vi":"Tối nay mình có rất ít bài tập, nên rốt cuộc mình có thể đến dự tiệc của Hoa.","explanation":"<b>Homework</b> is uncountable, so <b>few / a few</b> are impossible. <b>Little</b> (almost none) explains why she is free, and only <b>little</b> can follow <b>very</b> — <b>very a little</b> does not exist."},{"id":"gv-kc-12-12","level":"kc","focus":"conditional","q":"If I ______ more free time after school, I would join the school band.","options":["had","have","had had","would have"],"correct":0,"answer":"had","vi":"Nếu mình có nhiều thời gian rảnh sau giờ học hơn, mình sẽ tham gia ban nhạc của trường.","explanation":"A second conditional (an unreal present situation) uses the past simple in the if-clause: <b>If I had</b> ... <b>I would join</b>. <b>Had had</b> belongs to the third conditional and <b>would have</b> never goes in the if-clause."},{"id":"gv-kc-12-13","level":"kc","focus":"collocation","q":"Hurry up, or we will ______ the last bus home and have to call a taxi.","options":["lose","fail","miss","drop"],"correct":2,"answer":"miss","vi":"Nhanh lên, không thì chúng ta sẽ lỡ chuyến xe buýt cuối cùng về nhà và phải gọi taxi đấy.","explanation":"You <b>miss</b> a bus, train or flight when you arrive too late to catch it. <b>Lose</b> is for things you cannot find, <b>fail</b> is for tests, and <b>drop</b> is to let something fall."},{"id":"gv-kc-12-14","level":"kc","focus":"word-choice","q":"Dad ______ the bookshelves every weekend because the dust makes my brother sneeze.","options":["rinses","dusts","peels","stirs"],"correct":1,"answer":"dusts","vi":"Cuối tuần nào bố cũng lau bụi giá sách vì bụi làm em trai tôi hắt hơi.","explanation":"To <b>dust</b> is to wipe the dust off furniture. <b>Rinse</b> is to wash with clean water, and <b>peel</b> and <b>stir</b> are cooking verbs."},{"id":"gv-kc-12-15","level":"kc","focus":"modal","q":"Hoa ______ the party yet — her bag and jacket are still on the chair.","options":["must have left","should have left","can't have left","needn't have left"],"correct":2,"answer":"can't have left","vi":"Hoa không thể nào đã rời bữa tiệc được — túi và áo khoác của cô ấy vẫn còn trên ghế.","explanation":"<b>Can't have + past participle</b> expresses that something is impossible, based on evidence (her things are still here). <b>Must have</b> gives the opposite conclusion; <b>should have</b> and <b>needn't have</b> are about advice and necessity, not deduction."},{"id":"gv-kc-12-16","level":"kc","focus":"idiom","q":"Studying a little every day feels hard now, but it will pay off ______.","options":["in the nick of time","on the spur of the moment","at the drop of a hat","in the long run"],"correct":3,"answer":"in the long run","vi":"Mỗi ngày học một chút bây giờ thấy vất vả, nhưng về lâu dài sẽ có kết quả.","explanation":"<b>In the long run</b> means over a long period of time, eventually. <b>In the nick of time</b> is just before it is too late, <b>on the spur of the moment</b> is without planning, and <b>at the drop of a hat</b> is immediately."},{"id":"gv-kc-12-17","level":"kc","focus":"tense","q":"Mr Tran ______ maths at our school since 2015, and he still loves the job.","options":["taught","has taught","is teaching","had taught"],"correct":1,"answer":"has taught","vi":"Thầy Trần đã dạy toán ở trường chúng tôi từ năm 2015, và thầy vẫn yêu công việc này.","explanation":"<b>Since 2015</b> links a past starting point to now, so the present perfect <b>has taught</b> is needed. <b>Taught</b> and <b>had taught</b> would mean he no longer teaches there."},{"id":"gv-kc-12-18","level":"kc","focus":"relative","q":"The café ______ we usually meet at after school is closed for repairs this week.","options":["where","whom","whose","that"],"correct":3,"answer":"that","vi":"Quán cà phê mà bọn mình hay gặp nhau sau giờ học tuần này đóng cửa để sửa chữa.","explanation":"In a defining clause with the preposition left at the end (<b>meet at</b>), a thing or place takes <b>that</b> (or which). <b>Where</b> already contains the idea of <b>at</b>, so it cannot be used with the preposition; <b>whom</b> is for people and <b>whose</b> needs a noun after it."},{"id":"gv-kc-12-19","level":"kc","focus":"phrasal-verb","q":"Everyone says Mai ______ her mother — they have the same laugh and the same smile.","options":["takes up","looks after","takes after","takes off"],"correct":2,"answer":"takes after","vi":"Ai cũng bảo Mai giống mẹ — hai mẹ con có cùng tiếng cười và nụ cười.","explanation":"<b>Take after</b> someone means to resemble an older relative. <b>Take up</b> is to start a hobby, <b>look after</b> is to care for, and <b>take off</b> is to remove or to leave the ground."},{"id":"gv-kc-12-20","level":"kc","focus":"word-choice","q":"Hang the ______ on the line outside; it won't dry indoors in this weather.","options":["rubbish","dishes","groceries","laundry"],"correct":3,"answer":"laundry","vi":"Phơi quần áo giặt lên dây ngoài trời đi; thời tiết này để trong nhà sẽ không khô đâu.","explanation":"<b>Laundry</b> is the clothes you have washed, which you hang out to dry. <b>Rubbish</b> is taken out, <b>dishes</b> are washed and <b>groceries</b> are put away."},{"id":"gv-kc-12-21","level":"kc","focus":"linking","q":"______ the bad weather, the school football match went ahead on Sunday afternoon.","options":["Despite","Although","In spite","Even though"],"correct":0,"answer":"Despite","vi":"Dù thời tiết xấu, trận bóng đá của trường vẫn diễn ra vào chiều Chủ nhật.","explanation":"<b>Despite</b> is a preposition, so a noun phrase (<b>the bad weather</b>) follows it directly. <b>Although</b> and <b>even though</b> need a clause with a subject and verb, and <b>in spite</b> is incomplete without <b>of</b>."},{"id":"gv-kc-12-22","level":"kc","focus":"gerund-infinitive","q":"Remember ______ the lights before you leave the classroom this afternoon.","options":["to turn off","turning off","turn off","to turning off"],"correct":0,"answer":"to turn off","vi":"Nhớ tắt đèn trước khi rời lớp chiều nay nhé.","explanation":"<b>Remember + to-infinitive</b> is a reminder to do something in the future. <b>Remember + -ing</b> refers to a memory of something already done, which makes no sense here."},{"id":"gv-kc-12-23","level":"kc","focus":"tense","q":"When I called at seven, my friends ______ for the party, so nobody answered the phone.","options":["got ready","have got ready","are getting ready","were getting ready"],"correct":3,"answer":"were getting ready","vi":"Lúc mình gọi vào bảy giờ, các bạn mình đang chuẩn bị cho bữa tiệc, nên không ai nghe máy.","explanation":"A longer action in progress when a shorter past action (I called) interrupted it takes the past continuous: <b>were getting ready</b>."},{"id":"gv-kc-12-24","level":"kc","focus":"collocation","q":"We're ______ a party on Saturday to celebrate the end of the exams — can you come?","options":["making","doing","throwing","taking"],"correct":2,"answer":"throwing","vi":"Thứ Bảy này bọn mình tổ chức một bữa tiệc mừng thi xong — cậu đến được không?","explanation":"We <b>throw</b> (or have / hold) <b>a party</b>. <b>Make</b>, <b>do</b> and <b>take</b> do not collocate with <b>party</b>."},{"id":"gv-kc-12-25","level":"kc","focus":"inversion","q":"______ does Lan miss a homework deadline; she is the most organised student in the class.","options":["Not until","Rarely","No sooner","Only after"],"correct":1,"answer":"Rarely","vi":"Hiếm khi Lan trễ hạn nộp bài tập; cô ấy là học sinh ngăn nắp nhất lớp.","explanation":"A negative adverb like <b>Rarely</b> at the start of a sentence causes inversion: <b>Rarely does Lan miss</b>. <b>No sooner</b> needs <b>than</b>, and <b>Not until / Only after</b> need a time phrase or clause before the inverted verb."},{"id":"gv-kc-13-1","level":"kc","focus":"tense","q":"Mai ______ three novels by that author since January.","options":["read","is reading","has read","had read"],"correct":2,"answer":"has read","vi":"Từ tháng Một đến giờ Mai đã đọc ba cuốn tiểu thuyết của tác giả đó.","explanation":"<b>Since January</b> links a past starting point to now, so the present perfect <b>has read</b> is needed; the past simple and past perfect cut the action off from the present."},{"id":"gv-kc-13-2","level":"kc","focus":"word-choice","q":"My sister ______ the ending of the film in my ear so that nobody else in the cinema could hear.","options":["shouted","announced","whispered","declared"],"correct":2,"answer":"whispered","vi":"Chị tôi thì thầm vào tai tôi đoạn kết của bộ phim để không ai khác trong rạp nghe thấy.","explanation":"<b>So that nobody else could hear</b> tells you the words were said very quietly: <b>whisper</b>. <b>Shout</b> is loud, and <b>announce</b> / <b>declare</b> mean to say something openly to everyone."},{"id":"gv-kc-13-3","level":"kc","focus":"collocation","q":"We ______ a lot of money on new furniture for the living room.","options":["paid","spent","cost","took"],"correct":1,"answer":"spent","vi":"Chúng tôi đã tiêu rất nhiều tiền vào đồ nội thất mới cho phòng khách.","explanation":"The collocation is <b>spend money on</b> something. You <b>pay for</b> something, a thing <b>costs</b> money, and <b>take</b> does not go with money in this way."},{"id":"gv-kc-13-4","level":"kc","focus":"idiom","q":"Relax – it is only a tiny scratch on the car door. Don't ______.","options":["put all your eggs in one basket","bite off more than you can chew","kill two birds with one stone","make a mountain out of a molehill"],"correct":3,"answer":"make a mountain out of a molehill","vi":"Bình tĩnh đi, chỉ là một vết xước nhỏ xíu trên cửa xe thôi. Đừng có chuyện bé xé ra to.","explanation":"<b>Make a mountain out of a molehill</b> = treat a small problem as a big one. The others mean risking everything on one plan, taking on too much, and achieving two things at once."},{"id":"gv-kc-13-5","level":"kc","focus":"phrasal-verb","q":"We waited an hour outside the cinema, but Nam never ______.","options":["put up","turned down","turned up","turned off"],"correct":2,"answer":"turned up","vi":"Chúng tôi đợi cả tiếng ngoài rạp chiếu phim, nhưng Nam chẳng bao giờ xuất hiện.","explanation":"<b>Turn up</b> = arrive or appear. <b>Turn down</b> = refuse or lower the volume, <b>turn off</b> = switch off, and <b>put up</b> needs an object (put up a poster)."},{"id":"gv-kc-13-6","level":"kc","focus":"modal","q":"Nam ______ at the concert last night – I saw him at home at nine o'clock.","options":["mustn't have been","can't have been","needn't have been","shouldn't have been"],"correct":1,"answer":"can't have been","vi":"Tối qua Nam không thể nào ở buổi hòa nhạc được – lúc chín giờ tôi thấy cậu ấy ở nhà mà.","explanation":"<b>Can't have + past participle</b> expresses a confident conclusion that something was impossible in the past. <b>Mustn't have</b> is not used for deduction; <b>needn't have</b> and <b>shouldn't have</b> talk about necessity and advice."},{"id":"gv-kc-13-7","level":"kc","focus":"relative","q":"The coach with ______ we trained for the swimming competition has moved to another club.","options":["who","whose","which","whom"],"correct":3,"answer":"whom","vi":"Huấn luyện viên mà chúng tôi đã tập luyện cùng cho giải bơi đã chuyển sang câu lạc bộ khác.","explanation":"After a preposition (<b>with</b>) the relative pronoun for a person must be the object form <b>whom</b>: <b>with whom we trained</b>. <b>Who</b> cannot follow a preposition, <b>whose</b> needs a noun after it, and <b>which</b> refers to things."},{"id":"gv-kc-13-8","level":"kc","focus":"article-quantifier","q":"Linh has visited ______ countries in Asia, but she has never been to Japan.","options":["several","much","a little","every"],"correct":0,"answer":"several","vi":"Linh đã đi thăm vài nước ở châu Á, nhưng cô ấy chưa từng đến Nhật Bản.","explanation":"<b>Countries</b> is a plural countable noun, so it takes <b>several</b> (= a few, more than two). <b>Much</b> and <b>a little</b> go with uncountable nouns, and <b>every</b> must be followed by a singular noun."},{"id":"gv-kc-13-9","level":"kc","focus":"word-choice","q":"Could you ______ the last scene to me? I didn't understand why the hero left.","options":["complain","explain","persuade","argue"],"correct":1,"answer":"explain","vi":"Bạn giải thích cảnh cuối cho mình được không? Mình không hiểu tại sao nhân vật chính lại bỏ đi.","explanation":"<b>Explain something to someone</b> = make it clear. <b>Complain</b> = say you are unhappy, <b>persuade</b> takes a person as object, and you <b>argue with</b> someone, not a scene."},{"id":"gv-kc-13-10","level":"kc","focus":"gerund-infinitive","q":"Remember ______ the front door when you go out this evening.","options":["locking","lock","to locking","to lock"],"correct":3,"answer":"to lock","vi":"Nhớ khóa cửa trước khi con ra ngoài tối nay nhé.","explanation":"<b>Remember to do</b> = don't forget a task that is still to come. <b>Remember doing</b> looks back at a memory of something already done, so it does not fit an instruction."},{"id":"gv-kc-13-11","level":"kc","focus":"linking","q":"Nam still went to school ______ he had a bad cold and a sore throat.","options":["despite","in spite of","although","however"],"correct":2,"answer":"although","vi":"Nam vẫn đi học mặc dù cậu ấy bị cảm nặng và đau họng.","explanation":"A contrast followed by a full clause (<b>he had a bad cold</b>) needs the conjunction <b>although</b>. <b>Despite</b> and <b>in spite of</b> are followed by a noun or -ing form, and <b>however</b> is an adverb that cannot join two clauses like this."},{"id":"gv-kc-13-12","level":"kc","focus":"word-choice","q":"Could you ______ me to call Grandma tonight? I always forget.","options":["suggest","recommend","remind","mention"],"correct":2,"answer":"remind","vi":"Bạn nhắc mình gọi cho bà tối nay nhé? Mình lúc nào cũng quên.","explanation":"<b>Remind someone to do</b> something = help them not forget. <b>Suggest</b> and <b>recommend</b> do not take <b>someone to do</b>, and <b>mention</b> means to speak briefly about something."},{"id":"gv-kc-13-13","level":"kc","focus":"conditional","q":"I wish I ______ the film last night – everyone at school is talking about it.","options":["saw","have seen","had seen","would see"],"correct":2,"answer":"had seen","vi":"Giá mà tối qua tôi đã xem bộ phim đó – ở trường ai cũng đang bàn về nó.","explanation":"A wish about the <b>past</b> (last night) takes the past perfect: <b>wish + had seen</b>. <b>Saw</b> would be a wish about the present, and <b>would see</b> is for the future."},{"id":"gv-kc-13-14","level":"kc","focus":"collocation","q":"Could you ______ me a favour and return this book to the library?","options":["do","make","give","take"],"correct":0,"answer":"do","vi":"Bạn giúp mình một việc, trả cuốn sách này về thư viện được không?","explanation":"The fixed collocation is <b>do someone a favour</b>. <b>Make</b>, <b>give</b> and <b>take</b> do not combine with <b>favour</b> in this meaning."},{"id":"gv-kc-13-15","level":"kc","focus":"passive","q":"The film ______ in Da Lat last year, which is why the scenery looks so familiar.","options":["shot","has shot","is shot","was shot"],"correct":3,"answer":"was shot","vi":"Bộ phim được quay ở Đà Lạt năm ngoái, vì thế cảnh trong phim trông rất quen thuộc.","explanation":"The film does not shoot itself, so the passive is needed, and <b>last year</b> puts it in the past simple: <b>was shot</b>. <b>Is shot</b> is present, and <b>shot</b> / <b>has shot</b> are active."},{"id":"gv-kc-13-16","level":"kc","focus":"tense","q":"This time next week, my family ______ in our new house on the other side of town.","options":["live","will live","are living","will be living"],"correct":3,"answer":"will be living","vi":"Vào giờ này tuần sau, gia đình tôi sẽ đang sống trong ngôi nhà mới ở phía bên kia thành phố.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, so the future continuous <b>will be living</b> is used. <b>Will live</b> states a plain future fact, and <b>are living</b> is present."},{"id":"gv-kc-13-17","level":"kc","focus":"reported","q":"Mum asked me where ______ the TV remote after the film.","options":["had I put","I had put","did I put","have I put"],"correct":1,"answer":"I had put","vi":"Mẹ hỏi tôi đã để cái điều khiển ti vi ở đâu sau khi xem phim.","explanation":"In a reported question the word order is <b>subject + verb</b> (no inversion, no <b>did</b>), and <b>asked</b> moves the past simple back to the past perfect: <b>where I had put</b>. The other three keep the inverted order of a direct question."},{"id":"gv-kc-13-18","level":"kc","focus":"idiom","q":"After a long talk, my parents and I are finally ______ about my plan to study music.","options":["in the same boat","on the same page","under the weather","over the moon"],"correct":1,"answer":"on the same page","vi":"Sau một cuộc nói chuyện dài, cuối cùng bố mẹ và tôi cũng đã đồng quan điểm về kế hoạch học nhạc của tôi.","explanation":"<b>On the same page</b> = agreeing, sharing the same understanding. <b>In the same boat</b> = in the same difficult situation, <b>under the weather</b> = slightly ill, <b>over the moon</b> = very happy."},{"id":"gv-kc-13-19","level":"kc","focus":"preposition","q":"My sister is really keen ______ Korean pop music and knows every song by heart.","options":["in","of","at","on"],"correct":3,"answer":"on","vi":"Chị tôi rất mê nhạc pop Hàn Quốc và thuộc lòng mọi bài hát.","explanation":"The adjective <b>keen</b> takes the preposition <b>on</b>: <b>keen on</b> something. <b>Interested in</b>, <b>fond of</b> and <b>good at</b> are the patterns learners mix it up with."},{"id":"gv-kc-13-20","level":"kc","focus":"word-choice","q":"Please don't ______ while Grandma is telling her story – wait until she finishes.","options":["interrupt","repeat","describe","pronounce"],"correct":0,"answer":"interrupt","vi":"Đừng ngắt lời khi bà đang kể chuyện – hãy đợi bà kể xong đã.","explanation":"<b>Interrupt</b> = start speaking while someone else is still talking. <b>Repeat</b>, <b>describe</b> and <b>pronounce</b> all need an object and do not fit <b>wait until she finishes</b>."},{"id":"gv-kc-13-21","level":"kc","focus":"phrasal-verb","q":"My parents couldn't ______ how to use the new TV remote, so I showed them.","options":["work out","work up","carry out","set out"],"correct":0,"answer":"work out","vi":"Bố mẹ tôi không tìm ra cách dùng cái điều khiển ti vi mới, nên tôi chỉ cho họ.","explanation":"<b>Work out</b> = find the answer to something by thinking. <b>Carry out</b> = perform a task, <b>set out</b> = begin a journey, and <b>work up</b> = build up (an appetite, courage)."},{"id":"gv-kc-13-22","level":"kc","focus":"comparison","q":"The more pocket money you save now, ______ you can spend on the school trip.","options":["more","the more","the most","most"],"correct":1,"answer":"the more","vi":"Bây giờ bạn càng để dành nhiều tiền tiêu vặt, thì bạn càng có nhiều tiền để chi cho chuyến đi của trường.","explanation":"The double comparative pattern is <b>the more ..., the more ...</b>: both halves need <b>the</b> plus a comparative, never a superlative."},{"id":"gv-kc-13-23","level":"kc","focus":"tense","q":"By the time the film ended, the painkiller ______, and my tooth hurt again.","options":["wore off","had worn off","has worn off","wears off"],"correct":1,"answer":"had worn off","vi":"Đến lúc bộ phim kết thúc thì thuốc giảm đau đã hết tác dụng, và răng tôi lại đau.","explanation":"<b>By the time + past simple</b> marks a point in the past before which the other action was already complete, so it takes the past perfect: <b>had worn off</b> (stopped having an effect). <b>Has worn off</b> and <b>wears off</b> are present tenses."},{"id":"gv-kc-13-24","level":"kc","focus":"collocation","q":"The bookshop ______ a twenty per cent discount on all novels this week.","options":["offers","makes","does","brings"],"correct":0,"answer":"offers","vi":"Tuần này hiệu sách giảm giá hai mươi phần trăm cho tất cả tiểu thuyết.","explanation":"A shop <b>offers</b> (or gives) <b>a discount</b>. <b>Make</b>, <b>do</b> and <b>bring</b> do not collocate with <b>discount</b>."},{"id":"gv-kc-13-25","level":"kc","focus":"word-choice","q":"The shop assistant ______ that the phone was cheaper online, so we didn't buy it there.","options":["admitted","denied","refused","promised"],"correct":0,"answer":"admitted","vi":"Nhân viên cửa hàng thừa nhận rằng chiếc điện thoại mua trên mạng rẻ hơn, nên chúng tôi không mua ở đó.","explanation":"<b>Admit that</b> = agree that something (often unwelcome) is true. <b>Deny</b> is the opposite, <b>refuse</b> is not followed by a <b>that</b>-clause, and <b>promise that</b> would not lead to <b>we didn't buy it</b>."},{"id":"gv-kc-14-1","level":"kc","focus":"word-choice","q":"It was so dark in the clinic corridor that I had to ______ at the sign to read the doctor's name.","options":["glimpse","peer","notice","observe"],"correct":1,"answer":"peer","vi":"Hành lang phòng khám tối đến nỗi tôi phải nheo mắt nhìn kỹ tấm biển mới đọc được tên bác sĩ.","explanation":"<b>Peer at</b> means to look closely and with difficulty, often because it is dark. <b>Glimpse</b>, <b>notice</b> and <b>observe</b> take a direct object and none of them means looking hard to see."},{"id":"gv-kc-14-2","level":"kc","focus":"word-choice","q":"Can you ______ any spelling mistakes in my post before I upload it?","options":["spot","glance","stare","gaze"],"correct":0,"answer":"spot","vi":"Bạn có thể phát hiện lỗi chính tả nào trong bài đăng của mình trước khi mình tải lên không?","explanation":"<b>Spot</b> means to see or notice something that is hard to find. <b>Glance</b>, <b>stare</b> and <b>gaze</b> describe ways of looking and need <b>at</b>; they cannot take 'mistakes' as an object."},{"id":"gv-kc-14-3","level":"kc","focus":"word-choice","q":"The little boy ______ at the goldfish in the doctor's waiting room for almost an hour.","options":["glimpsed","spotted","gazed","noticed"],"correct":2,"answer":"gazed","vi":"Cậu bé ngắm nhìn đàn cá vàng trong phòng chờ của bác sĩ gần cả tiếng đồng hồ.","explanation":"<b>Gaze at</b> is to look steadily for a long time, which fits 'for almost an hour'. <b>Glimpse</b>, <b>spot</b> and <b>notice</b> are momentary and take a direct object, not <b>at</b>."},{"id":"gv-kc-14-4","level":"kc","focus":"word-choice","q":"I only caught a ______ of the famous striker before the crowd closed in around him.","options":["glance","view","stare","glimpse"],"correct":3,"answer":"glimpse","vi":"Tôi chỉ kịp thoáng thấy cầu thủ tiền đạo nổi tiếng trước khi đám đông vây quanh anh ấy.","explanation":"<b>Catch a glimpse of</b> = see something very briefly. A <b>glance</b> is a quick look you <b>take</b>, not catch; <b>view</b> and <b>stare</b> do not fit this expression."},{"id":"gv-kc-14-5","level":"kc","focus":"word-choice","q":"Lan spent the whole evening ______ the internet for a second-hand bicycle.","options":["browsing","peeking","glancing","staring"],"correct":0,"answer":"browsing","vi":"Lan dành cả buổi tối lướt mạng để tìm một chiếc xe đạp cũ.","explanation":"<b>Browse the internet</b> means to look through websites without a fixed plan. <b>Peek</b>, <b>glance</b> and <b>stare</b> need <b>at</b> and describe a single look, not searching online."},{"id":"gv-kc-14-6","level":"kc","focus":"collocation","q":"Please ______ attention to the road signs when you cycle through the city centre.","options":["pay","take","make","put"],"correct":0,"answer":"pay","vi":"Hãy chú ý các biển báo giao thông khi bạn đạp xe qua trung tâm thành phố.","explanation":"The fixed collocation is <b>pay attention to</b>. We do not <b>take</b>, <b>make</b> or <b>put</b> attention."},{"id":"gv-kc-14-7","level":"kc","focus":"collocation","q":"When the teacher asked who had broken the window, Nam decided to ______ the truth.","options":["say","speak","tell","talk"],"correct":2,"answer":"tell","vi":"Khi cô giáo hỏi ai đã làm vỡ cửa sổ, Nam quyết định nói thật.","explanation":"<b>Tell the truth</b> (like tell a lie, tell a story) is the fixed collocation. <b>Say</b> reports words, not truth or lies, and <b>speak</b> and <b>talk</b> do not take this object."},{"id":"gv-kc-14-8","level":"kc","focus":"collocation","q":"My grandfather cycles ten kilometres every morning to ______ fit.","options":["hold","make","go","keep"],"correct":3,"answer":"keep","vi":"Ông tôi đạp xe mười ki-lô-mét mỗi sáng để giữ gìn sức khỏe.","explanation":"<b>Keep fit</b> (or stay fit) is the collocation for staying healthy through exercise. <b>Hold fit</b>, <b>make fit</b> and <b>go fit</b> are not English."},{"id":"gv-kc-14-9","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Minh: He ______ badminton at the sports centre. He'll be home by six.","options":["plays","is playing","has played","played"],"correct":1,"answer":"is playing","vi":"Lan: Nam đâu rồi? / Minh: Cậu ấy đang chơi cầu lông ở trung tâm thể thao. Sáu giờ cậu ấy sẽ về.","explanation":"An action happening <b>right now</b> takes the present continuous: <b>is playing</b>. The present simple describes habits and the past forms describe finished actions."},{"id":"gv-kc-14-10","level":"kc","focus":"tense","q":"I ______ this phone for three years, and the battery still lasts all day.","options":["had","am having","have had","have"],"correct":2,"answer":"have had","vi":"Tôi đã dùng chiếc điện thoại này ba năm rồi mà pin vẫn dùng được cả ngày.","explanation":"<b>For three years</b> with a situation that continues to now needs the present perfect: <b>have had</b>. <b>Had</b> would mean I no longer have it, and <b>have</b> (possess) is not used in the continuous."},{"id":"gv-kc-14-11","level":"kc","focus":"tense","q":"Lan: Are you free on Sunday? / Nam: No, I ______ my cousin in Da Lat. We booked the bus tickets last week.","options":["visit","visited","have visited","am visiting"],"correct":3,"answer":"am visiting","vi":"Lan: Chủ nhật bạn có rảnh không? / Nam: Không, mình đi thăm anh họ ở Đà Lạt. Bọn mình đặt vé xe từ tuần trước rồi.","explanation":"A fixed future arrangement (the tickets are already booked) takes the present continuous: <b>am visiting</b>. The present simple is for timetables, not personal plans, and the past forms do not describe the future."},{"id":"gv-kc-14-12","level":"kc","focus":"idiom","q":"Mai was ______ when she found out she had won the chess tournament.","options":["under the weather","over the moon","on the fence","in the dark"],"correct":1,"answer":"over the moon","vi":"Mai vui sướng tột độ khi biết mình đã thắng giải cờ vua.","explanation":"<b>Over the moon</b> = extremely happy. <b>Under the weather</b> = slightly ill, <b>on the fence</b> = undecided, <b>in the dark</b> = not informed."},{"id":"gv-kc-14-13","level":"kc","focus":"idiom","q":"After months of talking about it, my brother finally ______ and signed up for the marathon.","options":["took the plunge","took the biscuit","took the floor","took the hint"],"correct":0,"answer":"took the plunge","vi":"Sau nhiều tháng chỉ nói suông, cuối cùng anh tôi cũng quyết tâm dấn thân và đăng ký chạy marathon.","explanation":"<b>Take the plunge</b> = finally decide to do something big or risky after hesitating. <b>Take the biscuit</b> = be the most annoying, <b>take the floor</b> = start speaking, <b>take the hint</b> = understand an indirect message."},{"id":"gv-kc-14-14","level":"kc","focus":"phrasal-verb","q":"Don't ______ our team just because we lost the first two matches of the season.","options":["write down","write up","write off","write out"],"correct":2,"answer":"write off","vi":"Đừng vội coi đội mình là vô vọng chỉ vì thua hai trận đầu mùa giải.","explanation":"<b>Write off</b> = decide that someone or something is a failure and no longer worth attention. <b>Write down</b> = note, <b>write up</b> = write a full report, <b>write out</b> = write in full."},{"id":"gv-kc-14-15","level":"kc","focus":"phrasal-verb","q":"Nam refused to ______ in the argument about which phone is better, even when he was clearly wrong.","options":["back up","back out","back away","back down"],"correct":3,"answer":"back down","vi":"Nam nhất quyết không chịu nhượng bộ trong cuộc tranh cãi xem điện thoại nào tốt hơn, dù cậu ấy rõ ràng đã sai.","explanation":"<b>Back down</b> = admit you are wrong and stop arguing. <b>Back up</b> = support or copy data, <b>back out</b> = withdraw from an agreement, <b>back away</b> = move backwards physically."},{"id":"gv-kc-14-16","level":"kc","focus":"modal","q":"Lan: Nam isn't answering his phone. / Mai: He ______ be at the doctor's; he said he had an appointment at nine.","options":["can't","must","needn't","mustn't"],"correct":1,"answer":"must","vi":"Lan: Nam không nghe điện thoại. / Mai: Chắc chắn cậu ấy đang ở chỗ bác sĩ; cậu ấy nói có hẹn lúc chín giờ.","explanation":"<b>Must</b> expresses a logical deduction that something is almost certainly true. <b>Can't</b> would mean it is impossible, and <b>needn't</b> / <b>mustn't</b> express necessity or prohibition, not deduction."},{"id":"gv-kc-14-17","level":"kc","focus":"relative","q":"The doctor ______ treated my grandmother has just opened a clinic near our school.","options":["whom","whose","which","who"],"correct":3,"answer":"who","vi":"Vị bác sĩ đã chữa bệnh cho bà tôi vừa mở một phòng khám gần trường chúng tôi.","explanation":"The relative pronoun is the <b>subject</b> of 'treated' and refers to a person, so <b>who</b> is needed. <b>Whom</b> is for objects, <b>whose</b> shows possession and <b>which</b> is for things."},{"id":"gv-kc-14-18","level":"kc","focus":"article-quantifier","q":"Only ______ people in my class still use a phone without internet access.","options":["a little","a few","much","little"],"correct":1,"answer":"a few","vi":"Chỉ một vài bạn trong lớp tôi còn dùng điện thoại không có kết nối mạng.","explanation":"<b>People</b> is a plural countable noun, so it takes <b>a few</b>. <b>A little</b>, <b>much</b> and <b>little</b> are used only with uncountable nouns."},{"id":"gv-kc-14-19","level":"kc","focus":"gerund-infinitive","q":"Remember ______ your phone before the exam starts, or the teacher will take it away.","options":["switching off","to switch off","switch off","to switching off"],"correct":1,"answer":"to switch off","vi":"Nhớ tắt điện thoại trước khi bài thi bắt đầu, nếu không cô giáo sẽ thu đấy.","explanation":"<b>Remember to do</b> = do not forget a duty you still have to do. <b>Remember doing</b> refers to a memory of something already done, and the other two forms are not grammatical after remember."},{"id":"gv-kc-14-20","level":"kc","focus":"linking","q":"Mai forgot to water the plants on the balcony for two weeks; ______, most of them died.","options":["as a result","even so","in addition","on the contrary"],"correct":0,"answer":"as a result","vi":"Mai quên tưới cây trên ban công suốt hai tuần; kết quả là phần lớn cây đều chết.","explanation":"The second clause is the <b>consequence</b> of the first, so we need <b>as a result</b>. <b>Even so</b> and <b>on the contrary</b> express contrast, and <b>in addition</b> adds a similar point."},{"id":"gv-kc-14-21","level":"kc","focus":"conditional","q":"If my dad hadn't bailed me out, I ______ my phone bill last month.","options":["couldn't have paid","couldn't pay","can't pay","won't pay"],"correct":0,"answer":"couldn't have paid","vi":"Nếu bố không giúp tôi thoát khỏi cảnh túng thiếu, tháng trước tôi đã không thể trả nổi tiền cước điện thoại.","explanation":"An unreal past situation (third conditional) uses <b>if + past perfect</b> in one clause and <b>could/would have + past participle</b> in the other: <b>couldn't have paid</b>."},{"id":"gv-kc-14-22","level":"kc","focus":"agreement","q":"Neither the coach nor the players ______ happy with the referee's decision.","options":["was","is","has been","were"],"correct":3,"answer":"were","vi":"Cả huấn luyện viên lẫn các cầu thủ đều không hài lòng với quyết định của trọng tài.","explanation":"With <b>neither ... nor</b>, the verb agrees with the <b>nearer</b> subject. 'The players' is plural, so the verb is <b>were</b>."},{"id":"gv-kc-14-23","level":"kc","focus":"participle","q":"______ by a virus from a free download site, my laptop stopped working completely.","options":["Infecting","Having infected","Infected","To infect"],"correct":2,"answer":"Infected","vi":"Bị nhiễm vi-rút từ một trang tải miễn phí, máy tính xách tay của tôi ngừng hoạt động hoàn toàn.","explanation":"The laptop was infected (it did not infect anything), so a <b>past participle</b> with passive meaning opens the clause: <b>Infected by</b>. The active forms and the infinitive make the laptop the one doing the infecting."},{"id":"gv-kc-14-24","level":"kc","focus":"pronoun","q":"______ finishes the crossword first will get a free ice cream from Dad.","options":["Whomever","Whom","Whose","Whoever"],"correct":3,"answer":"Whoever","vi":"Ai giải xong ô chữ trước sẽ được bố thưởng một cây kem miễn phí.","explanation":"<b>Whoever</b> = 'the person who' and acts as the <b>subject</b> of 'finishes'. <b>Whomever</b> and <b>whom</b> are object forms, and <b>whose</b> shows possession."},{"id":"gv-kc-14-25","level":"kc","focus":"question-tag","q":"You haven't been to the dentist for two years, ______?","options":["have you","haven't you","did you","do you"],"correct":0,"answer":"have you","vi":"Hai năm nay bạn chưa đi khám nha sĩ, đúng không?","explanation":"A negative present perfect statement (<b>haven't been</b>) takes a positive tag with the same auxiliary: <b>have you</b>."},{"id":"gv-kc-15-1","level":"kc","focus":"tense","q":"Look! A whale ______ right next to our boat!","options":["swims","is swimming","swam","has swum"],"correct":1,"answer":"is swimming","vi":"Nhìn kìa! Một con cá voi đang bơi ngay cạnh thuyền của chúng ta!","explanation":"<b>Look!</b> points to something happening at this moment, so the present continuous <b>is swimming</b> is needed; the present simple, past simple and present perfect do not describe an action in progress now."},{"id":"gv-kc-15-2","level":"kc","focus":"word-choice","q":"Lan ______ the early bus to the beach because she woke up late.","options":["missed","lost","failed","dropped"],"correct":0,"answer":"missed","vi":"Lan lỡ chuyến xe buýt sớm ra biển vì cô ấy dậy muộn.","explanation":"You <b>miss</b> a bus or train when you arrive too late to catch it. You <b>lose</b> an object or a match, you <b>fail</b> an exam, and you <b>drop</b> something you are holding."},{"id":"gv-kc-15-3","level":"kc","focus":"collocation","q":"The boat trip was cancelled because of ______ winds along the coast.","options":["heavy","hard","strong","big"],"correct":2,"answer":"strong","vi":"Chuyến đi thuyền bị hủy vì gió mạnh dọc bờ biển.","explanation":"Wind that blows with great force is <b>strong wind</b>. <b>Heavy</b> collocates with rain and snow, while <b>hard</b> and <b>big</b> do not go with wind."},{"id":"gv-kc-15-4","level":"kc","focus":"idiom","q":"The hotel was lovely, and the free boat trip to the island was ______.","options":["the tip of the iceberg","a piece of cake","the last straw","the icing on the cake"],"correct":3,"answer":"the icing on the cake","vi":"Khách sạn rất đẹp, và chuyến đi thuyền miễn phí ra đảo là phần thưởng tuyệt vời thêm vào.","explanation":"<b>The icing on the cake</b> is something extra that makes a good situation even better. <b>The tip of the iceberg</b> is a small visible part of a big problem, <b>a piece of cake</b> is something very easy, and <b>the last straw</b> is the final problem that makes you lose patience."},{"id":"gv-kc-15-5","level":"kc","focus":"phrasal-verb","q":"Let's stay inside the tent until the storm ______.","options":["blows over","blows up","blows out","breaks down"],"correct":0,"answer":"blows over","vi":"Chúng ta hãy ở trong lều cho đến khi cơn bão qua đi.","explanation":"A storm or an argument <b>blows over</b> when it passes and ends. <b>Blow up</b> means to explode, <b>blow out</b> is what you do to a candle, and a car or machine <b>breaks down</b> when it stops working."},{"id":"gv-kc-15-6","level":"kc","focus":"modal","q":"The dog ______ the gate open by itself; it was locked all night.","options":["mustn't have pushed","can't have pushed","shouldn't have pushed","needn't have pushed"],"correct":1,"answer":"can't have pushed","vi":"Con chó không thể nào tự đẩy cổng mở được; cổng đã bị khóa suốt đêm.","explanation":"<b>Can't have + past participle</b> says we are sure something did NOT happen in the past. <b>Mustn't have</b> is not used for past deduction, <b>shouldn't have</b> criticises an action that did happen, and <b>needn't have</b> means it was unnecessary."},{"id":"gv-kc-15-7","level":"kc","focus":"relative","q":"The whole class passed the chemistry test, ______ the teacher very proud.","options":["that made","what made","which made","who made"],"correct":2,"answer":"which made","vi":"Cả lớp đều đậu bài kiểm tra Hóa, điều đó khiến cô giáo rất tự hào.","explanation":"After a comma, <b>which</b> can refer back to the WHOLE previous clause (the fact that the class passed), so <b>, which made</b> is correct. <b>That</b> cannot follow a comma in this way, <b>what</b> does not refer back to a clause, and <b>who</b> is only for people."},{"id":"gv-kc-15-8","level":"kc","focus":"word-choice","q":"Our school team ______ the visitors 3–1 in the final of the eco-quiz.","options":["won","gained","achieved","beat"],"correct":3,"answer":"beat","vi":"Đội trường mình đã thắng đội khách 3–1 trong trận chung kết cuộc thi đố vui về môi trường.","explanation":"You <b>beat</b> a person or a team (the opponent). You <b>win</b> a match or a prize, and you <b>gain</b> or <b>achieve</b> something such as experience or a goal, never an opponent."},{"id":"gv-kc-15-9","level":"kc","focus":"tense","q":"By next summer, my family ______ every beach in Da Nang.","options":["will have visited","will visit","has visited","is visiting"],"correct":0,"answer":"will have visited","vi":"Đến mùa hè năm sau, gia đình tôi sẽ đi hết mọi bãi biển ở Đà Nẵng.","explanation":"<b>By + a future time</b> marks an action completed before that point, so the future perfect <b>will have visited</b> is used; the simple future, present perfect and present continuous do not show completion by a deadline."},{"id":"gv-kc-15-10","level":"kc","focus":"article-quantifier","q":"Don't worry about lunch – Mum has packed ______ sandwiches for the whole group.","options":["much","plenty of","a great deal of","a large amount of"],"correct":1,"answer":"plenty of","vi":"Đừng lo về bữa trưa – mẹ đã gói rất nhiều bánh mì kẹp cho cả nhóm rồi.","explanation":"<b>Plenty of</b> (more than enough) is used with BOTH plural countable nouns like <b>sandwiches</b> and uncountable nouns. <b>Much</b>, <b>a great deal of</b> and <b>a large amount of</b> go only with uncountable nouns."},{"id":"gv-kc-15-11","level":"kc","focus":"gerund-infinitive","q":"Before our trip to Australia, Dad spent every evening ______ his English.","options":["to brush up on","brush up on","brushing up on","brushed up on"],"correct":2,"answer":"brushing up on","vi":"Trước chuyến đi Úc, bố dành mỗi tối để ôn lại tiếng Anh.","explanation":"<b>Spend time + -ing</b>: <b>spent every evening brushing up on</b> (improving his knowledge again). An infinitive, a base form or a past form cannot follow <b>spend time</b>."},{"id":"gv-kc-15-12","level":"kc","focus":"collocation","q":"We ______ hundreds of photos of the elephants at the sanctuary.","options":["made","did","caught","took"],"correct":3,"answer":"took","vi":"Chúng tôi đã chụp hàng trăm bức ảnh về những con voi ở khu bảo tồn.","explanation":"In English you <b>take a photo</b>. <b>Make</b>, <b>do</b> and <b>catch</b> do not collocate with <b>photo</b>."},{"id":"gv-kc-15-13","level":"kc","focus":"word-choice","q":"The zoo's plan to breed rare parrots ended in ______ when none of the eggs hatched.","options":["failure","defeat","loss","mistake"],"correct":0,"answer":"failure","vi":"Kế hoạch nhân giống vẹt quý hiếm của sở thú đã thất bại khi không quả trứng nào nở.","explanation":"A plan that does not achieve its aim <b>ends in failure</b>. A <b>defeat</b> is being beaten by an opponent in a contest, a <b>loss</b> is something you no longer have, and a <b>mistake</b> is a wrong action, not a result."},{"id":"gv-kc-15-14","level":"kc","focus":"linking","q":"Living in the city centre is exciting; ______, the rent costs a fortune.","options":["in addition","on the other hand","as a result","for instance"],"correct":1,"answer":"on the other hand","vi":"Sống ở trung tâm thành phố rất thú vị; mặt khác, tiền thuê nhà thì đắt khủng khiếp.","explanation":"<b>On the other hand</b> presents the opposite side of a situation (exciting, but expensive). <b>In addition</b> adds a similar point, <b>as a result</b> shows a consequence, and <b>for instance</b> gives an example."},{"id":"gv-kc-15-15","level":"kc","focus":"phrasal-verb","q":"Choosing where to go on holiday usually ______ how much money you have.","options":["boils over","breaks down","boils down to","puts up with"],"correct":2,"answer":"boils down to","vi":"Việc chọn đi nghỉ ở đâu thường quy về chuyện bạn có bao nhiêu tiền.","explanation":"Something <b>boils down to</b> one thing when that thing is the real deciding factor. <b>Boil over</b> is what milk does on the stove, <b>break down</b> means to stop working, and <b>put up with</b> means to tolerate."},{"id":"gv-kc-15-16","level":"kc","focus":"modal","q":"You ______ bring a tent; the campsite lends them to visitors for free.","options":["mustn't","can't","shouldn't","needn't"],"correct":3,"answer":"needn't","vi":"Bạn không cần mang lều; khu cắm trại cho khách mượn miễn phí.","explanation":"<b>Needn't</b> means it is not necessary, which fits the reason given. <b>Mustn't</b> and <b>can't</b> express prohibition or impossibility, and <b>shouldn't</b> gives advice against something."},{"id":"gv-kc-15-17","level":"kc","focus":"tense","q":"My family ______ in this fishing village since my grandfather was a boy.","options":["have lived","live","lived","are living"],"correct":0,"answer":"have lived","vi":"Gia đình tôi đã sống ở làng chài này từ khi ông tôi còn là một cậu bé.","explanation":"<b>Since + a past time</b> with a situation that continues up to now takes the present perfect <b>have lived</b>; the present simple, past simple and present continuous do not link the past starting point to the present."},{"id":"gv-kc-15-18","level":"kc","focus":"conditional","q":"Lan wishes she ______ her camera to the bird park yesterday.","options":["brought","had brought","has brought","would bring"],"correct":1,"answer":"had brought","vi":"Lan ước gì hôm qua cô ấy đã mang máy ảnh đến công viên chim.","explanation":"A regret about the past (<b>yesterday</b>) uses <b>wish + past perfect</b>: <b>had brought</b>. <b>Wish + past simple</b> is for a present situation, and the present perfect and <b>would</b> are not used after <b>wish</b> here."},{"id":"gv-kc-15-19","level":"kc","focus":"word-choice","q":"It took the campers three ______ to light the fire in the wet forest.","options":["efforts","trials","attempts","tests"],"correct":2,"answer":"attempts","vi":"Những người cắm trại phải thử đến ba lần mới nhóm được lửa trong khu rừng ẩm ướt.","explanation":"An <b>attempt</b> is one act of trying to do something, so you count <b>three attempts</b>. <b>Effort</b> is the energy you use, a <b>trial</b> is a scientific or legal test, and a <b>test</b> checks knowledge or quality."},{"id":"gv-kc-15-20","level":"kc","focus":"relative","q":"The beach ______ we camped last year is now closed to protect the sea turtles.","options":["which","that","whom","where"],"correct":3,"answer":"where","vi":"Bãi biển nơi chúng tôi cắm trại năm ngoái nay đã đóng cửa để bảo vệ rùa biển.","explanation":"<b>Where</b> replaces a place adverb (we camped <b>there</b>). <b>Which</b> and <b>that</b> would need a preposition (<b>on which</b>), and <b>whom</b> is only for people."},{"id":"gv-kc-15-21","level":"kc","focus":"idiom","q":"The showers at the campsite were not ______, so we complained to the owner.","options":["up to scratch","up in the air","up in arms","under the weather"],"correct":0,"answer":"up to scratch","vi":"Nhà tắm ở khu cắm trại không đạt yêu cầu, nên chúng tôi đã phàn nàn với chủ khu.","explanation":"<b>Up to scratch</b> means of an acceptable standard. <b>Up in the air</b> means still undecided, <b>up in arms</b> means very angry about something, and <b>under the weather</b> means slightly ill."},{"id":"gv-kc-15-22","level":"kc","focus":"inversion","q":"______ had we reached the campsite when it began to pour with rain.","options":["No sooner","Hardly","Not until","Only when"],"correct":1,"answer":"Hardly","vi":"Chúng tôi vừa mới tới khu cắm trại thì trời bắt đầu mưa như trút nước.","explanation":"<b>Hardly + had + subject + past participle ... when</b> means one thing happened immediately after another. <b>No sooner</b> pairs with <b>than</b>, not <b>when</b>, and <b>not until</b> and <b>only when</b> need a full clause before the inversion."},{"id":"gv-kc-15-23","level":"kc","focus":"collocation","q":"The guide told us to ______ a close eye on our bags at the night market.","options":["hold","take","keep","put"],"correct":2,"answer":"keep","vi":"Hướng dẫn viên bảo chúng tôi để mắt kỹ tới túi xách của mình ở chợ đêm.","explanation":"The fixed expression is <b>keep an eye on</b> something (watch it carefully). <b>Hold</b>, <b>take</b> and <b>put</b> do not form this collocation with <b>eye</b>."},{"id":"gv-kc-15-24","level":"kc","focus":"tense","q":"Mai ______ her passport twice before she finally found it in her coat pocket.","options":["has checked","checks","is checking","had checked"],"correct":3,"answer":"had checked","vi":"Mai đã kiểm tra hộ chiếu hai lần trước khi cuối cùng tìm thấy nó trong túi áo khoác.","explanation":"The checking happened <b>before</b> another past action (she found it), so the past perfect <b>had checked</b> is needed; the present tenses cannot describe an earlier past event."},{"id":"gv-kc-15-25","level":"kc","focus":"word-choice","q":"The baby turtle ______ to reach the sea before the seagulls noticed it.","options":["managed","succeeded","achieved","reached"],"correct":0,"answer":"managed","vi":"Chú rùa con đã tìm được cách ra tới biển trước khi lũ mòng biển phát hiện.","explanation":"<b>Manage to + verb</b> means to succeed in doing something difficult. <b>Succeed</b> needs <b>in + -ing</b>, and <b>achieve</b> and <b>reach</b> take a noun object (a goal, a place), not a to-infinitive."},{"id":"gv-kc-16-1","level":"kc","focus":"tense","q":"Lan: Where's Nam? / Mai: He ______ dumplings in the kitchen since noon.","options":["makes","is making","has been making","made"],"correct":2,"answer":"has been making","vi":"Lan: Nam đâu rồi? / Mai: Cậu ấy gói bánh trong bếp từ trưa tới giờ.","explanation":"<b>Since noon</b> marks an action that started in the past and is still going on, so the present perfect continuous <b>has been making</b> is needed."},{"id":"gv-kc-16-2","level":"kc","focus":"word-choice","q":"I still ______ Nam fifty thousand dong for the bánh mì he bought me yesterday.","options":["owe","own","lend","keep"],"correct":0,"answer":"owe","vi":"Tôi vẫn còn nợ Nam năm mươi nghìn tiền ổ bánh mì cậu ấy mua cho tôi hôm qua.","explanation":"<b>Owe</b> someone money = you must pay it back. <b>Own</b> means possess, <b>lend</b> is giving money out, and <b>keep</b> does not take two objects like this."},{"id":"gv-kc-16-3","level":"kc","focus":"idiom","q":"Lan: Sorry, I'm an hour late for the dumpling class! / Nam: Well, ______.","options":["better safe than sorry","better late than never","easier said than done","no pain, no gain"],"correct":1,"answer":"better late than never","vi":"Lan: Xin lỗi, mình đến lớp gói bánh trễ cả tiếng! / Nam: Thôi, trễ còn hơn không.","explanation":"<b>Better late than never</b> is what you say when someone arrives late but you are still glad they came. The other three are real sayings, but they do not answer an apology for being late."},{"id":"gv-kc-16-4","level":"kc","focus":"collocation","q":"Lan ______ a photo of the lantern display and sent it to her cousin in Da Nang.","options":["made","did","got","took"],"correct":3,"answer":"took","vi":"Lan chụp một tấm ảnh gian trưng bày lồng đèn rồi gửi cho em họ ở Đà Nẵng.","explanation":"English says <b>take a photo</b> (here in the past: <b>took</b>). <b>Make</b>, <b>do</b> and <b>get</b> do not collocate with <b>a photo</b> in this sense."},{"id":"gv-kc-16-5","level":"kc","focus":"phrasal-verb","q":"Everyone in our street ______ to buy lanterns for the Mid-Autumn party.","options":["chipped in","dropped in","chipped away","gave in"],"correct":0,"answer":"chipped in","vi":"Cả xóm tôi góp tiền mua lồng đèn cho buổi tiệc Trung thu.","explanation":"<b>Chip in</b> = each person gives some money towards a shared cost. <b>Drop in</b> is a short visit, <b>chip away</b> is to remove bit by bit, and <b>give in</b> is to surrender."},{"id":"gv-kc-16-6","level":"kc","focus":"modal","q":"Lan: The bánh chưng is burnt! / Nam: You ______ the heat on so high.","options":["needn't have left","mustn't have left","shouldn't have left","couldn't have left"],"correct":2,"answer":"shouldn't have left","vi":"Lan: Bánh chưng bị khét rồi! / Nam: Đáng lẽ cậu không nên để lửa to như thế.","explanation":"<b>Shouldn't have + past participle</b> criticises a past action that was a mistake. <b>Needn't have</b> means it was unnecessary, <b>couldn't have</b> is a deduction (it was impossible), and <b>mustn't have</b> is not a form English uses for past criticism."},{"id":"gv-kc-16-7","level":"kc","focus":"word-choice","q":"We can't ______ to eat out every night, so I cook at home most days.","options":["pay","afford","spend","cost"],"correct":1,"answer":"afford","vi":"Nhà tôi không đủ tiền ăn ngoài mỗi tối, nên hầu như ngày nào tôi cũng nấu ở nhà.","explanation":"<b>Can't afford to do something</b> = not have enough money for it. <b>Pay</b> and <b>spend</b> need an amount or object, and <b>cost</b> takes a thing, not a person, as its subject."},{"id":"gv-kc-16-8","level":"kc","focus":"relative","q":"The town ______ my grandparents live is famous for its floating market.","options":["which","who","that","where"],"correct":3,"answer":"where","vi":"Thị trấn nơi ông bà tôi sống nổi tiếng với chợ nổi.","explanation":"<b>My grandparents live</b> is a complete clause, so the relative adverb <b>where</b> (= in which) is needed after a place. <b>Which</b> and <b>that</b> would need a preposition (<b>in which</b>), and <b>who</b> is for people."},{"id":"gv-kc-16-9","level":"kc","focus":"tense","q":"This time next week we ______ mooncakes at the Mid-Autumn fair.","options":["will be eating","are eating","will have eaten","eat"],"correct":0,"answer":"will be eating","vi":"Giờ này tuần sau chúng ta sẽ đang ăn bánh trung thu ở hội chợ Trung thu.","explanation":"<b>This time next week</b> points to an action in progress at a future moment, so the future continuous <b>will be eating</b> is correct."},{"id":"gv-kc-16-10","level":"kc","focus":"collocation","q":"If we don't hurry, we'll ______ the last bus home.","options":["lose","miss","drop","fail"],"correct":1,"answer":"miss","vi":"Nếu không nhanh lên, chúng ta sẽ lỡ chuyến xe buýt cuối về nhà.","explanation":"You <b>miss</b> a bus, a train or a plane when you arrive too late for it. <b>Lose</b>, <b>drop</b> and <b>fail</b> do not collocate with <b>the bus</b>."},{"id":"gv-kc-16-11","level":"kc","focus":"preposition","q":"My mother is very proud ______ her recipe for fish sauce dressing.","options":["on","with","of","about"],"correct":2,"answer":"of","vi":"Mẹ tôi rất tự hào về công thức nước mắm chấm của bà.","explanation":"The adjective <b>proud</b> is always followed by <b>of</b>: <b>proud of</b> someone / something."},{"id":"gv-kc-16-12","level":"kc","focus":"word-choice","q":"Remember to ______ the cookery book to the library by Friday.","options":["borrow","lend","rent","return"],"correct":3,"answer":"return","vi":"Nhớ trả cuốn sách nấu ăn cho thư viện trước thứ Sáu nhé.","explanation":"<b>Return</b> = give something back. <b>Borrow</b> is taking it, <b>lend</b> is giving your own thing out, and you <b>rent</b> a room or a bike, not a library book."},{"id":"gv-kc-16-13","level":"kc","focus":"phrasal-verb","q":"Half the class ______ flu after eating ice cream in the rain at the fair.","options":["came up with","came down with","put up with","came across"],"correct":1,"answer":"came down with","vi":"Nửa lớp bị cúm sau khi ăn kem dưới mưa ở hội chợ.","explanation":"<b>Come down with</b> an illness = start to suffer from it. <b>Come up with</b> is to think of an idea, <b>put up with</b> is to tolerate, and <b>come across</b> is to find by chance."},{"id":"gv-kc-16-14","level":"kc","focus":"article-quantifier","q":"Wrapping bánh chưng takes ______ patience, so my grandmother starts early in the morning.","options":["a great deal of","a large number of","a few","many"],"correct":0,"answer":"a great deal of","vi":"Gói bánh chưng cần rất nhiều kiên nhẫn, nên bà tôi bắt đầu từ sáng sớm.","explanation":"<b>Patience</b> is uncountable, so it takes <b>a great deal of</b> (= a lot of). <b>A large number of</b>, <b>a few</b> and <b>many</b> go only with plural countable nouns."},{"id":"gv-kc-16-15","level":"kc","focus":"idiom","q":"Nam keeps promising to help clean up after the festival, but ______.","options":["practice makes perfect","every cloud has a silver lining","actions speak louder than words","two heads are better than one"],"correct":2,"answer":"actions speak louder than words","vi":"Nam cứ hứa sẽ giúp dọn dẹp sau lễ hội, nhưng hành động mới nói lên tất cả.","explanation":"<b>Actions speak louder than words</b> = what you do matters more than what you promise. The other sayings are about practice, bad luck and teamwork, so they do not fit."},{"id":"gv-kc-16-16","level":"kc","focus":"gerund-infinitive","q":"We're all looking forward ______ the lantern parade next week.","options":["to see","seeing","see","to seeing"],"correct":3,"answer":"to seeing","vi":"Tất cả chúng tôi đều mong được xem lễ rước đèn tuần tới.","explanation":"In <b>look forward to</b>, <b>to</b> is a preposition, so it is followed by a gerund: <b>to seeing</b>, not the infinitive."},{"id":"gv-kc-16-17","level":"kc","focus":"word-choice","q":"The restaurant will ______ your phở to your door within thirty minutes.","options":["order","deliver","serve","receive"],"correct":1,"answer":"deliver","vi":"Nhà hàng sẽ giao phở tới tận cửa nhà bạn trong vòng ba mươi phút.","explanation":"<b>Deliver</b> = take goods to someone's home. You <b>order</b> or <b>receive</b> food as a customer, and a restaurant <b>serves</b> food at the table, not to your door."},{"id":"gv-kc-16-18","level":"kc","focus":"linking","q":"You won't find a seat at the night market food stalls ______ you get there before six.","options":["unless","if","although","so that"],"correct":0,"answer":"unless","vi":"Bạn sẽ không kiếm được chỗ ngồi ở các quầy ăn chợ đêm trừ khi bạn tới đó trước sáu giờ.","explanation":"<b>Unless</b> = if ... not: you will not find a seat if you do <b>not</b> arrive before six. <b>If</b> would give the opposite meaning, <b>although</b> shows contrast, and <b>so that</b> shows purpose."},{"id":"gv-kc-16-19","level":"kc","focus":"tense","q":"Nam: Why weren't you at the parade? / Lan: Something ______ at home just as I was leaving.","options":["has cropped up","crops up","is cropping up","cropped up"],"correct":3,"answer":"cropped up","vi":"Nam: Sao cậu không đến xem diễu hành? / Lan: Có chuyện phát sinh ở nhà đúng lúc mình chuẩn bị đi.","explanation":"<b>Just as I was leaving</b> fixes the event at a finished moment in the past, so the past simple <b>cropped up</b> (= happened unexpectedly) is correct, not a present form."},{"id":"gv-kc-16-20","level":"kc","focus":"conditional","q":"I wish I ______ how to make mooncakes as well as my grandmother does.","options":["know","had known","knew","would know"],"correct":2,"answer":"knew","vi":"Ước gì tôi biết làm bánh trung thu ngon như bà tôi.","explanation":"A wish about a present situation uses <b>wish + past simple</b>: <b>I wish I knew</b>. <b>Had known</b> would be a regret about the past, and <b>know</b> / <b>would know</b> are not used after <b>wish</b> here."},{"id":"gv-kc-16-21","level":"kc","focus":"collocation","q":"Could you ______ the table while I fry the fish?","options":["put","lay","place","fix"],"correct":1,"answer":"lay","vi":"Con dọn bàn ăn giúp mẹ trong lúc mẹ chiên cá nhé?","explanation":"You <b>lay</b> (or set) <b>the table</b> = put plates and cutlery on it before a meal. <b>Put</b>, <b>place</b> and <b>fix</b> do not form this collocation."},{"id":"gv-kc-16-22","level":"kc","focus":"passive","q":"Red envelopes ______ to children on the first morning of Tet.","options":["are given","give","are giving","given"],"correct":0,"answer":"are given","vi":"Bao lì xì được trao cho trẻ em vào sáng mùng Một Tết.","explanation":"The envelopes receive the action, so the present simple passive <b>are given</b> is needed: <b>be + past participle</b>."},{"id":"gv-kc-16-23","level":"kc","focus":"word-choice","q":"Can you ______ me a few minutes to explain the new bus route?","options":["share","save","spend","spare"],"correct":3,"answer":"spare","vi":"Bạn có thể dành cho mình vài phút để giải thích tuyến xe buýt mới không?","explanation":"<b>Spare someone a few minutes</b> = give them a little of your time. <b>Share</b>, <b>save</b> and <b>spend</b> do not take this pattern with a person and time."},{"id":"gv-kc-16-24","level":"kc","focus":"reported","q":"Mai said she ______ the flower market the next morning to buy peach blossom.","options":["will visit","visits","would visit","has visited"],"correct":2,"answer":"would visit","vi":"Mai nói sáng hôm sau cô ấy sẽ đi chợ hoa mua cành đào.","explanation":"In reported speech after <b>said</b>, <b>will</b> becomes <b>would</b>: <b>would visit</b>. The other forms do not shift the tense back."},{"id":"gv-kc-16-25","level":"kc","focus":"comparison","q":"The traffic in the city centre is ______ than it was five years ago.","options":["more worse","far worse","much worst","worst"],"correct":1,"answer":"far worse","vi":"Giao thông ở trung tâm thành phố tệ hơn nhiều so với năm năm trước.","explanation":"<b>Than</b> needs a comparative: <b>worse</b>, and it can be strengthened with <b>far</b> or <b>much</b>. <b>More worse</b> is a double comparative, and <b>worst</b> is a superlative."},{"id":"gv-ch-17-1","level":"ch","focus":"tense","q":"By the end of this decade, the carmaker ______ more than half of its plants to fully automated lines.","options":["has converted","will convert","is converting","will have converted"],"correct":3,"answer":"will have converted","vi":"Đến cuối thập kỷ này, hãng xe sẽ chuyển đổi xong hơn một nửa số nhà máy của mình sang dây chuyền hoàn toàn tự động.","explanation":"<b>By the end of this decade</b> marks a future deadline before which the action will be complete, so the future perfect <b>will have converted</b> is needed; the present perfect and present continuous describe the present, and the plain future ignores the deadline."},{"id":"gv-ch-17-2","level":"ch","focus":"word-choice","q":"In an effort to curb obesity, the government has decided to ______ a levy on sugary drinks from next April.","options":["inflict","impose","impart","install"],"correct":1,"answer":"impose","vi":"Nhằm kiềm chế béo phì, chính phủ đã quyết định áp một khoản thuế lên đồ uống có đường từ tháng Tư năm sau.","explanation":"A government <b>imposes</b> a tax, levy or ban. You <b>inflict</b> pain or damage, <b>impart</b> knowledge or a flavour, and <b>install</b> equipment or software."},{"id":"gv-ch-17-3","level":"ch","focus":"idiom","q":"If the shares keep sliding, you may be wiser to ______ now than to wait years for a recovery that may never come.","options":["cut corners","cut a long story short","cut your losses","cut your teeth"],"correct":2,"answer":"cut your losses","vi":"Nếu cổ phiếu tiếp tục trượt giá, có lẽ bạn nên cắt lỗ ngay bây giờ thay vì chờ đợi nhiều năm cho một sự phục hồi có thể chẳng bao giờ đến.","explanation":"To <b>cut your losses</b> is to abandon a failing venture before it costs you more. <b>Cut corners</b> means to do something cheaply or carelessly, <b>cut a long story short</b> introduces a summary, and <b>cut your teeth</b> means to gain first experience."},{"id":"gv-ch-17-4","level":"ch","focus":"collocation","q":"Regulators must ______ a balance between protecting consumers and leaving room for innovation in the fintech sector.","options":["strike","hit","beat","knock"],"correct":0,"answer":"strike","vi":"Các cơ quan quản lý phải tìm được sự cân bằng giữa việc bảo vệ người tiêu dùng và tạo dư địa cho đổi mới trong lĩnh vực công nghệ tài chính.","explanation":"The fixed collocation is <b>strike a balance</b> (also strike a deal, strike a chord). <b>Hit</b>, <b>beat</b> and <b>knock</b> share the sense of striking but never combine with <b>balance</b>."},{"id":"gv-ch-17-5","level":"ch","focus":"phrasal-verb","q":"Once the outcry over the product recall had ______, the company quietly relaunched the toy under a new name.","options":["died out","died away","died down","died off"],"correct":2,"answer":"died down","vi":"Khi làn sóng phẫn nộ về vụ thu hồi sản phẩm đã lắng xuống, công ty lặng lẽ tung lại món đồ chơi dưới một cái tên mới.","explanation":"Anger, excitement or controversy <b>dies down</b> (becomes less intense). <b>Die out</b> is to disappear completely like a species, <b>die away</b> is used of a sound fading, and <b>die off</b> means to die one after another."},{"id":"gv-ch-17-6","level":"ch","focus":"relative","q":"The economist ______ forecasts the ministry relied on has admitted that her model ignored energy prices entirely.","options":["whom","which","whose","that"],"correct":2,"answer":"whose","vi":"Nhà kinh tế có các dự báo mà bộ đã dựa vào thừa nhận rằng mô hình của bà hoàn toàn bỏ qua giá năng lượng.","explanation":"The forecasts belong to the economist, so the possessive relative <b>whose</b> is required before the noun <b>forecasts</b>; <b>whom</b>, <b>which</b> and <b>that</b> cannot show possession."},{"id":"gv-ch-17-7","level":"ch","focus":"word-choice","q":"Several hospitals have ______ a strict no-visitor policy during the flu season to protect vulnerable patients.","options":["adapted","adjusted","accommodated","adopted"],"correct":3,"answer":"adopted","vi":"Nhiều bệnh viện đã áp dụng chính sách cấm thăm bệnh nghiêm ngặt trong mùa cúm để bảo vệ những bệnh nhân dễ tổn thương.","explanation":"To <b>adopt</b> a policy is to start using it. <b>Adapt</b> and <b>adjust</b> mean to modify something that already exists, and <b>accommodate</b> means to make room for or satisfy someone's needs."},{"id":"gv-ch-17-8","level":"ch","focus":"inversion","q":"______ had the central bank cut interest rates than the currency began to slide against the dollar.","options":["Hardly","No sooner","Scarcely","Not until"],"correct":1,"answer":"No sooner","vi":"Ngân hàng trung ương vừa mới cắt giảm lãi suất thì đồng nội tệ đã bắt đầu trượt giá so với đô la.","explanation":"The second clause begins with <b>than</b>, which pairs only with <b>No sooner</b> (+ inverted past perfect). <b>Hardly</b> and <b>Scarcely</b> pair with <b>when</b>, and <b>Not until</b> would need a different structure."},{"id":"gv-ch-17-9","level":"ch","focus":"idiom","q":"Before signing up for any 'free' trial, shoppers should always ______, since a monthly fee usually kicks in after thirty days.","options":["read between the lines","read the fine print","read the riot act","read them like a book"],"correct":1,"answer":"read the fine print","vi":"Trước khi đăng ký bất kỳ gói dùng thử 'miễn phí' nào, người mua nên luôn đọc kỹ các điều khoản in nhỏ, vì thường sau ba mươi ngày sẽ bắt đầu bị tính phí hằng tháng.","explanation":"To <b>read the fine print</b> is to check the small, easily missed conditions of a contract. <b>Read between the lines</b> means to infer a hidden meaning, <b>read the riot act</b> means to reprimand someone sharply, and <b>read someone like a book</b> means to understand their thoughts easily."},{"id":"gv-ch-17-10","level":"ch","focus":"double-blank","q":"Tracking down the so-called miracle cure turned out to be a wild ______ chase that ______ the family thousands of dollars.","options":["duck / charged","fox / paid","goose / cost","hare / spent"],"correct":2,"answer":"goose / cost","vi":"Việc săn lùng cái gọi là thần dược hóa ra là một cuộc truy tìm vô vọng khiến gia đình tốn hàng nghìn đô la.","explanation":"The idiom for a hopeless search is <b>a wild goose chase</b>, and something that makes you lose money <b>costs</b> you that amount. A chase cannot <b>charge</b>, <b>pay</b> or <b>spend</b> money on someone's behalf."},{"id":"gv-ch-17-11","level":"ch","focus":"modal","q":"The patient ______ the medication as prescribed — his blood tests show no trace of it whatsoever.","options":["shouldn't have taken","needn't have taken","must have taken","can't have taken"],"correct":3,"answer":"can't have taken","vi":"Bệnh nhân không thể nào đã uống thuốc theo đơn — xét nghiệm máu của anh ta không cho thấy chút dấu vết nào của thuốc.","explanation":"The blood tests make it logically impossible that he took the drug, and a confident negative deduction about the past is <b>can't have</b> + past participle. <b>Shouldn't have</b> criticises, <b>needn't have</b> says it was unnecessary, and <b>must have</b> would assert the opposite of what the evidence shows."},{"id":"gv-ch-17-12","level":"ch","focus":"word-choice","q":"Researchers ______ a large-scale trial across twelve countries to test whether the vaccine protects adults over seventy.","options":["conducted","directed","governed","steered"],"correct":0,"answer":"conducted","vi":"Các nhà nghiên cứu đã tiến hành một thử nghiệm quy mô lớn tại mười hai quốc gia để kiểm tra liệu vắc-xin có bảo vệ người trên bảy mươi tuổi hay không.","explanation":"You <b>conduct</b> a trial, survey, experiment or investigation. <b>Direct</b> is used of films, traffic or an organisation, <b>govern</b> of countries or rules, and <b>steer</b> of vehicles or a conversation."},{"id":"gv-ch-17-13","level":"ch","focus":"linking","q":"Sales of organic food have doubled in five years, ______ the number of certified organic farms has barely changed.","options":["despite","consequently","whereas","otherwise"],"correct":2,"answer":"whereas","vi":"Doanh số thực phẩm hữu cơ đã tăng gấp đôi trong năm năm, trong khi số trang trại được chứng nhận hữu cơ hầu như không thay đổi.","explanation":"The two clauses contrast, and <b>whereas</b> is the conjunction that joins two contrasting clauses. <b>Despite</b> must be followed by a noun or -ing form, while <b>consequently</b> (result) and <b>otherwise</b> (if not) give the wrong meaning."},{"id":"gv-ch-17-14","level":"ch","focus":"collocation","q":"Antibiotic resistance ______ a far greater threat to public health than most consumers realise.","options":["puts","poses","places","sets"],"correct":1,"answer":"poses","vi":"Tình trạng kháng kháng sinh đặt ra mối đe dọa với sức khỏe cộng đồng lớn hơn nhiều so với những gì hầu hết người tiêu dùng nhận thấy.","explanation":"The collocation is <b>pose a threat</b> (also pose a risk, pose a question). <b>Put</b>, <b>place</b> and <b>set</b> do not combine with <b>threat</b>, though you can <b>put</b> someone <b>at risk</b>."},{"id":"gv-ch-17-15","level":"ch","focus":"subjunctive","q":"The auditors recommended that every branch ______ its accounts to head office by the end of each quarter.","options":["submit","submits","submitted","will submit"],"correct":0,"answer":"submit","vi":"Các kiểm toán viên khuyến nghị rằng mỗi chi nhánh phải nộp sổ sách kế toán về trụ sở chính trước cuối mỗi quý.","explanation":"After <b>recommend / suggest / insist that</b>, the verb takes the subjunctive base form: <b>every branch submit</b>. The -s form, the past and <b>will</b> are all ruled out in this structure."},{"id":"gv-ch-17-16","level":"ch","focus":"idiom","q":"Rather than admit that the failed product launch was his own doing, the manager ______ in front of the whole board.","options":["threw down the gauntlet","threw in the towel","threw caution to the wind","threw his assistant under the bus"],"correct":3,"answer":"threw his assistant under the bus","vi":"Thay vì thừa nhận vụ ra mắt sản phẩm thất bại là do chính mình, người quản lý đã đổ hết trách nhiệm lên trợ lý của mình trước toàn thể hội đồng quản trị.","explanation":"To <b>throw someone under the bus</b> is to blame or sacrifice a colleague to protect yourself. <b>Throw down the gauntlet</b> is to issue a challenge, <b>throw in the towel</b> is to give up, and <b>throw caution to the wind</b> is to act recklessly."},{"id":"gv-ch-17-17","level":"ch","focus":"gerund-infinitive","q":"Many retailers now regret ______ so heavily in city-centre stores just before online shopping took off.","options":["to invest","investing","invest","to have invested"],"correct":1,"answer":"investing","vi":"Nhiều nhà bán lẻ giờ đây hối tiếc vì đã đầu tư quá mạnh vào các cửa hàng ở trung tâm thành phố ngay trước khi mua sắm trực tuyến bùng nổ.","explanation":"<b>Regret + -ing</b> means to be sorry about something already done, which fits an investment made in the past. <b>Regret to + infinitive</b> only introduces bad news (we regret to inform you), and the bare infinitive is impossible here."},{"id":"gv-ch-17-18","level":"ch","focus":"word-choice","q":"Parliament ______ a law last month requiring supermarkets to print the unit price on every shelf label.","options":["enforced","entailed","enabled","enacted"],"correct":3,"answer":"enacted","vi":"Tháng trước, Quốc hội đã ban hành một đạo luật yêu cầu các siêu thị in đơn giá trên mọi nhãn kệ hàng.","explanation":"A legislature <b>enacts</b> (passes) a law. <b>Enforce</b> is what police or regulators do to make people obey a law that already exists, <b>entail</b> means to involve as a necessary part, and <b>enable</b> means to make possible."},{"id":"gv-ch-17-19","level":"ch","focus":"phrasal-verb","q":"The trade talks ______ for almost three years, costing exporters billions in lost orders.","options":["dragged out","dragged in","dragged on","dragged along"],"correct":2,"answer":"dragged on","vi":"Các cuộc đàm phán thương mại kéo dài lê thê gần ba năm, khiến các nhà xuất khẩu mất hàng tỷ đô la đơn hàng.","explanation":"Something tedious that lasts far longer than it should <b>drags on</b> (no object). <b>Drag out</b> needs an object (they dragged the talks out), <b>drag in</b> means to involve someone unnecessarily, and <b>drag along</b> means to bring someone unwillingly."},{"id":"gv-ch-17-20","level":"ch","focus":"participle","q":"______ with last year's figures, the hospital's average waiting time has fallen by almost a third.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với số liệu năm ngoái, thời gian chờ trung bình của bệnh viện đã giảm gần một phần ba.","explanation":"The waiting time is the thing being compared, so the passive past participle <b>Compared with</b> is correct. <b>Comparing</b> and <b>Having compared</b> would make the waiting time the one doing the comparing, and <b>To compare</b> expresses purpose."},{"id":"gv-ch-17-21","level":"ch","focus":"idiom","q":"Trying to work out why the price of eggs had doubled, the reporter ______ of feed costs, tariffs and bird flu.","options":["went off the deep end","went down a rabbit hole","went round in circles","went up the wall"],"correct":1,"answer":"went down a rabbit hole","vi":"Cố tìm hiểu vì sao giá trứng tăng gấp đôi, phóng viên đã sa vào mê cung của chi phí thức ăn chăn nuôi, thuế quan và cúm gia cầm.","explanation":"To go <b>down a rabbit hole</b> is to become absorbed in an ever more complicated topic, and only this idiom can be followed by <b>of</b> + the topic. <b>Go off the deep end</b> is to lose your temper, <b>go round in circles</b> is to make no progress, and <b>go up the wall</b> is to become very annoyed."},{"id":"gv-ch-17-22","level":"ch","focus":"conditional","q":"The rural clinic ______ its doors last spring if the local council hadn't stepped in with an emergency grant.","options":["would close","had closed","would have closed","will have closed"],"correct":2,"answer":"would have closed","vi":"Phòng khám nông thôn hẳn đã phải đóng cửa vào mùa xuân năm ngoái nếu hội đồng địa phương không kịp thời hỗ trợ một khoản trợ cấp khẩn cấp.","explanation":"An unreal past condition (<b>if the council hadn't stepped in</b>) with a past result (<b>last spring</b>) is a third conditional: <b>would have closed</b>. <b>Would close</b> is the second conditional, and <b>had closed</b> belongs in the if-clause, not the result."},{"id":"gv-ch-17-23","level":"ch","focus":"word-choice","q":"Only trained nurses are permitted to ______ the vaccine, which has to be injected slowly into the upper arm.","options":["prescribe","apply","undergo","administer"],"correct":3,"answer":"administer","vi":"Chỉ những y tá đã qua đào tạo mới được phép tiêm vắc-xin này, loại vắc-xin phải được tiêm chậm vào bắp tay.","explanation":"To <b>administer</b> a drug or vaccine is to give it to the patient. Doctors <b>prescribe</b> medicine on paper, you <b>apply</b> a cream to the skin, and it is the patient who <b>undergoes</b> a treatment."},{"id":"gv-ch-17-24","level":"ch","focus":"collocation","q":"Mask factories ran around the clock, yet they still could not ______ the demand during the first weeks of the outbreak.","options":["meet","reach","hit","catch"],"correct":0,"answer":"meet","vi":"Các nhà máy khẩu trang chạy suốt ngày đêm nhưng vẫn không thể đáp ứng nhu cầu trong những tuần đầu của đợt bùng phát dịch.","explanation":"Demand, a deadline, a target or a need is <b>met</b>. You <b>reach</b> or <b>hit</b> a target or a level and <b>catch</b> a bus or a cold, but none of these combine with <b>demand</b>."},{"id":"gv-ch-17-25","level":"ch","focus":"double-blank","q":"Lawyers were asked to ______ up a contract that would ______ either side from walking away before the merger was complete.","options":["set / avoid","draw / prevent","make / refuse","put / deny"],"correct":1,"answer":"draw / prevent","vi":"Các luật sư được yêu cầu soạn thảo một hợp đồng ngăn không cho bên nào rút lui trước khi vụ sáp nhập hoàn tất.","explanation":"A contract or plan is <b>drawn up</b> (written in detail), and <b>prevent someone from</b> doing something is the pattern that takes <b>from</b>. <b>Avoid</b>, <b>refuse</b> and <b>deny</b> are never followed by <b>someone from</b>, and <b>set up</b>, <b>make up</b> and <b>put up</b> a contract are wrong."},{"id":"gv-ch-18-1","level":"ch","focus":"word-choice","q":"The laboratory's verdict was ______: the bone fragments were at least forty thousand years old.","options":["equivocal","unequivocal","equivalent","ambivalent"],"correct":1,"answer":"unequivocal","vi":"Kết luận của phòng thí nghiệm là không thể chối cãi: các mảnh xương có niên đại ít nhất bốn mươi nghìn năm.","explanation":"<b>Unequivocal</b> means leaving no room for doubt, which the clause after the colon confirms; <b>equivocal</b> means the opposite, <b>equivalent</b> means equal in value, and <b>ambivalent</b> describes a person's mixed feelings, not a result."},{"id":"gv-ch-18-2","level":"ch","focus":"idiom","q":"For almost a decade the data broker operated ______, compiling profiles that most users never knew existed.","options":["under the radar","off the hook","on the fence","up in the air"],"correct":0,"answer":"under the radar","vi":"Trong gần một thập kỷ, công ty môi giới dữ liệu ấy hoạt động âm thầm ngoài tầm chú ý, lập những hồ sơ mà hầu hết người dùng chưa từng biết là có.","explanation":"To operate <b>under the radar</b> is to escape attention; <b>off the hook</b> means freed from blame, <b>on the fence</b> means undecided and <b>up in the air</b> means not yet settled."},{"id":"gv-ch-18-3","level":"ch","focus":"modal","q":"The builders of the tomb ______ have used wheeled carts, since no trace of a wheel has ever been found in the region.","options":["mustn't","needn't","can't","shouldn't"],"correct":2,"answer":"can't","vi":"Những người xây lăng mộ này không thể nào đã dùng xe có bánh, vì chưa từng tìm thấy dấu vết bánh xe nào trong vùng.","explanation":"<b>Can't have + past participle</b> is a confident deduction that something did not happen; <b>mustn't have</b> is not used for deduction, and <b>needn't/shouldn't have</b> comment on necessity or advisability, not on what was possible."},{"id":"gv-ch-18-4","level":"ch","focus":"collocation","q":"Broadcasting your location in real time ______ a serious risk to your personal safety.","options":["puts","makes","does","poses"],"correct":3,"answer":"poses","vi":"Việc phát vị trí của bạn theo thời gian thực gây ra một rủi ro nghiêm trọng cho an toàn cá nhân.","explanation":"A danger <b>poses a risk</b> (or threat) to someone; <b>put</b> needs the pattern <i>put someone at risk</i>, and <b>make/do a risk</b> are not English collocations."},{"id":"gv-ch-18-5","level":"ch","focus":"word-choice","q":"With no witnesses and no fingerprints, the case against the hacker rested entirely on ______ evidence.","options":["circumstantial","coincidental","incidental","accidental"],"correct":0,"answer":"circumstantial","vi":"Không có nhân chứng và không có dấu vân tay, vụ án chống lại tin tặc ấy hoàn toàn dựa vào bằng chứng gián tiếp.","explanation":"<b>Circumstantial evidence</b> is indirect evidence that suggests guilt without proving it; <b>coincidental</b> means happening by chance, <b>incidental</b> means minor or secondary, and <b>accidental</b> means unintended."},{"id":"gv-ch-18-6","level":"ch","focus":"phrasal-verb","q":"The deal to digitise the museum's entire archive ______ when the main sponsor withdrew at the last minute.","options":["fell out","fell through","fell behind","fell off"],"correct":1,"answer":"fell through","vi":"Thỏa thuận số hóa toàn bộ kho lưu trữ của bảo tàng đã đổ bể khi nhà tài trợ chính rút lui vào phút chót.","explanation":"A plan or deal that <b>falls through</b> fails to happen; <b>fall out</b> means to quarrel, <b>fall behind</b> means to fail to keep up, and <b>fall off</b> means to decline in amount."},{"id":"gv-ch-18-7","level":"ch","focus":"inversion","q":"______ had the probe been launched than contact with it was lost.","options":["Hardly","Not until","No sooner","Only when"],"correct":2,"answer":"No sooner","vi":"Tàu thăm dò vừa mới được phóng lên thì đã mất liên lạc.","explanation":"The inverted pattern <b>No sooner had … than …</b> pairs with <i>than</i>; <b>Hardly</b> would need <i>when</i>, and <b>Not until</b> and <b>Only when</b> invert the main clause, not the one they introduce."},{"id":"gv-ch-18-8","level":"ch","focus":"idiom","q":"Rather than cut down gradually, he decided to ______ and deleted every social media app from his phone in a single evening.","options":["go the extra mile","go with the flow","go through the roof","go cold turkey"],"correct":3,"answer":"go cold turkey","vi":"Thay vì giảm dần, anh ấy quyết định cai hẳn một lần và xóa toàn bộ ứng dụng mạng xã hội khỏi điện thoại chỉ trong một buổi tối.","explanation":"To <b>go cold turkey</b> is to stop a habit abruptly and completely; <b>go the extra mile</b> means to make extra effort, <b>go with the flow</b> means to accept what happens, and <b>go through the roof</b> means to rise sharply or lose one's temper."},{"id":"gv-ch-18-9","level":"ch","focus":"word-choice","q":"The privacy cost of a single photo upload may seem ______, but every post adds another data point to your profile.","options":["negligible","negligent","neglected","neglectful"],"correct":0,"answer":"negligible","vi":"Cái giá về quyền riêng tư của một lần tải ảnh lên có vẻ không đáng kể, nhưng mỗi bài đăng lại thêm một điểm dữ liệu vào hồ sơ của bạn.","explanation":"<b>Negligible</b> means too small to matter; <b>negligent</b> and <b>neglectful</b> describe a person who fails to take proper care, and <b>neglected</b> describes something that has not been looked after."},{"id":"gv-ch-18-10","level":"ch","focus":"double-blank","q":"Each new leak ______ the stakes, ______ regulators to act sooner than they had planned.","options":["rose / forced","raised / forcing","raised / forced","rose / forcing"],"correct":1,"answer":"raised / forcing","vi":"Mỗi vụ rò rỉ mới lại nâng cao mức độ rủi ro, buộc các cơ quan quản lý phải hành động sớm hơn dự kiến.","explanation":"<b>Raise the stakes</b> needs the transitive verb <i>raise</i> (<i>rise</i> takes no object), and the second blank is a present participle <b>forcing</b> giving the result; a second finite verb <i>forced</i> would need a conjunction."},{"id":"gv-ch-18-11","level":"ch","focus":"subjunctive","q":"The regulator demanded that the company ______ fully transparent about which third parties receive users' data.","options":["is","was","be","were"],"correct":2,"answer":"be","vi":"Cơ quan quản lý yêu cầu công ty phải hoàn toàn minh bạch về việc những bên thứ ba nào nhận được dữ liệu của người dùng.","explanation":"After <b>demand that</b>, the subjunctive uses the base form <b>be</b> for every subject; <i>is/was/were</i> are indicative forms and do not follow a verb of demand."},{"id":"gv-ch-18-12","level":"ch","focus":"collocation","q":"The pottery unearthed at the site ______ a striking resemblance to designs found five hundred kilometres away.","options":["holds","carries","keeps","bears"],"correct":3,"answer":"bears","vi":"Đồ gốm khai quật tại di chỉ này mang nét tương đồng đáng kinh ngạc với các hoa văn được tìm thấy cách đó năm trăm cây số.","explanation":"The fixed collocation is <b>bear a resemblance to</b>; <i>hold, carry</i> and <i>keep</i> do not combine with <i>resemblance</i>."},{"id":"gv-ch-18-13","level":"ch","focus":"idiom","q":"The team had located the tomb in 2015 but, rather than dig at once, chose to ______ until better scanning technology became available.","options":["bide their time","cut their losses","pull their weight","mend their fences"],"correct":0,"answer":"bide their time","vi":"Nhóm nghiên cứu đã xác định được vị trí lăng mộ từ năm 2015 nhưng, thay vì đào ngay, họ chọn kiên nhẫn chờ thời cơ cho đến khi có công nghệ quét tốt hơn.","explanation":"To <b>bide your time</b> is to wait patiently for the right moment; <b>cut your losses</b> means to abandon a failing venture, <b>pull your weight</b> means to do your share, and <b>mend fences</b> means to repair a relationship."},{"id":"gv-ch-18-14","level":"ch","focus":"word-choice","q":"The historian's claim that the city had a written language remained ______ until the clay tablets were finally deciphered.","options":["insubstantial","unsubstantiated","substantive","substantial"],"correct":1,"answer":"unsubstantiated","vi":"Luận điểm của nhà sử học rằng thành phố này từng có chữ viết vẫn chưa được chứng thực cho đến khi các phiến đất sét cuối cùng được giải mã.","explanation":"<b>Unsubstantiated</b> means not yet supported by evidence; <b>insubstantial</b> means flimsy or lacking solidity, <b>substantive</b> means real and meaningful, and <b>substantial</b> means large."},{"id":"gv-ch-18-15","level":"ch","focus":"gerund-infinitive","q":"The site's founders now openly regret ______ user data to advertisers in the company's early years.","options":["to sell","sell","selling","to have sold"],"correct":2,"answer":"selling","vi":"Những người sáng lập trang web giờ đây công khai hối tiếc vì đã bán dữ liệu người dùng cho các nhà quảng cáo trong những năm đầu của công ty.","explanation":"<b>Regret + -ing</b> looks back on something already done; <b>regret to + infinitive</b> announces bad news now (<i>we regret to inform you</i>), and the bare infinitive is impossible after <i>regret</i>."},{"id":"gv-ch-18-16","level":"ch","focus":"phrasal-verb","q":"Every day the site's servers must ______ thousands of automated login attempts from hijacked computers.","options":["fend for","put off","set off","fend off"],"correct":3,"answer":"fend off","vi":"Mỗi ngày, máy chủ của trang web phải chống đỡ hàng nghìn lượt đăng nhập tự động từ các máy tính bị chiếm quyền điều khiển.","explanation":"To <b>fend off</b> an attack is to repel it; <b>fend for yourself</b> means to look after yourself, <b>put off</b> means to postpone, and <b>set off</b> means to trigger or to depart."},{"id":"gv-ch-18-17","level":"ch","focus":"participle","q":"______ with the paper surveys of the 1990s, today's online census forms take barely ten minutes to complete.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với các phiếu khảo sát giấy của thập niên 1990, mẫu điều tra dân số trực tuyến ngày nay chỉ mất chưa đầy mười phút để hoàn thành.","explanation":"The forms are the thing being compared, so the past participle <b>Compared with</b> is needed; <i>Comparing</i> and <i>Having compared</i> would make the forms the ones doing the comparing."},{"id":"gv-ch-18-18","level":"ch","focus":"double-blank","q":"Once the researchers had ______ how the algorithm ranked posts, they ______ that outrage was being rewarded.","options":["figured in / realised","figured out / realised","figured on / to realise","worked out / realising"],"correct":1,"answer":"figured out / realised","vi":"Một khi các nhà nghiên cứu đã hiểu ra cách thuật toán xếp hạng bài đăng, họ nhận ra rằng sự phẫn nộ đang được tưởng thưởng.","explanation":"<b>Figure out</b> means to work out or understand; <i>figure in</i> means to include and <i>figure on</i> means to expect. The main clause after <i>Once …</i> needs a finite past verb, <b>realised</b>, not an infinitive or participle."},{"id":"gv-ch-18-19","level":"ch","focus":"linking","q":"______ carefully a password is chosen, it is worthless once it has been reused on a dozen sites.","options":["However much","Whatever","No matter how","Even though"],"correct":2,"answer":"No matter how","vi":"Dù mật khẩu được chọn cẩn thận đến đâu, nó cũng trở nên vô giá trị một khi đã được dùng lại trên cả chục trang web.","explanation":"<b>No matter how + adverb</b> introduces a concession of degree; <i>However much</i> and <i>Whatever</i> cannot be followed directly by an adverb, and <i>Even though carefully</i> is not a grammatical clause."},{"id":"gv-ch-18-20","level":"ch","focus":"idiom","q":"By selling the family farm to fund the expedition, the explorer had ______: there was simply no going back.","options":["burnt his fingers","burnt the midnight oil","burnt a hole in his pocket","burnt his boats"],"correct":3,"answer":"burnt his boats","vi":"Bằng việc bán nông trại của gia đình để tài trợ cho chuyến thám hiểm, nhà thám hiểm đã tự đốt thuyền chặt đứt đường lui: đơn giản là không còn đường quay về nữa.","explanation":"To <b>burn your boats</b> (or bridges) is to act so that retreat is impossible; <b>burn your fingers</b> means to suffer from a risky venture, <b>burn the midnight oil</b> means to work late, and money that <b>burns a hole in your pocket</b> is money you cannot wait to spend."},{"id":"gv-ch-18-21","level":"ch","focus":"word-choice","q":"Radiocarbon dating gave the team ______ grounds for redating the temple by three centuries.","options":["compelling","compulsive","compulsory","compelled"],"correct":0,"answer":"compelling","vi":"Phương pháp định tuổi bằng carbon phóng xạ đã cho nhóm nghiên cứu những cơ sở rất thuyết phục để xác định lại niên đại ngôi đền, chênh lệch tới ba thế kỷ.","explanation":"<b>Compelling</b> evidence or grounds are convincing; <b>compulsive</b> describes an uncontrollable habit, <b>compulsory</b> means required by rule, and <b>compelled</b> means forced."},{"id":"gv-ch-18-22","level":"ch","focus":"agreement","q":"Neither the archaeologists nor the museum director ______ willing to say when the sealed chamber will be opened.","options":["are","is","were","have been"],"correct":1,"answer":"is","vi":"Cả các nhà khảo cổ lẫn giám đốc bảo tàng đều không sẵn lòng cho biết khi nào căn phòng bị niêm phong sẽ được mở.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, the singular <i>director</i>, so <b>is</b>; <i>are</i> and <i>have been</i> are plural, and <i>were</i> is both plural and the wrong tense for a statement about the present."},{"id":"gv-ch-18-23","level":"ch","focus":"comparison","q":"The more personal data a platform collects, ______ it becomes to advertisers.","options":["the most valuable","more valuable","the more valuable","the more valuably"],"correct":2,"answer":"the more valuable","vi":"Nền tảng càng thu thập nhiều dữ liệu cá nhân thì càng trở nên có giá trị đối với các nhà quảng cáo.","explanation":"The double comparative <b>the more …, the more …</b> needs <i>the</i> before both comparatives; <i>becomes</i> takes an adjective, so the adverb <i>valuably</i> is wrong."},{"id":"gv-ch-18-24","level":"ch","focus":"collocation","q":"After months of checks, the physicists ______ the conclusion that the signal was nothing more than noise from a nearby fridge.","options":["arrived","came","got","reached"],"correct":3,"answer":"reached","vi":"Sau nhiều tháng kiểm tra, các nhà vật lý đi đến kết luận rằng tín hiệu đó chẳng qua chỉ là nhiễu từ một chiếc tủ lạnh gần đó.","explanation":"You <b>reach a conclusion</b> directly; <i>arrive at</i>, <i>come to</i> and <i>get to</i> would all need a preposition before <i>the conclusion</i>."},{"id":"gv-ch-18-25","level":"ch","focus":"passive","q":"By the end of the decade, most routine scans ______ by algorithms rather than by radiologists.","options":["will have read","will have been read","will be reading","have been read"],"correct":1,"answer":"will have been read","vi":"Đến cuối thập kỷ này, hầu hết các ảnh chụp thường quy sẽ được thuật toán đọc thay vì bác sĩ chẩn đoán hình ảnh.","explanation":"<i>By the end of the decade</i> points to a future deadline and the scans are read <i>by</i> algorithms, so the future perfect passive <b>will have been read</b> is required; the active forms make the scans the readers, and the present perfect ignores the future time marker."},{"id":"gv-ch-19-1","level":"ch","focus":"word-choice","q":"The prize-winning novel was ______ for the stage in 2019, with the narrator's fading memories performed by a chorus.","options":["adjusted","adapted","converted","altered"],"correct":1,"answer":"adapted","vi":"Cuốn tiểu thuyết đoạt giải được chuyển thể cho sân khấu năm 2019, với những ký ức phai nhạt của người kể chuyện do một dàn đồng ca thể hiện.","explanation":"A book <b>adapted for</b> the stage or screen is rewritten in a new form; <b>adjust</b> is a small correction, <b>convert</b> changes function or units, and <b>alter</b> is a general, unspecific change."},{"id":"gv-ch-19-2","level":"ch","focus":"idiom","q":"Most of the mayor's promises about a second airport proved to be ______: no site was ever even surveyed.","options":["hot air","cold comfort","thin ice","sour grapes"],"correct":0,"answer":"hot air","vi":"Phần lớn lời hứa của thị trưởng về sân bay thứ hai hóa ra chỉ là lời nói suông: chưa từng có địa điểm nào được khảo sát.","explanation":"<b>Hot air</b> is empty talk with nothing behind it. <b>Cold comfort</b> is poor consolation, <b>thin ice</b> a risky position, and <b>sour grapes</b> pretending not to want what you cannot have."},{"id":"gv-ch-19-3","level":"ch","focus":"collocation","q":"Two decades of touring had ______ a heavy toll on the conductor's hearing.","options":["paid","made","taken","done"],"correct":2,"answer":"taken","vi":"Hai thập kỷ lưu diễn đã gây tổn hại nặng nề cho thính giác của vị nhạc trưởng.","explanation":"Damage or strain <b>takes a toll on</b> someone; you <b>pay</b> a toll on a road, but a toll is never made or done."},{"id":"gv-ch-19-4","level":"ch","focus":"modal","q":"The coach ______ the nine o'clock ferry; it was still in the hotel car park at ten.","options":["mustn't have caught","needn't have caught","shouldn't have caught","can't have caught"],"correct":3,"answer":"can't have caught","vi":"Chiếc xe khách không thể nào đã kịp chuyến phà chín giờ; mười giờ nó vẫn còn nằm trong bãi đỗ của khách sạn.","explanation":"A confident deduction that something did NOT happen uses <b>can't have</b> + past participle; <b>mustn't have</b> is not used for deduction, and <b>needn't / shouldn't have</b> comment on necessity or advisability, not on what happened."},{"id":"gv-ch-19-5","level":"ch","focus":"word-choice","q":"Researchers found that self-control tends to ______ across the day, sagging after lunch and recovering by early evening.","options":["fluctuate","mutate","convert","transform"],"correct":0,"answer":"fluctuate","vi":"Các nhà nghiên cứu nhận thấy khả năng tự chủ có xu hướng dao động trong ngày, sụt xuống sau bữa trưa rồi hồi phục vào đầu buổi tối.","explanation":"To <b>fluctuate</b> is to rise and fall repeatedly, which the sagging-and-recovering pattern describes; <b>mutate</b>, <b>convert</b> and <b>transform</b> all mean turning into something else."},{"id":"gv-ch-19-6","level":"ch","focus":"phrasal-verb","q":"The campaign to reopen the town's only cinema ______ once its two loudest supporters moved away.","options":["wore out","broke out","passed out","fizzled out"],"correct":3,"answer":"fizzled out","vi":"Chiến dịch đòi mở lại rạp chiếu phim duy nhất của thị trấn lụi dần rồi tắt hẳn khi hai người ủng hộ nhiệt thành nhất chuyển đi nơi khác.","explanation":"<b>Fizzle out</b> = end weakly after a promising start. <b>Wear out</b> is to become unusable, <b>break out</b> is to start suddenly (a fire, a war), and <b>pass out</b> is to faint."},{"id":"gv-ch-19-7","level":"ch","focus":"inversion","q":"______ had the curtain risen than a phone began ringing in the front row.","options":["Hardly","Scarcely","No sooner","Not until"],"correct":2,"answer":"No sooner","vi":"Màn vừa mới kéo lên thì một chiếc điện thoại đã đổ chuông ngay hàng ghế đầu.","explanation":"<b>No sooner</b> pairs with <b>than</b>; <b>hardly</b> and <b>scarcely</b> pair with <b>when</b>, and <b>not until</b> must be followed by a time phrase or clause, not the inverted main clause directly."},{"id":"gv-ch-19-8","level":"ch","focus":"idiom","q":"Trying to drum up interest in a third sequel after those reviews is ______; the studio would do better to move on.","options":["putting the cart before the horse","flogging a dead horse","beating around the bush","barking up the wrong tree"],"correct":1,"answer":"flogging a dead horse","vi":"Cố khơi lại sự quan tâm cho phần phim thứ ba sau những bài đánh giá như thế chẳng khác nào phí công vô ích; hãng phim nên chuyển hướng thì hơn.","explanation":"<b>Flog a dead horse</b> = waste effort on something already finished or hopeless. <b>Put the cart before the horse</b> is doing things in the wrong order, <b>beat around the bush</b> is avoiding the point, and <b>bark up the wrong tree</b> is pursuing the wrong target."},{"id":"gv-ch-19-9","level":"ch","focus":"double-blank","q":"Having thrown ______ to the ______, the couple sold their flat and bought one-way tickets to Lisbon.","options":["caution / wind","care / winds","caution / air","fear / wind"],"correct":0,"answer":"caution / wind","vi":"Bất chấp mọi rủi ro, hai vợ chồng bán căn hộ và mua vé một chiều đi Lisbon.","explanation":"The fixed idiom is <b>throw caution to the wind</b> — stop worrying about risk and act boldly; no other noun pair forms an English expression."},{"id":"gv-ch-19-10","level":"ch","focus":"subjunctive","q":"The curator insisted that every painting on loan ______ insured before it left the building.","options":["was","be","is","were"],"correct":1,"answer":"be","vi":"Người phụ trách bảo tàng nhất quyết yêu cầu mọi bức tranh cho mượn phải được bảo hiểm trước khi rời khỏi tòa nhà.","explanation":"After <b>insist / demand / recommend that</b>, the verb takes the base-form subjunctive: <b>that every painting be insured</b>, regardless of tense or subject."},{"id":"gv-ch-19-11","level":"ch","focus":"word-choice","q":"After the trial of self-service kiosks ended in chaos, the airline ______ to its old check-in desks within a week.","options":["reversed","restored","reverted","retreated"],"correct":2,"answer":"reverted","vi":"Sau khi thử nghiệm quầy tự phục vụ kết thúc trong hỗn loạn, hãng hàng không quay lại dùng quầy làm thủ tục cũ chỉ trong một tuần.","explanation":"<b>Revert to</b> = go back to a former state or system. <b>Reverse</b> and <b>restore</b> need an object (reverse a decision, restore a system), and <b>retreat</b> is physical or military withdrawal."},{"id":"gv-ch-19-12","level":"ch","focus":"collocation","q":"Good guides learn to ______ a balance between keeping to the timetable and letting the group linger where it wants.","options":["hit","draw","set","strike"],"correct":3,"answer":"strike","vi":"Hướng dẫn viên giỏi biết cách giữ được sự cân bằng giữa việc bám sát lịch trình và để đoàn nán lại nơi họ muốn.","explanation":"The fixed collocation is <b>strike a balance</b>; <b>hit</b>, <b>draw</b> and <b>set</b> do not combine with <b>balance</b> in this sense."},{"id":"gv-ch-19-13","level":"ch","focus":"gerund-infinitive","q":"After a decade in publishing, she has grown used to ______ manuscripts that are competent but unsellable.","options":["reject","have rejected","rejecting","being rejected"],"correct":2,"answer":"rejecting","vi":"Sau một thập kỷ làm xuất bản, cô đã quen với việc từ chối những bản thảo viết ổn nhưng không thể bán được.","explanation":"<b>Be / grow used to</b> is followed by a noun or -ing form because <b>to</b> is a preposition here; <b>used to + infinitive</b> describes a past habit, and the passive <b>being rejected</b> cannot take an object."},{"id":"gv-ch-19-14","level":"ch","focus":"idiom","q":"The review never calls the play a failure, but anyone able to ______ will sense the critic's disappointment.","options":["read the fine print","read between the lines","read the riot act","read it and weep"],"correct":1,"answer":"read between the lines","vi":"Bài phê bình không hề gọi vở kịch là thất bại, nhưng ai biết đọc ý tứ ẩn sau câu chữ sẽ cảm nhận được nỗi thất vọng của nhà phê bình.","explanation":"<b>Read between the lines</b> = understand what is implied but not stated. <b>Read the fine print</b> is checking the small conditions of a contract, <b>read the riot act</b> is to scold severely, and <b>read it and weep</b> is a taunt when showing a winning result."},{"id":"gv-ch-19-15","level":"ch","focus":"participle","q":"______ with the sprawling four-hour original, the director's new ninety-minute cut feels almost brisk.","options":["Compared","Comparing","To compare","Having compared"],"correct":0,"answer":"Compared","vi":"So với bản gốc dài lê thê bốn tiếng, bản dựng mới chín mươi phút của đạo diễn tạo cảm giác gần như gọn gàng, nhanh nhẹn.","explanation":"The cut is the thing being compared, so the passive participle <b>Compared with</b> is needed; <b>Comparing</b> or <b>Having compared</b> would wrongly make the cut the one doing the comparing."},{"id":"gv-ch-19-16","level":"ch","focus":"word-choice","q":"Rather than a few cosmetic changes, the museum's new director wants to ______ the entire visitor experience, from ticketing to the café.","options":["tweak","amend","modify","overhaul"],"correct":3,"answer":"overhaul","vi":"Thay vì vài thay đổi bề ngoài, giám đốc mới của bảo tàng muốn cải tổ toàn diện trải nghiệm của khách tham quan, từ khâu bán vé đến quán cà phê.","explanation":"To <b>overhaul</b> is to examine and rebuild something completely, which 'rather than a few cosmetic changes' calls for; <b>tweak</b> and <b>modify</b> are small or partial changes, and <b>amend</b> is used for texts and laws."},{"id":"gv-ch-19-17","level":"ch","focus":"linking","q":"______ the critics admired the film's ambition, few of them could sit through its four-hour running time.","options":["Much as","Despite","However","Nonetheless"],"correct":0,"answer":"Much as","vi":"Dù giới phê bình rất ngưỡng mộ tham vọng của bộ phim, ít ai trong số họ ngồi được hết bốn tiếng chiếu.","explanation":"<b>Much as</b> + clause means 'although … very much'. <b>Despite</b> needs a noun phrase, and <b>however / nonetheless</b> are adverbs that cannot join two clauses without a full stop or semicolon."},{"id":"gv-ch-19-18","level":"ch","focus":"phrasal-verb","q":"Managers who announce sweeping changes but never ______ soon lose the trust of their staff.","options":["follow suit","follow through","fall through","carry out"],"correct":1,"answer":"follow through","vi":"Những nhà quản lý tuyên bố cải cách lớn nhưng không bao giờ thực hiện đến nơi đến chốn sẽ sớm đánh mất lòng tin của nhân viên.","explanation":"<b>Follow through</b> = complete what you have started or promised. <b>Follow suit</b> is copying what others do, <b>fall through</b> is a plan collapsing, and <b>carry out</b> needs an object."},{"id":"gv-ch-19-19","level":"ch","focus":"collocation","q":"Fans who had queued overnight were ______ disappointed when the author cancelled her signing at the last minute.","options":["strongly","heavily","bitterly","highly"],"correct":2,"answer":"bitterly","vi":"Những người hâm mộ xếp hàng suốt đêm đã thất vọng cay đắng khi tác giả hủy buổi ký tặng vào phút chót.","explanation":"<b>Bitterly disappointed</b> is the standard intensifier; <b>heavily</b> goes with rain or traffic, <b>highly</b> with likely or recommended, and <b>strongly</b> with advise or oppose."},{"id":"gv-ch-19-20","level":"ch","focus":"reported","q":"The interviewer asked the novelist ______ she had ever thought of abandoning the book halfway.","options":["that","did","how","whether"],"correct":3,"answer":"whether","vi":"Người phỏng vấn hỏi nữ tiểu thuyết gia liệu bà có bao giờ nghĩ đến chuyện bỏ dở cuốn sách giữa chừng không.","explanation":"A reported yes/no question is introduced by <b>whether</b> (or if) with statement word order; <b>did</b> keeps direct-question order, <b>that</b> reports a statement, and <b>how</b> would ask about manner."},{"id":"gv-ch-19-21","level":"ch","focus":"idiom","q":"A seasoned tour guide knows how to ______: if the group is flagging, the lecture on Gothic arches can wait.","options":["read the room","call the shots","hold the floor","steal the show"],"correct":0,"answer":"read the room","vi":"Hướng dẫn viên dày dạn biết cách nắm bắt tâm trạng đoàn: nếu cả nhóm đã thấm mệt, bài giảng về vòm Gothic có thể để sau.","explanation":"<b>Read the room</b> = sense the mood of the people present and act accordingly. <b>Call the shots</b> is to be in charge, <b>hold the floor</b> is to keep speaking, and <b>steal the show</b> is to attract all the attention."},{"id":"gv-ch-19-22","level":"ch","focus":"pronoun","q":"The two novelists reviewed ______ books for thirty years without once meeting in person.","options":["each other","themselves","one another","each other's"],"correct":3,"answer":"each other's","vi":"Hai nhà tiểu thuyết đã bình sách của nhau suốt ba mươi năm mà chưa từng một lần gặp mặt.","explanation":"A possessive is needed before <b>books</b>: <b>each other's</b>. <b>Each other / one another</b> without 's cannot modify a noun, and <b>themselves</b> would mean each reviewed his own books."},{"id":"gv-ch-19-23","level":"ch","focus":"double-blank","q":"Before the festival put the town on the map, most families ______ by ______ fishing and a little farming.","options":["went / on","made / on","got / on","got / from"],"correct":2,"answer":"got / on","vi":"Trước khi lễ hội khiến thị trấn nổi tiếng, hầu hết các gia đình sống qua ngày nhờ đánh cá và làm nông chút ít.","explanation":"<b>Get by on</b> something = survive using only that; <b>go by</b> and <b>make by</b> are not phrasal verbs with this meaning, and <b>get by</b> takes <b>on</b>, not <b>from</b>."},{"id":"gv-ch-19-24","level":"ch","focus":"word-choice","q":"Her editor asked her to ______ the manuscript one last time, cutting the second act and sharpening the dialogue.","options":["reverse","revise","rectify","revert"],"correct":1,"answer":"revise","vi":"Biên tập viên đề nghị cô sửa lại bản thảo lần cuối, cắt bỏ hồi hai và làm cho lời thoại sắc sảo hơn.","explanation":"To <b>revise</b> a text is to rework and improve it. <b>Rectify</b> means to correct a specific error, <b>reverse</b> to turn round or undo, and <b>revert</b> (to go back) takes no object."},{"id":"gv-ch-19-25","level":"ch","focus":"question-tag","q":"Nobody on the coach tour actually read the itinerary before setting off, ______?","options":["did they","didn't they","did he","had they"],"correct":0,"answer":"did they","vi":"Chẳng ai trên chuyến xe du lịch thực sự đọc lịch trình trước khi khởi hành, phải không?","explanation":"<b>Nobody</b> makes the statement negative, so the tag is positive, and the pronoun for nobody is <b>they</b>; the simple past <b>read</b> takes <b>did</b>."},{"id":"gv-ch-20-1","level":"ch","focus":"word-choice","q":"Figures released by the grid operator on Monday comprehensively ______ the allegation that the country had been days away from rolling blackouts.","options":["argued","objected","refuted","disagreed"],"correct":2,"answer":"refuted","vi":"Số liệu do đơn vị vận hành lưới điện công bố hôm thứ Hai đã bác bỏ hoàn toàn cáo buộc rằng đất nước chỉ còn vài ngày nữa là phải cắt điện luân phiên.","explanation":"<b>Refute</b> = prove a claim false, and it takes a direct object. <b>Object</b> and <b>disagree</b> need <b>to / with</b>, and you cannot <b>argue</b> an allegation."},{"id":"gv-ch-20-2","level":"ch","focus":"idiom","q":"The sponsor's late withdrawal threw ______ just weeks before the new stadium was due to open.","options":["a spanner in the works","a fly in the ointment","a bone of contention","a nail in the coffin"],"correct":0,"answer":"a spanner in the works","vi":"Việc nhà tài trợ rút lui vào phút chót đã phá hỏng kế hoạch chỉ vài tuần trước ngày sân vận động mới dự kiến khai trương.","explanation":"<b>Throw a spanner in the works</b> = suddenly wreck a plan. A <b>fly in the ointment</b> and a <b>bone of contention</b> are things that <b>are</b>, not thrown, and a nail is <b>put</b> in a coffin."},{"id":"gv-ch-20-3","level":"ch","focus":"inversion","q":"______ had the vaccine trial's results been published when three rival laboratories announced they were abandoning their own programmes.","options":["No sooner","Hardly","Not only","Seldom"],"correct":1,"answer":"Hardly","vi":"Kết quả thử nghiệm vắc-xin vừa mới được công bố thì ba phòng thí nghiệm đối thủ đã tuyên bố từ bỏ chương trình của riêng họ.","explanation":"<b>Hardly … when</b> is the pair that takes <b>when</b> (with the past perfect inverted). <b>No sooner</b> needs <b>than</b>, <b>Not only</b> needs <b>but (also)</b>, and <b>Seldom</b> does not form a pair with <b>when</b> at all."},{"id":"gv-ch-20-4","level":"ch","focus":"collocation","q":"Rolling blackouts ______ a serious threat to the region's hospitals, which cannot run their ventilators on generators for long.","options":["make","do","put","pose"],"correct":3,"answer":"pose","vi":"Cắt điện luân phiên gây ra mối đe dọa nghiêm trọng cho các bệnh viện trong vùng, vốn không thể chạy máy thở bằng máy phát điện lâu được.","explanation":"The fixed collocation is <b>pose a threat</b>; <b>make / do / put</b> do not combine with <b>threat</b>."},{"id":"gv-ch-20-5","level":"ch","focus":"phrasal-verb","q":"Despite weeks of pressure from broadcasters, the league refused to ______ and kept every kick-off time unchanged.","options":["give in","give off","give out","give away"],"correct":0,"answer":"give in","vi":"Dù bị các đài truyền hình gây sức ép suốt nhiều tuần, giải đấu vẫn không chịu nhượng bộ và giữ nguyên mọi giờ thi đấu.","explanation":"<b>Give in</b> = yield to pressure. <b>Give off</b> = emit, <b>give out</b> = distribute or run out, <b>give away</b> = reveal or donate — and all three need an object here."},{"id":"gv-ch-20-6","level":"ch","focus":"subjunctive","q":"The press commission recommended that the broadcaster ______ its correction on the front page of its website rather than bury it in a footnote.","options":["prints","printed","print","would print"],"correct":2,"answer":"print","vi":"Ủy ban báo chí khuyến nghị đài truyền hình đăng bản đính chính lên trang đầu của trang web thay vì giấu nó trong một ghi chú cuối trang.","explanation":"After <b>recommend that</b> the verb is in the bare subjunctive: <b>that the broadcaster print</b>, with no <b>-s</b>, no past form and no <b>would</b>."},{"id":"gv-ch-20-7","level":"ch","focus":"word-choice","q":"Once the replay had been shown on the big screen, the coach was forced to ______ that the goal had been perfectly legitimate.","options":["consent","concede","comply","conform"],"correct":1,"answer":"concede","vi":"Khi đoạn quay chậm được chiếu lên màn hình lớn, huấn luyện viên buộc phải thừa nhận rằng bàn thắng hoàn toàn hợp lệ.","explanation":"<b>Concede that</b> = reluctantly admit something is true. <b>Consent to</b>, <b>comply with</b> and <b>conform to</b> mean agreeing to a request or rule and never take a <b>that</b>-clause."},{"id":"gv-ch-20-8","level":"ch","focus":"idiom","q":"Aware that the drivers' union was losing patience, the ministry ______ by promising a review of shift patterns before the end of the year.","options":["threw in the towel","threw its weight around","threw caution to the wind","threw it a bone"],"correct":3,"answer":"threw it a bone","vi":"Biết công đoàn tài xế đang mất kiên nhẫn, bộ đã nhượng bộ chút ít bằng cách hứa xem xét lại lịch ca làm việc trước cuối năm.","explanation":"<b>Throw someone a bone</b> = give a small concession to keep them quiet. <b>Throw in the towel</b> = give up completely, <b>throw your weight around</b> = bully, <b>throw caution to the wind</b> = act recklessly."},{"id":"gv-ch-20-9","level":"ch","focus":"modal","q":"Judging by the vibration recorded within an hour of start-up, the turbine ______ been installed correctly.","options":["can't have","must have","needn't have","should have"],"correct":0,"answer":"can't have","vi":"Căn cứ vào độ rung ghi nhận được chỉ trong vòng một giờ sau khi khởi động, tua-bin chắc chắn đã không được lắp đặt đúng cách.","explanation":"<b>Judging by</b> signals a deduction, and the vibration is evidence that correct installation was impossible: <b>can't have been</b>. <b>Must have</b> deduces the opposite; <b>needn't have</b> and <b>should have</b> are not deductions."},{"id":"gv-ch-20-10","level":"ch","focus":"double-blank","q":"Having sat on the ______ for months, the regulator finally came ______ in favour of a single national grid operator.","options":["wall / down","fence / down","fence / up","line / out"],"correct":1,"answer":"fence / down","vi":"Sau nhiều tháng lưỡng lự không chọn bên nào, cơ quan quản lý cuối cùng đã quyết định ủng hộ mô hình một đơn vị vận hành lưới điện quốc gia duy nhất.","explanation":"<b>Sit on the fence</b> = refuse to take sides, and <b>come down in favour of</b> = finally decide for. <b>Wall / line</b> break the idiom, and <b>come up in favour of</b> does not exist."},{"id":"gv-ch-20-11","level":"ch","focus":"linking","q":"______ the home side dominated possession for eighty minutes, it was the visitors who created the clearer chances.","options":["Despite","However","Although","Nevertheless"],"correct":2,"answer":"Although","vi":"Mặc dù đội chủ nhà kiểm soát bóng áp đảo suốt tám mươi phút, chính đội khách mới là bên tạo ra những cơ hội rõ rệt hơn.","explanation":"A clause with a subject and verb needs the conjunction <b>Although</b>. <b>Despite</b> takes a noun or <b>-ing</b>, while <b>However / Nevertheless</b> are adverbs that cannot join two clauses."},{"id":"gv-ch-20-12","level":"ch","focus":"word-choice","q":"The columnist stopped short of an outright accusation, merely ______ that the sprinter's sudden improvement owed more to chemistry than to training.","options":["proclaiming","pronouncing","announcing","insinuating"],"correct":3,"answer":"insinuating","vi":"Cây bút bình luận không đưa ra lời buộc tội thẳng thừng mà chỉ ám chỉ rằng sự tiến bộ đột ngột của vận động viên chạy nước rút là nhờ hóa chất nhiều hơn là nhờ tập luyện.","explanation":"<b>Insinuate</b> = suggest something unpleasant indirectly, which fits <b>stopped short of an outright accusation</b>. <b>Proclaim / pronounce / announce</b> all mean stating something openly and publicly."},{"id":"gv-ch-20-13","level":"ch","focus":"collocation","q":"The pipeline has been running at ______ capacity since the faulty compressor was replaced in March.","options":["whole","full","entire","complete"],"correct":1,"answer":"full","vi":"Đường ống đã vận hành hết công suất kể từ khi máy nén bị lỗi được thay thế hồi tháng Ba.","explanation":"The collocation is <b>at full capacity</b>; <b>whole / entire / complete</b> describe a thing in its totality but do not pair with <b>capacity</b>."},{"id":"gv-ch-20-14","level":"ch","focus":"participle","q":"______ its survey of the reef, the research vessel headed north to sample a second stretch of coastline before the monsoon arrived.","options":["Having finished","Finished","Being finished","To have finished"],"correct":0,"answer":"Having finished","vi":"Sau khi hoàn tất khảo sát rạn san hô, tàu nghiên cứu đi lên phía bắc để lấy mẫu ở một dải bờ biển thứ hai trước khi gió mùa tới.","explanation":"The vessel did the finishing, and it finished <b>before</b> it headed north, so the perfect participle <b>Having finished</b> is needed. <b>Finished / Being finished</b> would make the vessel the thing that was finished, and <b>To have finished</b> expresses purpose or result, not sequence."},{"id":"gv-ch-20-15","level":"ch","focus":"idiom","q":"The night editor asked the reporter at the mine to ______ as the rescue unfolded, even if it meant calling at three in the morning.","options":["keep her at bay","keep her in the dark","keep her posted","keep her at arm's length"],"correct":2,"answer":"keep her posted","vi":"Biên tập viên ca đêm yêu cầu phóng viên tại hiện trường mỏ liên tục cập nhật tình hình khi cuộc giải cứu diễn ra, kể cả phải gọi lúc ba giờ sáng.","explanation":"<b>Keep someone posted</b> = keep sending them the latest news. <b>Keep at bay / at arm's length</b> = keep away, and <b>keep in the dark</b> means the exact opposite — tell them nothing."},{"id":"gv-ch-20-16","level":"ch","focus":"inversion","q":"______ the goalkeeper's save in stoppage time, the club would have been relegated on the final day of the season.","options":["Had not it been for","If it had not for","Were it not been for","Had it not been for"],"correct":3,"answer":"Had it not been for","vi":"Nếu không nhờ pha cứu thua của thủ môn ở phút bù giờ, câu lạc bộ đã xuống hạng ngay ngày thi đấu cuối cùng của mùa giải.","explanation":"The inverted third conditional is <b>Had it not been for</b> (= If it had not been for). <b>Not</b> must follow the subject, <b>had not for</b> lacks <b>been</b>, and <b>were</b> cannot combine with <b>been</b>."},{"id":"gv-ch-20-17","level":"ch","focus":"word-choice","q":"Under threat of legal action, the newspaper agreed to ______ the story and print an apology in the following day's edition.","options":["retract","rescind","revoke","repeal"],"correct":0,"answer":"retract","vi":"Trước nguy cơ bị kiện, tờ báo đồng ý rút lại bài viết và đăng lời xin lỗi trong số báo ngày hôm sau.","explanation":"You <b>retract</b> a statement or story (withdraw it as untrue). <b>Rescind</b> an order or decision, <b>revoke</b> a licence or permit, <b>repeal</b> a law."},{"id":"gv-ch-20-18","level":"ch","focus":"gerund-infinitive","q":"The club's owners would rather ______ a season in the second tier than sell the stadium to property developers.","options":["to endure","endure","enduring","endured"],"correct":1,"answer":"endure","vi":"Các ông chủ câu lạc bộ thà chịu đựng một mùa giải ở hạng hai còn hơn bán sân vận động cho các nhà phát triển bất động sản.","explanation":"<b>Would rather</b> + bare infinitive: <b>would rather endure … than sell</b>. The <b>-ing</b>, <b>to</b> and past forms are not possible after <b>would rather</b> when the subject stays the same."},{"id":"gv-ch-20-19","level":"ch","focus":"phrasal-verb","q":"Repairs to the transmission line were ______ for a month by a dispute over access to farmland along the route.","options":["held out","held on","set up","held up"],"correct":3,"answer":"held up","vi":"Việc sửa chữa đường dây truyền tải bị trì hoãn suốt một tháng vì tranh chấp về quyền đi qua đất nông nghiệp dọc tuyến.","explanation":"<b>Hold up</b> = delay, and only it makes sense in the passive here. <b>Hold out / hold on</b> are intransitive (last, wait), and <b>set up</b> = establish."},{"id":"gv-ch-20-20","level":"ch","focus":"subjunctive","q":"It's high time the federation ______ the anti-doping rules it wrote more than a decade ago.","options":["revise","revises","revised","has revised"],"correct":2,"answer":"revised","vi":"Đã đến lúc liên đoàn phải sửa đổi các quy định chống doping mà họ soạn ra từ hơn một thập kỷ trước.","explanation":"<b>It's high time</b> + past subjunctive: <b>It's high time the federation revised</b>, even though the meaning is present; the bare, present and present-perfect forms are wrong."},{"id":"gv-ch-20-21","level":"ch","focus":"idiom","q":"Missing the cup final through injury proved ______: the striker returned fully rested for the World Cup qualifiers.","options":["a shot in the dark","a blessing in disguise","a drop in the ocean","a storm in a teacup"],"correct":1,"answer":"a blessing in disguise","vi":"Việc lỡ trận chung kết cúp vì chấn thương hóa ra lại là trong cái rủi có cái may: tiền đạo trở lại với thể trạng sung sức cho vòng loại World Cup.","explanation":"<b>A blessing in disguise</b> = something that seems bad but turns out well. <b>A shot in the dark</b> = a wild guess, <b>a drop in the ocean</b> = a tiny amount, <b>a storm in a teacup</b> = fuss over nothing."},{"id":"gv-ch-20-22","level":"ch","focus":"article-quantifier","q":"Only ______ of the stadium's eighty thousand seats were empty when the final kicked off.","options":["a few","few","a little","little"],"correct":0,"answer":"a few","vi":"Chỉ có một vài chỗ trong số tám mươi nghìn ghế của sân vận động là còn trống khi trận chung kết bắt đầu.","explanation":"<b>Seats</b> are countable, so <b>a little / little</b> are out, and after <b>only</b> English uses <b>a few</b> (a small number), never bare <b>few</b>."},{"id":"gv-ch-20-23","level":"ch","focus":"collocation","q":"The inquiry's report drew a ______ distinction between honest reporting and the paid content that had been dressed up as news.","options":["strong","hard","sharp","heavy"],"correct":2,"answer":"sharp","vi":"Báo cáo của cuộc điều tra phân biệt rõ ràng giữa đưa tin trung thực và nội dung được trả tiền nhưng được khoác vỏ tin tức.","explanation":"The collocation is <b>draw a sharp / clear distinction</b>; <b>strong / hard / heavy</b> do not pair with <b>distinction</b>."},{"id":"gv-ch-20-24","level":"ch","focus":"word-choice","q":"Two independent engineers have since ______ the whistleblower's account of cracks in the dam's spillway.","options":["cooperated","coincided","conformed","corroborated"],"correct":3,"answer":"corroborated","vi":"Hai kỹ sư độc lập sau đó đã xác nhận lời kể của người tố giác về các vết nứt ở đập tràn của con đập.","explanation":"<b>Corroborate</b> = confirm someone's account with further evidence, and it takes a direct object. <b>Cooperate with</b>, <b>coincide with</b> and <b>conform to</b> mean something different and need a preposition."},{"id":"gv-ch-20-25","level":"ch","focus":"double-blank","q":"Once the last sticking points over image rights had been ______, the broadcasting deal was ______ by both boards on Monday.","options":["ironed off / sealed off","wiped out / signed off","ironed out / signed off","ironed out / sent off"],"correct":2,"answer":"ironed out / signed off","vi":"Khi những vướng mắc cuối cùng về bản quyền hình ảnh đã được giải quyết, thỏa thuận phát sóng được cả hai hội đồng quản trị phê duyệt hôm thứ Hai.","explanation":"<b>Iron out</b> = resolve small problems, and <b>sign off</b> = formally approve. <b>Wipe out</b> = destroy, <b>seal off</b> = close an area, <b>send off</b> = dismiss a player."},{"id":"gv-ch-21-1","level":"ch","focus":"tense","q":"By the time the new metro line finally opens, the city ______ on it for eleven years.","options":["will work","will have been working","is working","has been working"],"correct":1,"answer":"will have been working","vi":"Đến lúc tuyến metro mới cuối cùng khánh thành, thành phố sẽ thi công tuyến này được mười một năm rồi.","explanation":"An action continuing up to a point in the future (<b>by the time … opens</b>) takes the future perfect continuous: <b>will have been working</b>."},{"id":"gv-ch-21-2","level":"ch","focus":"word-choice","q":"The judge's ______ handling of the case was praised by both sides, neither of which felt it had been favoured.","options":["impartial","indifferent","apathetic","aloof"],"correct":0,"answer":"impartial","vi":"Cách xử lý vụ án công tâm của thẩm phán được cả hai bên khen ngợi, không bên nào cảm thấy mình được thiên vị.","explanation":"<b>Impartial</b> means treating both sides equally; <b>indifferent</b> and <b>apathetic</b> mean not caring at all, and <b>aloof</b> means cold and distant."},{"id":"gv-ch-21-3","level":"ch","focus":"idiom","q":"When the landlord raised the rent for the third time in a year, it was ______ for the tenants, who began organising a rent strike.","options":["the last word","the last resort","the last straw","the last laugh"],"correct":2,"answer":"the last straw","vi":"Khi chủ nhà tăng tiền thuê lần thứ ba trong một năm, đó là giọt nước tràn ly đối với người thuê, và họ bắt đầu tổ chức đình công tiền nhà.","explanation":"<b>The last straw</b> is the final small problem that makes a situation unbearable. <b>The last resort</b> is the only remaining option, <b>the last word</b> is the final say, and <b>the last laugh</b> is winning in the end."},{"id":"gv-ch-21-4","level":"ch","focus":"phrasal-verb","q":"The printing plant was forced to ______ a third of its workforce once the newspaper moved online.","options":["lay out","lay down","lay up","lay off"],"correct":3,"answer":"lay off","vi":"Nhà in buộc phải sa thải một phần ba nhân công khi tờ báo chuyển sang phát hành trực tuyến.","explanation":"<b>Lay off</b> means to dismiss workers because there is not enough work. <b>Lay out</b> is to arrange or spend, <b>lay down</b> is to put down or set (rules), and <b>lay up</b> is to store or to confine someone to bed."},{"id":"gv-ch-21-5","level":"ch","focus":"inversion","q":"______ the laboratory had repeated the test three times did the researchers announce that the river's lead levels were safe.","options":["Until","As soon as","Not until","By the time"],"correct":2,"answer":"Not until","vi":"Mãi đến khi phòng thí nghiệm lặp lại xét nghiệm ba lần, các nhà nghiên cứu mới công bố rằng mức chì trong con sông đã ở ngưỡng an toàn.","explanation":"<b>Not until + clause</b> at the start of a sentence is a negative opener, so the main clause inverts: <b>did the researchers announce</b>. <b>Until</b>, <b>as soon as</b> and <b>by the time</b> are ordinary time conjunctions and would need normal word order (the researchers announced)."},{"id":"gv-ch-21-6","level":"ch","focus":"word-choice","q":"The minister sounded distinctly ______ about the bill, praising its aims in one breath and questioning its cost in the next.","options":["indifferent","apathetic","oblivious","ambivalent"],"correct":3,"answer":"ambivalent","vi":"Bộ trưởng tỏ ra rõ ràng là nước đôi về dự luật, vừa khen mục tiêu của nó ở câu trước lại vừa nghi ngờ chi phí ở câu sau.","explanation":"<b>Ambivalent</b> means having mixed feelings, which the praise-then-doubt shows. <b>Indifferent</b> and <b>apathetic</b> mean not caring, and <b>oblivious</b> means unaware (and takes <b>to</b>)."},{"id":"gv-ch-21-7","level":"ch","focus":"collocation","q":"The appeal court ______ the original ruling, rejecting every ground on which the developer had challenged it.","options":["upheld","held up","kept up","retained"],"correct":0,"answer":"upheld","vi":"Tòa phúc thẩm giữ nguyên phán quyết ban đầu, bác bỏ mọi căn cứ mà chủ đầu tư đã dùng để khiếu nại.","explanation":"A court <b>upholds</b> a ruling, meaning it confirms it on appeal. <b>Held up</b> means delayed, and <b>kept up</b> and <b>retained</b> do not collocate with a ruling."},{"id":"gv-ch-21-8","level":"ch","focus":"modal","q":"The mayor ______ the report before the press conference; she stumbled over even its most basic figures.","options":["needn't have read","shouldn't have read","can't have read","mustn't have read"],"correct":2,"answer":"can't have read","vi":"Thị trưởng chắc chắn đã không đọc bản báo cáo trước buổi họp báo; bà vấp ngay cả ở những con số cơ bản nhất.","explanation":"<b>Can't have + past participle</b> expresses a confident deduction that something did not happen. <b>Needn't have</b> means it was unnecessary, <b>shouldn't have</b> is criticism, and <b>mustn't have</b> is not used for deduction."},{"id":"gv-ch-21-9","level":"ch","focus":"idiom","q":"Rather than keep patching the leaking roof every winter, the housing association decided to ______ and replace it entirely.","options":["bite the bullet","bite the dust","bite its tongue","bite off more than it could chew"],"correct":0,"answer":"bite the bullet","vi":"Thay vì cứ vá mái nhà dột mỗi mùa đông, hiệp hội nhà ở quyết định cắn răng chịu đựng và thay toàn bộ mái.","explanation":"To <b>bite the bullet</b> is to accept something unpleasant but necessary. <b>Bite the dust</b> means to fail or die, <b>bite your tongue</b> is to stay silent, and <b>bite off more than you can chew</b> is to take on too much."},{"id":"gv-ch-21-10","level":"ch","focus":"relative","q":"The linguist ______ fieldwork on endangered dialects won last year's prize is now advising the ministry on language policy.","options":["whom","whose","which","that"],"correct":1,"answer":"whose","vi":"Nhà ngôn ngữ học mà công trình điền dã về các phương ngữ đang mai một đã đoạt giải năm ngoái hiện đang cố vấn cho bộ về chính sách ngôn ngữ.","explanation":"<b>Whose</b> is the possessive relative: the fieldwork belongs to the linguist. <b>Whom</b>, <b>which</b> and <b>that</b> cannot stand directly before a noun in this way."},{"id":"gv-ch-21-11","level":"ch","focus":"double-blank","q":"The columnist ______ the nail on the head when she ______ that the city has plenty of homes, just not where people can afford to live.","options":["struck / observing","hit / observing","hit / observed","struck / observed"],"correct":2,"answer":"hit / observed","vi":"Nhà bình luận đã nói trúng phóc khi bà nhận xét rằng thành phố có thừa nhà ở, chỉ là không ở những nơi người dân đủ tiền sống.","explanation":"The idiom is <b>hit the nail on the head</b> (say exactly the right thing), and a <b>when</b>-clause needs a finite verb: <b>observed</b>, not the participle <b>observing</b>."},{"id":"gv-ch-21-12","level":"ch","focus":"word-choice","q":"Older residents are ______ to abandon the low-rise streets they grew up in, however generous the relocation package.","options":["averse","hostile","resistant","loath"],"correct":3,"answer":"loath","vi":"Những cư dân lớn tuổi không muốn rời bỏ những con phố nhà thấp tầng nơi họ lớn lên, dù gói tái định cư có hào phóng đến đâu.","explanation":"<b>Loath to do</b> something means very unwilling to do it. <b>Averse</b>, <b>hostile</b> and <b>resistant</b> all take <b>to + noun/-ing</b> (averse to abandoning), not <b>to + infinitive</b>."},{"id":"gv-ch-21-13","level":"ch","focus":"linking","q":"Rents in the capital have doubled in a decade; ______, wages have barely moved.","options":["meanwhile","therefore","otherwise","likewise"],"correct":0,"answer":"meanwhile","vi":"Tiền thuê nhà ở thủ đô đã tăng gấp đôi trong một thập kỷ; trong khi đó, tiền lương hầu như không nhúc nhích.","explanation":"<b>Meanwhile</b> sets two things happening over the same period against each other. <b>Therefore</b> gives a result, <b>otherwise</b> the consequence of not doing something, and <b>likewise</b> a similarity."},{"id":"gv-ch-21-14","level":"ch","focus":"phrasal-verb","q":"Most junior reporters would ______ the chance to cover a general election, even if it meant weeks without a day off.","options":["jump through","jump at","jump over","jump off"],"correct":1,"answer":"jump at","vi":"Hầu hết phóng viên trẻ sẽ chớp ngay cơ hội đưa tin về một cuộc tổng tuyển cử, dù phải làm nhiều tuần không nghỉ.","explanation":"To <b>jump at</b> a chance is to accept it eagerly. <b>Jump through</b> (hoops) means to go through tedious procedures; <b>jump over</b> and <b>jump off</b> are literal movements."},{"id":"gv-ch-21-15","level":"ch","focus":"subjunctive","q":"The committee recommended that the controversial clause ______ from the bill before its second reading.","options":["was removed","is removed","be removed","would be removed"],"correct":2,"answer":"be removed","vi":"Ủy ban đề nghị điều khoản gây tranh cãi được loại khỏi dự luật trước phiên đọc thứ hai.","explanation":"After <b>recommend that</b>, the verb is in the subjunctive, the base form: <b>be removed</b>, whatever the tense of the main verb."},{"id":"gv-ch-21-16","level":"ch","focus":"collocation","q":"The dictionary's editors keep a ______ eye on social media for words that are slipping into everyday use.","options":["tight","strict","near","close"],"correct":3,"answer":"close","vi":"Các biên tập viên từ điển theo dõi sát mạng xã hội để tìm những từ đang dần đi vào ngôn ngữ hằng ngày.","explanation":"<b>Keep a close eye on</b> is the fixed phrase for watching carefully. <b>Tight</b> goes with grip or rein, and <b>strict</b> and <b>near</b> do not collocate with <b>eye</b>."},{"id":"gv-ch-21-17","level":"ch","focus":"word-choice","q":"City officials were accused of being ______ about flood risk, insisting the century-old drains would cope as they always had.","options":["reluctant","complacent","apathetic","averse"],"correct":1,"answer":"complacent","vi":"Giới chức thành phố bị cáo buộc là chủ quan về nguy cơ ngập lụt, khăng khăng rằng hệ thống cống trăm năm tuổi vẫn sẽ chịu được như trước nay.","explanation":"<b>Complacent about</b> means so satisfied with things as they are that you ignore a danger. <b>Reluctant</b> and <b>averse</b> take <b>to</b>, and <b>apathetic</b> means lacking interest rather than falsely confident."},{"id":"gv-ch-21-18","level":"ch","focus":"idiom","q":"The developer ______ at the last minute and withdrew its bid for the riverside site, citing 'market uncertainty'.","options":["got cold feet","got itchy feet","got the cold shoulder","got off on the wrong foot"],"correct":0,"answer":"got cold feet","vi":"Chủ đầu tư chùn bước vào phút chót và rút hồ sơ đấu thầu khu đất ven sông, viện lý do 'thị trường bất ổn'.","explanation":"To <b>get cold feet</b> is to lose your nerve just before doing something. <b>Itchy feet</b> is a desire to travel, <b>the cold shoulder</b> is deliberate unfriendliness, and <b>off on the wrong foot</b> is a bad start."},{"id":"gv-ch-21-19","level":"ch","focus":"gerund-infinitive","q":"The tenants' association now regrets ______ the landlord's first offer, which looks generous beside the one on the table today.","options":["to reject","reject","rejecting","to be rejecting"],"correct":2,"answer":"rejecting","vi":"Hiệp hội người thuê nhà giờ hối tiếc vì đã từ chối đề nghị đầu tiên của chủ nhà, đề nghị ấy trông hào phóng hơn hẳn so với đề nghị đang bàn hôm nay.","explanation":"<b>Regret + -ing</b> looks back at something you wish you had not done; <b>regret + to-infinitive</b> is only for announcing bad news (we regret to inform you)."},{"id":"gv-ch-21-20","level":"ch","focus":"conditional","q":"If the city ______ its drainage system a decade ago, last week's storm would not have flooded three metro stations.","options":["modernised","has modernised","would have modernised","had modernised"],"correct":3,"answer":"had modernised","vi":"Nếu thành phố đã hiện đại hóa hệ thống thoát nước từ một thập kỷ trước, cơn bão tuần rồi đã không làm ngập ba ga metro.","explanation":"An unreal past condition with a past result (third conditional) takes <b>if + past perfect</b>: <b>had modernised</b>, with <b>would have + past participle</b> in the main clause."},{"id":"gv-ch-21-21","level":"ch","focus":"word-choice","q":"Voters grew steadily ______ with a government that promised change every spring and delivered none by autumn.","options":["dismissive","disillusioned","disinclined","disapproving"],"correct":1,"answer":"disillusioned","vi":"Cử tri ngày càng vỡ mộng với một chính phủ cứ mỗi mùa xuân hứa đổi thay mà đến mùa thu chẳng làm được gì.","explanation":"<b>Disillusioned with</b> means having lost your belief in something after being let down. <b>Dismissive of</b> and <b>disapproving of</b> take a different preposition, and <b>disinclined</b> takes <b>to</b>."},{"id":"gv-ch-21-22","level":"ch","focus":"participle","q":"______ in plain language rather than legal jargon, the new tenancy contract can be understood without a lawyer.","options":["Written","Writing","Having written","To write"],"correct":0,"answer":"Written","vi":"Được viết bằng ngôn ngữ giản dị thay vì thuật ngữ pháp lý, hợp đồng thuê nhà mới có thể hiểu được mà không cần luật sư.","explanation":"The contract is written by someone, so the reduced clause is passive: the past participle <b>Written</b>. <b>Writing</b> and <b>Having written</b> would make the contract the writer."},{"id":"gv-ch-21-23","level":"ch","focus":"idiom","q":"After fourteen hours of talks on the budget, the two parties agreed to ______ and resume in the morning.","options":["call the shots","call a spade a spade","call it a day","call the tune"],"correct":2,"answer":"call it a day","vi":"Sau mười bốn giờ đàm phán về ngân sách, hai đảng đồng ý dừng lại ở đây và tiếp tục vào sáng hôm sau.","explanation":"To <b>call it a day</b> is to stop working for now. <b>Call the shots</b> and <b>call the tune</b> both mean to be in charge, and <b>call a spade a spade</b> is to speak bluntly."},{"id":"gv-ch-21-24","level":"ch","focus":"double-blank","q":"Had the council ______ with residents from the outset, far fewer of them would ______ opposed the scheme.","options":["squared / had","levelled / had","squared / have","levelled / have"],"correct":3,"answer":"levelled / have","vi":"Nếu hội đồng thành phố thẳng thắn với cư dân ngay từ đầu, thì đã có ít người phản đối dự án hơn nhiều.","explanation":"<b>Level with</b> someone is to be honest with them (<b>square with</b> means to be consistent with), and the result clause of a past unreal condition is <b>would have + past participle</b>."},{"id":"gv-ch-21-25","level":"ch","focus":"collocation","q":"The new tram line is expected to ______ pressure on the city's overcrowded northern bus routes.","options":["release","relieve","loosen","lighten"],"correct":1,"answer":"relieve","vi":"Tuyến tàu điện mới được kỳ vọng sẽ giảm bớt áp lực cho các tuyến xe buýt quá tải ở phía bắc thành phố.","explanation":"<b>Relieve pressure on</b> is the collocation for reducing strain on a service. <b>Release</b> pressure is physical (a valve), and <b>loosen</b> and <b>lighten</b> do not combine with <b>pressure on</b>."},{"id":"gv-ch-22-1","level":"ch","focus":"word-choice","q":"The reforestation fund is facing a ______ of nearly two million dollars between what donors pledged and what they actually paid.","options":["scarcity","shortfall","deficiency","dearth"],"correct":1,"answer":"shortfall","vi":"Quỹ trồng lại rừng đang đối mặt với mức thiếu hụt gần hai triệu đô la giữa số tiền các nhà tài trợ cam kết và số tiền họ thực sự chi trả.","explanation":"A <b>shortfall</b> is the exact amount by which something falls short of what was expected; <b>scarcity</b>, <b>deficiency</b> and <b>dearth</b> describe a general lack and are not measured in dollars."},{"id":"gv-ch-22-2","level":"ch","focus":"idiom","q":"Once electric cars became fashionable, several oil companies were quick to ______, launching charging networks of their own.","options":["jump the gun","jump through hoops","jump on the bandwagon","jump ship"],"correct":2,"answer":"jump on the bandwagon","vi":"Khi xe điện trở nên thịnh hành, nhiều công ty dầu mỏ đã nhanh chóng chạy theo trào lưu, tự tung ra các mạng lưới trạm sạc của riêng mình.","explanation":"<b>Jump on the bandwagon</b> = join something once it has become popular. <b>Jump the gun</b> = act too soon; <b>jump through hoops</b> = go through a demanding process; <b>jump ship</b> = abandon an organisation."},{"id":"gv-ch-22-3","level":"ch","focus":"modal","q":"The burglars ______ in through the front door – it was still bolted from the inside when the police arrived.","options":["mightn't have come","needn't have come","shouldn't have come","can't have come"],"correct":3,"answer":"can't have come","vi":"Bọn trộm không thể nào đã vào bằng cửa trước – cửa vẫn còn cài then từ bên trong khi cảnh sát đến.","explanation":"A confident deduction that something was impossible in the past takes <b>can't have + past participle</b>; <b>mightn't have</b> only expresses a weak possibility, and <b>needn't / shouldn't have</b> express necessity or advice, not certainty."},{"id":"gv-ch-22-4","level":"ch","focus":"collocation","q":"Prosecutors decided to ______ charges against the chemical company after the spill was traced to its pipeline.","options":["bring","raise","put","make"],"correct":0,"answer":"bring","vi":"Các công tố viên quyết định khởi tố công ty hóa chất sau khi vụ rò rỉ được xác định bắt nguồn từ đường ống của công ty này.","explanation":"The fixed collocation is <b>bring (or press) charges against</b> someone; you <b>raise</b> objections and <b>make</b> accusations, but charges are <b>brought</b>."},{"id":"gv-ch-22-5","level":"ch","focus":"phrasal-verb","q":"The city's recycling scheme has failed to ______ the expectations of the residents who campaigned so hard for it.","options":["live down","live off","live through","live up to"],"correct":3,"answer":"live up to","vi":"Chương trình tái chế của thành phố đã không đáp ứng được kỳ vọng của những cư dân đã vận động hết mình cho nó.","explanation":"<b>Live up to</b> = be as good as what was expected. <b>Live down</b> = make people forget an embarrassing mistake; <b>live off</b> = depend on for money; <b>live through</b> = survive an experience."},{"id":"gv-ch-22-6","level":"ch","focus":"double-blank","q":"The council inspects its flood defences only once in a ______ moon, ______ neighbouring towns check theirs every spring.","options":["full / whereas","blue / whereas","blue / despite","new / while"],"correct":1,"answer":"blue / whereas","vi":"Hội đồng thành phố hiếm hoi lắm mới kiểm tra hệ thống đê chắn lũ, trong khi các thị trấn lân cận kiểm tra hàng năm vào mỗi mùa xuân.","explanation":"<b>Once in a blue moon</b> = very rarely, and the contrast between the two clauses needs the conjunction <b>whereas</b>; <b>despite</b> must be followed by a noun, not a clause."},{"id":"gv-ch-22-7","level":"ch","focus":"word-choice","q":"The courts are still struggling to clear a ______ of more than sixty thousand cases that built up during the pandemic.","options":["stockpile","reserve","backlog","surplus"],"correct":2,"answer":"backlog","vi":"Các tòa án vẫn đang chật vật giải quyết lượng tồn đọng hơn sáu mươi nghìn vụ án tích tụ trong đại dịch.","explanation":"A <b>backlog</b> is an accumulation of work that should already have been dealt with; a <b>stockpile</b> or <b>reserve</b> is kept deliberately for later, and a <b>surplus</b> is more than is needed."},{"id":"gv-ch-22-8","level":"ch","focus":"inversion","q":"______ the vaccine had been tested on ten thousand volunteers did the regulator agree to license it.","options":["Not only","Only after","Hardly","Seldom"],"correct":1,"answer":"Only after","vi":"Chỉ sau khi vắc-xin được thử nghiệm trên mười nghìn tình nguyện viên, cơ quan quản lý mới đồng ý cấp phép cho nó.","explanation":"<b>Only after</b> + clause at the start of a sentence forces inversion in the main clause: <b>did the regulator agree</b>. <b>Not only</b> and <b>Hardly</b> must be followed immediately by the inverted verb, and <b>Seldom</b> gives no time sequence at all."},{"id":"gv-ch-22-9","level":"ch","focus":"idiom","q":"The minister meant to unveil the carbon tax in June, but a careless tweet from an aide ______ three weeks early.","options":["let the cat out of the bag","let sleeping dogs lie","let off steam","let the grass grow under his feet"],"correct":0,"answer":"let the cat out of the bag","vi":"Bộ trưởng định công bố thuế các-bon vào tháng Sáu, nhưng một dòng tweet bất cẩn của trợ lý đã để lộ bí mật sớm ba tuần.","explanation":"<b>Let the cat out of the bag</b> = reveal a secret by accident. <b>Let sleeping dogs lie</b> = avoid stirring up trouble; <b>let off steam</b> = release pent-up anger; <b>let the grass grow under one's feet</b> = waste time."},{"id":"gv-ch-22-10","level":"ch","focus":"subjunctive","q":"The union insisted that every worker ______ issued with protective clothing before entering the contaminated site.","options":["were","has been","be","will be"],"correct":2,"answer":"be","vi":"Công đoàn khăng khăng yêu cầu mọi công nhân phải được cấp quần áo bảo hộ trước khi vào khu vực bị ô nhiễm.","explanation":"After verbs of demand such as <b>insist, demand, suggest</b> + that, the verb takes the bare subjunctive: <b>(should) be issued</b>, whatever the tense of the main verb."},{"id":"gv-ch-22-11","level":"ch","focus":"collocation","q":"The evidence against the ringleader was ______ – fingerprints, CCTV footage and two eyewitnesses who picked him out of a line-up.","options":["overpowering","overwhelming","overriding","overbearing"],"correct":1,"answer":"overwhelming","vi":"Bằng chứng chống lại kẻ cầm đầu là quá rõ ràng và áp đảo – dấu vân tay, hình ảnh camera an ninh và hai nhân chứng đã nhận diện được hắn.","explanation":"<b>Overwhelming evidence</b> is the collocation for evidence too strong to argue with; <b>overpowering</b> describes smells or feelings, <b>overriding</b> a priority, and <b>overbearing</b> a domineering person."},{"id":"gv-ch-22-12","level":"ch","focus":"gerund-infinitive","q":"The accountant admitted ______ the invoices but denied knowing that they had been forged.","options":["to sign","having signed","to have signed","sign"],"correct":1,"answer":"having signed","vi":"Kế toán viên thừa nhận đã ký các hóa đơn nhưng phủ nhận việc biết chúng là giả.","explanation":"<b>Admit</b> is followed by a gerund, never an infinitive; the perfect gerund <b>having signed</b> shows the signing happened before the admission."},{"id":"gv-ch-22-13","level":"ch","focus":"word-choice","q":"The new sentencing guidelines give judges very little ______ to shorten a term for a first-time offender.","options":["allowance","clearance","tolerance","leeway"],"correct":3,"answer":"leeway","vi":"Hướng dẫn tuyên án mới cho các thẩm phán rất ít khoảng linh hoạt để rút ngắn mức án đối với người phạm tội lần đầu.","explanation":"<b>Leeway</b> is the freedom to vary from a rule within limits; an <b>allowance</b> is money or a permitted amount, <b>clearance</b> is official permission or physical space, and <b>tolerance</b> is the willingness to accept something."},{"id":"gv-ch-22-14","level":"ch","focus":"phrasal-verb","q":"Give me a couple of days to ______ your offer before I hand in my notice at the bank.","options":["mull over","glaze over","hand over","take over"],"correct":0,"answer":"mull over","vi":"Hãy cho tôi vài ngày để cân nhắc kỹ lời đề nghị của anh trước khi tôi nộp đơn xin nghỉ việc ở ngân hàng.","explanation":"<b>Mull over</b> = think carefully about something for a period of time. <b>Glaze over</b> is what bored eyes do; <b>hand over</b> = give to someone; <b>take over</b> = gain control of."},{"id":"gv-ch-22-15","level":"ch","focus":"linking","q":"The tannery was fined twice last year; ______, it continues to discharge untreated waste into the river.","options":["whereas","therefore","nevertheless","otherwise"],"correct":2,"answer":"nevertheless","vi":"Xưởng thuộc da đã bị phạt hai lần vào năm ngoái; tuy vậy, nó vẫn tiếp tục xả chất thải chưa qua xử lý ra sông.","explanation":"The second clause goes against what the fines should have achieved, so the concessive adverb <b>nevertheless</b> fits; <b>whereas</b> is a conjunction, and <b>therefore / otherwise</b> give the wrong logic."},{"id":"gv-ch-22-16","level":"ch","focus":"participle","q":"______ afford the rising licence fees, the small radio station switched to streaming its programmes online.","options":["Been unable to","Be unable to","Having unable to","Being unable to"],"correct":3,"answer":"Being unable to","vi":"Vì không thể trả nổi phí bản quyền ngày càng tăng, đài phát thanh nhỏ đã chuyển sang phát trực tuyến các chương trình của mình.","explanation":"A present participle clause gives the reason for the main clause: <b>Being unable to afford</b> = because it was unable to afford. <b>Been</b> and <b>Be</b> cannot open a participle clause, and <b>having</b> needs a past participle (<b>having been unable</b>), not the adjective <b>unable</b> on its own."},{"id":"gv-ch-22-17","level":"ch","focus":"idiom","q":"Companies that delay investing in wind power now may well ______ when the government subsidies are withdrawn next year.","options":["miss the boat","miss the mark","miss the point","miss a beat"],"correct":0,"answer":"miss the boat","vi":"Những công ty trì hoãn đầu tư vào điện gió lúc này rất có thể sẽ bỏ lỡ cơ hội khi trợ cấp của chính phủ bị rút vào năm tới.","explanation":"<b>Miss the boat</b> = lose an opportunity by being too slow. <b>Miss the mark</b> = fail to achieve the aim; <b>miss the point</b> = fail to understand; <b>miss a beat</b> = hesitate."},{"id":"gv-ch-22-18","level":"ch","focus":"agreement","q":"A number of senior engineers ______ resigned since the merger was announced, leaving the department badly understaffed.","options":["has","have","is","was"],"correct":1,"answer":"have","vi":"Nhiều kỹ sư cấp cao đã từ chức kể từ khi vụ sáp nhập được công bố, khiến bộ phận này thiếu nhân lực trầm trọng.","explanation":"<b>A number of</b> + plural noun takes a plural verb, and <b>since</b> calls for the present perfect: <b>have resigned</b>. (<b>The number of</b> would be singular.)"},{"id":"gv-ch-22-19","level":"ch","focus":"word-choice","q":"Global coal consumption reached its ______ in 2013 and has been drifting downwards ever since.","options":["summit","climax","peak","crest"],"correct":2,"answer":"peak","vi":"Mức tiêu thụ than toàn cầu đạt đỉnh vào năm 2013 và đã giảm dần kể từ đó.","explanation":"A quantity reaches its <b>peak</b> (highest level); a <b>summit</b> is the top of a mountain or a leaders' meeting, a <b>climax</b> is the most exciting point of a story, and a <b>crest</b> is the top of a wave or hill."},{"id":"gv-ch-22-20","level":"ch","focus":"passive","q":"The suspect is believed ______ the country on a false passport within hours of the robbery.","options":["to have left","to leave","having left","to be left"],"correct":0,"answer":"to have left","vi":"Nghi phạm được cho là đã rời khỏi đất nước bằng hộ chiếu giả chỉ vài giờ sau vụ cướp.","explanation":"With <b>be believed / thought / said</b> + infinitive, an action that happened earlier takes the perfect infinitive: <b>is believed to have left</b>."},{"id":"gv-ch-22-21","level":"ch","focus":"comparison","q":"Recycling aluminium uses ______ energy than smelting it from raw ore, which is why scrap cans are so valuable.","options":["far less","much fewer","very less","the least"],"correct":0,"answer":"far less","vi":"Tái chế nhôm tiêu tốn ít năng lượng hơn nhiều so với luyện từ quặng thô, đó là lý do lon nhôm phế liệu có giá trị đến vậy.","explanation":"<b>Energy</b> is uncountable, so the comparative is <b>less</b>, intensified by <b>far</b> (or <b>much</b>); <b>fewer</b> goes with countable nouns and <b>very</b> cannot modify a comparative."},{"id":"gv-ch-22-22","level":"ch","focus":"idiom","q":"When my manager announced that the whole department would be relocating to Iceland, I assumed she was ______.","options":["pulling strings","pulling my leg","pulling her weight","pulling her punches"],"correct":1,"answer":"pulling my leg","vi":"Khi quản lý của tôi thông báo rằng cả phòng sẽ chuyển tới Iceland, tôi cứ tưởng chị ấy đang trêu tôi.","explanation":"<b>Pull someone's leg</b> = tease them with a joke that is not true. <b>Pull strings</b> = use influence; <b>pull one's weight</b> = do one's share of the work; <b>pull one's punches</b> = be less harsh than one could be."},{"id":"gv-ch-22-23","level":"ch","focus":"collocation","q":"An independent laboratory has ______ doubt on the company's claim that the leak was contained within hours.","options":["shed","laid","cast","drawn"],"correct":2,"answer":"cast","vi":"Một phòng thí nghiệm độc lập đã đặt nghi vấn về tuyên bố của công ty rằng vụ rò rỉ đã được khống chế trong vài giờ.","explanation":"The collocation is <b>cast doubt on</b> something; you <b>shed light on</b> a matter and <b>draw attention to</b> it, but doubt is <b>cast</b>."},{"id":"gv-ch-22-24","level":"ch","focus":"double-blank","q":"After weeks of haggling, the delegates finally ______ down the wording of the treaty, ______ that the wealthiest nations would fund the adaptation programme.","options":["pinned / unless","boiled / in case","narrowed / as long as","nailed / provided"],"correct":3,"answer":"nailed / provided","vi":"Sau nhiều tuần mặc cả, các đại biểu cuối cùng cũng chốt được câu chữ của hiệp ước, với điều kiện các quốc gia giàu nhất sẽ tài trợ cho chương trình thích ứng.","explanation":"<b>Nail down</b> = settle something definitely, and the condition attached is introduced by <b>provided that</b>; <b>unless / in case / as long as</b> cannot be followed by <b>that</b>."},{"id":"gv-ch-22-25","level":"ch","focus":"word-choice","q":"Even a minute ______ of the pesticide is enough to kill the bees that pollinate the orchard.","options":["portion","ration","serving","dose"],"correct":3,"answer":"dose","vi":"Chỉ một liều thuốc trừ sâu rất nhỏ cũng đủ để giết chết những con ong thụ phấn cho vườn cây.","explanation":"A <b>dose</b> is a measured quantity of a drug or chemical; <b>portion</b> and <b>serving</b> are amounts of food, and a <b>ration</b> is a fixed allowance in times of shortage."},{"id":"gv-ch-23-1","level":"ch","focus":"word-choice","q":"The board has appointed an independent auditor to ______ how the foundation spends its grant money.","options":["overlook","oversee","overhaul","overdo"],"correct":1,"answer":"oversee","vi":"Hội đồng đã bổ nhiệm một kiểm toán viên độc lập để giám sát cách quỹ chi tiêu tiền tài trợ.","explanation":"<b>Oversee</b> means to supervise or watch over a process. <b>Overlook</b> is to fail to notice, <b>overhaul</b> is to rebuild or reform something completely, and <b>overdo</b> is to do something to excess."},{"id":"gv-ch-23-2","level":"ch","focus":"idiom","q":"Although they belong to the same party, the two ministers seldom ______ on how tuition fees should be set.","options":["see eye to eye","go hand in hand","stand shoulder to shoulder","play cat and mouse"],"correct":0,"answer":"see eye to eye","vi":"Dù cùng một đảng, hai vị bộ trưởng hiếm khi đồng quan điểm về cách ấn định học phí.","explanation":"<b>See eye to eye (on something)</b> means to agree completely. <b>Go hand in hand</b> is used of two things that occur together, <b>stand shoulder to shoulder</b> means to support each other, and <b>play cat and mouse</b> means to tease or toy with someone."},{"id":"gv-ch-23-3","level":"ch","focus":"collocation","q":"Sociologists describe the rush to buy the latest phone as a form of ______ consumption, a way of displaying wealth rather than meeting a need.","options":["obvious","visible","conspicuous","noticeable"],"correct":2,"answer":"conspicuous","vi":"Các nhà xã hội học mô tả cơn sốt mua điện thoại đời mới nhất là một dạng tiêu dùng phô trương, một cách khoe của cải hơn là đáp ứng nhu cầu.","explanation":"<b>Conspicuous consumption</b> is the fixed term for buying expensive goods to show off one's wealth. <b>Obvious</b>, <b>visible</b> and <b>noticeable</b> are near-synonyms in meaning but do not form this collocation."},{"id":"gv-ch-23-4","level":"ch","focus":"linking","q":"______ the sharp rise in university tuition, enrolment has continued to climb for the fifth year running.","options":["Although","Whereas","However","Despite"],"correct":3,"answer":"Despite","vi":"Bất chấp học phí đại học tăng mạnh, số sinh viên nhập học vẫn tiếp tục tăng năm thứ năm liên tiếp.","explanation":"The blank is followed by a noun phrase (<b>the sharp rise</b>), so it needs the preposition <b>despite</b>. <b>Although</b> and <b>whereas</b> introduce a clause with a verb, and <b>however</b> links two separate sentences."},{"id":"gv-ch-23-5","level":"ch","focus":"phrasal-verb","q":"Parents who do not want their children's test scores shared with private companies may ______ of the scheme by returning a signed form.","options":["rule out","opt out","leave out","sort out"],"correct":1,"answer":"opt out","vi":"Phụ huynh không muốn điểm thi của con bị chia sẻ với các công ty tư nhân có thể rút khỏi chương trình bằng cách nộp lại mẫu đơn có chữ ký.","explanation":"<b>Opt out of</b> something means to choose not to take part in it. <b>Rule out</b>, <b>leave out</b> and <b>sort out</b> all need a direct object and cannot be followed by <b>of</b> here."},{"id":"gv-ch-23-6","level":"ch","focus":"modal","q":"The donors ______ have known that the funds were being misused; the accounts were never shown to them.","options":["can't","must","should","needn't"],"correct":0,"answer":"can't","vi":"Các nhà tài trợ không thể nào biết được rằng tiền đang bị sử dụng sai mục đích; họ chưa từng được xem sổ sách.","explanation":"<b>Can't have + past participle</b> expresses certainty that something did NOT happen in the past, which the second clause confirms. <b>Must have</b> would mean the opposite, <b>should have</b> criticises, and <b>needn't have</b> says an action was unnecessary."},{"id":"gv-ch-23-7","level":"ch","focus":"word-choice","q":"Frequent reversals of exam policy ______ public trust in the ministry far more than any single unpopular decision.","options":["underpin","underlie","undergo","undermine"],"correct":3,"answer":"undermine","vi":"Việc liên tục đảo ngược chính sách thi cử làm xói mòn lòng tin của công chúng vào bộ nhiều hơn bất kỳ quyết định không được lòng dân nào.","explanation":"<b>Undermine</b> means to gradually weaken something. <b>Underpin</b> means to support, <b>underlie</b> means to be the hidden basis of, and <b>undergo</b> means to experience a process."},{"id":"gv-ch-23-8","level":"ch","focus":"double-blank","q":"The ministry intends to ______ out printed textbooks ______ 2030, replacing them with tablets in every classroom.","options":["fade / until","wipe / at","phase / by","wear / in"],"correct":2,"answer":"phase / by","vi":"Bộ dự định loại bỏ dần sách giáo khoa in trước năm 2030, thay bằng máy tính bảng ở mọi lớp học.","explanation":"<b>Phase out</b> means to withdraw something gradually in stages, and a deadline takes <b>by</b> (no later than) 2030. <b>Fade out</b> is intransitive, <b>wipe out</b> means destroy, and <b>wear out</b> means use until unusable."},{"id":"gv-ch-23-9","level":"ch","focus":"inversion","q":"______ should laboratory staff attempt to dispose of chemical waste without wearing protective gloves.","options":["Only after","Not until","Under no circumstances","No sooner"],"correct":2,"answer":"Under no circumstances","vi":"Trong bất kỳ trường hợp nào, nhân viên phòng thí nghiệm cũng không được cố xử lý chất thải hóa học mà không đeo găng tay bảo hộ.","explanation":"<b>Under no circumstances</b> is a negative adverbial that stands alone at the front of a sentence and forces inversion (<b>should staff attempt</b>). <b>Only after</b> and <b>not until</b> need a time phrase or clause before the inverted verb, and <b>no sooner</b> requires a following <b>than</b>."},{"id":"gv-ch-23-10","level":"ch","focus":"idiom","q":"A: Has the sponsor replied to our proposal yet? B: Not yet. Oh, ______ - here she comes now.","options":["hold your horses","the talk of the town","bite your tongue","speak of the devil"],"correct":3,"answer":"speak of the devil","vi":"A: Nhà tài trợ đã trả lời đề xuất của chúng ta chưa? B: Chưa. Ồ, vừa nhắc đã tới - cô ấy đang đến kìa.","explanation":"<b>Speak of the devil</b> is said when the person you have just been talking about appears. <b>Hold your horses</b> means wait, <b>the talk of the town</b> is a topic everyone discusses, and <b>bite your tongue</b> means stop yourself from speaking."},{"id":"gv-ch-23-11","level":"ch","focus":"collocation","q":"Regulators must ______ a balance between protecting consumers and allowing online retailers to innovate.","options":["strike","hit","beat","knock"],"correct":0,"answer":"strike","vi":"Các cơ quan quản lý phải tìm được sự cân bằng giữa bảo vệ người tiêu dùng và cho phép các nhà bán lẻ trực tuyến đổi mới.","explanation":"<b>Strike a balance</b> is the fixed collocation meaning to find a fair compromise. <b>Hit</b>, <b>beat</b> and <b>knock</b> share the sense of striking but do not collocate with <b>balance</b>."},{"id":"gv-ch-23-12","level":"ch","focus":"reported","q":"In her speech the minister said that the new grading system ______ nationwide the following year.","options":["will be introduced","is introduced","would be introduced","had introduced"],"correct":2,"answer":"would be introduced","vi":"Trong bài phát biểu, bộ trưởng nói rằng hệ thống chấm điểm mới sẽ được áp dụng trên toàn quốc vào năm sau.","explanation":"In reported speech after <b>said</b>, <b>will be introduced</b> shifts back to <b>would be introduced</b>; <b>the following year</b> confirms the backshift. <b>Had introduced</b> is active and needs an object."},{"id":"gv-ch-23-13","level":"ch","focus":"word-choice","q":"Critics argue that the report ______ the benefits of private tutoring while ignoring the pressure it puts on families.","options":["overrules","overstates","overrides","overshadows"],"correct":1,"answer":"overstates","vi":"Giới phê bình cho rằng báo cáo thổi phồng lợi ích của việc học thêm trong khi phớt lờ áp lực mà nó gây ra cho các gia đình.","explanation":"<b>Overstate</b> means to describe something as bigger or better than it really is. <b>Overrule</b> is to reject a decision by authority, <b>override</b> is to cancel or take priority over, and <b>overshadow</b> is to make something seem less important."},{"id":"gv-ch-23-14","level":"ch","focus":"subjunctive","q":"The auditor recommended that the foundation ______ its full list of donors public before the next fundraising drive.","options":["make","makes","made","will make"],"correct":0,"answer":"make","vi":"Kiểm toán viên khuyến nghị quỹ công khai toàn bộ danh sách nhà tài trợ trước đợt gây quỹ tiếp theo.","explanation":"After <b>recommend that</b>, the verb takes the base-form subjunctive: <b>that the foundation make</b>. The subjunctive has no <b>-s</b>, no past form and no <b>will</b>."},{"id":"gv-ch-23-15","level":"ch","focus":"idiom","q":"We have submitted our final offer for the sponsorship deal, so now ______.","options":["the shoe is on the other foot","the coast is clear","the ball is in your court","the sky is the limit"],"correct":2,"answer":"the ball is in your court","vi":"Chúng tôi đã gửi đề nghị cuối cùng cho hợp đồng tài trợ, nên giờ quyền quyết định thuộc về các bạn.","explanation":"<b>The ball is in your court</b> means it is now your turn to act or decide. <b>The shoe is on the other foot</b> means the situation has reversed, <b>the coast is clear</b> means there is no danger, and <b>the sky is the limit</b> means there is no upper limit."},{"id":"gv-ch-23-16","level":"ch","focus":"gerund-infinitive","q":"Shoppers who are used to ______ discounts every weekend seldom notice when prices quietly rise.","options":["see","have seen","being seen","seeing"],"correct":3,"answer":"seeing","vi":"Những người mua sắm đã quen với việc thấy giảm giá mỗi cuối tuần hiếm khi để ý khi giá âm thầm tăng lên.","explanation":"<b>Be used to</b> (accustomed to) is followed by a gerund: <b>used to seeing</b>. The bare infinitive belongs to <b>used to</b> for past habits, and <b>being seen</b> is passive, which makes no sense here."},{"id":"gv-ch-23-17","level":"ch","focus":"phrasal-verb","q":"The plan to fund a library in every rural district did not ______ as hoped, and half the donated money was returned.","options":["pan out","pass out","hand out","peter out"],"correct":0,"answer":"pan out","vi":"Kế hoạch tài trợ một thư viện cho mỗi huyện nông thôn đã không thành công như mong đợi, và một nửa số tiền quyên góp bị trả lại.","explanation":"<b>Pan out</b> means to develop or turn out successfully. <b>Pass out</b> means to faint, <b>hand out</b> means to distribute, and <b>peter out</b> means to fade away gradually."},{"id":"gv-ch-23-18","level":"ch","focus":"participle","q":"______ a sudden shortage of nurses, the hospital has begun recruiting from overseas for the first time in its history.","options":["Facing with","Having faced with","To face with","Faced with"],"correct":3,"answer":"Faced with","vi":"Đứng trước tình trạng thiếu y tá đột ngột, bệnh viện lần đầu tiên trong lịch sử đã bắt đầu tuyển dụng từ nước ngoài.","explanation":"The hospital is the one confronted by the shortage, so the passive participle <b>faced with</b> (= confronted by) opens the clause. Active <b>face</b> takes a direct object with no preposition, so <b>facing with</b>, <b>having faced with</b> and <b>to face with</b> are all impossible."},{"id":"gv-ch-23-19","level":"ch","focus":"word-choice","q":"Investing in teacher training rather than new buildings was a ______ decision whose benefits are only now becoming visible.","options":["far-flung","far-off","far-sighted","far-out"],"correct":2,"answer":"far-sighted","vi":"Đầu tư vào đào tạo giáo viên thay vì xây dựng mới là một quyết định có tầm nhìn xa mà lợi ích chỉ giờ đây mới dần lộ rõ.","explanation":"<b>Far-sighted</b> describes a decision showing wise judgement about the future. <b>Far-flung</b> means distant and widely spread, <b>far-off</b> means remote in place or time, and <b>far-out</b> is informal for strange or unconventional."},{"id":"gv-ch-23-20","level":"ch","focus":"idiom","q":"Every speaker praised the new curriculum, but nobody mentioned ______: the chronic shortage of qualified teachers.","options":["the skeleton in the cupboard","the elephant in the room","the black sheep of the family","the last straw"],"correct":1,"answer":"the elephant in the room","vi":"Diễn giả nào cũng ca ngợi chương trình mới, nhưng không ai nhắc đến vấn đề hiển nhiên mà mọi người đều né tránh: tình trạng thiếu giáo viên có trình độ kéo dài.","explanation":"<b>The elephant in the room</b> is an obvious problem that everyone avoids discussing. <b>A skeleton in the cupboard</b> is a hidden shameful secret, <b>the black sheep</b> is a family member who is an embarrassment, and <b>the last straw</b> is the final problem that makes a situation unbearable."},{"id":"gv-ch-23-21","level":"ch","focus":"pronoun","q":"Rival fashion retailers now copy ______ so quickly that a new design rarely stays exclusive for more than a week.","options":["themselves","each","another","one another"],"correct":3,"answer":"one another","vi":"Các nhà bán lẻ thời trang đối thủ giờ sao chép lẫn nhau nhanh đến mức một mẫu thiết kế mới hiếm khi giữ được tính độc quyền quá một tuần.","explanation":"The retailers copy each other, so the reciprocal pronoun <b>one another</b> is needed. <b>Themselves</b> would mean each copies its own designs, and <b>each</b> or <b>another</b> alone cannot express the mutual action."},{"id":"gv-ch-23-22","level":"ch","focus":"double-blank","q":"Rather than ______ on the fence any longer, the school board must ______ a clear stance on mobile phones in class.","options":["sit / take","stand / make","lean / hold","stay / do"],"correct":0,"answer":"sit / take","vi":"Thay vì tiếp tục lưỡng lự không quyết, hội đồng trường phải có lập trường rõ ràng về điện thoại di động trong lớp.","explanation":"<b>Sit on the fence</b> means to avoid choosing a side, and the verb that collocates with <b>stance</b> is <b>take</b>. None of the other pairs completes both the idiom and the collocation."},{"id":"gv-ch-23-23","level":"ch","focus":"collocation","q":"Since the scandal broke, the charity's spending has come under ______ scrutiny from journalists and regulators alike.","options":["near","tight","thick","close"],"correct":3,"answer":"close","vi":"Từ khi vụ bê bối bị phanh phui, chi tiêu của tổ chức từ thiện này đã bị cả nhà báo lẫn cơ quan quản lý xem xét kỹ lưỡng.","explanation":"<b>Close scrutiny</b> is the standard collocation for very careful examination. <b>Near</b>, <b>tight</b> and <b>thick</b> do not collocate with <b>scrutiny</b>."},{"id":"gv-ch-23-24","level":"ch","focus":"question-tag","q":"Nobody really expects the cap on private-school fees to survive the next budget, ______?","options":["don't they","does it","do they","doesn't it"],"correct":2,"answer":"do they","vi":"Thật ra chẳng ai mong mức trần học phí trường tư sẽ tồn tại qua kỳ ngân sách tới, phải không?","explanation":"After <b>nobody</b>, the tag uses the pronoun <b>they</b> and, because the statement is already negative in meaning, a positive tag: <b>do they</b>."},{"id":"gv-ch-23-25","level":"ch","focus":"word-choice","q":"The fund offers full scholarships to ______ students who would otherwise have no chance of attending a specialist high school.","options":["underlying","underprivileged","understaffed","undervalued"],"correct":1,"answer":"underprivileged","vi":"Quỹ cấp học bổng toàn phần cho những học sinh có hoàn cảnh khó khăn, những em nếu không sẽ chẳng có cơ hội vào trường chuyên.","explanation":"<b>Underprivileged</b> describes people who lack the advantages and money others have. <b>Underlying</b> means basic or hidden, <b>understaffed</b> describes an organisation with too few workers, and <b>undervalued</b> means not appreciated enough."},{"id":"gv-ch-24-1","level":"ch","focus":"idiom","q":"Small family firms often weather a recession because their staff stand by them ______, even when wages are paid late.","options":["through thick and thin","by hook or by crook","by leaps and bounds","at sixes and sevens"],"correct":0,"answer":"through thick and thin","vi":"Các doanh nghiệp gia đình nhỏ thường vượt qua suy thoái vì nhân viên sát cánh cùng họ dù sướng hay khổ, ngay cả khi lương bị trả chậm.","explanation":"<b>Through thick and thin</b> = loyally, in good times and bad. <b>By hook or by crook</b> means by any means, <b>by leaps and bounds</b> describes rapid progress, and <b>at sixes and sevens</b> means in confusion — none describes loyalty."},{"id":"gv-ch-24-2","level":"ch","focus":"idiom","q":"Setting up two-factor authentication turned out to be ______ — the whole process took less than a minute.","options":["a hard nut to crack","a piece of cake","a storm in a teacup","a drop in the ocean"],"correct":1,"answer":"a piece of cake","vi":"Hóa ra việc cài đặt xác thực hai lớp dễ như ăn kẹo — toàn bộ quá trình chưa đến một phút.","explanation":"<b>A piece of cake</b> = something very easy. <b>A hard nut to crack</b> is the opposite, <b>a storm in a teacup</b> is a fuss about nothing, and <b>a drop in the ocean</b> is a tiny, insignificant amount."},{"id":"gv-ch-24-3","level":"ch","focus":"word-choice","q":"Data brokers can ______ a user's home address from nothing more than a handful of location pings.","options":["overlook","survey","pinpoint","browse"],"correct":2,"answer":"pinpoint","vi":"Các công ty môi giới dữ liệu có thể xác định chính xác địa chỉ nhà của người dùng chỉ từ vài tín hiệu định vị.","explanation":"<b>Pinpoint</b> = locate or identify exactly. <b>Overlook</b> means to fail to notice, <b>survey</b> means to look over a wide area, and <b>browse</b> means to look through casually."},{"id":"gv-ch-24-4","level":"ch","focus":"idiom","q":"When the regulator rejected the trial data, the research team found itself ______, with three years of work to repeat.","options":["on the same page","out of the woods","in the same boat","back to square one"],"correct":3,"answer":"back to square one","vi":"Khi cơ quan quản lý bác bỏ dữ liệu thử nghiệm, nhóm nghiên cứu thấy mình phải bắt đầu lại từ đầu, với ba năm công sức phải làm lại.","explanation":"<b>Back to square one</b> = back at the very beginning, having made no progress. <b>On the same page</b> means in agreement, <b>out of the woods</b> means safe from danger, and <b>in the same boat</b> means in the same difficult situation."},{"id":"gv-ch-24-5","level":"ch","focus":"word-choice","q":"The auditors spent three weeks ______ over the bank's ledgers before the missing transfers came to light.","options":["poring","peering","gazing","squinting"],"correct":0,"answer":"poring","vi":"Các kiểm toán viên mất ba tuần nghiền ngẫm sổ sách của ngân hàng trước khi các khoản chuyển tiền thất thoát bị phát hiện.","explanation":"<b>Pore over</b> = study something very carefully. <b>Peer</b>, <b>gaze</b> and <b>squint</b> describe how the eyes look (with difficulty, steadily, half-closed), not the careful study of a document."},{"id":"gv-ch-24-6","level":"ch","focus":"double-blank","q":"The surgeon was confident the patient would pull ______, though recovery ______ such an operation can take months.","options":["over / of","through / from","out / in","off / to"],"correct":1,"answer":"through / from","vi":"Bác sĩ phẫu thuật tin rằng bệnh nhân sẽ qua khỏi, dù việc hồi phục sau một ca mổ như vậy có thể mất nhiều tháng.","explanation":"<b>Pull through</b> = survive a serious illness or operation; the noun <b>recovery</b> takes the preposition <b>from</b>. <b>Pull over/out/off</b> have other meanings, and <b>recovery of/in/to</b> would not mean getting better after an illness."},{"id":"gv-ch-24-7","level":"ch","focus":"phrasal-verb","q":"Company spokespeople tried to ______ the scale of the breach, insisting only a handful of accounts had been exposed.","options":["play up","play off","play down","play along"],"correct":2,"answer":"play down","vi":"Người phát ngôn của công ty cố giảm nhẹ mức độ của vụ rò rỉ, khăng khăng rằng chỉ một số ít tài khoản bị lộ.","explanation":"<b>Play down</b> = make something seem less serious than it is. <b>Play up</b> is the opposite (exaggerate), <b>play off</b> means to set people against each other, and <b>play along</b> means to pretend to agree."},{"id":"gv-ch-24-8","level":"ch","focus":"phrasal-verb","q":"Despite objections from privacy groups, the ministry has decided to ______ with the facial-recognition scheme in every station.","options":["press for","get ahead","press upon","press ahead"],"correct":3,"answer":"press ahead","vi":"Bất chấp sự phản đối của các nhóm bảo vệ quyền riêng tư, bộ đã quyết định xúc tiến kế hoạch nhận diện khuôn mặt ở mọi nhà ga.","explanation":"<b>Press ahead with</b> = continue determinedly with a plan despite opposition. <b>Press for</b> means to demand, <b>press upon</b> means to force something on someone, and <b>get ahead</b> means to advance in a career."},{"id":"gv-ch-24-9","level":"ch","focus":"double-blank","q":"The merger is still ______ in the air, so the bank has put its hiring plans ______ hold.","options":["up / on","out / in","off / at","over / under"],"correct":0,"answer":"up / on","vi":"Vụ sáp nhập vẫn còn chưa ngã ngũ, nên ngân hàng đã tạm hoãn kế hoạch tuyển dụng.","explanation":"<b>Up in the air</b> = still undecided; <b>on hold</b> = postponed. No other pair completes both fixed expressions."},{"id":"gv-ch-24-10","level":"ch","focus":"collocation","q":"Economists warn that ______ inflation is quietly eroding the value of household savings.","options":["insistent","persistent","resistant","consistent"],"correct":1,"answer":"persistent","vi":"Các nhà kinh tế cảnh báo rằng lạm phát dai dẳng đang âm thầm bào mòn giá trị tiền tiết kiệm của các hộ gia đình.","explanation":"<b>Persistent inflation</b> is the standard collocation for inflation that refuses to go away. <b>Insistent</b> describes a demanding person, <b>resistant</b> needs <b>to</b>, and <b>consistent</b> means steady or unchanging, not stubborn."},{"id":"gv-ch-24-11","level":"ch","focus":"idiom","q":"The two governments reached a tariff deal ______, only minutes before the new duties were due to take effect.","options":["at the end of the day","around the clock","at the eleventh hour","in the long run"],"correct":2,"answer":"at the eleventh hour","vi":"Hai chính phủ đạt được thỏa thuận thuế quan vào phút chót, chỉ vài phút trước khi các mức thuế mới có hiệu lực.","explanation":"<b>At the eleventh hour</b> = at the last possible moment. <b>At the end of the day</b> means 'ultimately', <b>around the clock</b> means 'all day and night', and <b>in the long run</b> means 'eventually'."},{"id":"gv-ch-24-12","level":"ch","focus":"collocation","q":"The health ministry has ______ a thorough investigation into hygiene standards at the private clinic.","options":["made","done","taken","conducted"],"correct":3,"answer":"conducted","vi":"Bộ Y tế đã tiến hành một cuộc điều tra kỹ lưỡng về tiêu chuẩn vệ sinh tại phòng khám tư đó.","explanation":"<b>Conduct an investigation</b> (also <b>carry out</b> or <b>hold</b> one) is the collocation. <b>Make</b>, <b>do</b> and <b>take</b> do not combine with <b>investigation</b>."},{"id":"gv-ch-24-13","level":"ch","focus":"collocation","q":"Regulators fined the platform for failing to obtain ______ consent before selling users' browsing histories to advertisers.","options":["informed","knowing","advised","aware"],"correct":0,"answer":"informed","vi":"Cơ quan quản lý đã phạt nền tảng này vì không xin được sự đồng ý có hiểu biết của người dùng trước khi bán lịch sử duyệt web của họ cho các nhà quảng cáo.","explanation":"<b>Informed consent</b> is the fixed legal and medical collocation for agreement given with full knowledge of the facts. <b>Knowing</b>, <b>advised</b> and <b>aware</b> are related in meaning but do not collocate with <b>consent</b>."},{"id":"gv-ch-24-14","level":"ch","focus":"linking","q":"Ministers insist the economy is recovering, ______ most households report that their real incomes have fallen.","options":["despite","whereas","otherwise","so that"],"correct":1,"answer":"whereas","vi":"Các bộ trưởng khẳng định nền kinh tế đang hồi phục, trong khi hầu hết các hộ gia đình cho biết thu nhập thực tế của họ đã giảm.","explanation":"<b>Whereas</b> introduces a clause that contrasts directly with the first. <b>Despite</b> must be followed by a noun or -ing form, <b>otherwise</b> means 'if not', and <b>so that</b> expresses purpose."},{"id":"gv-ch-24-15","level":"ch","focus":"gerund-infinitive","q":"After a decade in investment banking, she found it hard to get used to ______ on a researcher's salary.","options":["live","to live","living","having lived"],"correct":2,"answer":"living","vi":"Sau mười năm làm ngân hàng đầu tư, cô thấy khó mà quen được với việc sống bằng đồng lương của một nhà nghiên cứu.","explanation":"In <b>get used to</b>, <b>to</b> is a preposition, so it is followed by a gerund: <b>living</b>. <b>Having lived</b> would wrongly refer to a completed past action."},{"id":"gv-ch-24-16","level":"ch","focus":"subjunctive","q":"The board recommended that the chief executive ______ from any decision involving her family's shareholding.","options":["abstains","abstained","will abstain","abstain"],"correct":3,"answer":"abstain","vi":"Hội đồng quản trị đề nghị giám đốc điều hành không tham gia bất kỳ quyết định nào liên quan đến cổ phần của gia đình bà.","explanation":"After <b>recommend that</b>, the verb takes the base-form subjunctive: <b>abstain</b>, whatever the subject or the tense of the main clause."},{"id":"gv-ch-24-17","level":"ch","focus":"inversion","q":"______ for the central bank's emergency intervention, the currency would have collapsed within days.","options":["Had it not been","Had not it been","It had not been","Not had it been"],"correct":0,"answer":"Had it not been","vi":"Nếu không có sự can thiệp khẩn cấp của ngân hàng trung ương, đồng tiền này đã sụp đổ chỉ trong vài ngày.","explanation":"<b>Had it not been for</b> is the inverted form of <b>If it had not been for</b> in a third conditional: the auxiliary <b>had</b> moves before the subject <b>it</b>, and <b>not</b> follows the subject."},{"id":"gv-ch-24-18","level":"ch","focus":"inversion","q":"Only after the second wave of infections ______ the true cost of years of underfunding the health service.","options":["the public realised","did the public realise","the public did realise","realised the public"],"correct":1,"answer":"did the public realise","vi":"Chỉ sau làn sóng lây nhiễm thứ hai công chúng mới nhận ra cái giá thực sự của nhiều năm cắt giảm ngân sách y tế.","explanation":"When a sentence opens with <b>Only after</b> + phrase, the main clause is inverted: the auxiliary <b>did</b> comes before the subject, followed by the bare verb <b>realise</b>."},{"id":"gv-ch-24-19","level":"ch","focus":"word-choice","q":"Without her glasses, the pharmacist had to ______ at the tiny print on the label to read the dosage.","options":["gaze","glare","peer","observe"],"correct":2,"answer":"peer","vi":"Không có kính, dược sĩ phải nheo mắt nhìn kỹ dòng chữ li ti trên nhãn để đọc liều dùng.","explanation":"<b>Peer at</b> = look closely at something that is hard to see. <b>Gaze</b> is a long, steady look, <b>glare</b> is an angry look, and <b>observe</b> takes a direct object without <b>at</b>."},{"id":"gv-ch-24-20","level":"ch","focus":"word-choice","q":"Journalists eventually ______ the leaked memo to a contractor working for the health ministry.","options":["spotted","sighted","located","traced"],"correct":3,"answer":"traced","vi":"Cuối cùng các nhà báo đã lần ra bản ghi nhớ bị rò rỉ xuất phát từ một nhà thầu làm việc cho Bộ Y tế.","explanation":"<b>Trace something to</b> = follow evidence back to its source. <b>Spot</b>, <b>sight</b> and <b>locate</b> mean to find or see something, but none of them takes <b>to</b> a source."},{"id":"gv-ch-24-21","level":"ch","focus":"subjunctive","q":"It's high time regulators ______ a clear line between targeted advertising and outright surveillance.","options":["drew","draw","will draw","have drawn"],"correct":0,"answer":"drew","vi":"Đã đến lúc các cơ quan quản lý phải vạch ra ranh giới rõ ràng giữa quảng cáo nhắm mục tiêu và giám sát trắng trợn.","explanation":"<b>It's high time</b> + subject takes a past subjunctive (<b>drew</b>) to say something should already be happening. A present, future or perfect form is not used after this expression."},{"id":"gv-ch-24-22","level":"ch","focus":"article-quantifier","q":"______ research has been done on how late-night scrolling affects teenagers' sleep, so no one can yet say whether the harm is real.","options":["A little","Little","Few","A few"],"correct":1,"answer":"Little","vi":"Rất ít nghiên cứu được thực hiện về việc lướt điện thoại khuya ảnh hưởng thế nào đến giấc ngủ của thanh thiếu niên, nên chưa ai dám nói tác hại đó là có thật.","explanation":"<b>Research</b> is uncountable, so <b>few/a few</b> are impossible; <b>little</b> (without <b>a</b>) means 'almost none', which is why nobody can yet judge. <b>A little</b> would stress that some research does exist."},{"id":"gv-ch-24-23","level":"ch","focus":"modal","q":"The patient ______ the wrong dose — the pharmacy's records show every prescription that day was filled correctly.","options":["shouldn't have been given","needn't have been given","can't have been given","mustn't have been given"],"correct":2,"answer":"can't have been given","vi":"Bệnh nhân không thể nào đã bị đưa sai liều — hồ sơ nhà thuốc cho thấy mọi đơn thuốc hôm đó đều được cấp phát đúng.","explanation":"<b>Can't have + past participle</b> expresses a confident deduction that something did NOT happen. <b>Shouldn't have</b> criticises something that did happen, <b>needn't have</b> means it was unnecessary, and <b>mustn't have</b> is not used for deduction."},{"id":"gv-ch-24-24","level":"ch","focus":"participle","q":"______ the sheer volume of records exposed in the breach, investigators expect the inquiry to take at least a year.","options":["Giving","Give","Given","To give"],"correct":2,"answer":"Given","vi":"Xét đến khối lượng hồ sơ bị lộ quá lớn trong vụ rò rỉ, các điều tra viên dự đoán cuộc điều tra sẽ kéo dài ít nhất một năm.","explanation":"The past participle <b>Given</b> + noun works as a fixed preposition meaning 'considering, taking into account'. <b>Giving</b> would make the investigators the ones doing the giving, and <b>Give</b> or <b>To give</b> cannot introduce a noun phrase in this way."},{"id":"gv-ch-24-25","level":"ch","focus":"word-choice","q":"Most users simply ______ the headlines in their news feed rather than read a single article to the end.","options":["stare","skim","gaze","squint"],"correct":1,"answer":"skim","vi":"Hầu hết người dùng chỉ lướt qua các tiêu đề trong bảng tin thay vì đọc trọn vẹn dù chỉ một bài báo.","explanation":"<b>Skim</b> = read quickly to get the general idea, and it takes a direct object. <b>Stare</b>, <b>gaze</b> and <b>squint</b> are ways of looking (fixedly, steadily, with narrowed eyes) and would need <b>at</b>."},{"id":"gv-ch-25-1","level":"ch","focus":"tense","q":"By the end of this decade, the orbiting telescope ______ data for longer than any of its predecessors.","options":["will collect","is collecting","has been collecting","will have been collecting"],"correct":3,"answer":"will have been collecting","vi":"Đến cuối thập kỷ này, kính viễn vọng trên quỹ đạo sẽ đã thu thập dữ liệu lâu hơn bất kỳ kính tiền nhiệm nào.","explanation":"<b>By the end of this decade</b> marks a future deadline and <b>for longer than</b> stresses duration, so the future perfect continuous <b>will have been collecting</b> is needed; the present forms cannot reach a future point."},{"id":"gv-ch-25-2","level":"ch","focus":"idiom","q":"The minister spent ten minutes ______ before finally admitting that the excavation had been cancelled.","options":["beating around the bush","barking up the wrong tree","jumping the gun","burning her bridges"],"correct":0,"answer":"beating around the bush","vi":"Bà bộ trưởng vòng vo mất mười phút rồi cuối cùng mới thừa nhận rằng cuộc khai quật đã bị hủy.","explanation":"<b>Beat around the bush</b> = avoid saying something directly, which fits 'before finally admitting'. <b>Bark up the wrong tree</b> = pursue a mistaken idea, <b>jump the gun</b> = act too soon, <b>burn one's bridges</b> = destroy a way back."},{"id":"gv-ch-25-3","level":"ch","focus":"word-choice","q":"Insurers were reluctant to ______ the deep-sea expedition, since nobody could put a price on the risk of losing the submersible.","options":["undercut","outbid","underwrite","overcharge"],"correct":2,"answer":"underwrite","vi":"Các hãng bảo hiểm ngần ngại bảo lãnh cho chuyến thám hiểm biển sâu, vì không ai định giá nổi rủi ro mất chiếc tàu lặn.","explanation":"<b>Underwrite</b> = accept financial responsibility for a risk or loss, exactly what an insurer does. <b>Undercut</b> = sell cheaper than a rival, <b>outbid</b> = offer more money than, <b>overcharge</b> = charge too much."},{"id":"gv-ch-25-4","level":"ch","focus":"phrasal-verb","q":"The launch has been ______ to October after engineers found a hairline crack in a fuel line.","options":["pushed for","pushed back","pulled back","pushed on"],"correct":1,"answer":"pushed back","vi":"Vụ phóng đã bị lùi sang tháng Mười sau khi các kỹ sư phát hiện một vết nứt li ti trên đường ống nhiên liệu.","explanation":"<b>Push back</b> = postpone to a later date. <b>Push for</b> = campaign for, <b>push on</b> = continue, and <b>pull back</b> = withdraw, none of which takes 'to October'."},{"id":"gv-ch-25-5","level":"ch","focus":"collocation","q":"The eroding cliff poses a ______ threat to the Roman fort perched on top of it.","options":["heavy","high","deep","grave"],"correct":3,"answer":"grave","vi":"Vách đá đang xói mòn là một mối đe dọa nghiêm trọng đối với pháo đài La Mã nằm chênh vênh bên trên.","explanation":"A <b>grave threat</b> (or serious threat) is the fixed collocation; <b>heavy</b>, <b>high</b> and <b>deep</b> do not combine with 'threat'."},{"id":"gv-ch-25-6","level":"ch","focus":"subjunctive","q":"The safety board recommended that the airline ______ every aircraft of that type until the fault was traced.","options":["ground","grounds","grounded","would ground"],"correct":0,"answer":"ground","vi":"Ủy ban an toàn khuyến nghị rằng hãng hàng không đình bay mọi máy bay loại đó cho tới khi tìm ra lỗi.","explanation":"After <b>recommend that</b>, the verb takes the subjunctive base form <b>ground</b> regardless of the subject or the past-tense main verb."},{"id":"gv-ch-25-7","level":"ch","focus":"word-choice","q":"Cruise lines expect to ______ the cost of the new terminals within a decade through higher berthing fees.","options":["refund","recoup","redeem","reimburse"],"correct":1,"answer":"recoup","vi":"Các hãng du thuyền dự kiến thu hồi chi phí xây các bến cảng mới trong vòng một thập kỷ nhờ phí neo đậu cao hơn.","explanation":"<b>Recoup</b> = get back money you have spent or lost. <b>Refund</b> and <b>reimburse</b> mean paying money back <b>to someone else</b>; <b>redeem</b> = exchange a voucher or pay off a debt."},{"id":"gv-ch-25-8","level":"ch","focus":"idiom","q":"The hotel staff ______ to make the stranded passengers comfortable, even lending out their own phone chargers.","options":["turned over a new leaf","got cold feet","bent over backwards","let their hair down"],"correct":2,"answer":"bent over backwards","vi":"Nhân viên khách sạn đã hết lòng hết sức để hành khách bị mắc kẹt được thoải mái, thậm chí cho mượn cả sạc điện thoại của mình.","explanation":"<b>Bend over backwards</b> = try extremely hard to help someone. <b>Turn over a new leaf</b> = start behaving better, <b>get cold feet</b> = lose your nerve, <b>let your hair down</b> = relax and enjoy yourself."},{"id":"gv-ch-25-9","level":"ch","focus":"modal","q":"These bones ______ to a child; the growth plates had already fused when the person died.","options":["can't have belonged","mustn't have belonged","needn't have belonged","shouldn't have belonged"],"correct":0,"answer":"can't have belonged","vi":"Những mẩu xương này không thể là của một đứa trẻ; các đĩa sụn tăng trưởng đã liền hẳn khi người đó qua đời.","explanation":"A confident deduction that something was <b>impossible</b> in the past uses <b>can't have + past participle</b>. <b>Mustn't have</b> is not used for deduction; <b>needn't have</b> = it was unnecessary; <b>shouldn't have</b> = it was wrong to."},{"id":"gv-ch-25-10","level":"ch","focus":"double-blank","q":"The museum ______ several retired teachers ______ leading the weekend tours when its own guides fell ill.","options":["tied / into","roped / on","hauled / in","roped / into"],"correct":3,"answer":"roped / into","vi":"Bảo tàng đã lôi kéo mấy giáo viên về hưu vào việc dẫn các tour cuối tuần khi hướng dẫn viên của họ ngã bệnh.","explanation":"<b>Rope someone into doing something</b> = persuade them to take part in a task they did not plan to do. The verb <b>rope in</b> takes <b>into</b> before an -ing form; <b>tie into</b> and <b>haul in</b> do not carry this meaning."},{"id":"gv-ch-25-11","level":"ch","focus":"inversion","q":"Not until the ice cores had been analysed ______ how abruptly the climate had shifted.","options":["scientists realised","did scientists realise","had scientists realised","scientists did realise"],"correct":1,"answer":"did scientists realise","vi":"Mãi đến khi các lõi băng được phân tích, các nhà khoa học mới nhận ra khí hậu đã thay đổi đột ngột đến mức nào.","explanation":"A sentence opening with <b>Not until…</b> inverts the main clause: auxiliary <b>did</b> + subject + base verb. The realising happened after the analysis, so the past perfect <b>had scientists realised</b> is the wrong time."},{"id":"gv-ch-25-12","level":"ch","focus":"word-choice","q":"The council will ______ a small charge on every hotel night to pay for repairs to the medieval walls.","options":["impose","inflict","exert","instil"],"correct":0,"answer":"impose","vi":"Hội đồng thành phố sẽ áp một khoản phí nhỏ lên mỗi đêm lưu trú khách sạn để trả cho việc sửa chữa tường thành thời trung cổ.","explanation":"You <b>impose</b> a tax, charge or fine on people. <b>Inflict</b> goes with pain or damage, <b>exert</b> with pressure or influence, <b>instil</b> with values or feelings."},{"id":"gv-ch-25-13","level":"ch","focus":"participle","q":"______ from the same volcanic rock as the temple, the statues have weathered surprisingly little.","options":["Carving","Having carved","Carved","To carve"],"correct":2,"answer":"Carved","vi":"Được tạc từ cùng loại đá núi lửa với ngôi đền, các bức tượng phong hóa ít đến ngạc nhiên.","explanation":"The statues <b>were carved</b>, so the reduced clause needs the past participle <b>Carved</b> (passive meaning). <b>Carving</b> and <b>Having carved</b> would make the statues the carver."},{"id":"gv-ch-25-14","level":"ch","focus":"idiom","q":"The probe's landing sequence worked, but engineers admitted it had survived the descent ______.","options":["by leaps and bounds","by word of mouth","by the book","by the skin of its teeth"],"correct":3,"answer":"by the skin of its teeth","vi":"Chuỗi thao tác hạ cánh của tàu thăm dò đã thành công, nhưng các kỹ sư thừa nhận nó đã sống sót qua pha hạ cánh trong gang tấc.","explanation":"<b>By the skin of your teeth</b> = only just, narrowly. <b>By leaps and bounds</b> = very quickly, <b>by word of mouth</b> = through people talking, <b>by the book</b> = strictly following the rules."},{"id":"gv-ch-25-15","level":"ch","focus":"collocation","q":"Pollen trapped in the lake bed has ______ new light on how the harbour silted up.","options":["given","shed","put","set"],"correct":1,"answer":"shed","vi":"Phấn hoa mắc kẹt dưới đáy hồ đã soi rọi thêm về cách cảng biển bị bồi lấp.","explanation":"<b>Shed light on</b> (also throw/cast light on) = help explain. <b>Give</b>, <b>put</b> and <b>set</b> do not collocate with 'light on'."},{"id":"gv-ch-25-16","level":"ch","focus":"linking","q":"______ carefully a mission is planned, the launch still depends on the weather on the day.","options":["Even though","Whatever","No matter how","Despite"],"correct":2,"answer":"No matter how","vi":"Dù một sứ mệnh được lên kế hoạch kỹ lưỡng đến đâu, vụ phóng vẫn phụ thuộc vào thời tiết trong ngày.","explanation":"<b>No matter how + adverb + clause</b> = however carefully. <b>Despite</b> needs a noun, <b>Whatever</b> needs a noun, and <b>Even though</b> cannot be followed directly by an adverb like 'carefully'."},{"id":"gv-ch-25-17","level":"ch","focus":"word-choice","q":"The bronze helmet ______ a record price at auction, three times the estimate printed in the catalogue.","options":["charged","spent","afforded","fetched"],"correct":3,"answer":"fetched","vi":"Chiếc mũ trụ bằng đồng đã được bán với giá kỷ lục tại phiên đấu giá, gấp ba lần mức ước tính in trong catalogue.","explanation":"An object <b>fetches</b> a price = is sold for that amount. People <b>charge</b>, <b>spend</b> or can <b>afford</b> money; an object cannot."},{"id":"gv-ch-25-18","level":"ch","focus":"gerund-infinitive","q":"Having lived at the desert camp for months, the team had grown used ______ without running water.","options":["to living","to live","living","live"],"correct":0,"answer":"to living","vi":"Sau nhiều tháng sống ở trại giữa sa mạc, cả đội đã quen với việc không có nước máy.","explanation":"In <b>be/get/grow used to</b>, <b>to</b> is a preposition, so it is followed by the -ing form: <b>used to living</b>. 'Used to live' would mean a past habit, not a habit acquired."},{"id":"gv-ch-25-19","level":"ch","focus":"phrasal-verb","q":"The guide ______ the tangled history of the temple so clearly that even the youngest visitors could follow it.","options":["put off","put across","put down","put up"],"correct":1,"answer":"put across","vi":"Hướng dẫn viên trình bày lịch sử rối rắm của ngôi đền rõ ràng đến mức ngay cả những du khách nhỏ tuổi nhất cũng theo dõi được.","explanation":"<b>Put across</b> = communicate an idea so that people understand it. <b>Put off</b> = postpone/discourage, <b>put down</b> = criticise or write down, <b>put up</b> = build or accommodate."},{"id":"gv-ch-25-20","level":"ch","focus":"relative","q":"The tools, only half of ______ have been catalogued so far, date from the early Bronze Age.","options":["them","whom","which","whose"],"correct":2,"answer":"which","vi":"Những công cụ này, mà mới chỉ một nửa được lập danh mục, có niên đại từ đầu thời đại đồ đồng.","explanation":"A quantifier + <b>of which</b> introduces a non-defining relative clause about things; <b>whom</b> is for people, <b>whose</b> shows possession, and <b>them</b> would need a new sentence, not a comma."},{"id":"gv-ch-25-21","level":"ch","focus":"idiom","q":"With the conference paper due on Monday, the two researchers ______ all weekend.","options":["burned the midnight oil","hit the sack","threw in the towel","got the sack"],"correct":0,"answer":"burned the midnight oil","vi":"Bài báo hội nghị phải nộp vào thứ Hai nên hai nhà nghiên cứu đã thức trắng làm việc suốt cả cuối tuần.","explanation":"<b>Burn the midnight oil</b> = work late into the night. <b>Hit the sack</b> = go to bed, <b>throw in the towel</b> = give up, <b>get the sack</b> = be dismissed from a job."},{"id":"gv-ch-25-22","level":"ch","focus":"word-choice","q":"Entrance fees help to ______ the cost of conserving the mosaics, but they never cover it entirely.","options":["deduct","defray","deplete","default"],"correct":1,"answer":"defray","vi":"Tiền vé vào cửa giúp bù đắp một phần chi phí bảo tồn các bức tranh khảm, nhưng không bao giờ trang trải được toàn bộ.","explanation":"<b>Defray</b> a cost = provide money to pay part or all of it. <b>Deduct</b> = subtract from an amount, <b>deplete</b> = use up, <b>default</b> = fail to pay a debt."},{"id":"gv-ch-25-23","level":"ch","focus":"conditional","q":"The tourism board now wishes it ______ its marketing budget just before the pandemic struck.","options":["didn't cut","wouldn't cut","hasn't cut","hadn't cut"],"correct":3,"answer":"hadn't cut","vi":"Giờ đây cơ quan du lịch ước gì họ đã không cắt ngân sách quảng bá ngay trước khi đại dịch ập đến.","explanation":"A regret about a <b>past</b> action after <b>wish</b> takes the past perfect: <b>wishes it hadn't cut</b>. 'Didn't cut' would be a wish about the present; 'wouldn't cut' a complaint about future behaviour."},{"id":"gv-ch-25-24","level":"ch","focus":"double-blank","q":"Restoring the mosaic ______ the city an arm and a ______, but visitor numbers have doubled since it reopened.","options":["paid / foot","charged / hand","cost / leg","spent / leg"],"correct":2,"answer":"cost / leg","vi":"Việc phục chế bức tranh khảm khiến thành phố tốn một khoản tiền khổng lồ, nhưng lượng khách tham quan đã tăng gấp đôi từ khi mở cửa lại.","explanation":"The idiom is <b>cost (someone) an arm and a leg</b> = be extremely expensive; both the verb and the final noun are fixed, so 'foot', 'hand', 'paid' and 'spent' break it."},{"id":"gv-ch-25-25","level":"ch","focus":"collocation","q":"The authorities have ______ the ban on photography inside the tomb, to the delight of tour groups.","options":["lifted","raised","risen","elevated"],"correct":0,"answer":"lifted","vi":"Nhà chức trách đã dỡ bỏ lệnh cấm chụp ảnh bên trong lăng mộ, khiến các đoàn du khách vui mừng.","explanation":"You <b>lift</b> a ban, restriction or sanction = end it. <b>Raise</b> and <b>elevate</b> mean move higher, and <b>risen</b> is intransitive, so none collocates with 'ban'."},{"id":"gv-ch-26-1","level":"ch","focus":"word-choice","q":"Having spent a decade on the novel, she was ______ when every publisher rejected it and did not write another word for years.","options":["complacent","disconsolate","nonchalant","euphoric"],"correct":1,"answer":"disconsolate","vi":"Sau khi dành cả một thập kỷ cho cuốn tiểu thuyết, bà đã vô cùng đau khổ khi mọi nhà xuất bản đều từ chối nó và suốt nhiều năm không viết thêm một chữ nào.","explanation":"<b>Disconsolate</b> means so unhappy that nothing can comfort you, which fits the rejection and the years of silence; complacent (smugly satisfied), nonchalant (calmly unconcerned) and euphoric (intensely happy) all clash with the context."},{"id":"gv-ch-26-2","level":"ch","focus":"collocation","q":"Wind and solar now ______ almost a third of the country's demand for electricity on a typical summer afternoon.","options":["meet","reach","fill","answer"],"correct":0,"answer":"meet","vi":"Điện gió và điện mặt trời hiện đáp ứng gần một phần ba nhu cầu điện của cả nước vào một buổi chiều mùa hè điển hình.","explanation":"The verb that collocates with <b>demand</b> is <b>meet</b> (meet the demand for something); you reach a target, fill a gap and answer a question, not a demand."},{"id":"gv-ch-26-3","level":"ch","focus":"idiom","q":"The festival lost money this year, but as its director put it, there is no use ______ when next summer's programme still has to be planned.","options":["beating about the bush","burning the midnight oil","crying over spilt milk","sitting on the fence"],"correct":2,"answer":"crying over spilt milk","vi":"Liên hoan năm nay bị lỗ, nhưng như giám đốc nói, than khóc chuyện đã rồi cũng chẳng ích gì khi chương trình mùa hè năm sau vẫn còn phải lên kế hoạch.","explanation":"<b>Cry over spilt milk</b> means waste time regretting something that cannot be undone. Beating about the bush is avoiding the point, burning the midnight oil is working late, and sitting on the fence is refusing to take sides."},{"id":"gv-ch-26-4","level":"ch","focus":"inversion","q":"______ the engineers suspect that the bridge's cables had been corroding for years when they signed off the routine inspection report.","options":["Hardly had","Not until","Only when","Little did"],"correct":3,"answer":"Little did","vi":"Các kỹ sư hầu như không hề ngờ rằng dây cáp của cây cầu đã bị ăn mòn suốt nhiều năm khi họ ký duyệt báo cáo kiểm tra định kỳ.","explanation":"Fronted <b>Little</b> (= not at all) forces auxiliary inversion before a bare verb: <b>Little did</b> the engineers suspect. Hardly had needs a past participle and a later 'when', while Not until / Only when open a clause with an ordinary subject + verb and put the inversion in the main clause, not here."},{"id":"gv-ch-26-5","level":"ch","focus":"phrasal-verb","q":"With borrowing costs rising sharply, the utility has ______ its plans for a second offshore wind farm to a fraction of the original size.","options":["scaled back","scaled up","brought back","fallen back"],"correct":0,"answer":"scaled back","vi":"Do chi phí vay tăng mạnh, công ty điện lực đã thu hẹp kế hoạch xây trang trại điện gió ngoài khơi thứ hai xuống chỉ còn một phần nhỏ so với quy mô ban đầu.","explanation":"<b>Scale back</b> means reduce the size or extent of something, which matches 'to a fraction of the original size'. Scale up is the opposite, bring back means reintroduce, and fall back (retreat) takes no object."},{"id":"gv-ch-26-6","level":"ch","focus":"modal","q":"The reviewer ______ the whole novel; her summary gets the ending completely wrong.","options":["needn't have read","can't have read","shouldn't have read","mustn't have read"],"correct":1,"answer":"can't have read","vi":"Nhà phê bình chắc chắn đã không đọc hết cuốn tiểu thuyết; bản tóm tắt của bà ấy sai hoàn toàn về đoạn kết.","explanation":"A confident conclusion that something did <b>not</b> happen in the past uses <b>can't have</b> + past participle. Needn't have means it was unnecessary, shouldn't have expresses regret, and mustn't have is not used for deduction."},{"id":"gv-ch-26-7","level":"ch","focus":"word-choice","q":"Local investors remain ______ about the new pipeline, fearing that a single leak could wipe out years of returns.","options":["jubilant","nostalgic","resentful","apprehensive"],"correct":3,"answer":"apprehensive","vi":"Các nhà đầu tư địa phương vẫn lo ngại về đường ống mới, e rằng chỉ một vụ rò rỉ cũng có thể xóa sạch lợi nhuận của nhiều năm.","explanation":"<b>Apprehensive</b> means anxious that something bad may happen, which 'fearing that a single leak could...' spells out; jubilant is triumphant, nostalgic longs for the past, and resentful is bitter about a wrong already done."},{"id":"gv-ch-26-8","level":"ch","focus":"double-blank","q":"The conductor was determined to ______ the restoration of the concert hall ______, however long the fundraising took.","options":["look / through","see / off","see / through","see / into"],"correct":2,"answer":"see / through","vi":"Vị nhạc trưởng quyết tâm theo đuổi việc trùng tu nhà hát hòa nhạc đến cùng, dù việc gây quỹ có kéo dài bao lâu.","explanation":"<b>See something through</b> means continue with it until it is finished. Look through means examine quickly, see off means say goodbye to or drive away, and see into (understand the true nature of something, as in see into the future) makes no sense with a restoration project."},{"id":"gv-ch-26-9","level":"ch","focus":"subjunctive","q":"The safety board recommended that the ageing reactor ______ offline until every crack in the cooling system had been examined.","options":["be taken","was taken","is taken","would be taken"],"correct":0,"answer":"be taken","vi":"Ủy ban an toàn khuyến nghị rằng lò phản ứng cũ kỹ phải được ngừng hoạt động cho đến khi mọi vết nứt trong hệ thống làm mát được kiểm tra.","explanation":"After <b>recommend that</b>, the clause takes the subjunctive: the bare form <b>be taken</b>, with no tense marking. Was, is and would be are ordinary indicative forms and do not fit."},{"id":"gv-ch-26-10","level":"ch","focus":"idiom","q":"When the boy insisted he had not meant to break the vase, his mother chose to ______ rather than punish him.","options":["give him a piece of her mind","give him the benefit of the doubt","give him the cold shoulder","give him a run for his money"],"correct":1,"answer":"give him the benefit of the doubt","vi":"Khi cậu bé khăng khăng rằng mình không cố ý làm vỡ bình hoa, mẹ cậu quyết định tin lời cậu thay vì phạt cậu.","explanation":"<b>Give someone the benefit of the doubt</b> means accept their word even though you cannot be sure it is true. A piece of one's mind is an angry telling-off, the cold shoulder is deliberate unfriendliness, and a run for one's money is strong competition."},{"id":"gv-ch-26-11","level":"ch","focus":"collocation","q":"Several critics ______ the charge of plagiarism at the young novelist, though none produced a single copied sentence.","options":["threw","pointed","sent","levelled"],"correct":3,"answer":"levelled","vi":"Nhiều nhà phê bình đã buộc tội nhà tiểu thuyết trẻ đạo văn, dù không ai đưa ra được một câu sao chép nào.","explanation":"The collocation is <b>level a charge / an accusation / criticism at</b> someone. You throw a ball, point a finger and send a letter, but none of these verbs takes 'charge' in this sense."},{"id":"gv-ch-26-12","level":"ch","focus":"participle","q":"______, the rescue helicopters will resume their search of the northern slopes at first light tomorrow.","options":["Weather permitted","Weather to permit","Weather permitting","Weather having permitted"],"correct":2,"answer":"Weather permitting","vi":"Nếu thời tiết cho phép, các trực thăng cứu hộ sẽ nối lại việc tìm kiếm trên các sườn núi phía bắc vào lúc rạng sáng mai.","explanation":"The absolute clause <b>Weather permitting</b> (= if the weather permits) takes a present participle because the weather is the thing that permits. The past participle would make the weather the thing permitted, the infinitive is not used in absolute clauses, and the perfect form describes a condition already met, not tomorrow's."},{"id":"gv-ch-26-13","level":"ch","focus":"word-choice","q":"After the fourth blackout in a single week, residents were ______, and dozens wrote to the newspapers demanding that the grid operator resign.","options":["exasperated","serene","gratified","apathetic"],"correct":0,"answer":"exasperated","vi":"Sau lần mất điện thứ tư chỉ trong một tuần, cư dân vô cùng bực tức, và hàng chục người đã viết thư cho báo chí yêu cầu đơn vị vận hành lưới điện từ chức.","explanation":"<b>Exasperated</b> means intensely irritated after repeated annoyance, which the fourth blackout and the angry letters confirm. Serene (calm), gratified (pleased) and apathetic (uninterested) contradict the demand for a resignation."},{"id":"gv-ch-26-14","level":"ch","focus":"gerund-infinitive","q":"Most participants denied ______ the instructions, even though the recording showed them reading the page twice.","options":["to read","having read","to have read","read"],"correct":1,"answer":"having read","vi":"Hầu hết người tham gia phủ nhận đã đọc hướng dẫn, dù đoạn ghi hình cho thấy họ đọc trang đó hai lần.","explanation":"<b>Deny</b> is followed by a gerund, and <b>having read</b> (perfect gerund) marks the reading as earlier than the denying. Deny never takes a to-infinitive."},{"id":"gv-ch-26-15","level":"ch","focus":"phrasal-verb","q":"The appeal court ______ the verdict after new evidence showed that the key witness had lied under oath.","options":["set about","set out","set aside","set off"],"correct":2,"answer":"set aside","vi":"Tòa phúc thẩm đã hủy bản án sau khi bằng chứng mới cho thấy nhân chứng chủ chốt đã khai man khi tuyên thệ.","explanation":"In legal use, <b>set aside</b> a verdict means cancel it officially. Set about means begin a task, set out means start a journey or explain, and set off means depart or trigger."},{"id":"gv-ch-26-16","level":"ch","focus":"linking","q":"The city's grid was designed for half its present population; ______, blackouts have become a routine feature of every heatwave.","options":["nevertheless","otherwise","moreover","consequently"],"correct":3,"answer":"consequently","vi":"Lưới điện của thành phố được thiết kế cho một nửa dân số hiện tại; do đó, mất điện đã trở thành chuyện thường lệ trong mỗi đợt nắng nóng.","explanation":"The blackouts are the <b>result</b> of the undersized grid, so the linking adverb is <b>consequently</b>. Nevertheless signals contrast, otherwise a condition not met, and moreover simply adds a point."},{"id":"gv-ch-26-17","level":"ch","focus":"idiom","q":"Nurses who ______ for their patients report higher job satisfaction, the study found, even though they work longer hours.","options":["go the extra mile","go through the roof","go with the flow","go round in circles"],"correct":0,"answer":"go the extra mile","vi":"Nghiên cứu cho thấy những y tá nỗ lực hết mình vì bệnh nhân có mức độ hài lòng với công việc cao hơn, dù họ làm việc nhiều giờ hơn.","explanation":"<b>Go the extra mile</b> means make more effort than is expected. Go through the roof means rise very fast or lose one's temper, go with the flow means accept things passively, and go round in circles means make no progress."},{"id":"gv-ch-26-18","level":"ch","focus":"agreement","q":"Neither the playwright nor the actors ______ willing to comment on the cancelled tour when the press arrived.","options":["was","were","is","has been"],"correct":1,"answer":"were","vi":"Cả nhà viết kịch lẫn các diễn viên đều không muốn bình luận về chuyến lưu diễn bị hủy khi báo chí đến.","explanation":"With <b>neither... nor</b>, the verb agrees with the nearer subject, <b>the actors</b> (plural), and the past context ('when the press arrived') requires <b>were</b>."},{"id":"gv-ch-26-19","level":"ch","focus":"word-choice","q":"He was ______ to discover that he had sent the unfinished draft, complete with his private notes, to the entire faculty.","options":["overjoyed","appeased","mortified","vindicated"],"correct":2,"answer":"mortified","vi":"Anh ta vô cùng xấu hổ khi phát hiện ra mình đã gửi bản thảo chưa hoàn thành, kèm cả những ghi chú riêng tư, cho toàn bộ khoa.","explanation":"<b>Mortified</b> means extremely embarrassed, which fits sending private notes to everyone by mistake. Overjoyed is delighted, appeased is calmed after anger, and vindicated is proved right."},{"id":"gv-ch-26-20","level":"ch","focus":"double-blank","q":"To ______ the ball ______, the moderator asked each panellist to name one film that had changed their mind about something.","options":["put / rolling","get / running","make / turning","get / rolling"],"correct":3,"answer":"get / rolling","vi":"Để khởi động buổi thảo luận, người điều phối đề nghị mỗi khách mời kể tên một bộ phim đã làm thay đổi suy nghĩ của họ về điều gì đó.","explanation":"<b>Get the ball rolling</b> means start something happening. The idiom is fixed: neither the verb nor the participle can be swapped for a near-synonym."},{"id":"gv-ch-26-21","level":"ch","focus":"comparison","q":"______ a community feels about the reliability of its power supply, the less willing it is to oppose new pylons nearby.","options":["The more anxious","The most anxious","More anxious","The much anxious"],"correct":0,"answer":"The more anxious","vi":"Một cộng đồng càng lo lắng về độ tin cậy của nguồn điện thì càng ít muốn phản đối việc dựng cột điện mới gần đó.","explanation":"The double comparative <b>the more..., the less...</b> links two changes that go together; it needs <b>the</b> plus a comparative in both halves, so a superlative or a bare comparative breaks the pattern."},{"id":"gv-ch-26-22","level":"ch","focus":"collocation","q":"Researchers are careful to ______ a distinction between a habit, which is automatic, and an addiction, which persists despite harm.","options":["put","take","draw","set"],"correct":2,"answer":"draw","vi":"Các nhà nghiên cứu cẩn thận phân biệt giữa thói quen, vốn mang tính tự động, và chứng nghiện, vốn tồn tại dai dẳng bất chấp tác hại.","explanation":"The collocation is <b>draw a distinction</b> between two things (make a distinction is also possible, but is not offered). Put, take and set do not combine with 'distinction' in this sense."},{"id":"gv-ch-26-23","level":"ch","focus":"idiom","q":"'What if the grant runs out before the survey is finished?' 'It may never happen, so let's ______.'","options":["burn our bridges","cross that bridge when we come to it","bite the bullet","let sleeping dogs lie"],"correct":1,"answer":"cross that bridge when we come to it","vi":"'Nếu khoản tài trợ cạn trước khi cuộc khảo sát hoàn thành thì sao?' 'Chuyện đó có thể chẳng bao giờ xảy ra, nên đến lúc đó rồi tính.'","explanation":"<b>Cross that bridge when you come to it</b> means deal with a problem only if and when it actually arises. Burn your bridges means destroy a way back, bite the bullet means face something unpleasant now, and let sleeping dogs lie means avoid stirring up an old problem."},{"id":"gv-ch-26-24","level":"ch","focus":"passive","q":"By the time the new dam is completed, an estimated forty villages ______ to higher ground by the authorities.","options":["will have moved","will be moving","have been moving","will have been moved"],"correct":3,"answer":"will have been moved","vi":"Đến khi con đập mới hoàn thành, ước tính khoảng bốn mươi ngôi làng sẽ đã được chính quyền di dời lên vùng đất cao hơn.","explanation":"The villages are moved by the authorities (agent with <b>by</b>), and 'by the time... is completed' points to a future completed action, so the future perfect passive <b>will have been moved</b> is required."},{"id":"gv-ch-26-25","level":"ch","focus":"word-choice","q":"The finding that participants who were paid more performed worse left the psychologists ______, as it contradicted every existing model of motivation.","options":["reassured","perplexed","smug","remorseful"],"correct":1,"answer":"perplexed","vi":"Phát hiện rằng những người tham gia được trả nhiều tiền hơn lại làm việc kém hơn khiến các nhà tâm lý học bối rối, vì nó mâu thuẫn với mọi mô hình động lực hiện có.","explanation":"<b>Perplexed</b> means confused because something cannot be explained, which suits a result that contradicts every model. Reassured (comforted), smug (self-satisfied) and remorseful (sorry for a wrong) do not match."},{"id":"gv-ch-27-1","level":"ch","focus":"word-choice","q":"The gap between gold and silver in the 100 metres was ______ — three hundredths of a second — but in elite sprinting that is the difference between a medal and obscurity.","options":["meagre","trivial","minute","petty"],"correct":2,"answer":"minute","vi":"Khoảng cách giữa huy chương vàng và bạc ở cự ly 100 mét là cực kỳ nhỏ — ba phần trăm giây — nhưng trong môn chạy nước rút đỉnh cao, đó là khác biệt giữa một tấm huy chương và sự vô danh.","explanation":"<b>Minute</b> (/maɪˈnjuːt/) means extremely small in size or amount, which fits a gap of three hundredths of a second. <b>Trivial</b> means unimportant, which the sentence goes on to deny; <b>meagre</b> describes an amount that is not enough (a meagre salary), and <b>petty</b> describes small-minded behaviour, not a measurement."},{"id":"gv-ch-27-2","level":"ch","focus":"idiom","q":"Ever since his boyhood club released him at sixteen, the striker has ______, treating every question about his past as a personal insult.","options":["had a chip on his shoulder","had a bee in his bonnet","had an axe to grind","had a finger in every pie"],"correct":0,"answer":"had a chip on his shoulder","vi":"Kể từ khi câu lạc bộ thời niên thiếu cho anh ra đi năm mười sáu tuổi, tiền đạo này luôn mang nỗi hậm hực trong lòng, coi mọi câu hỏi về quá khứ như một sự xúc phạm cá nhân.","explanation":"To <b>have a chip on your shoulder</b> is to stay resentful about a past injustice and be quick to take offence. <b>A bee in your bonnet</b> is an obsession with an idea, <b>an axe to grind</b> is a hidden personal motive, and <b>a finger in every pie</b> means being involved in everything."},{"id":"gv-ch-27-3","level":"ch","focus":"collocation","q":"After nine hours of deliberation, the jury in the data-fraud trial ______ a unanimous verdict of guilty on all three counts.","options":["arrived","reached","achieved","came"],"correct":1,"answer":"reached","vi":"Sau chín giờ nghị án, bồi thẩm đoàn trong phiên tòa xét xử vụ gian lận dữ liệu đã đi đến phán quyết nhất trí là có tội ở cả ba tội danh.","explanation":"<b>Reach a verdict</b> is the fixed collocation for a jury deciding its answer. <b>Arrive</b> and <b>come</b> need a preposition (<b>arrive at</b>, <b>come to</b> a verdict), and <b>achieve</b> is used of goals and results, not verdicts."},{"id":"gv-ch-27-4","level":"ch","focus":"modal","q":"The striker ______ offside when the pass was played; the freeze-frame clearly shows two defenders standing goal-side of him.","options":["shouldn't have been","needn't have been","mustn't have been","can't have been"],"correct":3,"answer":"can't have been","vi":"Tiền đạo không thể nào đã việt vị lúc đường chuyền được thực hiện; hình dừng cho thấy rõ hai hậu vệ đứng gần khung thành hơn anh ta.","explanation":"<b>Can't have been</b> expresses a confident deduction that something in the past was impossible. <b>Mustn't have</b> is not used for deduction in standard British English, <b>needn't have</b> means it was unnecessary, and <b>shouldn't have</b> criticises a choice."},{"id":"gv-ch-27-5","level":"ch","focus":"phrasal-verb","q":"The world number one ______ the first-round defeat as a blip and was back on the practice court within hours.","options":["called off","shrugged off","put off","fended off"],"correct":1,"answer":"shrugged off","vi":"Tay vợt số một thế giới gạt phăng trận thua vòng một, coi đó chỉ là một sự cố nhỏ, và quay lại sân tập chỉ vài giờ sau.","explanation":"<b>Shrug off</b> means to treat a setback as unimportant. <b>Call off</b> is to cancel, <b>put off</b> is to postpone, and <b>fend off</b> is to defend yourself against an attack or awkward questions."},{"id":"gv-ch-27-6","level":"ch","focus":"word-choice","q":"Abolishing the offside rule would be a ______ decision, one that historians of the game would still be arguing about a century from now.","options":["momentous","eminent","imposing","colossal"],"correct":0,"answer":"momentous","vi":"Bãi bỏ luật việt vị sẽ là một quyết định trọng đại, mà các nhà sử học bóng đá vẫn còn tranh cãi cả trăm năm sau.","explanation":"<b>Momentous</b> describes a decision or event of great and lasting importance. <b>Eminent</b> is used of distinguished people, <b>imposing</b> of impressive buildings or figures, and <b>colossal</b> of physical size or huge amounts."},{"id":"gv-ch-27-7","level":"ch","focus":"inversion","q":"Rarely ______ dominated a single Olympic programme so completely, winning all seven of her events by clear water.","options":["a swimmer has","does a swimmer","has a swimmer","a swimmer had"],"correct":2,"answer":"has a swimmer","vi":"Hiếm khi có một vận động viên bơi lội nào thống trị trọn vẹn một kỳ Olympic đến thế, thắng cả bảy nội dung với khoảng cách rõ rệt.","explanation":"After a negative adverb such as <b>Rarely</b> at the start of a sentence, the auxiliary comes before the subject: <b>has a swimmer</b> dominated. <b>Does a swimmer</b> would need the base form <b>dominate</b>, and the other two are not inverted."},{"id":"gv-ch-27-8","level":"ch","focus":"idiom","q":"The anchor found himself ______ after a live microphone picked him up mocking a guest during the commercial break.","options":["in the red","in the doldrums","in the dark","in hot water"],"correct":3,"answer":"in hot water","vi":"Người dẫn chương trình rơi vào rắc rối sau khi micro đang bật thu được cảnh anh ta chế giễu một vị khách trong lúc nghỉ quảng cáo.","explanation":"To be <b>in hot water</b> is to be in trouble because of something you have done. <b>In the red</b> means owing money, <b>in the doldrums</b> means inactive or depressed, and <b>in the dark</b> means uninformed."},{"id":"gv-ch-27-9","level":"ch","focus":"double-blank","q":"Many freelance reporters, ______ fees have fallen by a third in real terms, can barely make ends ______ on what online outlets pay per article.","options":["whose / meet","who / meet","whose / match","whom / met"],"correct":0,"answer":"whose / meet","vi":"Nhiều phóng viên tự do, những người có nhuận bút đã giảm một phần ba theo giá trị thực, hầu như không đủ sống với mức các trang tin trực tuyến trả cho mỗi bài.","explanation":"The first blank needs the possessive relative <b>whose</b> (their fees); the second completes the idiom <b>make ends meet</b>, to earn just enough to live on. <b>Match</b> and <b>met</b> break the idiom."},{"id":"gv-ch-27-10","level":"ch","focus":"linking","q":"The public broadcaster's audience has grown steadily over the past two years, ______ its commercial rivals' has shrunk for six quarters in a row.","options":["despite","whereas","otherwise","nevertheless"],"correct":1,"answer":"whereas","vi":"Lượng khán giả của đài truyền hình công đã tăng đều trong hai năm qua, trong khi lượng khán giả của các đối thủ thương mại lại giảm sáu quý liên tiếp.","explanation":"<b>Whereas</b> is a conjunction that contrasts two clauses directly. <b>Despite</b> must be followed by a noun or -ing form, and <b>otherwise</b> and <b>nevertheless</b> are adverbs that cannot join two clauses with a comma."},{"id":"gv-ch-27-11","level":"ch","focus":"word-choice","q":"Despite the scale of the doping scandal, the story received only ______ attention from the national broadcasters, which were busy covering the election.","options":["sparse","scarce","slender","scant"],"correct":3,"answer":"scant","vi":"Dù vụ bê bối doping có quy mô lớn, câu chuyện chỉ nhận được rất ít sự chú ý từ các đài truyền hình quốc gia, vốn đang bận đưa tin về cuộc bầu cử.","explanation":"<b>Scant attention</b> is a fixed pairing meaning very little attention. <b>Scarce</b> describes resources in short supply, <b>sparse</b> describes things thinly spread out, and <b>slender</b> describes a thin build or a narrow margin."},{"id":"gv-ch-27-12","level":"ch","focus":"subjunctive","q":"The press ombudsman recommended that the correction ______ on the same page and in the same type size as the original error.","options":["was printed","would be printed","be printed","is printed"],"correct":2,"answer":"be printed","vi":"Thanh tra báo chí khuyến nghị rằng đính chính phải được đăng trên cùng trang và với cùng cỡ chữ như lỗi ban đầu.","explanation":"After verbs such as <b>recommend</b>, <b>suggest</b> and <b>insist</b>, the that-clause takes the subjunctive base form: <b>that the correction be printed</b>. The indicative forms <b>was</b>, <b>is</b> and <b>would be</b> are not used here."},{"id":"gv-ch-27-13","level":"ch","focus":"phrasal-verb","q":"Before announcing her candidacy for the federation presidency, she quietly ______ several national coaches to gauge how much support she could count on.","options":["sounded out","spoke out","sounded off","spelled out"],"correct":0,"answer":"sounded out","vi":"Trước khi tuyên bố ứng cử chức chủ tịch liên đoàn, bà đã âm thầm thăm dò ý kiến vài huấn luyện viên đội tuyển quốc gia để xem mình có thể trông cậy vào bao nhiêu sự ủng hộ.","explanation":"<b>Sound someone out</b> means to ask them discreetly to find out their opinion. <b>Speak out</b> is to state views publicly, <b>sound off</b> is to complain loudly, and <b>spell out</b> is to explain in detail."},{"id":"gv-ch-27-14","level":"ch","focus":"idiom","q":"\"______,\" the coach told the gymnast, who was close to tears after her fall; \"the all-around final is still two days away.\"","options":["Keep your hair on","Keep your chin up","Keep your head down","Keep your shirt on"],"correct":1,"answer":"Keep your chin up","vi":"\"Cứ ngẩng cao đầu lên,\" huấn luyện viên nói với cô vận động viên thể dục dụng cụ đang rưng rưng nước mắt sau cú ngã; \"chung kết toàn năng vẫn còn hai ngày nữa.\"","explanation":"<b>Keep your chin up</b> means stay cheerful in a difficult situation. <b>Keep your hair on</b> and <b>keep your shirt on</b> both mean calm down, and <b>keep your head down</b> means avoid attracting attention."},{"id":"gv-ch-27-15","level":"ch","focus":"collocation","q":"The documentary ______ a furious debate about the ethics of secretly filming athletes in their changing rooms.","options":["lit","flared","blazed","sparked"],"correct":3,"answer":"sparked","vi":"Bộ phim tài liệu đã châm ngòi cho một cuộc tranh luận dữ dội về đạo đức của việc quay lén vận động viên trong phòng thay đồ.","explanation":"<b>Spark a debate</b> is the standard verb + noun collocation for causing a discussion to start. <b>Lit</b>, <b>flared</b> and <b>blazed</b> keep the fire image but do not collocate with <b>debate</b>."},{"id":"gv-ch-27-16","level":"ch","focus":"gerund-infinitive","q":"The club now regrets ______ the young winger a longer contract before its wealthier rivals came calling.","options":["not to offer","to not offer","not offering","not offer"],"correct":2,"answer":"not offering","vi":"Câu lạc bộ giờ hối tiếc vì đã không đề nghị cầu thủ chạy cánh trẻ một hợp đồng dài hạn hơn trước khi các đối thủ giàu có hơn tìm đến.","explanation":"<b>Regret + -ing</b> looks back on something already done or not done: <b>regrets not offering</b>. <b>Regret + to-infinitive</b> is used only to announce bad news politely (we regret to inform you), so <b>not to offer</b> is wrong here."},{"id":"gv-ch-27-17","level":"ch","focus":"word-choice","q":"The proposal to expand the tournament to 48 teams was approved by an ______ majority of member associations, with only four voting against.","options":["overriding","overwhelming","overpowering","overbearing"],"correct":1,"answer":"overwhelming","vi":"Đề xuất mở rộng giải đấu lên 48 đội đã được đa số áp đảo các liên đoàn thành viên thông qua, chỉ có bốn phiếu chống.","explanation":"<b>An overwhelming majority</b> is a very large majority. <b>Overriding</b> means more important than anything else (an overriding priority), <b>overpowering</b> describes a smell or emotion too strong to resist, and <b>overbearing</b> describes a bossy person."},{"id":"gv-ch-27-18","level":"ch","focus":"reported","q":"The club's spokesman told reporters on Sunday evening that the board ______ the allegations at a press conference the following morning.","options":["would address","will address","addresses","had addressed"],"correct":0,"answer":"would address","vi":"Người phát ngôn câu lạc bộ nói với các phóng viên tối Chủ nhật rằng ban lãnh đạo sẽ trả lời các cáo buộc tại cuộc họp báo vào sáng hôm sau.","explanation":"In reported speech after a past reporting verb (<b>told</b>), <b>will</b> shifts back to <b>would</b>; <b>the following morning</b> confirms the time was still future from the speaker's point of view, so <b>had addressed</b> is impossible."},{"id":"gv-ch-27-19","level":"ch","focus":"idiom","q":"The editor promised to ______ in tracing the source of the leaked memo, even if it meant reviewing every email sent from the building that week.","options":["leave well alone","leave it at that","leave no stone unturned","leave a lot to be desired"],"correct":2,"answer":"leave no stone unturned","vi":"Tổng biên tập hứa sẽ không bỏ sót bất cứ manh mối nào trong việc truy tìm nguồn của bản ghi nhớ bị rò rỉ, kể cả khi phải rà soát mọi email gửi đi từ tòa nhà trong tuần đó.","explanation":"<b>Leave no stone unturned</b> means to try every possible way to find or achieve something. <b>Leave well alone</b> is to avoid interfering, <b>leave it at that</b> is to say or do no more, and <b>leave a lot to be desired</b> means to be far from satisfactory."},{"id":"gv-ch-27-20","level":"ch","focus":"participle","q":"______ how long the power cut would last, the laboratory staff moved the vaccine samples into a backup freezer running on a generator.","options":["Not known","Not to know","Not having known","Not knowing"],"correct":3,"answer":"Not knowing","vi":"Không biết sự cố mất điện sẽ kéo dài bao lâu, nhân viên phòng thí nghiệm đã chuyển các mẫu vắc-xin sang tủ đông dự phòng chạy bằng máy phát.","explanation":"A present participle clause gives the reason for the main action, and its negative is formed by putting <b>not</b> before the -ing form: <b>Not knowing</b> how long it would last, the staff moved the samples. <b>Not known</b> is passive (the staff were not being known), <b>Not to know</b> is an infinitive that cannot open a reason clause, and <b>Not having known</b> wrongly suggests the ignorance was over before they acted."},{"id":"gv-ch-27-21","level":"ch","focus":"double-blank","q":"Instead of ______ any one player ______ for blame, the coach said the whole squad had underperformed in the second half.","options":["single / out","singling / out","singling / up","singled / out"],"correct":1,"answer":"singling / out","vi":"Thay vì chỉ trích riêng một cầu thủ nào, huấn luyện viên nói rằng cả đội đã thi đấu dưới sức trong hiệp hai.","explanation":"<b>Instead of</b> is a preposition, so it is followed by the -ing form; the phrasal verb <b>single somebody out</b> means to pick one person from a group for special treatment. <b>Single up</b> does not exist."},{"id":"gv-ch-27-22","level":"ch","focus":"pronoun","q":"With the two sides level after extra time, the semi-final will be decided by ______ keeps their nerve in the penalty shoot-out.","options":["who","whom","whomever","whoever"],"correct":3,"answer":"whoever","vi":"Với hai đội hòa nhau sau hiệp phụ, trận bán kết sẽ được định đoạt bởi bất cứ ai giữ được bình tĩnh trong loạt sút luân lưu.","explanation":"Only <b>whoever</b> means 'the person who' and can stand as the subject of <b>keeps</b>; the preposition <b>by</b> governs the whole clause, not the pronoun, so the object form <b>whomever</b> is wrong, and <b>who</b>/<b>whom</b> would need a stated antecedent."},{"id":"gv-ch-27-23","level":"ch","focus":"word-choice","q":"For four decades he was a ______ figure in sports broadcasting, whose commentary shaped how a whole generation heard the game.","options":["towering","lofty","soaring","elevated"],"correct":0,"answer":"towering","vi":"Trong bốn thập kỷ, ông là một tượng đài của ngành bình luận thể thao, người mà lời bình đã định hình cách cả một thế hệ nghe trận đấu.","explanation":"<b>A towering figure</b> is a person of outstanding importance in a field. <b>Lofty</b> describes ideals or a superior attitude, <b>soaring</b> describes rising prices or birds, and <b>elevated</b> describes a raised position or level."},{"id":"gv-ch-27-24","level":"ch","focus":"collocation","q":"Unregulated betting apps ______ a serious threat to the integrity of lower-league football, the inquiry concluded.","options":["put","make","pose","set"],"correct":2,"answer":"pose","vi":"Các ứng dụng cá cược không được quản lý đặt ra mối đe dọa nghiêm trọng đối với sự trong sạch của bóng đá hạng dưới, cuộc điều tra kết luận.","explanation":"<b>Pose a threat</b> is the fixed verb + noun collocation. <b>Put</b>, <b>make</b> and <b>set</b> are not used with <b>threat</b>."},{"id":"gv-ch-27-25","level":"ch","focus":"question-tag","q":"Nobody in the press room expected the manager to announce his resignation that afternoon, ______?","options":["didn't they","did they","didn't he","did he"],"correct":1,"answer":"did they","vi":"Không ai trong phòng họp báo ngờ rằng huấn luyện viên sẽ tuyên bố từ chức chiều hôm đó, phải không?","explanation":"<b>Nobody</b> makes the statement negative, so the tag is positive, and indefinite pronouns such as <b>nobody</b> take <b>they</b> in the tag: <b>did they</b>."},{"id":"gv-ch-28-1","level":"ch","focus":"word-choice","q":"After years of complaints from tenants, the city council finally voted to ______ the by-law that let landlords evict without notice.","options":["retract","repeal","cancel","dismiss"],"correct":1,"answer":"repeal","vi":"Sau nhiều năm bị người thuê nhà phàn nàn, hội đồng thành phố cuối cùng đã bỏ phiếu bãi bỏ quy định cho phép chủ nhà đuổi người thuê mà không cần báo trước.","explanation":"Laws and by-laws are <b>repealed</b>. <i>Cancel</i> takes events or orders, <i>dismiss</i> a case or an idea, and <i>retract</i> a statement."},{"id":"gv-ch-28-2","level":"ch","focus":"idiom","q":"Having already been cautioned twice for leaking to the press, the junior minister knew he was ______.","options":["on thin ice","on the fence","on the rocks","on cloud nine"],"correct":0,"answer":"on thin ice","vi":"Đã hai lần bị cảnh cáo vì để lộ tin cho báo chí, vị thứ trưởng trẻ biết mình đang ở thế ngàn cân treo sợi tóc.","explanation":"<b>On thin ice</b> = in a risky position where one more mistake brings disaster. <i>On the fence</i> is undecided, <i>on the rocks</i> is failing (a marriage, a business), <i>on cloud nine</i> is very happy."},{"id":"gv-ch-28-3","level":"ch","focus":"inversion","q":"______ has a single online rumour wiped so much value off a listed company as the one that circulated on Monday.","options":["Not only","Seldom","Not until","Only when"],"correct":1,"answer":"Seldom","vi":"Hiếm khi một tin đồn trên mạng lại làm bốc hơi nhiều giá trị của một công ty niêm yết đến vậy như tin đồn lan truyền hôm thứ Hai.","explanation":"The negative frequency adverb <b>Seldom</b> at the front of a sentence forces inversion: <b>Seldom has a rumour wiped…</b>. <i>Not only</i> would need <i>but also</i>, and <i>Not until / Only when</i> must be followed by a time clause before the inverted main clause."},{"id":"gv-ch-28-4","level":"ch","focus":"collocation","q":"Residents complained that the unlit stairwells had turned the estate into a ______ ground for petty crime.","options":["feeding","growing","nursing","breeding"],"correct":3,"answer":"breeding","vi":"Cư dân than phiền rằng những cầu thang không có đèn đã biến khu chung cư thành mảnh đất màu mỡ cho tội phạm vặt.","explanation":"The fixed collocation is <b>breeding ground</b> (for crime, disease, ideas). The other adjectives do not combine with <i>ground</i> in this sense."},{"id":"gv-ch-28-5","level":"ch","focus":"phrasal-verb","q":"The commissioner announced that she would ______ at the end of the year rather than face a vote of no confidence.","options":["step down","step in","step up","stand by"],"correct":0,"answer":"step down","vi":"Bà cảnh sát trưởng tuyên bố sẽ từ chức vào cuối năm thay vì đối mặt với cuộc bỏ phiếu bất tín nhiệm.","explanation":"<b>Step down</b> = resign from a post. <i>Step in</i> is to intervene, <i>step up</i> is to increase or take on more responsibility, <i>stand by</i> is to wait ready or to support someone."},{"id":"gv-ch-28-6","level":"ch","focus":"subjunctive","q":"The tribunal recommended that the landlord ______ the deposit in full within fourteen days.","options":["returns","return","returned","will return"],"correct":1,"answer":"return","vi":"Toà án đã khuyến nghị rằng chủ nhà phải hoàn trả toàn bộ tiền đặt cọc trong vòng mười bốn ngày.","explanation":"After <i>recommend/suggest/insist that</i>, the verb takes the bare subjunctive: <b>that the landlord return</b>, with no -s and no tense change."},{"id":"gv-ch-28-7","level":"ch","focus":"word-choice","q":"The Court of Appeal ______ the conviction after DNA evidence showed the defendant had been elsewhere that night.","options":["abolished","suspended","quashed","terminated"],"correct":2,"answer":"quashed","vi":"Toà phúc thẩm đã huỷ bản án sau khi bằng chứng ADN cho thấy bị cáo ở nơi khác vào đêm hôm đó.","explanation":"A conviction or verdict is <b>quashed</b> (declared invalid). <i>Abolish</i> applies to laws and institutions, <i>suspend</i> to a sentence or a rule, <i>terminate</i> to a contract."},{"id":"gv-ch-28-8","level":"ch","focus":"double-blank","q":"The ombudsman insisted that the council ______ its reasons in full, ______ residents assume the decision had been arbitrary.","options":["spill out / lest","spell out / unless","spill over / so that","spell out / lest"],"correct":3,"answer":"spell out / lest","vi":"Thanh tra viên yêu cầu hội đồng phải giải thích rõ ràng đầy đủ lý do, kẻo người dân cho rằng quyết định đó là tuỳ tiện.","explanation":"<b>Spell out</b> = explain in detail; <b>lest</b> = for fear that, followed here by a bare subjunctive. <i>Spill out</i> is to pour out, and <i>unless</i> reverses the logic of the sentence."},{"id":"gv-ch-28-9","level":"ch","focus":"idiom","q":"With no way of knowing how many people would turn up to the housing consultation, the planning officers decided to ______.","options":["play for time","play it by ear","play the field","play with fire"],"correct":1,"answer":"play it by ear","vi":"Không thể biết sẽ có bao nhiêu người đến buổi tham vấn về nhà ở, các cán bộ quy hoạch quyết định tuỳ cơ ứng biến.","explanation":"<b>Play it by ear</b> = decide as things happen rather than plan ahead. <i>Play for time</i> is to delay deliberately, <i>play the field</i> is to date many people, <i>play with fire</i> is to take a dangerous risk."},{"id":"gv-ch-28-10","level":"ch","focus":"modal","q":"The defendant ______ been at the scene; his phone records place him fifty miles away at the time.","options":["can't have","mustn't have","needn't have","shouldn't have"],"correct":0,"answer":"can't have","vi":"Bị cáo không thể nào có mặt ở hiện trường được; dữ liệu điện thoại cho thấy anh ta ở cách đó năm mươi dặm vào thời điểm đó.","explanation":"<b>Can't have + past participle</b> expresses a confident deduction that something did NOT happen. <i>Mustn't have</i> is not used for deduction, <i>needn't have</i> means it was unnecessary, <i>shouldn't have</i> is criticism."},{"id":"gv-ch-28-11","level":"ch","focus":"collocation","q":"The judge ______ a heavy fine on the developer for ignoring the safety order.","options":["inflicted","charged","imposed","delivered"],"correct":2,"answer":"imposed","vi":"Thẩm phán đã áp mức phạt nặng lên chủ đầu tư vì phớt lờ lệnh an toàn.","explanation":"The collocation is <b>impose a fine/penalty/tax on</b> someone. You <i>inflict</i> pain or damage, <i>charge</i> a fee, and <i>deliver</i> a verdict."},{"id":"gv-ch-28-12","level":"ch","focus":"word-choice","q":"The housing charity was forced to ______ its night-shelter programme when the council grant ran out.","options":["disband","dissolve","dispel","discontinue"],"correct":3,"answer":"discontinue","vi":"Tổ chức từ thiện về nhà ở buộc phải ngừng chương trình nhà tạm trú ban đêm khi khoản tài trợ của hội đồng cạn kiệt.","explanation":"A service or programme is <b>discontinued</b>. You <i>disband</i> a group of people, <i>dissolve</i> a parliament or a company, and <i>dispel</i> doubts or fears."},{"id":"gv-ch-28-13","level":"ch","focus":"linking","q":"______ loudly residents object, the developer has the legal right to proceed once planning permission is granted.","options":["However","Whatever","Although","Despite"],"correct":0,"answer":"However","vi":"Dù người dân phản đối lớn tiếng đến đâu, chủ đầu tư vẫn có quyền hợp pháp tiến hành một khi đã được cấp phép quy hoạch.","explanation":"<b>However + adverb/adjective</b> (= no matter how) introduces a concession clause. <i>Whatever</i> needs a noun, <i>although</i> cannot take <i>loudly</i> directly, and <i>despite</i> takes a noun phrase."},{"id":"gv-ch-28-14","level":"ch","focus":"idiom","q":"Faced with spiralling costs and a hostile audit, the ministry finally decided to ______ the new stadium.","options":["pull the wool over","pull the plug on","pull the strings behind","pull rank on"],"correct":1,"answer":"pull the plug on","vi":"Đối mặt với chi phí leo thang và một cuộc kiểm toán bất lợi, bộ cuối cùng quyết định ngừng hẳn dự án sân vận động mới.","explanation":"<b>Pull the plug on</b> something = stop it by cutting off its support. <i>Pull the wool over someone's eyes</i> is to deceive, <i>pull the strings</i> is to control secretly, <i>pull rank on</i> is to use seniority over a person."},{"id":"gv-ch-28-15","level":"ch","focus":"gerund-infinitive","q":"After years of rising rents, many young graduates have been reduced to ______ in converted garages on the edge of town.","options":["live","be living","living","have lived"],"correct":2,"answer":"living","vi":"Sau nhiều năm giá thuê tăng, nhiều cử nhân trẻ đã rơi vào cảnh phải sống trong những gara cải tạo ở rìa thành phố.","explanation":"<b>Be reduced to + -ing</b>: here <i>to</i> is a preposition, so the verb takes the gerund, not the infinitive."},{"id":"gv-ch-28-16","level":"ch","focus":"word-choice","q":"Police believe the riots were ______ by a rumour that an officer had shot an unarmed teenager.","options":["instigated","inaugurated","instituted","installed"],"correct":0,"answer":"instigated","vi":"Cảnh sát tin rằng cuộc bạo loạn đã bị kích động bởi tin đồn rằng một sĩ quan đã bắn một thiếu niên không vũ trang.","explanation":"<b>Instigate</b> = provoke or stir up trouble. <i>Inaugurate</i> opens something ceremonially, <i>institute</i> sets up a system or policy, <i>install</i> puts equipment or a person in place."},{"id":"gv-ch-28-17","level":"ch","focus":"participle","q":"______ orbit, the delta’s patchwork of shrimp farms looks like a sheet of shattered glass.","options":["Seeing from","To see from","Seen from","Having seen from"],"correct":2,"answer":"Seen from","vi":"Nhìn từ quỹ đạo, mạng lưới đầm nuôi tôm chằng chịt của vùng châu thổ trông như một tấm kính vỡ.","explanation":"The subject <i>patchwork of shrimp farms</i> is what is <b>seen</b>, not what sees, so the reduced clause takes the past participle: <b>Seen from orbit</b>. <i>Seeing</i> and <i>having seen</i> would dangle, and <i>to see</i> would state a purpose."},{"id":"gv-ch-28-18","level":"ch","focus":"double-blank","q":"The minister's resignation came ______ the ______, catching even his closest aides unawares.","options":["off / cuff","out of / blue","under / radar","out of / ordinary"],"correct":1,"answer":"out of / blue","vi":"Việc bộ trưởng từ chức diễn ra hoàn toàn bất ngờ, khiến ngay cả các trợ lý thân cận nhất của ông cũng trở tay không kịp.","explanation":"<b>Out of the blue</b> = completely unexpectedly. <i>Off the cuff</i> means unrehearsed, <i>under the radar</i> means unnoticed, and <i>out of the ordinary</i> is an adjective phrase that does not follow <i>came</i>."},{"id":"gv-ch-28-19","level":"ch","focus":"subjunctive","q":"It is high time the government ______ something about the chronic shortage of social housing.","options":["does","do","did","will do"],"correct":2,"answer":"did","vi":"Đã đến lúc chính phủ phải làm gì đó về tình trạng thiếu nhà ở xã hội kinh niên.","explanation":"<b>It's (high) time + past subjunctive</b>: the past form <b>did</b> refers to the present and shows the action is overdue."},{"id":"gv-ch-28-20","level":"ch","focus":"phrasal-verb","q":"The new chief constable has vowed to ______ bribery in the traffic division once and for all.","options":["stamp out","rule out","wear out","phase out"],"correct":0,"answer":"stamp out","vi":"Tân cảnh sát trưởng đã thề sẽ dẹp tận gốc nạn hối lộ trong đội cảnh sát giao thông một lần và mãi mãi.","explanation":"<b>Stamp out</b> = eliminate something bad completely. <i>Rule out</i> excludes a possibility, <i>wear out</i> exhausts, <i>phase out</i> withdraws something gradually."},{"id":"gv-ch-28-21","level":"ch","focus":"article-quantifier","q":"______ tenants had even heard of the compensation scheme, so turnout at the meeting was poor.","options":["A few","Little","A little","Few"],"correct":3,"answer":"Few","vi":"Rất ít người thuê nhà từng nghe nói đến chương trình bồi thường, nên số người đến dự họp rất thưa thớt.","explanation":"<b>Few</b> (without <i>a</i>) means hardly any and carries a negative sense, matching the poor turnout; <i>a few</i> is positive (some), and <i>little/a little</i> go with uncountable nouns."},{"id":"gv-ch-28-22","level":"ch","focus":"idiom","q":"Economists warned the city not to ______ by tying its entire budget to tourism revenue.","options":["put the cart before the horse","walk on eggshells","put all its eggs in one basket","count its chickens before they hatch"],"correct":2,"answer":"put all its eggs in one basket","vi":"Các nhà kinh tế cảnh báo thành phố không nên dồn hết trứng vào một giỏ bằng cách gắn toàn bộ ngân sách vào nguồn thu từ du lịch.","explanation":"<b>Put all your eggs in one basket</b> = depend entirely on one thing. <i>Put the cart before the horse</i> is to do things in the wrong order, <i>walk on eggshells</i> is to be very careful not to offend, <i>count your chickens</i> is to assume success too early."},{"id":"gv-ch-28-23","level":"ch","focus":"inversion","q":"Only after the third burglary in a single month ______ to install cameras on the estate.","options":["the council agreed","did the council agree","the council did agree","the council had agreed"],"correct":1,"answer":"did the council agree","vi":"Chỉ sau vụ trộm thứ ba trong vòng một tháng, hội đồng mới đồng ý lắp camera trong khu chung cư.","explanation":"When <b>Only after…</b> opens the sentence, the main clause inverts: <b>did the council agree</b>. The auxiliary must come before the subject; <i>the council agreed / did agree / had agreed</i> all leave the subject in front, and there is no earlier event for a past perfect to precede."},{"id":"gv-ch-28-24","level":"ch","focus":"word-choice","q":"The licensing board ______ the nightclub's licence after a third stabbing on its premises in a year.","options":["revoked","refuted","retrieved","repelled"],"correct":0,"answer":"revoked","vi":"Ban cấp phép đã thu hồi giấy phép của hộp đêm sau vụ đâm chém thứ ba trong khuôn viên trong vòng một năm.","explanation":"A licence, permit or permission is <b>revoked</b> (officially withdrawn). <i>Refute</i> is to disprove a claim, <i>retrieve</i> is to get something back, <i>repel</i> is to drive away."},{"id":"gv-ch-28-25","level":"ch","focus":"collocation","q":"Prosecutors ______ doubt on the alibi after CCTV placed the defendant near the scene an hour before the robbery.","options":["placed","laid","set","cast"],"correct":3,"answer":"cast","vi":"Các công tố viên đã gieo nghi ngờ lên bằng chứng ngoại phạm sau khi camera an ninh cho thấy bị cáo ở gần hiện trường một giờ trước vụ cướp.","explanation":"The collocation is <b>cast doubt on</b> something. <i>Place</i>, <i>lay</i> and <i>set</i> do not combine with <i>doubt</i> in this sense."},{"id":"gv-ch-29-1","level":"ch","focus":"word-choice","q":"Years of broken promises have gradually ______ public confidence in the government's climate pledges.","options":["collapsed","eroded","dissolved","decayed"],"correct":1,"answer":"eroded","vi":"Nhiều năm thất hứa đã dần dần bào mòn niềm tin của công chúng vào những cam kết khí hậu của chính phủ.","explanation":"<b>Erode</b> is the transitive verb for wearing something away gradually (erode confidence/trust/support). <b>Collapse</b> and <b>decay</b> are intransitive here, and <b>dissolve</b> is used of substances, partnerships or parliaments, not confidence."},{"id":"gv-ch-29-2","level":"ch","focus":"tense","q":"By the end of this decade, the logistics firm ______ its entire delivery fleet with electric vehicles.","options":["will replace","has replaced","will have replaced","will be replacing"],"correct":2,"answer":"will have replaced","vi":"Đến cuối thập kỷ này, công ty logistics sẽ thay thế xong toàn bộ đội xe giao hàng bằng xe điện.","explanation":"<b>By + a future time</b> marks a deadline before which the action will be complete, so the future perfect <b>will have replaced</b> is needed; the future continuous would describe an action still in progress at that point."},{"id":"gv-ch-29-3","level":"ch","focus":"idiom","q":"I hate to ______, but the grant you have been promised is far from guaranteed.","options":["rain on your parade","throw in the towel","bite the bullet","jump the gun"],"correct":0,"answer":"rain on your parade","vi":"Tôi không muốn làm bạn mất hứng, nhưng khoản tài trợ mà bạn được hứa hẹn còn lâu mới chắc chắn.","explanation":"To <b>rain on someone's parade</b> is to spoil their excitement with unwelcome news, which is exactly what the speaker apologises for doing. <b>Throw in the towel</b> = give up, <b>bite the bullet</b> = face something unpleasant, <b>jump the gun</b> = act too soon."},{"id":"gv-ch-29-4","level":"ch","focus":"collocation","q":"Rising sea levels ______ a grave threat to low-lying island nations such as the Maldives.","options":["put","place","set","pose"],"correct":3,"answer":"pose","vi":"Mực nước biển dâng gây ra mối đe dọa nghiêm trọng cho các quốc đảo thấp như Maldives.","explanation":"The fixed collocation is <b>pose a threat / a risk / a danger</b>. Put, place and set are not used with <b>threat</b> in this sense."},{"id":"gv-ch-29-5","level":"ch","focus":"phrasal-verb","q":"The documentary ______ fresh anger over the dumping of toxic waste near the village.","options":["brought up","took up","stirred up","set up"],"correct":2,"answer":"stirred up","vi":"Bộ phim tài liệu đã khơi dậy làn sóng phẫn nộ mới về việc đổ chất thải độc hại gần ngôi làng.","explanation":"<b>Stir up</b> means to provoke strong feelings or trouble (stir up anger/resentment/controversy). <b>Bring up</b> = mention, <b>take up</b> = start a hobby or occupy space, <b>set up</b> = establish."},{"id":"gv-ch-29-6","level":"ch","focus":"modal","q":"The samples ______ contaminated in the laboratory; they were sealed the moment they were collected.","options":["mustn't have been","can't have been","needn't have been","shouldn't have been"],"correct":1,"answer":"can't have been","vi":"Các mẫu không thể nào bị nhiễm bẩn trong phòng thí nghiệm được; chúng đã được niêm phong ngay lúc thu thập.","explanation":"A confident deduction that something was <b>impossible</b> in the past uses <b>can't have + past participle</b>. <b>Mustn't have</b> is not used for deduction, <b>needn't have</b> = it was unnecessary, and <b>shouldn't have</b> = it was wrong to do so."},{"id":"gv-ch-29-7","level":"ch","focus":"word-choice","q":"The appeal court ______ the original verdict, rejecting all three grounds of appeal.","options":["sustained","retained","preserved","upheld"],"correct":3,"answer":"upheld","vi":"Tòa phúc thẩm giữ nguyên phán quyết ban đầu, bác bỏ cả ba căn cứ kháng cáo.","explanation":"A court <b>upholds</b> a verdict, ruling or decision when it confirms it on appeal. <b>Sustain</b> is used of objections in court, while <b>retain</b> and <b>preserve</b> describe keeping objects or conditions, not confirming a legal decision."},{"id":"gv-ch-29-8","level":"ch","focus":"inversion","q":"______ did the new tram line cut journey times across the city, but it also reduced traffic on the ring road by a fifth.","options":["Not only","Hardly","Only after","Not until"],"correct":0,"answer":"Not only","vi":"Tuyến tàu điện mới không những rút ngắn thời gian đi lại trong thành phố mà còn giảm một phần năm lượng xe cộ trên đường vành đai.","explanation":"The second half <b>but it also reduced</b> demands the pairing <b>Not only … but also</b>, with inversion (did the tram line cut) after the fronted negative. <b>Hardly</b> pairs with <b>when</b>, and <b>Not until</b> / <b>Only after</b> need a time phrase or clause before the inverted verb."},{"id":"gv-ch-29-9","level":"ch","focus":"idiom","q":"Junior staff are often reluctant to ______ by questioning decisions made higher up.","options":["spill the beans","break the ice","rock the boat","hold the fort"],"correct":2,"answer":"rock the boat","vi":"Nhân viên cấp dưới thường ngại gây xáo trộn bằng cách chất vấn những quyết định từ cấp trên.","explanation":"To <b>rock the boat</b> is to disturb a stable situation by challenging it, which fits questioning senior decisions. <b>Spill the beans</b> = reveal a secret, <b>break the ice</b> = ease first meetings, <b>hold the fort</b> = take charge while others are away."},{"id":"gv-ch-29-10","level":"ch","focus":"double-blank","q":"The missing funds uncovered so far are only the ______ of the ______; investigators believe far more was diverted.","options":["tip / iceberg","top / mountain","edge / cliff","peak / glacier"],"correct":0,"answer":"tip / iceberg","vi":"Số tiền thất thoát được phát hiện cho đến nay chỉ là phần nổi của tảng băng chìm; các điều tra viên tin rằng còn nhiều hơn thế đã bị chuyển đi.","explanation":"<b>The tip of the iceberg</b> is the small visible part of a much larger hidden problem. The other pairs are made-up variations that do not exist as idioms."},{"id":"gv-ch-29-11","level":"ch","focus":"relative","q":"The researchers, most of ______ had spent years in the Arctic, warned that the ice was thinning faster than predicted.","options":["which","whom","them","whose"],"correct":1,"answer":"whom","vi":"Các nhà nghiên cứu, mà phần lớn trong số họ đã dành nhiều năm ở Bắc Cực, cảnh báo rằng băng đang mỏng đi nhanh hơn dự đoán.","explanation":"After a quantifier + <b>of</b> in a non-defining relative clause, people take <b>whom</b> (most of whom, many of whom). <b>Which</b> is for things, <b>them</b> cannot introduce a relative clause, and <b>whose</b> needs a following noun."},{"id":"gv-ch-29-12","level":"ch","focus":"word-choice","q":"The report ______ that roughly a third of the region's wells are contaminated with pesticides.","options":["assesses","evaluates","appraises","estimates"],"correct":3,"answer":"estimates","vi":"Báo cáo ước tính rằng khoảng một phần ba số giếng trong khu vực bị nhiễm thuốc trừ sâu.","explanation":"<b>Estimate</b> means to give an approximate figure and takes a <b>that</b>-clause. <b>Assess</b>, <b>evaluate</b> and <b>appraise</b> mean to judge the quality or value of something and take a direct object, not a clause with a rough number."},{"id":"gv-ch-29-13","level":"ch","focus":"collocation","q":"The airline ______ a loss of forty million dollars in the final quarter of the year.","options":["posted","noted","marked","scored"],"correct":0,"answer":"posted","vi":"Hãng hàng không ghi nhận khoản lỗ bốn mươi triệu đô la trong quý cuối năm.","explanation":"In financial news a company <b>posts</b> a profit or a loss, meaning it reports it officially. Note, mark and score do not collocate with <b>a loss</b> in this sense."},{"id":"gv-ch-29-14","level":"ch","focus":"subjunctive","q":"The auditor recommended that the foundation ______ an independent trustee before the next funding round.","options":["appoints","appointed","would appoint","appoint"],"correct":3,"answer":"appoint","vi":"Kiểm toán viên khuyến nghị quỹ bổ nhiệm một ủy viên quản trị độc lập trước vòng tài trợ tiếp theo.","explanation":"After <b>recommend / suggest / insist that</b>, the that-clause takes the base-form subjunctive: <b>that the foundation appoint</b>, with no -s, no past tense and no would."},{"id":"gv-ch-29-15","level":"ch","focus":"idiom","q":"By unveiling its own electric van a day early, the rival firm ______ at the trade fair.","options":["pulled the company's leg","stole the company's thunder","twisted the company's arm","got the company's goat"],"correct":1,"answer":"stole the company's thunder","vi":"Bằng cách ra mắt chiếc xe tải điện của mình sớm một ngày, hãng đối thủ đã cướp mất sự chú ý của công ty tại hội chợ thương mại.","explanation":"To <b>steal someone's thunder</b> is to take the attention or praise they expected by acting first. <b>Pull someone's leg</b> = tease, <b>twist someone's arm</b> = pressure them, <b>get someone's goat</b> = annoy them."},{"id":"gv-ch-29-16","level":"ch","focus":"linking","q":"______ generous the pension scheme may seem, few employees stay long enough to benefit from it.","options":["Whatever","No matter","However","Although"],"correct":2,"answer":"However","vi":"Dù chương trình hưu trí có vẻ hào phóng đến đâu, ít nhân viên ở lại đủ lâu để được hưởng lợi từ nó.","explanation":"Before an adjective, the concessive form is <b>However + adjective + subject + verb</b>. <b>No matter</b> would need <b>how</b>, <b>Whatever</b> is followed by a noun, and <b>Although</b> introduces a full clause, not an adjective."},{"id":"gv-ch-29-17","level":"ch","focus":"phrasal-verb","q":"Before accepting the overseas posting, she wanted to ______ the decision with her family.","options":["talk back","talk down","talk into","talk over"],"correct":3,"answer":"talk over","vi":"Trước khi nhận nhiệm vụ ở nước ngoài, cô ấy muốn bàn bạc kỹ quyết định đó với gia đình.","explanation":"<b>Talk something over (with someone)</b> means to discuss it thoroughly before deciding. <b>Talk back</b> = answer rudely, <b>talk down (to)</b> = speak condescendingly, and <b>talk someone into</b> needs a person as its object."},{"id":"gv-ch-29-18","level":"ch","focus":"word-choice","q":"Several studies have ______ a direct link between air pollution and premature births.","options":["founded","established","instituted","formulated"],"correct":1,"answer":"established","vi":"Nhiều nghiên cứu đã xác lập được mối liên hệ trực tiếp giữa ô nhiễm không khí và sinh non.","explanation":"Research <b>establishes</b> a link, a fact or a connection, meaning it proves it. <b>Found</b> is for organisations, <b>institute</b> for systems or procedures, and <b>formulate</b> for plans or theories."},{"id":"gv-ch-29-19","level":"ch","focus":"conditional","q":"______ for the anonymous donation, the hospice would have closed last winter.","options":["Were it not","If it were not","Had it not been","Unless it were"],"correct":2,"answer":"Had it not been","vi":"Nếu không nhờ khoản quyên góp ẩn danh, nhà chăm sóc cuối đời đã phải đóng cửa vào mùa đông năm ngoái.","explanation":"The result clause <b>would have closed</b> refers to the past, so the condition must be the third-conditional form <b>Had it not been for</b>. <b>Were it not for</b> / <b>If it were not for</b> describe a present situation, and <b>unless</b> is not used with this pattern."},{"id":"gv-ch-29-20","level":"ch","focus":"participle","q":"______ how little rain has fallen this year, the region's reservoirs are in surprisingly good shape.","options":["Considered","To consider","Considering","Having considered"],"correct":2,"answer":"Considering","vi":"Xét đến việc năm nay mưa quá ít, các hồ chứa của khu vực đang ở trong tình trạng tốt đến bất ngờ.","explanation":"<b>Considering (how / that / + noun)</b> is a fixed participle used like a preposition, meaning taking into account, and it needs no subject of its own. <b>Considered</b> is passive and would make the reservoirs the thing considered, while <b>Having considered</b> and <b>To consider</b> would require the reservoirs to do the considering."},{"id":"gv-ch-29-21","level":"ch","focus":"idiom","q":"Figures released by the lobby group should be ______, since it is funded by the very industry it defends.","options":["swept under the carpet","kept under wraps","taken with a pinch of salt","put on the back burner"],"correct":2,"answer":"taken with a pinch of salt","vi":"Những số liệu do nhóm vận động hành lang công bố nên được tiếp nhận một cách dè dặt, vì nhóm này được tài trợ bởi chính ngành mà nó bênh vực.","explanation":"To <b>take something with a pinch of salt</b> is to doubt whether it is fully accurate, which fits figures from a biased source. <b>Sweep under the carpet</b> = hide a problem, <b>keep under wraps</b> = keep secret, <b>put on the back burner</b> = postpone."},{"id":"gv-ch-29-22","level":"ch","focus":"gerund-infinitive","q":"After a decade in banking, she has finally got used ______ far less than her former colleagues.","options":["to earning","to earn","earning","for earning"],"correct":0,"answer":"to earning","vi":"Sau một thập kỷ làm trong ngành ngân hàng, cuối cùng cô ấy đã quen với việc kiếm được ít hơn nhiều so với các đồng nghiệp cũ.","explanation":"In <b>be/get used to</b>, <b>to</b> is a preposition and is followed by an <b>-ing</b> form: <b>get used to earning</b>. <b>Used to + infinitive</b> describes a past habit, a different structure."},{"id":"gv-ch-29-23","level":"ch","focus":"double-blank","q":"The foundation has agreed to ______ on the running costs of the shelter ______ the council pays for the repairs.","options":["put / unless","bring / in case","carry / whereas","take / provided"],"correct":3,"answer":"take / provided","vi":"Quỹ đã đồng ý gánh vác chi phí vận hành của nhà tạm trú với điều kiện hội đồng thành phố chi trả cho việc sửa chữa.","explanation":"<b>Take on</b> means to accept a responsibility or cost, and <b>provided (that)</b> means on condition that. Put on, bring on and carry on do not mean accept a burden, and unless / in case / whereas give the wrong logical link."},{"id":"gv-ch-29-24","level":"ch","focus":"word-choice","q":"The retraining scheme ______ of three phases, the first of which begins next spring.","options":["consists","comprises","composes","constitutes"],"correct":0,"answer":"consists","vi":"Chương trình đào tạo lại gồm ba giai đoạn, giai đoạn đầu tiên bắt đầu vào mùa xuân tới.","explanation":"Only <b>consist</b> takes <b>of</b>: the scheme consists of three phases. <b>Comprise</b> takes a direct object with no preposition, while <b>compose</b> and <b>constitute</b> work the other way round (three phases constitute the scheme)."},{"id":"gv-ch-29-25","level":"ch","focus":"collocation","q":"Small manufacturers often struggle to ______ the strict new emissions standards.","options":["reach","meet","fill","match"],"correct":1,"answer":"meet","vi":"Các nhà sản xuất nhỏ thường chật vật để đáp ứng các tiêu chuẩn khí thải nghiêm ngặt mới.","explanation":"The collocation is <b>meet standards / requirements / targets</b>, meaning to satisfy them. Reach, fill and match are not used with <b>standards</b> in this sense."},{"id":"gv-ch-30-1","level":"ch","focus":"inversion","q":"______ the swift response of local volunteers, last month's flood would have swept away the entire rice harvest.","options":["Were it not for","Hadn't it been for","Had it not been for","If it had not been"],"correct":2,"answer":"Had it not been for","vi":"Nếu không nhờ phản ứng nhanh chóng của các tình nguyện viên địa phương, trận lũ tháng trước đã cuốn trôi toàn bộ vụ lúa.","explanation":"A past unreal condition (<b>would have swept</b>) inverts as <b>Had it not been for</b> + noun. <b>Were it not for</b> is the present form, <b>Hadn't it been for</b> wrongly inverts the contracted negative, and <b>If it had not been</b> lacks the <b>for</b> the noun phrase needs."},{"id":"gv-ch-30-2","level":"ch","focus":"word-choice","q":"Consumer watchdogs warned that the ______ workmanship of the imported toys — loose seams, sharp edges, paint that flaked at a touch — made them unsafe for toddlers.","options":["scanty","meagre","substandard","negligible"],"correct":2,"answer":"substandard","vi":"Các tổ chức bảo vệ người tiêu dùng cảnh báo rằng tay nghề gia công kém chất lượng của lô đồ chơi nhập khẩu — đường may lỏng, cạnh sắc, sơn bong chỉ chạm nhẹ — khiến chúng không an toàn cho trẻ nhỏ.","explanation":"<b>Substandard</b> means below the accepted level of quality, which is what the faults describe; <b>scanty</b>, <b>meagre</b> and <b>negligible</b> all describe a small <b>amount</b>, not poor quality."},{"id":"gv-ch-30-3","level":"ch","focus":"idiom","q":"Regulators were accused of ______ the misleading price tags that supermarkets displayed all season, even after shoppers complained.","options":["keeping an eye on","turning a blind eye to","seeing eye to eye with","catching the eye of"],"correct":1,"answer":"turning a blind eye to","vi":"Cơ quan quản lý bị cáo buộc làm ngơ trước những nhãn giá gây hiểu lầm mà các siêu thị trưng bày suốt cả mùa, ngay cả sau khi người mua đã khiếu nại.","explanation":"<b>Turn a blind eye to</b> = deliberately ignore wrongdoing. <b>Keep an eye on</b> = watch carefully, <b>see eye to eye with</b> = agree with someone, <b>catch the eye of</b> = attract attention — none fits an accusation of neglect."},{"id":"gv-ch-30-4","level":"ch","focus":"collocation","q":"The supermarket chain ______ a record profit last year despite the squeeze on household budgets.","options":["placed","put","stood","posted"],"correct":3,"answer":"posted","vi":"Chuỗi siêu thị đã công bố mức lợi nhuận kỷ lục năm ngoái bất chấp ngân sách các hộ gia đình bị thắt chặt.","explanation":"In financial English a company <b>posts</b> a profit or a loss (announces its results); <b>place</b>, <b>put</b> and <b>stand</b> do not collocate with <b>profit</b>."},{"id":"gv-ch-30-5","level":"ch","focus":"phrasal-verb","q":"The minister's speech only briefly ______ the shortage of maths teachers before moving on to school buildings.","options":["touched on","touched up","touched down","touched off"],"correct":0,"answer":"touched on","vi":"Bài phát biểu của bộ trưởng chỉ đề cập lướt qua tình trạng thiếu giáo viên toán rồi chuyển sang chuyện cơ sở vật chất trường học.","explanation":"<b>Touch on</b> = mention a subject briefly. <b>Touch up</b> = improve small details of a picture, <b>touch down</b> = land (a plane), <b>touch off</b> = trigger a reaction or crisis."},{"id":"gv-ch-30-6","level":"ch","focus":"modal","q":"The retailer ______ its Christmas stock months in advance — the shelves were already full the day the holiday season opened.","options":["should have ordered","needn't have ordered","must have ordered","can't have ordered"],"correct":2,"answer":"must have ordered","vi":"Nhà bán lẻ hẳn đã đặt hàng Giáng sinh từ nhiều tháng trước — các kệ hàng đã đầy ắp ngay ngày mùa lễ hội bắt đầu.","explanation":"The full shelves are evidence, so we deduce a past certainty with <b>must have</b>. <b>Should have</b> implies they did not order, <b>needn't have</b> implies a wasted effort, and <b>can't have</b> is the opposite deduction."},{"id":"gv-ch-30-7","level":"ch","focus":"word-choice","q":"The auditors described the company's accounts as ______: not a single figure out of place across three years of trading.","options":["faulty","faultless","fault-finding","faulted"],"correct":1,"answer":"faultless","vi":"Các kiểm toán viên mô tả sổ sách của công ty là hoàn hảo không tì vết: không một con số nào sai lệch trong suốt ba năm kinh doanh.","explanation":"<b>Faultless</b> = without a single error, matching the colon clause. <b>Faulty</b> means the opposite, <b>fault-finding</b> describes a critical person, and <b>faulted</b> is a past participle meaning criticised."},{"id":"gv-ch-30-8","level":"ch","focus":"double-blank","q":"Engineers worked ______ the ______ to patch the payment system before the Black Friday rush began.","options":["against / time","before / clock","behind / time","against / clock"],"correct":3,"answer":"against / clock","vi":"Các kỹ sư chạy đua với thời gian để vá hệ thống thanh toán trước khi đợt mua sắm Black Friday bắt đầu.","explanation":"<b>Work against the clock</b> = work as fast as possible to meet a deadline. English has <b>a race against time</b> but not <b>against the time</b>, and <b>before the clock</b> / <b>behind the time</b> are not idioms."},{"id":"gv-ch-30-9","level":"ch","focus":"idiom","q":"Thanks to its low debt, the retailer managed to ______ that drove several rivals into bankruptcy.","options":["weather the storm","take by storm","go down a storm","storm the barricades"],"correct":0,"answer":"weather the storm","vi":"Nhờ nợ thấp, nhà bán lẻ đã vượt qua được cơn bão khủng hoảng vốn đẩy nhiều đối thủ vào cảnh phá sản.","explanation":"<b>Weather the storm</b> = survive a difficult period, and <b>the storm</b> is then the noun that <b>that drove …</b> describes. <b>Take by storm</b> = conquer suddenly, <b>go down a storm</b> = be received enthusiastically, <b>storm the barricades</b> = attack."},{"id":"gv-ch-30-10","level":"ch","focus":"linking","q":"______ the sharp rise in tuition fees, applications to the most selective universities have continued to climb.","options":["Nevertheless","Nonetheless","Notwithstanding","Albeit"],"correct":2,"answer":"Notwithstanding","vi":"Bất chấp học phí tăng mạnh, số đơn xin vào các trường đại học chọn lọc nhất vẫn tiếp tục tăng.","explanation":"<b>Notwithstanding</b> is a preposition (= despite) and can take the noun phrase <b>the sharp rise</b>; <b>nevertheless</b> and <b>nonetheless</b> are adverbs that join clauses, and <b>albeit</b> introduces a reduced clause, not a noun."},{"id":"gv-ch-30-11","level":"ch","focus":"word-choice","q":"Critics dismissed the new curriculum as ______, arguing that it recycled old material and offered nothing that would stretch the brightest pupils.","options":["lukewarm","luminous","lucrative","lacklustre"],"correct":3,"answer":"lacklustre","vi":"Giới phê bình gạt bỏ chương trình học mới là nhạt nhẽo thiếu sức sống, cho rằng nó xào lại nội dung cũ và chẳng có gì để thử thách những học sinh giỏi nhất.","explanation":"<b>Lacklustre</b> = dull, lacking energy or originality, which fits recycled material. <b>Lukewarm</b> describes an unenthusiastic <b>response</b>, <b>luminous</b> = shining, <b>lucrative</b> = profitable."},{"id":"gv-ch-30-12","level":"ch","focus":"subjunctive","q":"The audit committee recommended that the chief executive ______ from the bonus scheme until the accounts had been restated.","options":["was removed","be removed","is removed","would be removed"],"correct":1,"answer":"be removed","vi":"Ủy ban kiểm toán đề nghị rằng tổng giám đốc bị loại khỏi chương trình thưởng cho đến khi báo cáo tài chính được lập lại.","explanation":"After <b>recommend that</b>, the subjunctive uses the base form: <b>(should) be removed</b>. Indicative <b>was / is</b> and the conditional <b>would be</b> are not used in this pattern."},{"id":"gv-ch-30-13","level":"ch","focus":"collocation","q":"Online retailers face ______ competition from overseas platforms that undercut them on price.","options":["stiff","rigid","firm","solid"],"correct":0,"answer":"stiff","vi":"Các nhà bán lẻ trực tuyến đối mặt với sự cạnh tranh gay gắt từ những nền tảng nước ngoài bán phá giá họ.","explanation":"<b>Stiff competition</b> is the fixed collocation for intense competition; <b>rigid</b>, <b>firm</b> and <b>solid</b> share the sense of inflexibility but do not collocate with <b>competition</b>."},{"id":"gv-ch-30-14","level":"ch","focus":"idiom","q":"Economists dismissed the furious row over the 2p rise in the price of bread as ______ — a great deal of noise about something that hardly mattered.","options":["a drop in the ocean","a shot in the dark","a storm in a teacup","a blessing in disguise"],"correct":2,"answer":"a storm in a teacup","vi":"Các nhà kinh tế gạt bỏ cuộc tranh cãi dữ dội về việc giá bánh mì tăng 2 xu, coi đó chỉ là chuyện bé xé ra to — ồn ào rất nhiều về một điều chẳng đáng kể.","explanation":"<b>A storm in a teacup</b> = a big fuss about something trivial, exactly the gloss after the dash. <b>A drop in the ocean</b> = a tiny amount, <b>a shot in the dark</b> = a wild guess, <b>a blessing in disguise</b> = hidden good luck."},{"id":"gv-ch-30-15","level":"ch","focus":"participle","q":"______ for even a few minutes, a charging e-scooter battery can overheat and set an entire flat alight, fire officers warned.","options":["Leaving unattended","Having left unattended","To leave unattended","Left unattended"],"correct":3,"answer":"Left unattended","vi":"Nếu bị bỏ mặc không ai trông chừng dù chỉ vài phút, pin xe điện đang sạc có thể quá nóng và thiêu rụi cả căn hộ, lực lượng cứu hỏa cảnh báo.","explanation":"The battery is the thing that is left, so the reduced clause takes the passive past participle <b>Left unattended</b> (= if it is left unattended). <b>Leaving</b> and <b>Having left</b> would make the battery the one doing the leaving, and <b>To leave</b> expresses purpose."},{"id":"gv-ch-30-16","level":"ch","focus":"phrasal-verb","q":"It took investigators three months to ______ the owner of the website that had been selling counterfeit trainers.","options":["turn down","tone down","tie down","track down"],"correct":3,"answer":"track down","vi":"Các điều tra viên mất ba tháng mới lần ra được chủ nhân trang web bán giày thể thao giả.","explanation":"<b>Track down</b> = find someone after a long search. <b>Turn down</b> = reject, <b>tone down</b> = make less extreme, <b>tie down</b> = restrict someone's freedom."},{"id":"gv-ch-30-17","level":"ch","focus":"word-choice","q":"For thirty years the firm has enjoyed an ______ reputation for customer service, which is why shoppers tolerate its higher prices.","options":["unblemished","unbalanced","unbounded","unbiased"],"correct":0,"answer":"unblemished","vi":"Suốt ba mươi năm, công ty đã có được danh tiếng không tì vết về dịch vụ khách hàng, và đó là lý do người mua chấp nhận giá cao hơn.","explanation":"An <b>unblemished reputation</b> is one with no stain or fault on it. <b>Unbalanced</b> = unstable, <b>unbounded</b> = limitless (used of joy, enthusiasm), <b>unbiased</b> = impartial — none collocates with <b>reputation</b> in this sense."},{"id":"gv-ch-30-18","level":"ch","focus":"gerund-infinitive","q":"Many parents told the survey they would rather pay for private tutors ______ their children fall behind.","options":["than letting","than to let","than let","rather than let"],"correct":2,"answer":"than let","vi":"Nhiều phụ huynh cho biết trong khảo sát rằng họ thà trả tiền thuê gia sư còn hơn để con mình tụt lại phía sau.","explanation":"<b>Would rather + bare infinitive … than + bare infinitive</b>: <b>pay … than let</b>. The <b>-ing</b> and <b>to</b> forms break the parallel, and <b>rather than</b> cannot follow a sentence that already has <b>would rather</b>."},{"id":"gv-ch-30-19","level":"ch","focus":"comparison","q":"Households in the capital spend nearly ______ on private tuition as those in rural provinces.","options":["twice more","twice as much","as twice much","twice as many"],"correct":1,"answer":"twice as much","vi":"Các hộ gia đình ở thủ đô chi cho học thêm gần gấp đôi so với các hộ ở nông thôn.","explanation":"Multiples use <b>twice as much/many … as</b>; money spent is uncountable, so <b>as much</b>, not <b>as many</b>. <b>Twice more</b> and <b>as twice much</b> are not English."},{"id":"gv-ch-30-20","level":"ch","focus":"idiom","q":"The delivery firm broke the sofa and then, ______, billed the customer for the return journey.","options":["to add fuel to the fire","to add another string to its bow","to add its two cents","to add insult to injury"],"correct":3,"answer":"to add insult to injury","vi":"Công ty giao hàng làm hỏng chiếc ghế sofa rồi, như xát muối vào vết thương, còn tính phí khách hàng cho chuyến chở trả lại.","explanation":"<b>Add insult to injury</b> = make an already bad situation even more unfair. <b>Add fuel to the fire</b> = inflame an argument or anger, <b>add another string to one's bow</b> = gain a new skill, <b>add one's two cents</b> = offer an opinion."},{"id":"gv-ch-30-21","level":"ch","focus":"agreement","q":"Neither the minister nor her advisers ______ willing to say when the revised syllabus would be published.","options":["were","was","is","has been"],"correct":0,"answer":"were","vi":"Cả bộ trưởng lẫn các cố vấn của bà đều không sẵn lòng cho biết khi nào chương trình học sửa đổi sẽ được công bố.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, the plural <b>advisers</b>, and the reporting frame is past, so <b>were</b>."},{"id":"gv-ch-30-22","level":"ch","focus":"double-blank","q":"A small loan from her brother ______ the bakery ______ until the tourists returned in June.","options":["took / over","tied / up","tided / over","turned / over"],"correct":2,"answer":"tided / over","vi":"Một khoản vay nhỏ từ anh trai đã giúp tiệm bánh cầm cự qua giai đoạn khó khăn cho đến khi khách du lịch quay lại vào tháng Sáu.","explanation":"<b>Tide somebody/something over</b> = help through a short period of difficulty, so a loan <b>tided the bakery over</b>. <b>Take over</b> = seize control, <b>tie up</b> = occupy or immobilise, <b>turn over</b> = generate (revenue) — none works with a loan and <b>until</b>."},{"id":"gv-ch-30-23","level":"ch","focus":"collocation","q":"From the survey data, researchers ______ the conclusion that free school meals improve attendance.","options":["took","drew","made","brought"],"correct":1,"answer":"drew","vi":"Từ dữ liệu khảo sát, các nhà nghiên cứu rút ra kết luận rằng bữa ăn miễn phí ở trường giúp cải thiện tỷ lệ đi học.","explanation":"You <b>draw</b> (or <b>reach</b>) a conclusion; <b>take</b>, <b>make</b> and <b>bring</b> do not collocate with <b>conclusion</b>."},{"id":"gv-ch-30-24","level":"ch","focus":"passive","q":"The new consumer-protection rules ______ to have been drafted in a hurry, with several clauses contradicting one another.","options":["are saying","say","have said","are said"],"correct":3,"answer":"are said","vi":"Bộ quy định bảo vệ người tiêu dùng mới được cho là đã được soạn thảo vội vàng, với nhiều điều khoản mâu thuẫn nhau.","explanation":"The impersonal passive <b>be said to + perfect infinitive</b> reports what people claim about a past action: <b>are said to have been drafted</b>. The rules cannot <b>say</b> anything themselves, so the active forms are wrong."},{"id":"gv-ch-30-25","level":"ch","focus":"word-choice","q":"Shoppers who bought the discounted laptops soon found them ______: they worked, but the screens were dim and the batteries barely lasted an hour.","options":["second-hand","second-rate","second-best","secondary"],"correct":1,"answer":"second-rate","vi":"Những người mua laptop giảm giá sớm nhận ra chúng thuộc hạng xoàng: máy vẫn chạy, nhưng màn hình tối và pin chỉ trụ được chưa đầy một tiếng.","explanation":"<b>Second-rate</b> = of inferior quality, which the dim screens and weak batteries show. <b>Second-hand</b> = previously owned, <b>second-best</b> = the next choice after the best, <b>secondary</b> = less important."},{"id":"gv-ch-31-1","level":"ch","focus":"word-choice","q":"Sales of home blood-pressure monitors ______ after the ministry's warning about undiagnosed hypertension, rising fivefold in a single month.","options":["dwindled","skyrocketed","fluctuated","stagnated"],"correct":1,"answer":"skyrocketed","vi":"Doanh số máy đo huyết áp tại nhà tăng vọt sau cảnh báo của bộ y tế về tình trạng cao huyết áp chưa được chẩn đoán, tăng gấp năm lần chỉ trong một tháng.","explanation":"<b>Skyrocket</b> = rise extremely fast, which matches 'rising fivefold in a single month'. <b>Dwindle</b> = shrink gradually, <b>fluctuate</b> = move up and down, <b>stagnate</b> = stop growing."},{"id":"gv-ch-31-2","level":"ch","focus":"idiom","q":"Persuading teenagers to switch off location sharing has proved ______ for privacy campaigners, who report that fewer than one in ten has done so.","options":["an uphill battle","a foregone conclusion","a blessing in disguise","a red herring"],"correct":0,"answer":"an uphill battle","vi":"Việc thuyết phục thanh thiếu niên tắt chia sẻ vị trí đã tỏ ra là một cuộc chiến gian nan đối với các nhà vận động về quyền riêng tư, những người cho biết chưa tới một phần mười các em làm vậy.","explanation":"<b>An uphill battle</b> = a struggle that is very hard to win, which fits 'fewer than one in ten'. <b>A foregone conclusion</b> = a certain result, <b>a blessing in disguise</b> = hidden good luck, <b>a red herring</b> = a misleading clue."},{"id":"gv-ch-31-3","level":"ch","focus":"collocation","q":"Facial recognition in shopping centres ______ a serious threat to the anonymity that city life once guaranteed.","options":["makes","does","poses","puts"],"correct":2,"answer":"poses","vi":"Công nghệ nhận diện khuôn mặt ở các trung tâm mua sắm đặt ra mối đe dọa nghiêm trọng đối với sự ẩn danh mà đời sống đô thị từng bảo đảm.","explanation":"The fixed collocation for presenting a danger is <b>pose a threat</b> (also pose a risk / a danger / a question). <b>Make a threat</b> means to utter one, not to be a danger to something, and <b>do</b> and <b>put</b> do not combine with 'threat' at all."},{"id":"gv-ch-31-4","level":"ch","focus":"inversion","q":"Not until a journalist published the leaked database ______ that millions of accounts had been exposed.","options":["the company admitted","had the company admitted","the company did admit","did the company admit"],"correct":3,"answer":"did the company admit","vi":"Mãi đến khi một nhà báo công bố cơ sở dữ liệu bị rò rỉ, công ty mới thừa nhận rằng hàng triệu tài khoản đã bị lộ.","explanation":"After a fronted <b>Not until</b> clause the main clause is inverted: auxiliary + subject + bare verb, <b>did the company admit</b>. The admission comes after the publishing, so the past perfect 'had ... admitted' is wrong, and the uninverted forms are ungrammatical here."},{"id":"gv-ch-31-5","level":"ch","focus":"phrasal-verb","q":"The laboratory will gradually ______ its vaccine production over the next six months rather than halt it overnight.","options":["wind down","wind up","wear down","tone down"],"correct":0,"answer":"wind down","vi":"Phòng thí nghiệm sẽ dần thu hẹp hoạt động sản xuất vắc-xin trong sáu tháng tới thay vì dừng đột ngột.","explanation":"<b>Wind down</b> = reduce an activity gradually before ending it, the opposite of 'halt it overnight'. <b>Wind up</b> = bring to a complete end (a company, a meeting), <b>wear down</b> = exhaust or erode, <b>tone down</b> = make less forceful (language, colours)."},{"id":"gv-ch-31-6","level":"ch","focus":"word-choice","q":"Public enthusiasm for the fitness app began to ______ once users discovered how much location data it had been collecting.","options":["accelerate","rebound","escalate","wane"],"correct":3,"answer":"wane","vi":"Sự hào hứng của công chúng với ứng dụng thể dục bắt đầu nguội dần khi người dùng phát hiện nó đã thu thập bao nhiêu dữ liệu vị trí.","explanation":"<b>Wane</b> = decrease gradually in strength or intensity, the natural reaction to a privacy scandal. <b>Accelerate</b> and <b>escalate</b> mean to increase, and <b>rebound</b> = recover after a fall, none of which fits a discovery that damages trust."},{"id":"gv-ch-31-7","level":"ch","focus":"double-blank","q":"After a decade of lawsuits, the two chip makers agreed to ______ the ______ and pool their patents on medical sensors.","options":["bite / bullet","bury / hatchet","break / ice","call / shots"],"correct":1,"answer":"bury / hatchet","vi":"Sau một thập kỷ kiện tụng, hai hãng sản xuất chip đồng ý gác lại hiềm khích và gộp chung các bằng sáng chế về cảm biến y tế.","explanation":"<b>Bury the hatchet</b> = end a long quarrel and make peace, which 'a decade of lawsuits' followed by pooling patents describes. <b>Bite the bullet</b> = accept something painful, <b>break the ice</b> = ease first-meeting awkwardness, <b>call the shots</b> = be in control."},{"id":"gv-ch-31-8","level":"ch","focus":"modal","q":"The patient ______ the tablets on an empty stomach, or she would not be feeling this nauseous now.","options":["should have taken","needn't have taken","must have taken","can't have taken"],"correct":2,"answer":"must have taken","vi":"Bệnh nhân hẳn đã uống thuốc lúc bụng đói, nếu không thì giờ cô ấy đã không buồn nôn đến thế.","explanation":"The nausea is evidence, so the speaker draws a confident conclusion about the past: <b>must have taken</b>. <b>Can't have</b> expresses the opposite deduction, <b>should have</b> is criticism, and <b>needn't have</b> means it was unnecessary."},{"id":"gv-ch-31-9","level":"ch","focus":"idiom","q":"Researchers who blame screen time alone for teenage insomnia may be ______, since the latest data point to caffeine as the stronger factor.","options":["beating around the bush","barking up the wrong tree","jumping on the bandwagon","putting the cart before the horse"],"correct":1,"answer":"barking up the wrong tree","vi":"Các nhà nghiên cứu chỉ đổ lỗi cho thời gian dùng màn hình gây mất ngủ ở tuổi teen có lẽ đang nhắm sai hướng, vì dữ liệu mới nhất cho thấy caffeine là yếu tố mạnh hơn.","explanation":"<b>Bark up the wrong tree</b> = pursue a mistaken explanation or target, which the caffeine data suggest. <b>Beat around the bush</b> = avoid the point, <b>jump on the bandwagon</b> = follow a fashion, <b>put the cart before the horse</b> = do things in the wrong order."},{"id":"gv-ch-31-10","level":"ch","focus":"collocation","q":"Rural clinics have been left to ______ the burden of the vaccination drive while city hospitals receive most of the extra funding.","options":["foot","head","hand","shoulder"],"correct":3,"answer":"shoulder","vi":"Các phòng khám nông thôn bị bỏ mặc gánh vác gánh nặng của chiến dịch tiêm chủng, trong khi các bệnh viện thành phố nhận phần lớn khoản kinh phí bổ sung.","explanation":"To take on a heavy responsibility is to <b>shoulder the burden</b> (also shoulder the cost / the blame). <b>Foot</b> collocates with 'the bill', <b>head</b> with a committee or a list, and <b>hand</b> needs 'over' or 'out'; none of them combines with 'burden'."},{"id":"gv-ch-31-11","level":"ch","focus":"subjunctive","q":"It is vital that the lead researcher ______ the safety briefing in person before the trial resumes.","options":["attended","attending","attend","will attend"],"correct":2,"answer":"attend","vi":"Điều thiết yếu là trưởng nhóm nghiên cứu phải trực tiếp tham dự buổi phổ biến an toàn trước khi thử nghiệm được nối lại.","explanation":"After <b>It is vital / essential / important that</b> the clause takes the base-form subjunctive whatever the subject: <b>that she attend</b>. The past form attended and the future 'will attend' do not fit this pattern, and attending is not a finite verb, so the clause would have no verb at all."},{"id":"gv-ch-31-12","level":"ch","focus":"word-choice","q":"Shares in the social network ______ by a fifth in a single afternoon after regulators announced a privacy investigation.","options":["dwindled","crept","tumbled","hovered"],"correct":2,"answer":"tumbled","vi":"Cổ phiếu của mạng xã hội này lao dốc một phần năm chỉ trong một buổi chiều sau khi cơ quan quản lý công bố cuộc điều tra về quyền riêng tư.","explanation":"<b>Tumble</b> = fall suddenly and steeply, matching 'by a fifth in a single afternoon'. <b>Dwindle</b> is a slow, gradual decline, <b>creep</b> is slow movement, and <b>hover</b> means to stay roughly level."},{"id":"gv-ch-31-13","level":"ch","focus":"linking","q":"______ carefully a hospital encrypts its records, a single careless password can undo the whole effort.","options":["Whatever","No matter how","Even though","In spite of"],"correct":1,"answer":"No matter how","vi":"Dù một bệnh viện mã hóa hồ sơ cẩn thận đến đâu, chỉ một mật khẩu bất cẩn cũng có thể làm đổ sông đổ biển toàn bộ nỗ lực.","explanation":"Before an adverb (<b>carefully</b>) the concessive link is <b>No matter how</b> (= however carefully). <b>Whatever</b> needs a noun, <b>even though</b> introduces a full clause, and <b>in spite of</b> takes a noun phrase."},{"id":"gv-ch-31-14","level":"ch","focus":"phrasal-verb","q":"Using the phone's metadata, investigators were able to ______ the exact building from which the stolen files had been uploaded.","options":["zoom in at","home in to","close in at","zero in on"],"correct":3,"answer":"zero in on","vi":"Nhờ siêu dữ liệu của chiếc điện thoại, các điều tra viên đã khoanh vùng được chính xác tòa nhà nơi các tệp bị đánh cắp đã được tải lên.","explanation":"<b>Zero in on</b> = identify and focus precisely on a target. The others use the wrong particle: it is home in <b>on</b>, close in <b>on</b> and zoom in <b>on</b>, never 'to' or 'at'."},{"id":"gv-ch-31-15","level":"ch","focus":"reported","q":"At the hearing, the journalist asked the chief executive ______ the company had ever sold its users' location history to advertisers.","options":["whether","that","what","did"],"correct":0,"answer":"whether","vi":"Tại phiên điều trần, nhà báo hỏi vị tổng giám đốc liệu công ty có bao giờ bán lịch sử vị trí của người dùng cho các nhà quảng cáo hay không.","explanation":"A reported yes/no question is introduced by <b>whether</b> (or if) with statement word order. <b>That</b> reports a statement, <b>what</b> would need a missing object, and <b>did</b> belongs to direct-question order."},{"id":"gv-ch-31-16","level":"ch","focus":"idiom","q":"The surgeon is not one to ______, but her transplant team's survival figures speak for themselves.","options":["blow hot and cold","blow the whistle","blow her own trumpet","blow her top"],"correct":2,"answer":"blow her own trumpet","vi":"Vị bác sĩ phẫu thuật không phải người thích khoe khoang, nhưng con số tỷ lệ sống sót của đội ghép tạng của bà đã tự nói lên tất cả.","explanation":"<b>Blow your own trumpet</b> = boast about your achievements, which contrasts with the figures doing the talking. <b>Blow hot and cold</b> = keep changing your mind, <b>blow the whistle</b> = expose wrongdoing, <b>blow your top</b> = lose your temper."},{"id":"gv-ch-31-17","level":"ch","focus":"gerund-infinitive","q":"Older users seem resigned to ______ tracked wherever they go online, whereas teenagers are increasingly fighting back.","options":["be","being","to be","been"],"correct":1,"answer":"being","vi":"Người dùng lớn tuổi dường như cam chịu việc bị theo dõi ở bất cứ đâu họ lên mạng, trong khi thanh thiếu niên ngày càng phản kháng.","explanation":"In <b>resigned to</b>, 'to' is a preposition (like 'used to', 'look forward to'), so it is followed by a gerund: <b>being tracked</b>. The bare infinitive, 'to be' and 'been' cannot follow a preposition."},{"id":"gv-ch-31-18","level":"ch","focus":"word-choice","q":"The probe is now ______ towards Jupiter at almost 200,000 kilometres an hour, faster than any craft before it.","options":["hurtling","drifting","dawdling","meandering"],"correct":0,"answer":"hurtling","vi":"Tàu thăm dò hiện đang lao về phía Sao Mộc với tốc độ gần 200.000 km/giờ, nhanh hơn bất kỳ con tàu nào trước đó.","explanation":"<b>Hurtle</b> = move at great speed, often uncontrollably, so it fits a record-breaking velocity. <b>Drift</b> = move slowly with no power, <b>dawdle</b> = move slowly and lazily, <b>meander</b> = wander along a winding path."},{"id":"gv-ch-31-19","level":"ch","focus":"participle","q":"______ a surge in counterfeit medicines, the health ministry has ordered every pharmacy to scan a barcode on each pack it sells.","options":["Prompted by","Prompting by","Having prompted by","To prompt by"],"correct":0,"answer":"Prompted by","vi":"Trước tình trạng thuốc giả gia tăng, bộ y tế đã yêu cầu mọi hiệu thuốc quét mã vạch trên từng hộp thuốc bán ra.","explanation":"The ministry was moved to act <b>by</b> the surge, so the past participle with passive meaning is needed: <b>Prompted by</b>. <b>Prompting</b> and <b>Having prompted</b> would make the ministry the cause rather than the thing acted on, and 'to prompt by' is not a participle clause."},{"id":"gv-ch-31-20","level":"ch","focus":"collocation","q":"Even a ______ smoker who quits at fifty regains several years of life expectancy, the study concludes.","options":["strong","heavy","hard","big"],"correct":1,"answer":"heavy","vi":"Ngay cả một người nghiện thuốc nặng bỏ thuốc ở tuổi năm mươi cũng lấy lại được vài năm tuổi thọ, nghiên cứu kết luận.","explanation":"Someone who smokes a great deal is a <b>heavy smoker</b> (likewise a heavy drinker, heavy traffic, heavy rain). <b>Strong</b>, <b>hard</b> and <b>big</b> are not used with 'smoker'."},{"id":"gv-ch-31-21","level":"ch","focus":"double-blank","q":"It ______ out that the clinic had been ______ patient records on an unsecured server for almost three years.","options":["ended / to store","worked / stored","turned / storing","made / storing"],"correct":2,"answer":"turned / storing","vi":"Hóa ra phòng khám đã lưu trữ hồ sơ bệnh nhân trên một máy chủ không được bảo mật trong gần ba năm.","explanation":"<b>It turned out that</b> = it was discovered that; after 'had been' the past perfect continuous needs the -ing form, <b>storing</b>. 'End out' and 'make out that' do not mean discover, and 'had been stored patient records' has no grammatical object slot."},{"id":"gv-ch-31-22","level":"ch","focus":"idiom","q":"The telehealth start-up expects to ______ by next spring, once subscription income finally covers its server costs.","options":["break ground","break ranks","break the bank","break even"],"correct":3,"answer":"break even","vi":"Công ty khởi nghiệp y tế từ xa dự kiến sẽ hòa vốn vào mùa xuân tới, khi thu nhập từ thuê bao cuối cùng bù đắp được chi phí máy chủ.","explanation":"<b>Break even</b> = make neither a profit nor a loss, exactly what 'income covers its costs' means. <b>Break ground</b> = start building, <b>break ranks</b> = stop supporting your group, <b>break the bank</b> = cost too much."},{"id":"gv-ch-31-23","level":"ch","focus":"pronoun","q":"______ leaks a patient's records, even unintentionally, now faces a fine of up to a year's salary under the new law.","options":["Whoever","Whomever","Whichever","Whom"],"correct":0,"answer":"Whoever","vi":"Bất kỳ ai làm rò rỉ hồ sơ bệnh nhân, dù vô ý, giờ đây đều đối mặt với khoản phạt lên tới một năm lương theo luật mới.","explanation":"<b>Whoever</b> = any person who, and it is the subject of 'leaks', so the subject form is needed. <b>Whomever</b> and <b>whom</b> are object forms, and <b>whichever</b> refers to a choice among things, not to an unknown person."},{"id":"gv-ch-31-24","level":"ch","focus":"word-choice","q":"Life expectancy in the region has ______ at around 72 for a decade, despite heavy investment in new hospitals.","options":["rocketed","rebounded","plateaued","dipped"],"correct":2,"answer":"plateaued","vi":"Tuổi thọ trung bình ở khu vực này đã chững lại ở mức khoảng 72 suốt một thập kỷ, bất chấp đầu tư mạnh vào các bệnh viện mới.","explanation":"<b>Plateau</b> = stop rising and stay level, which 'at around 72 for a decade' and 'despite investment' both signal. <b>Rocket</b> and <b>rebound</b> describe rises, and <b>dip</b> is a short fall; none can be followed by 'at around 72 for a decade'."},{"id":"gv-ch-31-25","level":"ch","focus":"question-tag","q":"Nobody expected the vaccine to clear the regulator's review this quickly, ______?","options":["didn't they","did they","did it","wasn't it"],"correct":1,"answer":"did they","vi":"Không ai ngờ vắc-xin lại vượt qua đợt xét duyệt của cơ quan quản lý nhanh đến thế, phải không?","explanation":"<b>Nobody</b> makes the statement negative, so the tag is positive, and indefinite person subjects take <b>they</b>: <b>did they</b>. 'Didn't they' repeats the negative, and 'it' would refer to the vaccine, not to the subject."},{"id":"gv-ch-32-1","level":"ch","focus":"word-choice","q":"Many long-term backpackers pride themselves on being ______, stretching a modest budget over months on the road without ever feeling deprived.","options":["thrifty","stingy","miserly","tight-fisted"],"correct":0,"answer":"thrifty","vi":"Nhiều người đi du lịch bụi dài ngày tự hào vì mình tiết kiệm, kéo dài một ngân sách khiêm tốn qua nhiều tháng trên đường mà chưa bao giờ thấy thiếu thốn.","explanation":"<b>Thrifty</b> is the approving word for someone who spends carefully, so it fits <b>pride themselves on</b>. <b>Stingy</b>, <b>miserly</b> and <b>tight-fisted</b> all mean meanly unwilling to spend and are insults, not points of pride."},{"id":"gv-ch-32-2","level":"ch","focus":"idiom","q":"When the exhibition's visitor figures were queried, it was the junior curator who was left to ______, although every decision had been taken far above her.","options":["carry the day","carry the can","carry the torch","carry the weight"],"correct":1,"answer":"carry the can","vi":"Khi số liệu khách tham quan của triển lãm bị chất vấn, chính cô phụ trách trưng bày trẻ tuổi phải đứng ra gánh trách nhiệm, dù mọi quyết định đều do cấp trên đưa ra.","explanation":"<b>Carry the can</b> = take the blame for something others did. <b>Carry the day</b> = win, <b>carry the torch</b> = keep a cause alive, and <b>carry the weight</b> is not an idiom of blame."},{"id":"gv-ch-32-3","level":"ch","focus":"collocation","q":"Under mounting pressure from residents, the council has ______ strict limits on the number of cruise ships allowed to dock each day.","options":["installed","inflicted","imposed","instilled"],"correct":2,"answer":"imposed","vi":"Trước sức ép ngày càng lớn từ cư dân, hội đồng thành phố đã áp đặt giới hạn nghiêm ngặt về số tàu du lịch được phép cập cảng mỗi ngày.","explanation":"You <b>impose</b> limits, rules or taxes. <b>Inflict</b> goes with damage or pain, <b>instil</b> with values or fear, and <b>install</b> with equipment or software."},{"id":"gv-ch-32-4","level":"ch","focus":"phrasal-verb","q":"Visitors from a single neighbouring country ______ nearly half of all overnight stays recorded in the province last year.","options":["answer for","allow for","stand for","account for"],"correct":3,"answer":"account for","vi":"Du khách từ một nước láng giềng duy nhất chiếm gần một nửa tổng số đêm lưu trú được ghi nhận ở tỉnh này năm ngoái.","explanation":"<b>Account for</b> = make up a stated share of a total. <b>Answer for</b> = be responsible for a fault, <b>allow for</b> = take into consideration, <b>stand for</b> = represent."},{"id":"gv-ch-32-5","level":"ch","focus":"inversion","q":"Only when the last tour bus has pulled away ______ the village square return to its usual silence.","options":["does","do","did","has"],"correct":0,"answer":"does","vi":"Chỉ khi chiếc xe du lịch cuối cùng đã rời đi, quảng trường làng mới trở lại sự tĩnh lặng thường ngày.","explanation":"After a fronted <b>Only when…</b> clause the main clause inverts with an auxiliary: <b>does the square return</b>. The subject is singular (not <b>do</b>), the habit is present (not <b>did</b>), and <b>has</b> would need a past participle."},{"id":"gv-ch-32-6","level":"ch","focus":"word-choice","q":"Reviewers described the resort's manager as ______, brushing aside complaints about the flooded rooms with a shrug and a joke.","options":["impartial","disinterested","indifferent","unbiased"],"correct":2,"answer":"indifferent","vi":"Người đánh giá mô tả quản lý khu nghỉ dưỡng là kẻ thờ ơ, gạt phăng những lời phàn nàn về các phòng bị ngập bằng cái nhún vai và một câu đùa.","explanation":"<b>Indifferent</b> = not caring at all, which matches the shrug. <b>Impartial</b>, <b>unbiased</b> and <b>disinterested</b> all mean fair and not favouring either side, a quality, not a fault."},{"id":"gv-ch-32-7","level":"ch","focus":"subjunctive","q":"The tribunal recommended that the operator ______ every guide in emergency first aid before the trekking season resumes.","options":["trains","train","trained","would train"],"correct":1,"answer":"train","vi":"Hội đồng xét xử khuyến nghị nhà điều hành đào tạo sơ cứu khẩn cấp cho mọi hướng dẫn viên trước khi mùa leo núi bắt đầu lại.","explanation":"After <b>recommend / suggest / insist that</b> the verb takes the base-form subjunctive: <b>that the operator train</b>. Neither <b>-s</b>, past tense nor <b>would</b> belongs in this clause."},{"id":"gv-ch-32-8","level":"ch","focus":"idiom","q":"Scholars who explain the missing layer by an earthquake that no chronicle records are merely ______, the reviewer argued.","options":["splitting hairs","beating about the bush","sitting on the fence","clutching at straws"],"correct":3,"answer":"clutching at straws","vi":"Những học giả giải thích tầng địa chất bị thiếu bằng một trận động đất mà không biên niên sử nào ghi lại chỉ đang bám víu vào hy vọng mong manh, nhà phê bình lập luận.","explanation":"<b>Clutch at straws</b> = rely on a hopeless explanation because nothing better is available. <b>Split hairs</b> = argue over tiny details, <b>beat about the bush</b> = avoid the point, <b>sit on the fence</b> = refuse to take sides."},{"id":"gv-ch-32-9","level":"ch","focus":"double-blank","q":"Reluctant to ______ corners on safety, the operator insisted that every raft ______ inspected before the river reopened to tourists.","options":["clip / be","cut / be","cut / to be","trim / being"],"correct":1,"answer":"cut / be","vi":"Không muốn làm ẩu về an toàn, nhà điều hành yêu cầu mọi chiếc bè phải được kiểm tra trước khi con sông mở cửa lại cho du khách.","explanation":"The idiom is <b>cut corners</b> = do something cheaply and carelessly; <b>clip</b> and <b>trim</b> do not form it. <b>Insisted that</b> takes the base-form subjunctive <b>be inspected</b>, not <b>to be</b> or <b>being</b>."},{"id":"gv-ch-32-10","level":"ch","focus":"linking","q":"______ the lure of overseas travel, most trips taken in the region are still to places within three hours' drive of home.","options":["Notwithstanding","Nevertheless","Whereas","Albeit"],"correct":0,"answer":"Notwithstanding","vi":"Bất chấp sức hút của du lịch nước ngoài, phần lớn các chuyến đi trong khu vực vẫn là tới những nơi cách nhà không quá ba giờ lái xe.","explanation":"<b>Notwithstanding</b> is a preposition (= despite) and can be followed by a noun phrase. <b>Nevertheless</b> is an adverb, <b>whereas</b> needs a full clause, and <b>albeit</b> introduces a reduced clause or adjective, not a noun."},{"id":"gv-ch-32-11","level":"ch","focus":"word-choice","q":"The dig director was ______ to a fault, insisting that every shard be photographed in place before anyone lifted it.","options":["unscrupulous","sceptical","secretive","scrupulous"],"correct":3,"answer":"scrupulous","vi":"Người chỉ đạo khai quật cẩn trọng đến mức thái quá, yêu cầu mọi mảnh gốm phải được chụp ảnh tại chỗ trước khi ai đó nhấc lên.","explanation":"<b>Scrupulous</b> = extremely careful and exact, which the photographing rule illustrates. <b>Unscrupulous</b> is the opposite (without morals), <b>sceptical</b> = doubting, <b>secretive</b> = hiding things."},{"id":"gv-ch-32-12","level":"ch","focus":"modal","q":"The pottery ______ locally, since its clay contains minerals found nowhere in the valley.","options":["needn't have been made","mustn't have been made","can't have been made","shouldn't have been made"],"correct":2,"answer":"can't have been made","vi":"Số gốm này không thể được làm tại địa phương, vì đất sét của nó chứa những khoáng chất không hề có trong thung lũng.","explanation":"<b>Can't have + past participle</b> expresses a confident deduction that something was impossible. <b>Needn't have</b> = it was unnecessary, <b>shouldn't have</b> = it was wrong, and <b>mustn't have</b> is not used for deduction."},{"id":"gv-ch-32-13","level":"ch","focus":"phrasal-verb","q":"The traveller's timeline simply does not ______: she claims to have crossed the border twice in a single afternoon.","options":["add on","add up","add in","sum up"],"correct":1,"answer":"add up","vi":"Mốc thời gian của nữ du khách đơn giản là không hợp lý: cô ta khai đã qua biên giới hai lần chỉ trong một buổi chiều.","explanation":"<b>Add up</b> (intransitive) = make sense, be consistent. <b>Add on</b> and <b>add in</b> mean include something extra, and <b>sum up</b> = summarise."},{"id":"gv-ch-32-14","level":"ch","focus":"collocation","q":"The hoard of foreign coins ______ new light on trade routes that no written source ever mentions.","options":["sheds","pours","spreads","spills"],"correct":0,"answer":"sheds","vi":"Kho tiền xu nước ngoài đã làm sáng tỏ thêm những tuyến thương mại mà không tài liệu thành văn nào từng nhắc tới.","explanation":"The fixed collocation is <b>shed light on</b> = make something clearer. <b>Pour</b>, <b>spread</b> and <b>spill</b> do not combine with <b>light on</b> in this sense."},{"id":"gv-ch-32-15","level":"ch","focus":"idiom","q":"Tension over overcrowding on the island finally ______ last August, when residents blockaded the ferry terminal.","options":["came to light","came to grief","came to a head","came to nothing"],"correct":2,"answer":"came to a head","vi":"Căng thẳng về tình trạng quá tải trên đảo cuối cùng đã lên đến đỉnh điểm vào tháng Tám năm ngoái, khi cư dân phong toả bến phà.","explanation":"<b>Come to a head</b> = reach a crisis point demanding action. <b>Come to light</b> = become known, <b>come to grief</b> = fail or have an accident, <b>come to nothing</b> = produce no result."},{"id":"gv-ch-32-16","level":"ch","focus":"participle","q":"______ twice about the unstable slope, the mining company nevertheless pressed ahead with blasting directly beneath the village.","options":["Having warned","Warning","Being warned","Having been warned"],"correct":3,"answer":"Having been warned","vi":"Dù đã hai lần bị cảnh báo về sườn dốc không ổn định, công ty khai mỏ vẫn tiếp tục cho nổ mìn ngay bên dưới ngôi làng.","explanation":"The company received the warnings, and it did so before it pressed ahead, so the perfect passive participle <b>Having been warned</b> is needed. <b>Having warned</b> and <b>Warning</b> would make the company give the warning, and <b>Being warned</b> does not show the warnings came first."},{"id":"gv-ch-32-17","level":"ch","focus":"word-choice","q":"Psychologists find that ______ colleagues, who voice the objections others keep to themselves, are often valued more than they are liked.","options":["outspoken","outstanding","outgoing","outlandish"],"correct":0,"answer":"outspoken","vi":"Các nhà tâm lý học nhận thấy những đồng nghiệp thẳng thắn, người nói ra những phản đối mà người khác giữ trong lòng, thường được coi trọng hơn là được yêu mến.","explanation":"<b>Outspoken</b> = saying frankly what you think, which the relative clause defines. <b>Outstanding</b> = excellent, <b>outgoing</b> = sociable, <b>outlandish</b> = bizarre."},{"id":"gv-ch-32-18","level":"ch","focus":"subjunctive","q":"It is high time the ministry ______ how many visitors the caves can safely absorb in a day.","options":["decides","decided","decide","will decide"],"correct":1,"answer":"decided","vi":"Đã đến lúc bộ phải quyết định các hang động có thể tiếp nhận an toàn bao nhiêu du khách mỗi ngày.","explanation":"<b>It is high time + past subjunctive</b>: the past form <b>decided</b> refers to the present and shows the action is overdue. Present, base form and <b>will</b> are all wrong after <b>high time</b>."},{"id":"gv-ch-32-19","level":"ch","focus":"gerund-infinitive","q":"After one bad experience, the group would sooner ______ the night on the bus than trust another roadside hotel.","options":["spending","to spend","spend","spent"],"correct":2,"answer":"spend","vi":"Sau một trải nghiệm tồi tệ, cả nhóm thà qua đêm trên xe còn hơn tin thêm một khách sạn ven đường nào nữa.","explanation":"<b>Would sooner / would rather</b> is followed by the bare infinitive: <b>would sooner spend</b>. The <b>-ing</b>, <b>to</b> and past forms are all wrong here."},{"id":"gv-ch-32-20","level":"ch","focus":"article-quantifier","q":"______ evidence survives of the ancient harbour suggests that it silted up within a single century.","options":["The few","A little","Little of","What little"],"correct":3,"answer":"What little","vi":"Chút ít bằng chứng còn sót lại về thương cảng cổ cho thấy nó đã bị bồi lấp chỉ trong vòng một thế kỷ.","explanation":"<b>What little evidence survives</b> = the small amount that survives, and the whole phrase is the subject of <b>suggests</b>. <b>Evidence</b> is uncountable (not <b>the few</b>), <b>a little evidence survives</b> leaves <b>suggests</b> without a subject, and <b>little of</b> needs <b>the</b>."},{"id":"gv-ch-32-21","level":"ch","focus":"idiom","q":"Guides will cheerfully embellish a castle's ghost story, but most ______ inventing a massacre that never took place.","options":["draw the line at","draw a veil over","draw a bead on","draw a blank on"],"correct":0,"answer":"draw the line at","vi":"Hướng dẫn viên sẵn sàng thêu dệt chuyện ma ở lâu đài, nhưng phần lớn dứt khoát không bịa ra một vụ thảm sát chưa từng xảy ra.","explanation":"<b>Draw the line at</b> = refuse to go as far as something. <b>Draw a veil over</b> = keep something quiet, <b>draw a bead on</b> = aim at, <b>draw a blank</b> = fail to find or remember."},{"id":"gv-ch-32-22","level":"ch","focus":"inversion","q":"______ the volunteer divers who map the reef every spring, nobody would know how quickly the coral is disappearing.","options":["Had it not been for","Should it not be for","Were it not for","Were it not"],"correct":2,"answer":"Were it not for","vi":"Nếu không có những thợ lặn tình nguyện lập bản đồ rạn san hô mỗi mùa xuân, sẽ chẳng ai biết san hô đang biến mất nhanh đến mức nào.","explanation":"<b>Were it not for + noun</b> is the inverted form of <b>If it were not for</b>, and the present result <b>nobody would know</b> shows a present unreal condition. <b>Had it not been for</b> pairs with a past result (<b>would have</b>), <b>Should it not be for</b> is not an English pattern, and <b>Were it not</b> lacks the <b>for</b> that the noun requires."},{"id":"gv-ch-32-23","level":"ch","focus":"double-blank","q":"Later digs ______ her hunch: a second gateway was found exactly ______ she had predicted it would be.","options":["bore up / where","bore out / where","bore out / which","bore with / that"],"correct":1,"answer":"bore out / where","vi":"Những đợt khai quật sau đó đã chứng thực linh cảm của bà: cổng thứ hai được tìm thấy đúng nơi bà đã dự đoán.","explanation":"<b>Bear out</b> = confirm, support (a theory or claim); <b>bear up</b> = stay strong, <b>bear with</b> = be patient with. The second blank needs the place word <b>where</b>, not <b>which</b> or <b>that</b>."},{"id":"gv-ch-32-24","level":"ch","focus":"word-choice","q":"The chronicle portrays the emperor as a ______ ruler who taxed his provinces into ruin to pay for a single palace.","options":["proficient","profound","prolific","profligate"],"correct":3,"answer":"profligate","vi":"Biên niên sử khắc hoạ vị hoàng đế như một kẻ hoang phí, đánh thuế các tỉnh đến kiệt quệ chỉ để xây một cung điện.","explanation":"<b>Profligate</b> = recklessly wasteful with money, exactly what the palace shows. <b>Proficient</b> = skilled, <b>profound</b> = deep, <b>prolific</b> = producing a lot."},{"id":"gv-ch-32-25","level":"ch","focus":"collocation","q":"Although they hold no formal office, the island's fishing cooperatives still ______ considerable influence over how the marine reserve is policed.","options":["brandish","wield","flex","swing"],"correct":1,"answer":"wield","vi":"Dù không nắm giữ chức vụ chính thức nào, các hợp tác xã ngư dân trên đảo vẫn có ảnh hưởng đáng kể tới cách khu bảo tồn biển được giám sát.","explanation":"The fixed collocation is <b>wield influence / power</b>. <b>Brandish</b> goes with a weapon, <b>flex</b> with muscles, and <b>swing</b> with a bat or an axe; none of them takes <b>influence</b>."},{"id":"gv-ch-33-1","level":"ch","focus":"tense","q":"By the end of next year the offshore wind farm ______ power to the island for a full decade.","options":["will supply","will have been supplying","has supplied","will be supplying"],"correct":1,"answer":"will have been supplying","vi":"Đến cuối năm sau, trang trại điện gió ngoài khơi sẽ cung cấp điện cho hòn đảo được tròn một thập kỷ.","explanation":"<b>By the end of next year</b> + a duration (<b>for a decade</b>) describes an action continuing up to a point in the future, so the future perfect continuous <b>will have been supplying</b> is needed; the other forms cannot carry <b>for a decade</b> up to that deadline."},{"id":"gv-ch-33-2","level":"ch","focus":"word-choice","q":"The novelist's leukaemia went into ______ after a year of treatment, giving her time to finish the final volume of the trilogy.","options":["remission","relapse","recession","regression"],"correct":0,"answer":"remission","vi":"Bệnh bạch cầu của nữ tiểu thuyết gia đã thuyên giảm sau một năm điều trị, cho bà thời gian hoàn thành tập cuối của bộ ba tác phẩm.","explanation":"A disease that stops getting worse or disappears for a time goes into <b>remission</b>. A <b>relapse</b> is the return of an illness, a <b>recession</b> is an economic decline, and <b>regression</b> is a return to an earlier, less developed state."},{"id":"gv-ch-33-3","level":"ch","focus":"idiom","q":"The regulator ______ badly when it approved the gas pipeline without commissioning a single environmental survey.","options":["kept the ball rolling","was on the ball","dropped the ball","played ball"],"correct":2,"answer":"dropped the ball","vi":"Cơ quan quản lý đã sai sót nghiêm trọng khi phê duyệt đường ống dẫn khí mà không hề yêu cầu một cuộc khảo sát môi trường nào.","explanation":"To <b>drop the ball</b> is to fail to do something you are responsible for. <b>Keep the ball rolling</b> means keep an activity going, <b>be on the ball</b> means be alert and competent, and <b>play ball</b> means cooperate."},{"id":"gv-ch-33-4","level":"ch","focus":"collocation","q":"The city council has finally ______ approval for a second bridge across the estuary.","options":["allowed","permitted","admitted","granted"],"correct":3,"answer":"granted","vi":"Hội đồng thành phố cuối cùng đã cấp phép xây cây cầu thứ hai bắc qua cửa sông.","explanation":"The fixed collocation is <b>grant approval</b> (also grant permission, grant a licence). <b>Allow</b> and <b>permit</b> take the action itself, not the noun <b>approval</b>, and <b>admit</b> means confess or let in."},{"id":"gv-ch-33-5","level":"ch","focus":"phrasal-verb","q":"The switch to rooftop solar has ______ a sharp fall in electricity bills for rural households.","options":["brought about","brought up","brought down","brought off"],"correct":0,"answer":"brought about","vi":"Việc chuyển sang điện mặt trời áp mái đã tạo ra sự sụt giảm mạnh trong hóa đơn tiền điện của các hộ gia đình nông thôn.","explanation":"<b>Bring about</b> means cause something to happen. <b>Bring up</b> is to raise a topic or a child, <b>bring down</b> is to reduce or topple (you bring down bills, not a fall), and <b>bring off</b> is to succeed in doing something difficult."},{"id":"gv-ch-33-6","level":"ch","focus":"modal","q":"The blackout ______ have been caused by the storm, since the transmission lines went down two hours before it reached the coast.","options":["must","can't","might","should"],"correct":1,"answer":"can't","vi":"Vụ mất điện không thể do cơn bão gây ra, vì các đường dây truyền tải đã đổ hai tiếng trước khi bão vào đến bờ biển.","explanation":"<b>Can't have been</b> expresses a confident deduction that something was impossible in the past; the timing rules the storm out. <b>Must have</b> and <b>might have</b> claim the storm was a likely or possible cause, and <b>should have</b> expresses what ought to have happened."},{"id":"gv-ch-33-7","level":"ch","focus":"word-choice","q":"A persistent cough is often the first ______ of the lung disease that miners in the coalfield develop.","options":["syndrome","diagnosis","symptom","prognosis"],"correct":2,"answer":"symptom","vi":"Ho dai dẳng thường là triệu chứng đầu tiên của căn bệnh phổi mà các thợ mỏ ở vùng than mắc phải.","explanation":"A <b>symptom</b> is a sign of illness felt by the patient. A <b>syndrome</b> is a whole group of symptoms forming a condition, a <b>diagnosis</b> is the doctor's identification of the disease, and a <b>prognosis</b> is the forecast of how it will develop."},{"id":"gv-ch-33-8","level":"ch","focus":"inversion","q":"______ must a reporter reveal the identity of a confidential source, even when the police demand it.","options":["In any case","At all costs","On no account","Under any circumstances"],"correct":2,"answer":"On no account","vi":"Trong bất kỳ trường hợp nào, phóng viên cũng không được tiết lộ danh tính của nguồn tin bí mật, ngay cả khi cảnh sát yêu cầu.","explanation":"<b>On no account</b> (= never, for no reason) is a negative adverbial that opens the sentence and forces the inversion <b>must a reporter reveal</b>. <b>In any case</b>, <b>At all costs</b> and <b>Under any circumstances</b> are not negative, so they cannot trigger an inverted verb; <b>Under any circumstances</b> would need <b>no</b> instead of <b>any</b>."},{"id":"gv-ch-33-9","level":"ch","focus":"idiom","q":"Having inflated the magazine's circulation figures for years, the publisher finally had to ______ and answer for the fraud in court.","options":["face the music","call the tune","change his tune","blow his own trumpet"],"correct":0,"answer":"face the music","vi":"Sau nhiều năm thổi phồng số lượng phát hành của tạp chí, nhà xuất bản cuối cùng phải chịu trách nhiệm và trả lời về vụ gian lận trước tòa.","explanation":"To <b>face the music</b> is to accept punishment or criticism for what you have done. <b>Call the tune</b> means be in control, <b>change your tune</b> means change your opinion, and <b>blow your own trumpet</b> means boast."},{"id":"gv-ch-33-10","level":"ch","focus":"double-blank","q":"Unless the state broadcaster gets its ______ together, advertisers will simply take their money ______.","options":["show / away","act / elsewhere","house / out","game / off"],"correct":1,"answer":"act / elsewhere","vi":"Nếu đài truyền hình nhà nước không chấn chỉnh lại cách làm việc, các nhà quảng cáo sẽ đơn giản mang tiền đi nơi khác.","explanation":"<b>Get your act together</b> means organise yourself and start doing things properly, and customers who leave <b>take their money elsewhere</b>. <b>Get your house in order</b> and <b>get the show on the road</b> are different idioms, and <b>away / out / off</b> do not complete the second phrase."},{"id":"gv-ch-33-11","level":"ch","focus":"relative","q":"The engineer ______ the tidal barrage was designed died before its first turbine ever turned.","options":["who","whose","by whom","whom"],"correct":2,"answer":"by whom","vi":"Người kỹ sư đã thiết kế đập thủy triều ấy qua đời trước khi tua-bin đầu tiên của nó quay.","explanation":"The barrage <b>was designed by</b> the engineer, so the passive agent needs <b>by whom</b>. <b>Who</b> and <b>whom</b> leave the preposition missing, and <b>whose</b> would need a noun after it."},{"id":"gv-ch-33-12","level":"ch","focus":"word-choice","q":"The newspaper's health desk was the first to report an ______ of cholera in the flooded villages below the dam.","options":["outburst","outcome","outset","outbreak"],"correct":3,"answer":"outbreak","vi":"Ban y tế của tờ báo là nơi đầu tiên đưa tin về một đợt bùng phát dịch tả ở các làng bị ngập bên dưới con đập.","explanation":"The sudden start of a disease, war or violence is an <b>outbreak</b>. An <b>outburst</b> is a sudden show of emotion, an <b>outcome</b> is a result, and the <b>outset</b> is the beginning of an activity."},{"id":"gv-ch-33-13","level":"ch","focus":"collocation","q":"The national grid struggles to meet ______ demand on the hottest afternoons of the year, when every air conditioner is running.","options":["peak","top","summit","climax"],"correct":0,"answer":"peak","vi":"Lưới điện quốc gia chật vật đáp ứng nhu cầu cao điểm vào những buổi chiều nóng nhất trong năm, khi mọi máy điều hòa đều chạy.","explanation":"<b>Peak demand</b> (like peak hours, peak season) is the fixed collocation for the highest level of use. <b>Top</b>, <b>summit</b> and <b>climax</b> are not used before <b>demand</b>."},{"id":"gv-ch-33-14","level":"ch","focus":"subjunctive","q":"The station keeps a diesel generator on standby lest the wind farm ______ to deliver on a calm day.","options":["fails","fail","failed","would fail"],"correct":1,"answer":"fail","vi":"Nhà máy luôn để sẵn một máy phát diesel đề phòng trường hợp trang trại điện gió không phát được điện vào ngày lặng gió.","explanation":"After <b>lest</b> (= for fear that) the verb takes the present subjunctive, the base form <b>fail</b> with no -s, whatever the subject; the indicative and conditional forms are not used."},{"id":"gv-ch-33-15","level":"ch","focus":"idiom","q":"For three years the engineers' warnings that the spillway was cracking ______, until the flood of 2019 proved them right.","options":["turned a deaf ear","were all ears","fell on deaf ears","played it by ear"],"correct":2,"answer":"fell on deaf ears","vi":"Suốt ba năm, những cảnh báo của các kỹ sư rằng đập tràn đang nứt đều bị bỏ ngoài tai, cho đến khi trận lũ năm 2019 chứng minh họ đúng.","explanation":"Advice or warnings that are ignored <b>fall on deaf ears</b>. A person <b>turns a deaf ear</b> to something, <b>is all ears</b> when listening eagerly, or <b>plays it by ear</b> when improvising; none of these fits <b>warnings</b> as the subject."},{"id":"gv-ch-33-16","level":"ch","focus":"phrasal-verb","q":"The editorial ______ an independent inquiry into the grid failure, arguing that the ministry could not investigate itself.","options":["called off","called up","called out","called for"],"correct":3,"answer":"called for","vi":"Bài xã luận kêu gọi một cuộc điều tra độc lập về sự cố lưới điện, lập luận rằng bộ không thể tự điều tra chính mình.","explanation":"<b>Call for</b> means publicly demand that something be done. <b>Call off</b> is to cancel, <b>call up</b> is to telephone or summon for military service, and <b>call out</b> is to criticise someone publicly."},{"id":"gv-ch-33-17","level":"ch","focus":"word-choice","q":"The scan revealed a ______ tumour, so the poet cancelled his reading tour to begin chemotherapy at once.","options":["malignant","malicious","malevolent","malign"],"correct":0,"answer":"malignant","vi":"Kết quả chụp cho thấy một khối u ác tính, nên nhà thơ hủy chuyến lưu diễn đọc thơ để bắt đầu hóa trị ngay lập tức.","explanation":"A cancerous tumour is <b>malignant</b> (the opposite of benign). <b>Malicious</b> and <b>malevolent</b> describe people or actions intended to harm, and <b>malign</b> as an adjective means harmful in influence, not a medical term."},{"id":"gv-ch-33-18","level":"ch","focus":"linking","q":"The pipeline was completed on schedule; ______, it ended up costing nearly twice the original estimate.","options":["whereas","however","despite","although"],"correct":1,"answer":"however","vi":"Đường ống được hoàn thành đúng tiến độ; tuy nhiên, chi phí cuối cùng gần gấp đôi dự toán ban đầu.","explanation":"Between a semicolon and a comma only the adverb <b>however</b> can stand alone. <b>Whereas</b> and <b>although</b> are conjunctions that must introduce a clause joined directly to the other, and <b>despite</b> needs a noun or -ing form."},{"id":"gv-ch-33-19","level":"ch","focus":"participle","q":"______ entirely from recycled glass, the installation changes colour as the sun moves across the gallery.","options":["Making","Having made","Made","To make"],"correct":2,"answer":"Made","vi":"Được làm hoàn toàn từ thủy tinh tái chế, tác phẩm sắp đặt đổi màu khi mặt trời di chuyển ngang phòng trưng bày.","explanation":"The installation <b>is made</b> from glass, so the reduced clause needs the passive past participle <b>Made</b>. <b>Making</b> and <b>Having made</b> would mean the installation itself made something, and <b>To make</b> expresses purpose."},{"id":"gv-ch-33-20","level":"ch","focus":"idiom","q":"Residents ______ to stop the coal-fired plant being built on the edge of the wetland, and in the end they won.","options":["fought shy","fought like cat and dog","picked a fight","fought tooth and nail"],"correct":3,"answer":"fought tooth and nail","vi":"Người dân đã đấu tranh quyết liệt để ngăn nhà máy nhiệt điện than được xây ở rìa vùng đất ngập nước, và cuối cùng họ đã thắng.","explanation":"To <b>fight tooth and nail</b> is to fight fiercely with every means available. <b>Fight shy of</b> means avoid something, <b>fight like cat and dog</b> describes two people quarrelling constantly, and <b>pick a fight</b> means deliberately start a quarrel."},{"id":"gv-ch-33-21","level":"ch","focus":"double-blank","q":"The new arts centre ______ for audiences ______ tastes range from opera to hip-hop.","options":["caters / whose","calls / who","provides / which","serves / whom"],"correct":0,"answer":"caters / whose","vi":"Trung tâm nghệ thuật mới phục vụ những khán giả có gu thưởng thức trải dài từ opera đến hip-hop.","explanation":"<b>Cater for</b> means provide what a particular group wants, and the possessive relative <b>whose</b> links <b>audiences</b> to <b>tastes</b>. <b>Call for</b> means demand, <b>provide for</b> is to support financially, <b>serve</b> takes no <b>for</b>, and <b>who / which / whom</b> cannot show possession."},{"id":"gv-ch-33-22","level":"ch","focus":"conditional","q":"______ the emergency generators, the newsroom would have gone dark in the middle of the election broadcast.","options":["If it hadn't been","Had it not been for","Were it not for","Unless there were"],"correct":1,"answer":"Had it not been for","vi":"Nếu không nhờ các máy phát điện dự phòng, phòng tin đã chìm trong bóng tối ngay giữa buổi phát sóng bầu cử.","explanation":"The main clause <b>would have gone</b> is a past unreal result, so the condition must be the inverted third conditional <b>Had it not been for</b>. <b>If it hadn't been</b> lacks the essential <b>for</b>, <b>Were it not for</b> refers to the present, and <b>Unless there were</b> is a present unreal form."},{"id":"gv-ch-33-23","level":"ch","focus":"word-choice","q":"The condition is ______, passed from parent to child through a faulty gene, rather than caught from anyone the patient has met.","options":["contagious","congenital","hereditary","infectious"],"correct":2,"answer":"hereditary","vi":"Căn bệnh này mang tính di truyền, truyền từ cha mẹ sang con qua một gen lỗi, chứ không phải lây từ bất kỳ ai bệnh nhân từng gặp.","explanation":"A disease passed down through the genes is <b>hereditary</b>. <b>Contagious</b> and <b>infectious</b> diseases are caught from other people, and <b>congenital</b> means present from birth without saying it was inherited."},{"id":"gv-ch-33-24","level":"ch","focus":"gerund-infinitive","q":"The volcanologist says she will never ______ the lava fountain burst through the crater floor on her first field trip to Iceland.","options":["forget to see","forget seeing","forget to have seen","forget being seen"],"correct":1,"answer":"forget seeing","vi":"Nhà nghiên cứu núi lửa nói rằng cô sẽ không bao giờ quên cảnh cột dung nham phun trào qua đáy miệng núi lửa trong chuyến thực địa đầu tiên ở Iceland.","explanation":"<b>Forget + -ing</b> refers to the memory of something that already happened: she will never <b>forget seeing</b> the eruption. <b>Forget to see</b> would mean fail to see something she was supposed to see, and the perfect infinitive and the passive gerund do not follow <b>forget</b> in this sense."},{"id":"gv-ch-33-25","level":"ch","focus":"collocation","q":"Years of rotating night shifts at the refinery ______ a heavy toll on the workers' health.","options":["took","paid","made","had"],"correct":0,"answer":"took","vi":"Nhiều năm làm ca đêm luân phiên ở nhà máy lọc dầu đã gây tổn hại nặng nề đến sức khỏe của công nhân.","explanation":"The collocation for causing serious harm or loss is <b>take a toll on</b>. You <b>pay</b> a toll only literally at a toll gate, and <b>make</b> and <b>have</b> do not combine with <b>toll</b>."},{"id":"gv-ch-34-1","level":"ch","focus":"word-choice","q":"Players who fail to ______ by the anti-doping code face an automatic two-year suspension.","options":["observe","abide","obey","conform"],"correct":1,"answer":"abide","vi":"Những vận động viên không tuân thủ bộ quy tắc chống doping sẽ bị treo giò tự động hai năm.","explanation":"Only <b>abide</b> takes the preposition <b>by</b> (abide by a rule); observe and obey take a direct object, and conform is followed by to."},{"id":"gv-ch-34-2","level":"ch","focus":"idiom","q":"The minister's proposal to ban foreign words from state broadcasts ______ in parliament, with members of her own party voting against it.","options":["went down in flames","went through the roof","went off the rails","went under the hammer"],"correct":0,"answer":"went down in flames","vi":"Đề xuất cấm từ ngoại lai trên đài phát thanh nhà nước của bà bộ trưởng đã thất bại thảm hại ở quốc hội, khi chính các nghị sĩ đảng bà bỏ phiếu chống.","explanation":"<b>Go down in flames</b> = fail spectacularly and publicly. Go through the roof is for prices or tempers, go off the rails is to lose control, and go under the hammer is to be sold at auction."},{"id":"gv-ch-34-3","level":"ch","focus":"passive","q":"The bill ______ by the president twice before a revised version finally became law.","options":["was vetoing","had vetoed","had been vetoed","has been vetoed"],"correct":2,"answer":"had been vetoed","vi":"Dự luật đã bị tổng thống phủ quyết hai lần trước khi phiên bản sửa đổi cuối cùng trở thành luật.","explanation":"The bill receives the action, so the passive is needed, and the vetoes happened <b>before</b> a past event (became law): past perfect passive <b>had been vetoed</b>."},{"id":"gv-ch-34-4","level":"ch","focus":"collocation","q":"Having promised deep tax cuts, the opposition cruised to a ______ victory in the general election.","options":["avalanche","earthquake","mudslide","landslide"],"correct":3,"answer":"landslide","vi":"Sau khi hứa cắt giảm mạnh thuế, phe đối lập đã giành chiến thắng áp đảo trong cuộc tổng tuyển cử.","explanation":"A <b>landslide victory</b> is the fixed collocation for winning by a huge margin; the other natural disasters never pair with victory."},{"id":"gv-ch-34-5","level":"ch","focus":"phrasal-verb","q":"Campaigners who try to replace legal jargon with plain English soon ______ centuries of professional tradition.","options":["come round to","come up against","come in for","come down with"],"correct":1,"answer":"come up against","vi":"Những người vận động thay thế thuật ngữ pháp lý bằng tiếng Anh giản dị sớm vấp phải truyền thống nghề nghiệp hàng thế kỷ.","explanation":"<b>Come up against</b> = meet an obstacle or opposition. Come round to = gradually accept, come in for = receive (criticism), come down with = fall ill with."},{"id":"gv-ch-34-6","level":"ch","focus":"modal","q":"The assistant referee ______ his flag so hastily: the replay showed the striker was a yard onside.","options":["can't have raised","mustn't have raised","needn't have raised","might not have raised"],"correct":2,"answer":"needn't have raised","vi":"Trợ lý trọng tài lẽ ra không cần phất cờ vội vàng đến thế: pha quay chậm cho thấy tiền đạo đã đứng trên việt vị cả mét.","explanation":"<b>Needn't have + past participle</b> = he did it, but it was unnecessary. Can't have would deny that he raised it at all, and mustn't have is not used for past deduction in British English."},{"id":"gv-ch-34-7","level":"ch","focus":"word-choice","q":"To encourage younger competitors, the federation agreed to ______ the entry fee for athletes under eighteen.","options":["waive","revoke","repeal","annul"],"correct":0,"answer":"waive","vi":"Để khuyến khích các vận động viên trẻ, liên đoàn đồng ý miễn lệ phí đăng ký cho những người dưới mười tám tuổi.","explanation":"<b>Waive</b> = choose not to demand a fee or right you are entitled to. You revoke a licence, repeal a law and annul a marriage or contract."},{"id":"gv-ch-34-8","level":"ch","focus":"inversion","q":"______ has a scientific paper attracted so much public attention as the study linking teenagers' screen time to loss of sleep.","options":["Not until","Rarely","Only when","Little"],"correct":1,"answer":"Rarely","vi":"Hiếm khi một bài báo khoa học lại thu hút nhiều sự chú ý của công chúng đến thế như nghiên cứu liên hệ thời gian dùng màn hình của thanh thiếu niên với tình trạng mất ngủ.","explanation":"A fronted negative adverb such as <b>Rarely</b> forces subject–verb inversion (Rarely has a paper attracted …). Not until and only when need a time clause or noun before the inverted part, and little inverts only with verbs like know, realise or suspect."},{"id":"gv-ch-34-9","level":"ch","focus":"idiom","q":"Rather than argue with the coaching staff, the young striker decided to ______ and accept his new role on the wing.","options":["go by the book","go with the flow","go against the grain","go the extra mile"],"correct":1,"answer":"go with the flow","vi":"Thay vì tranh cãi với ban huấn luyện, tiền đạo trẻ quyết định thuận theo tình hình và chấp nhận vai trò mới ở biên.","explanation":"<b>Go with the flow</b> = accept what is happening without resisting. Go by the book = follow rules strictly, go against the grain = do the opposite of what is natural, go the extra mile = make extra effort."},{"id":"gv-ch-34-10","level":"ch","focus":"double-blank","q":"Once the chair had ______ with the roll call, the committee ______ straight to the vote.","options":["disposed / preceded","dispensed / preceded","dispensed / proceeded","disposed / proceeded"],"correct":2,"answer":"dispensed / proceeded","vi":"Sau khi chủ tọa bỏ qua thủ tục điểm danh, ủy ban chuyển thẳng sang bỏ phiếu.","explanation":"<b>Dispense with</b> = do without (dispose of = throw away), and <b>proceed to</b> = move on to (precede = come before)."},{"id":"gv-ch-34-11","level":"ch","focus":"word-choice","q":"Anti-corruption laws are only as effective as the authorities' willingness to ______ them.","options":["enforce","enact","ratify","legislate"],"correct":0,"answer":"enforce","vi":"Luật chống tham nhũng chỉ hiệu quả ngang với mức độ sẵn sàng thực thi chúng của nhà chức trách.","explanation":"<b>Enforce</b> = make people obey a law that already exists. Enact and legislate refer to passing a law, and ratify is to formally approve a treaty."},{"id":"gv-ch-34-12","level":"ch","focus":"agreement","q":"Neither the head coach nor the players ______ willing to comment on the leaked dressing-room footage.","options":["was","is","has been","were"],"correct":3,"answer":"were","vi":"Cả huấn luyện viên trưởng lẫn các cầu thủ đều không muốn bình luận về đoạn phim phòng thay đồ bị rò rỉ.","explanation":"With <b>neither … nor</b> the verb agrees with the nearer subject, the plural <b>players</b>, so <b>were</b>."},{"id":"gv-ch-34-13","level":"ch","focus":"collocation","q":"The new commissioner has promised ______ reforms of the way doping cases are investigated.","options":["brushing","sweeping","wiping","mopping"],"correct":1,"answer":"sweeping","vi":"Tân cao ủy hứa hẹn những cải cách sâu rộng về cách điều tra các vụ doping.","explanation":"<b>Sweeping reforms/changes</b> = wide-ranging ones; brushing, wiping and mopping are cleaning verbs with no such figurative use."},{"id":"gv-ch-34-14","level":"ch","focus":"phrasal-verb","q":"It only ______ the commentators afterwards that the referee had misapplied the offside rule.","options":["dwelt on","hit on","dawned on","touched on"],"correct":2,"answer":"dawned on","vi":"Mãi sau đó các bình luận viên mới nhận ra rằng trọng tài đã áp dụng sai luật việt vị.","explanation":"<b>It dawns on someone that</b> = they slowly realise. Dwell on = keep thinking about, hit on = suddenly think of, touch on = mention briefly."},{"id":"gv-ch-34-15","level":"ch","focus":"linking","q":"______ the referee's lengthy explanation, the home fans remained convinced they had been robbed.","options":["Notwithstanding","Nevertheless","Although","Whereas"],"correct":0,"answer":"Notwithstanding","vi":"Bất chấp lời giải thích dài dòng của trọng tài, cổ động viên chủ nhà vẫn tin chắc họ đã bị cướp mất chiến thắng.","explanation":"A noun phrase follows, so a preposition is needed: <b>notwithstanding</b> = despite. Although and whereas introduce clauses, and nevertheless is an adverb that cannot govern a noun."},{"id":"gv-ch-34-16","level":"ch","focus":"idiom","q":"With two minutes left and the champions a goal down, their unbeaten record was ______.","options":["hanging in the air","hanging out to dry","hanging on every word","hanging by a thread"],"correct":3,"answer":"hanging by a thread","vi":"Còn hai phút, đội đương kim vô địch đang bị dẫn một bàn, thành tích bất bại của họ đang treo trên sợi tóc.","explanation":"<b>Hang by a thread</b> = be in a very precarious position. Hanging in the air = left unresolved, hung out to dry = abandoned to take the blame, hanging on every word = listening eagerly."},{"id":"gv-ch-34-17","level":"ch","focus":"subjunctive","q":"It is high time the federation ______ its outdated rules on which nationality an athlete may represent.","options":["revise","revised","revises","has revised"],"correct":1,"answer":"revised","vi":"Đã đến lúc liên đoàn phải sửa đổi các quy định lỗi thời về việc vận động viên được đại diện cho quốc tịch nào.","explanation":"<b>It is high time</b> is followed by a past-tense form with present meaning: <b>revised</b>."},{"id":"gv-ch-34-18","level":"ch","focus":"word-choice","q":"Broadcasting the interview before the trial would ______ the reporting restrictions imposed by the court.","options":["offend","trespass","contravene","overrule"],"correct":2,"answer":"contravene","vi":"Phát sóng cuộc phỏng vấn trước phiên tòa sẽ vi phạm các hạn chế đưa tin do tòa án áp đặt.","explanation":"<b>Contravene</b> = act against a rule or law, taking a direct object. Offend and trespass need against, and only a higher court can overrule a decision."},{"id":"gv-ch-34-19","level":"ch","focus":"comparison","q":"The more technical the wording of a contract, ______ an ordinary citizen is to understand it.","options":["the less likely","less likely","the least likely","the less likelier"],"correct":0,"answer":"the less likely","vi":"Câu chữ hợp đồng càng chuyên môn thì người dân bình thường càng ít có khả năng hiểu được nó.","explanation":"The double comparative <b>the more …, the less …</b> needs <b>the</b> in both halves; likelier is already comparative, so less likelier is wrong."},{"id":"gv-ch-34-20","level":"ch","focus":"collocation","q":"The club has ______ an appeal against the six-point deduction with the league's independent panel.","options":["placed","put","laid","lodged"],"correct":3,"answer":"lodged","vi":"Câu lạc bộ đã nộp đơn kháng cáo lên hội đồng độc lập của giải đấu phản đối việc bị trừ sáu điểm.","explanation":"<b>Lodge an appeal/complaint</b> is the fixed legal collocation; place, put and lay do not pair with appeal."},{"id":"gv-ch-34-21","level":"ch","focus":"gerund-infinitive","q":"The party leader is reported ______ the coalition offer at a private meeting late last night.","options":["to reject","to have rejected","rejecting","having rejected"],"correct":1,"answer":"to have rejected","vi":"Lãnh đạo đảng được cho là đã bác bỏ đề nghị liên minh tại một cuộc gặp riêng khuya qua.","explanation":"After <b>be reported/said/believed</b> an earlier action takes the perfect infinitive: <b>to have rejected</b>. To reject would describe a present or general action."},{"id":"gv-ch-34-22","level":"ch","focus":"idiom","q":"The press officer ______ fielding calls from reporters once the memo had been leaked.","options":["had her hands tied","had her heart in her mouth","had her hands full","had her feet on the ground"],"correct":2,"answer":"had her hands full","vi":"Nữ cán bộ báo chí bận tối mắt tối mũi trả lời các cuộc gọi từ phóng viên khi bản ghi nhớ bị rò rỉ.","explanation":"<b>Have your hands full</b> = be extremely busy. Have your hands tied = be unable to act, have your heart in your mouth = be very nervous, have your feet on the ground = be sensible."},{"id":"gv-ch-34-23","level":"ch","focus":"participle","q":"______ in plain English rather than legal jargon, the new tenancy agreement can be understood without a lawyer.","options":["Written","Writing","Having written","To write"],"correct":0,"answer":"Written","vi":"Được viết bằng tiếng Anh giản dị thay vì thuật ngữ pháp lý, hợp đồng thuê nhà mới có thể hiểu được mà không cần luật sư.","explanation":"The agreement is written by someone, so the reduced clause is passive: past participle <b>Written</b>. Writing or having written would make the agreement the writer."},{"id":"gv-ch-34-24","level":"ch","focus":"word-choice","q":"The High Court ______ the conviction after new evidence showed the confession had been obtained under duress.","options":["squashed","crushed","smashed","quashed"],"correct":3,"answer":"quashed","vi":"Tòa án Tối cao đã hủy bản án sau khi bằng chứng mới cho thấy lời thú tội được lấy dưới sự cưỡng ép.","explanation":"<b>Quash</b> is the legal verb for officially cancelling a conviction or decision; squash, crush and smash are physical."},{"id":"gv-ch-34-25","level":"ch","focus":"double-blank","q":"Small clubs and wealthy giants alike are ______ the same ______ when it comes to the new salary cap.","options":["on / ship","in / ship","in / boat","on / boat"],"correct":2,"answer":"in / boat","vi":"Các câu lạc bộ nhỏ lẫn các đại gia giàu có đều cùng chung cảnh ngộ khi nói đến mức trần lương mới.","explanation":"<b>In the same boat</b> = in the same difficult situation; the idiom is fixed with in and boat."},{"id":"gv-ch-35-1","level":"ch","focus":"word-choice","q":"Witnesses caught only a ______ glimpse of the getaway driver before the car sped off down the alley.","options":["temporary","interim","fleeting","provisional"],"correct":2,"answer":"fleeting","vi":"Các nhân chứng chỉ thoáng thấy tài xế xe tẩu thoát trong chốc lát trước khi chiếc xe lao vụt xuống con hẻm.","explanation":"<b>Fleeting</b> (lasting a very short moment) is the word that collocates with <i>glimpse</i>; <i>temporary</i>, <i>interim</i> and <i>provisional</i> describe arrangements that will later be replaced, not a moment of seeing."},{"id":"gv-ch-35-2","level":"ch","focus":"idiom","q":"New officers seldom ______ before their second year, so each is paired with a veteran detective until then.","options":["know the ropes","pull the strings","call the shots","hold the fort"],"correct":0,"answer":"know the ropes","vi":"Cảnh sát mới hiếm khi nắm vững công việc trước năm thứ hai, nên mỗi người được ghép cặp với một thám tử kỳ cựu cho đến lúc đó.","explanation":"<b>Know the ropes</b> = understand how a job is done. <i>Pull the strings</i> (control from behind the scenes), <i>call the shots</i> (be in charge) and <i>hold the fort</i> (take charge while others are away) describe power or cover, not familiarity with a job."},{"id":"gv-ch-35-3","level":"ch","focus":"collocation","q":"After three days of deliberation the jury was still unable to ______ a verdict.","options":["arrive","reach","make","come"],"correct":1,"answer":"reach","vi":"Sau ba ngày nghị án, bồi thẩm đoàn vẫn không thể đưa ra được phán quyết.","explanation":"The fixed collocation is <b>reach a verdict</b>. <i>Arrive</i> and <i>come</i> would need <i>at</i> before the noun, and <i>make a verdict</i> is not English."},{"id":"gv-ch-35-4","level":"ch","focus":"modal","q":"The accused ______ the getaway car that night — he was already in police custody.","options":["mustn't have driven","needn't have driven","shouldn't have driven","can't have driven"],"correct":3,"answer":"can't have driven","vi":"Bị cáo không thể nào đã lái chiếc xe tẩu thoát đêm đó — lúc ấy anh ta đã bị cảnh sát tạm giữ rồi.","explanation":"<b>Can't have + past participle</b> expresses certainty that something was impossible in the past. <i>Mustn't have</i> is not used for deduction, <i>needn't have</i> means it was unnecessary, and <i>shouldn't have</i> means it was wrong to do."},{"id":"gv-ch-35-5","level":"ch","focus":"word-choice","q":"The rain was ______ all afternoon, stopping and starting so often that the flood sirens were tested three times.","options":["chronic","intermittent","perennial","interim"],"correct":1,"answer":"intermittent","vi":"Mưa rơi ngắt quãng suốt buổi chiều, ngừng rồi lại rơi thường xuyên đến mức còi báo lũ được thử tới ba lần.","explanation":"<b>Intermittent</b> = stopping and starting at intervals. <i>Chronic</i> describes a long-lasting problem or illness, <i>perennial</i> something that recurs every year, and <i>interim</i> a temporary arrangement."},{"id":"gv-ch-35-6","level":"ch","focus":"inversion","q":"Only after the river had burst its banks twice ______ to fund the dredging work.","options":["the council agreed","the council did agree","did the council agree","had the council agreed"],"correct":2,"answer":"did the council agree","vi":"Chỉ sau khi con sông đã tràn bờ hai lần, hội đồng thành phố mới đồng ý cấp kinh phí nạo vét.","explanation":"A sentence opening with <b>Only after…</b> inverts the main clause: <b>did the council agree</b>. The past perfect belongs in the <i>after</i> clause, not in the inverted main clause."},{"id":"gv-ch-35-7","level":"ch","focus":"phrasal-verb","q":"With no savings to ______, the evicted family spent the winter sleeping in their car.","options":["fall back on","fall behind with","fall in with","fall out with"],"correct":0,"answer":"fall back on","vi":"Không có khoản tiết kiệm nào để dựa vào, gia đình bị đuổi khỏi nhà phải ngủ trong xe suốt mùa đông.","explanation":"<b>Fall back on</b> = use something as a reserve when nothing else is available. <i>Fall behind with</i> (payments), <i>fall in with</i> (a group or a plan) and <i>fall out with</i> (quarrel with) all take different objects."},{"id":"gv-ch-35-8","level":"ch","focus":"double-blank","q":"For decades the old seawall has ______ the rising tide ______ bay, but engineers now doubt it can survive another winter.","options":["held / in","put / to","set / from","kept / at"],"correct":3,"answer":"kept / at","vi":"Suốt hàng chục năm, bức tường chắn sóng cũ đã ngăn được thủy triều dâng, nhưng nay các kỹ sư nghi ngờ nó có thể trụ thêm một mùa đông nữa.","explanation":"The idiom is <b>keep something at bay</b> = prevent something harmful from reaching you. No other verb–preposition pair forms an expression with <i>bay</i>."},{"id":"gv-ch-35-9","level":"ch","focus":"subjunctive","q":"It is high time the city ______ its century-old sewers instead of patching them every monsoon.","options":["replaces","replaced","will replace","has replaced"],"correct":1,"answer":"replaced","vi":"Đã đến lúc thành phố phải thay hệ thống cống trăm năm tuổi thay vì cứ vá víu mỗi mùa mưa.","explanation":"<b>It is high time + past subjunctive</b>: the past form <b>replaced</b> refers to the present and means the action is overdue. Present, future and present-perfect forms are not used after <i>high time</i>."},{"id":"gv-ch-35-10","level":"ch","focus":"word-choice","q":"Warnings of the ______ storm surge sent thousands of residents inland before nightfall.","options":["impending","eventual","forthcoming","subsequent"],"correct":0,"answer":"impending","vi":"Những cảnh báo về đợt nước dâng do bão sắp ập đến khiến hàng nghìn cư dân đổ vào đất liền trước khi trời tối.","explanation":"<b>Impending</b> = about to happen, usually something threatening. <i>Forthcoming</i> is used for scheduled events or publications, <i>eventual</i> means happening at the end of a process, and <i>subsequent</i> means coming after."},{"id":"gv-ch-35-11","level":"ch","focus":"idiom","q":"Coastal towns that ignored the flood warnings ______ that a seawall costs far less than a rebuild.","options":["took a hard line","played hardball","learned the hard way","had a hard time"],"correct":2,"answer":"learned the hard way","vi":"Những thị trấn ven biển phớt lờ cảnh báo lũ đã phải trả giá đắt để hiểu rằng xây tường chắn sóng rẻ hơn nhiều so với xây dựng lại.","explanation":"<b>Learn the hard way</b> = discover something through a painful experience, and it takes a <i>that</i>-clause. <i>Take a hard line</i>, <i>play hardball</i> and <i>have a hard time</i> cannot be followed by <i>that…</i>."},{"id":"gv-ch-35-12","level":"ch","focus":"participle","q":"______ the sheer volume of complaints, the new bus timetable has satisfied almost no one.","options":["Judged from","Judge from","Judging from","Having been judged from"],"correct":2,"answer":"Judging from","vi":"Xét từ số lượng khiếu nại khổng lồ, lịch chạy xe buýt mới hầu như chẳng làm hài lòng ai.","explanation":"<b>Judging from</b> (= if one considers) is a fixed participle phrase whose understood subject is the speaker, who does the judging, so the active -ing form is used. The passive <i>judged</i> / <i>having been judged</i> would make the timetable the thing judged, and the bare <i>judge</i> cannot open a participle clause."},{"id":"gv-ch-35-13","level":"ch","focus":"collocation","q":"The documentary set out to ______ public awareness of the smog choking the capital every winter.","options":["rise","lift","grow","raise"],"correct":3,"answer":"raise","vi":"Bộ phim tài liệu nhằm nâng cao nhận thức của công chúng về màn sương mù ô nhiễm bao trùm thủ đô mỗi mùa đông.","explanation":"The collocation is <b>raise awareness</b>. <i>Rise</i> is intransitive and cannot take an object; <i>lift</i> and <i>grow</i> do not collocate with <i>awareness</i>."},{"id":"gv-ch-35-14","level":"ch","focus":"reported","q":"The housing inspector asked the tenant how long ______ in the damp basement flat.","options":["she had been living","had she been living","she has been living","has she been living"],"correct":0,"answer":"she had been living","vi":"Thanh tra nhà ở hỏi người thuê rằng cô ấy đã sống trong căn hộ tầng hầm ẩm thấp đó bao lâu rồi.","explanation":"A reported question keeps statement word order and shifts the tense back: <b>she had been living</b>. The inverted forms and the present perfect belong to the direct question."},{"id":"gv-ch-35-15","level":"ch","focus":"word-choice","q":"The judge ruled that the two prison terms would run ______ rather than one after the other.","options":["contemporarily","coincidentally","concurrently","instantaneously"],"correct":2,"answer":"concurrently","vi":"Thẩm phán phán quyết rằng hai án tù sẽ được thi hành đồng thời chứ không phải nối tiếp nhau.","explanation":"<b>Concurrently</b> = at the same time, the legal term for sentences served together. <i>Contemporarily</i> refers to the same era, <i>coincidentally</i> means by chance, and <i>instantaneously</i> means immediately."},{"id":"gv-ch-35-16","level":"ch","focus":"idiom","q":"Once the most feared prosecutor in the city, she seems to have ______ — her last three cases collapsed within a week.","options":["lost her head","lost her voice","lost her footing","lost her touch"],"correct":3,"answer":"lost her touch","vi":"Từng là công tố viên đáng sợ nhất thành phố, giờ bà dường như đã mất đi sự sắc bén — ba vụ gần nhất của bà đều đổ vỡ trong vòng một tuần.","explanation":"<b>Lose your touch</b> = no longer have the skill you once had. <i>Lose your head</i> means panic, <i>lose your voice</i> is literal, and <i>lose your footing</i> means slip."},{"id":"gv-ch-35-17","level":"ch","focus":"pronoun","q":"Residents of the tower block rarely speak to ______, even after years on the same floor.","options":["each other's","one another","themselves","the other"],"correct":1,"answer":"one another","vi":"Cư dân tòa chung cư hiếm khi trò chuyện với nhau, dù đã sống cùng tầng nhiều năm.","explanation":"The reciprocal pronoun <b>one another</b> (= each other) is needed. <i>Each other's</i> is possessive, <i>themselves</i> is reflexive, and <i>the other</i> would need a specific second party."},{"id":"gv-ch-35-18","level":"ch","focus":"phrasal-verb","q":"The jury foreman refused to ______ the majority verdict until every doubt had been discussed.","options":["go in for","go down with","go along with","go off with"],"correct":2,"answer":"go along with","vi":"Chủ tịch bồi thẩm đoàn từ chối tán thành phán quyết của đa số cho đến khi mọi nghi vấn đã được thảo luận.","explanation":"<b>Go along with</b> = accept or agree with. <i>Go in for</i> (enjoy, enter a competition), <i>go down with</i> (fall ill with) and <i>go off with</i> (take away, run away with) do not fit a verdict."},{"id":"gv-ch-35-19","level":"ch","focus":"linking","q":"The clinic now opens at six in the morning ______ shift workers can be seen before they start work.","options":["in order to","so as to","in case","so that"],"correct":3,"answer":"so that","vi":"Phòng khám nay mở cửa từ sáu giờ sáng để công nhân làm ca có thể được khám trước khi vào làm.","explanation":"<b>So that</b> introduces a purpose clause with its own subject and verb (<i>shift workers can be seen</i>). <i>In order to</i> and <i>so as to</i> must be followed by a bare infinitive, not a clause, and <i>in case</i> expresses a precaution, not a purpose."},{"id":"gv-ch-35-20","level":"ch","focus":"collocation","q":"Small farmers along the delta will ______ the brunt of the new export tariffs, according to the ministry's own forecast.","options":["bear","carry","hold","stand"],"correct":0,"answer":"bear","vi":"Theo chính dự báo của bộ, các nông hộ nhỏ dọc vùng châu thổ sẽ phải gánh chịu nặng nề nhất từ mức thuế xuất khẩu mới.","explanation":"The fixed collocation is <b>bear the brunt of</b> = suffer the worst part of something. <i>Carry</i>, <i>hold</i> and <i>stand</i> can all take a burden in other expressions, but none of them combines with <i>the brunt</i>."},{"id":"gv-ch-35-21","level":"ch","focus":"gerund-infinitive","q":"The witness admitted ______ the accused leave the warehouse, but denied having spoken to him.","options":["to see","see","to have seen","having seen"],"correct":3,"answer":"having seen","vi":"Nhân chứng thừa nhận đã thấy bị cáo rời khỏi nhà kho, nhưng phủ nhận việc đã nói chuyện với anh ta.","explanation":"<b>Admit</b> takes a gerund; the perfect gerund <b>having seen</b> shows the seeing happened before the admission. <i>Admit</i> is never followed by an infinitive."},{"id":"gv-ch-35-22","level":"ch","focus":"double-blank","q":"The residents' committee only ______ round to ______ the leaking roof after part of the ceiling had collapsed.","options":["set / repairing","got / repair","got / repairing","put / repair"],"correct":2,"answer":"got / repairing","vi":"Ban đại diện cư dân chỉ chịu bắt tay vào sửa mái dột sau khi một phần trần nhà đã sập.","explanation":"<b>Get round to + -ing</b> = finally find the time to do something. Only <i>get</i> forms this phrasal verb, and the <i>to</i> here is a preposition, so it must be followed by a gerund."},{"id":"gv-ch-35-23","level":"ch","focus":"idiom","q":"Developers complain that the planning department keeps ______, adding fresh conditions every time a scheme is resubmitted.","options":["moving heaven and earth","moving the goalposts","moving with the times","moving mountains"],"correct":1,"answer":"moving the goalposts","vi":"Các nhà phát triển phàn nàn rằng sở quy hoạch cứ liên tục thay đổi luật chơi, thêm điều kiện mới mỗi lần hồ sơ được nộp lại.","explanation":"<b>Move the goalposts</b> = unfairly change the rules while something is in progress. <i>Move heaven and earth</i> and <i>move mountains</i> mean make a huge effort; <i>move with the times</i> means modernise."},{"id":"gv-ch-35-24","level":"ch","focus":"word-choice","q":"The inquiry published an ______ report on the landfill fire while the full investigation continues.","options":["instant","momentary","transitory","interim"],"correct":3,"answer":"interim","vi":"Ủy ban điều tra đã công bố báo cáo sơ bộ về vụ cháy bãi rác trong khi cuộc điều tra đầy đủ vẫn đang tiếp diễn.","explanation":"An <b>interim</b> report is issued in the period before the final one. <i>Momentary</i> and <i>transitory</i> mean lasting a very short time, and <i>instant</i> means immediate — none of them describes a document."},{"id":"gv-ch-35-25","level":"ch","focus":"question-tag","q":"Hardly anyone on the estate bothers to sort their recycling, ______?","options":["do they","don't they","does he","doesn't it"],"correct":0,"answer":"do they","vi":"Hầu như chẳng ai trong khu dân cư chịu phân loại rác tái chế, phải không?","explanation":"<b>Hardly</b> makes the statement negative, so the tag is positive, and <i>anyone</i> is picked up by the plural pronoun <b>they</b>: <b>do they</b>."},{"id":"gv-ch-36-1","level":"ch","focus":"inversion","q":"______ the public outcry over the data leak that the company's chief executive resigned within a week.","options":["So was","Such was","Such a","So great"],"correct":1,"answer":"Such was","vi":"Làn sóng phẫn nộ của công chúng về vụ rò rỉ dữ liệu lớn đến mức giám đốc điều hành của công ty đã từ chức trong vòng một tuần.","explanation":"Fronted <b>Such + be + noun phrase … that</b> inverts subject and verb: <b>Such was the outcry that</b>; <b>So</b> must be followed by an adjective (<b>So great was the outcry</b>), while <b>Such a</b> and <b>So great</b> leave the clause with no verb."},{"id":"gv-ch-36-2","level":"ch","focus":"word-choice","q":"Without access to the raw figures, critics can only ______ that the charity inflated its impact numbers.","options":["ascertain","verify","surmise","discern"],"correct":2,"answer":"surmise","vi":"Không được xem số liệu gốc, giới phê bình chỉ có thể phỏng đoán rằng tổ chức từ thiện đã thổi phồng các con số về tác động.","explanation":"<b>Surmise</b> means to conclude without firm evidence, which fits <b>without access to the raw figures</b>; <b>ascertain</b>, <b>verify</b> and <b>discern</b> all imply actually finding out or seeing, which the critics cannot do."},{"id":"gv-ch-36-3","level":"ch","focus":"idiom","q":"The claim that free tuition would bankrupt the state simply does not ______ once you look at the figures.","options":["hold water","hold the fort","hold sway","hold the line"],"correct":0,"answer":"hold water","vi":"Luận điểm rằng miễn học phí sẽ làm nhà nước phá sản đơn giản là không đứng vững khi ta nhìn vào các con số.","explanation":"An argument that <b>does not hold water</b> is unsound; <b>hold the fort</b> is to take charge temporarily, <b>hold sway</b> is to have influence, and <b>hold the line</b> is to refuse to change position."},{"id":"gv-ch-36-4","level":"ch","focus":"collocation","q":"The survey paints a ______ picture of morale in state secondary schools, with two in five teachers planning to leave.","options":["dim","faint","pale","bleak"],"correct":3,"answer":"bleak","vi":"Cuộc khảo sát vẽ nên một bức tranh ảm đạm về tinh thần trong các trường trung học công lập, với hai phần năm giáo viên dự định bỏ nghề.","explanation":"<b>Paint a bleak/gloomy/grim picture</b> is the collocation for a pessimistic account; <b>dim</b>, <b>faint</b> and <b>pale</b> describe light or colour, not a hopeless situation."},{"id":"gv-ch-36-5","level":"ch","focus":"subjunctive","q":"The lead author would rather her colleagues ______ the findings to the press until the peer review is complete.","options":["didn't release","don't release","wouldn't release","not to release"],"correct":0,"answer":"didn't release","vi":"Tác giả chính muốn các đồng nghiệp đừng công bố kết quả cho báo chí cho đến khi quá trình bình duyệt hoàn tất.","explanation":"<b>Would rather + another subject + past subjunctive</b> expresses a wish about the present or future: <b>would rather her colleagues didn't release</b>; the present <b>don't</b> and the conditional <b>wouldn't</b> are wrong forms, and the infinitive <b>not to release</b> cannot follow a subject after <b>would rather</b> (the infinitive is only possible with no second subject: <b>would rather not release</b>)."},{"id":"gv-ch-36-6","level":"ch","focus":"phrasal-verb","q":"Ministers met union leaders late into the night in an attempt to ______ a nationwide teachers' strike.","options":["head for","head off","head up","head back"],"correct":1,"answer":"head off","vi":"Các bộ trưởng đã họp với lãnh đạo công đoàn đến khuya nhằm ngăn chặn một cuộc đình công giáo viên trên toàn quốc.","explanation":"<b>Head off</b> means to prevent something from happening; <b>head for</b> is to move towards, <b>head up</b> is to lead an organisation, and <b>head back</b> is to return."},{"id":"gv-ch-36-7","level":"ch","focus":"word-choice","q":"The online scholarship scheme ______ that every applicant has reliable internet access, which is far from true in rural provinces.","options":["predicts","perceives","proposes","presupposes"],"correct":3,"answer":"presupposes","vi":"Chương trình học bổng trực tuyến mặc nhiên coi rằng mọi ứng viên đều có kết nối internet ổn định, điều hoàn toàn không đúng ở các tỉnh nông thôn.","explanation":"To <b>presuppose</b> is to take something for granted as a starting condition; the scheme does not <b>predict</b> or <b>propose</b> that applicants have access, and a scheme cannot <b>perceive</b>."},{"id":"gv-ch-36-8","level":"ch","focus":"double-blank","q":"Rather than ______ the buck to the previous administration, the new minister ______ full responsibility for the failed reform.","options":["push / took","throw / accepted","pass / accepted","pass / made"],"correct":2,"answer":"pass / accepted","vi":"Thay vì đổ trách nhiệm cho chính quyền tiền nhiệm, tân bộ trưởng đã nhận hoàn toàn trách nhiệm về cuộc cải cách thất bại.","explanation":"The idiom is <b>pass the buck</b> (shift blame to someone else), and one <b>accepts/takes</b> responsibility, never <b>makes</b> it; only <b>pass / accepted</b> gets both blanks right."},{"id":"gv-ch-36-9","level":"ch","focus":"linking","q":"Field researchers now carry satellite phones ______ the mobile network fails in the more remote provinces.","options":["in case","unless","so that","as long as"],"correct":0,"answer":"in case","vi":"Các nhà nghiên cứu thực địa hiện mang theo điện thoại vệ tinh phòng khi mạng di động mất sóng ở những tỉnh xa xôi hơn.","explanation":"<b>In case + present simple</b> introduces a precaution against something that might happen; <b>so that</b> states a purpose, which a network failure cannot be, and <b>unless</b> and <b>as long as</b> set conditions rather than a possibility to guard against."},{"id":"gv-ch-36-10","level":"ch","focus":"idiom","q":"The foundation deliberately works in villages that are ______, where the larger aid agencies rarely venture.","options":["off the record","off the beaten track","off the hook","off the cuff"],"correct":1,"answer":"off the beaten track","vi":"Quỹ này cố tình hoạt động ở những ngôi làng hẻo lánh ít người lui tới, nơi các tổ chức viện trợ lớn hiếm khi đặt chân đến.","explanation":"<b>Off the beaten track</b> describes a remote, rarely visited place; <b>off the record</b> is unofficial, <b>off the hook</b> is freed from blame, and <b>off the cuff</b> is unprepared."},{"id":"gv-ch-36-11","level":"ch","focus":"modal","q":"The auditors ______ the discrepancy months earlier, yet somehow it went unnoticed until a whistle-blower came forward.","options":["must have spotted","needn't have spotted","could have spotted","can't have spotted"],"correct":2,"answer":"could have spotted","vi":"Các kiểm toán viên lẽ ra đã có thể phát hiện sai lệch từ nhiều tháng trước, vậy mà không hiểu sao nó vẫn không bị phát hiện cho đến khi một người tố giác lên tiếng.","explanation":"<b>Could have + past participle</b> describes a past possibility that was not realised, which <b>yet it went unnoticed</b> confirms; <b>must have</b> and <b>can't have</b> are deductions that contradict the second clause, and <b>needn't have</b> means an action was done unnecessarily."},{"id":"gv-ch-36-12","level":"ch","focus":"word-choice","q":"From the guarded tone of the reference, we can ______ that her former manager was less than impressed with her work.","options":["infer","imply","insinuate","allude"],"correct":0,"answer":"infer","vi":"Từ giọng điệu dè dặt của thư giới thiệu, ta có thể suy ra rằng người quản lý cũ không mấy ấn tượng với công việc của cô ấy.","explanation":"The reader <b>infers</b> (draws a conclusion); the writer <b>implies</b> or <b>insinuates</b>, and <b>allude</b> is intransitive (<b>allude to</b>) and cannot take a that-clause."},{"id":"gv-ch-36-13","level":"ch","focus":"collocation","q":"The embezzlement scandal has done ______ damage to the charity's reputation among its long-standing donors.","options":["unspoken","unsaid","unmentioned","untold"],"correct":3,"answer":"untold","vi":"Vụ bê bối biển thủ đã gây thiệt hại khôn lường cho uy tín của tổ chức từ thiện trong mắt các nhà tài trợ lâu năm.","explanation":"<b>Untold damage</b> means damage too great to be measured; <b>unspoken</b>, <b>unsaid</b> and <b>unmentioned</b> describe things not put into words and do not collocate with <b>damage</b>."},{"id":"gv-ch-36-14","level":"ch","focus":"participle","q":"______, the three studies suggest that screen time has a far smaller effect on children's sleep than parents fear.","options":["Taking together","Taken together","Having taken together","To take together"],"correct":1,"answer":"Taken together","vi":"Gộp lại, ba nghiên cứu cho thấy thời gian dùng màn hình ảnh hưởng đến giấc ngủ của trẻ ít hơn nhiều so với những gì cha mẹ lo sợ.","explanation":"The studies <b>are taken</b> together by the reader, so the passive participle <b>Taken together</b> is needed; <b>Taking</b> and <b>Having taken</b> would make the studies the ones doing the taking, and <b>To take together</b> expresses purpose."},{"id":"gv-ch-36-15","level":"ch","focus":"idiom","q":"With the education budget frozen, plans for a new vocational college have been put ______ until at least next year.","options":["on the front line","on the back foot","on the back burner","on the cards"],"correct":2,"answer":"on the back burner","vi":"Với ngân sách giáo dục bị đóng băng, kế hoạch xây trường cao đẳng nghề mới đã bị gác lại ít nhất đến năm sau.","explanation":"To <b>put something on the back burner</b> is to postpone it; <b>on the back foot</b> means at a disadvantage, <b>on the cards</b> means likely to happen, and <b>on the front line</b> is where the action is."},{"id":"gv-ch-36-16","level":"ch","focus":"phrasal-verb","q":"Whether the merger goes ahead will ______ the outcome of Friday's shareholder vote.","options":["hold on","hand on","home in on","hinge on"],"correct":3,"answer":"hinge on","vi":"Việc sáp nhập có được tiến hành hay không sẽ phụ thuộc vào kết quả cuộc bỏ phiếu của cổ đông vào thứ Sáu.","explanation":"<b>Hinge on</b> means to depend entirely on; <b>hold on</b> is to wait or grip, <b>hand on</b> is to pass to someone else, and <b>home in on</b> is to move directly towards a target."},{"id":"gv-ch-36-17","level":"ch","focus":"subjunctive","q":"It is high time the government ______ teachers' pay to that of comparable graduate professions.","options":["linked","links","link","has linked"],"correct":0,"answer":"linked","vi":"Đã đến lúc chính phủ phải gắn lương giáo viên với mức lương của các ngành nghề tốt nghiệp đại học tương đương.","explanation":"<b>It is high time + subject + past subjunctive</b> expresses that something should already have been done: <b>high time the government linked</b>, not a present or perfect form."},{"id":"gv-ch-36-18","level":"ch","focus":"word-choice","q":"The trustees ______ the proposal too risky to fund, despite the founder's enthusiasm for it.","options":["regarded","viewed","deemed","looked"],"correct":2,"answer":"deemed","vi":"Các ủy viên quản trị cho rằng đề xuất này quá rủi ro để tài trợ, bất chấp sự nhiệt tình của người sáng lập.","explanation":"<b>Deem + object + adjective</b> needs no preposition; <b>regard</b>, <b>view</b> and <b>look on</b> all require <b>as</b> (regarded the proposal as too risky)."},{"id":"gv-ch-36-19","level":"ch","focus":"gerund-infinitive","q":"Having lost its final appeal, the trust had no choice but ______ the disputed funds to the donor's estate.","options":["returning","to return","return","to returning"],"correct":1,"answer":"to return","vi":"Sau khi thua kháng cáo cuối cùng, quỹ không còn lựa chọn nào khác ngoài việc trả lại số tiền tranh chấp cho di sản của nhà tài trợ.","explanation":"<b>Have no choice/alternative but + to-infinitive</b> is the fixed pattern; the bare infinitive follows <b>cannot but</b> or <b>do nothing but</b>, not <b>have no choice but</b>."},{"id":"gv-ch-36-20","level":"ch","focus":"idiom","q":"A one-off retention bonus will merely ______; it will do nothing about the culture that is driving nurses out of the profession.","options":["read between the lines","clutch at straws","slip through the cracks","paper over the cracks"],"correct":3,"answer":"paper over the cracks","vi":"Một khoản thưởng giữ chân một lần chỉ che đậy tạm thời vấn đề; nó chẳng làm gì được với văn hóa đang đẩy các y tá rời bỏ nghề.","explanation":"To <b>paper over the cracks</b> is to hide a problem rather than solve it; <b>slip through the cracks</b> is to be overlooked, <b>clutch at straws</b> is to try anything in desperation, and <b>read between the lines</b> is to find a hidden meaning."},{"id":"gv-ch-36-21","level":"ch","focus":"article-quantifier","q":"______ progress has been made on narrowing the attainment gap, but far less than the ministry's press release suggests.","options":["Some","A few","Many","Several"],"correct":0,"answer":"Some","vi":"Đã có một số tiến bộ trong việc thu hẹp khoảng cách thành tích, nhưng ít hơn nhiều so với những gì thông cáo báo chí của bộ gợi ý.","explanation":"<b>Progress</b> is uncountable, so only <b>some</b> can quantify it; <b>a few</b>, <b>many</b> and <b>several</b> go with plural countable nouns."},{"id":"gv-ch-36-22","level":"ch","focus":"double-blank","q":"While ______ through a decade of old survey data, the analyst ______ a pattern that nobody in the department had noticed.","options":["shifting / hit on","sorting / hit at","sifting / hit on","sifting / hit out"],"correct":2,"answer":"sifting / hit on","vi":"Trong lúc sàng lọc dữ liệu khảo sát cũ suốt một thập kỷ, nhà phân tích tình cờ phát hiện ra một quy luật mà chưa ai trong phòng để ý.","explanation":"<b>Sift through</b> is to examine carefully, and <b>hit on</b> is to discover by chance; <b>shifting through</b> is a spelling near-miss, <b>hit out</b> means to attack, and <b>hit at</b> is to strike towards."},{"id":"gv-ch-36-23","level":"ch","focus":"inversion","q":"Only after the audit was made public ______ how much of their money had gone on administration.","options":["donors realised","did donors realise","donors did realise","had donors realised"],"correct":1,"answer":"did donors realise","vi":"Chỉ sau khi báo cáo kiểm toán được công bố, các nhà tài trợ mới nhận ra bao nhiêu tiền của họ đã đi vào chi phí hành chính.","explanation":"A fronted <b>Only after + clause</b> forces subject–auxiliary inversion in the main clause: <b>did donors realise</b>; the realising happened after the audit, so the past perfect <b>had donors realised</b> is the wrong tense."},{"id":"gv-ch-36-24","level":"ch","focus":"word-choice","q":"Few head teachers could ______ of a timetable with no standardised testing at all.","options":["perceive","contemplate","consider","conceive"],"correct":3,"answer":"conceive","vi":"Ít hiệu trưởng nào có thể hình dung nổi một thời khóa biểu hoàn toàn không có kỳ thi chuẩn hóa.","explanation":"<b>Conceive of</b> means to imagine something as possible; <b>perceive</b>, <b>contemplate</b> and <b>consider</b> are transitive and take a direct object without <b>of</b>."},{"id":"gv-ch-36-25","level":"ch","focus":"collocation","q":"The central bank has raised interest rates twice this quarter in a bid to ______ inflation without tipping the economy into recession.","options":["deter","quench","curb","shrink"],"correct":2,"answer":"curb","vi":"Ngân hàng trung ương đã hai lần tăng lãi suất trong quý này nhằm kiềm chế lạm phát mà không đẩy nền kinh tế vào suy thoái.","explanation":"<b>Curb inflation/spending/emissions</b> is the collocation for keeping something under control; <b>deter</b> takes a person or a crime, <b>quench</b> goes with thirst or fire, and <b>shrink</b> collocates with a deficit or a workforce, not inflation."}];

if (typeof module !== 'undefined' && module.exports) { module.exports = { GRAMMAR_VOCAB_ITEMS }; }
